				if c != '0' && c != '1' {
					return false, false, 0, 0
				}
			case 8:
				if c < '0' || c > '7' {
					return false, false, 0, 0
				}
			}
		}
		u, err := strconv.ParseUint(digits, base, 64)
		if err != nil {
			return false, false, 0, 0
		}
		iv := int64(u)
		if neg {
			iv = -iv
		}
		return true, true, iv, 0
	}
	// Decimal: digits [. digits] [e[+-]digits]
	q := p
	nIntDigits := 0
	for q < n && isDecDigit(s[q]) {
		q++
		nIntDigits++
	}
	hasDot := false
	nFracDigits := 0
	if q < n && s[q] == '.' {
		hasDot = true
		q++
		for q < n && isDecDigit(s[q]) {
			q++
			nFracDigits++
		}
	}
	if nIntDigits == 0 && nFracDigits == 0 {
		return false, false, 0, 0
	}
	hasExp := false
	if q < n && (s[q] == 'e' || s[q] == 'E') {
		hasExp = true
		q++
		if q < n && (s[q] == '+' || s[q] == '-') {
			q++
		}
		nExpDigits := 0
		for q < n && isDecDigit(s[q]) {
			q++
			nExpDigits++
		}
		if nExpDigits == 0 {
			return false, false, 0, 0
		}
	}
	if q != n {
		return false, false, 0, 0
	}
	if !hasDot && !hasExp {
		// integer
		digits := s[p:]
		if len(digits) > 1 && digits[0] == '0' {
			// leading zeros
			if !inferOctal {
				return false, false, 0, 0
			}
			allOctal := true
			for k := 0; k < len(digits); k++ {
				if digits[k] > '7' {
					allOctal = false
				}
			}
			if allOctal {
				u, err := strconv.ParseInt(digits, 8, 64)
				if err != nil {
					return false, false, 0, 0
				}
				if neg {
					u = -u
				}
				return true, true, u, 0
			}
			u, err := strconv.ParseInt(digits, 10, 64)
			if err != nil {
				return false, false, 0, 0
			}
			if neg {
				u = -u
			}
			return true, true, u, 0
		}
		iv, err := strconv.ParseInt(s, 10, 64)
		if err != nil {
			// overflow: treat as string? Observed: string.
			return false, false, 0, 0
		}
		return true, true, iv, 0
	}
	fv, err := strconv.ParseFloat(s, 64)
	if err != nil {
		return false, false, 0, 0
	}
	if math.IsInf(fv, 0) {
		return false, false, 0, 0
	}
	return true, false, 0, fv
}

// ---------------------------------------------------------------- accessors

func (mv *Mlrval) IsAbsent() bool  { return mv.Type() == MT_ABSENT }
func (mv *Mlrval) IsError() bool   { return mv.Type() == MT_ERROR }
func (mv *Mlrval) IsVoid() bool    { return mv.Type() == MT_VOID }
func (mv *Mlrval) IsString() bool  { t := mv.Type(); return t == MT_STRING || t == MT_VOID }
func (mv *Mlrval) IsStringOrVoid() bool { t := mv.Type(); return t == MT_STRING || t == MT_VOID }
func (mv *Mlrval) IsInt() bool     { return mv.Type() == MT_INT }
func (mv *Mlrval) IsFloat() bool   { return mv.Type() == MT_FLOAT }
func (mv *Mlrval) IsNumeric() bool { t := mv.Type(); return t == MT_INT || t == MT_FLOAT }
func (mv *Mlrval) IsBool() bool    { return mv.Type() == MT_BOOLEAN }
func (mv *Mlrval) IsMap() bool     { return mv.Type() == MT_MAP }
func (mv *Mlrval) IsArray() bool   { return mv.Type() == MT_ARRAY }
func (mv *Mlrval) IsFunc() bool    { return mv.Type() == MT_FUNC }
func (mv *Mlrval) IsCollection() bool {
	t := mv.Type()
	return t == MT_MAP || t == MT_ARRAY
}
func (mv *Mlrval) IsAbsentOrVoid() bool {
	t := mv.Type()
	return t == MT_ABSENT || t == MT_VOID
}
func (mv *Mlrval) IsAbsentOrError() bool {
	t := mv.Type()
	return t == MT_ABSENT || t == MT_ERROR
}

// IsTrue: strict boolean true
func (mv *Mlrval) IsTrue() bool {
	return mv.Type() == MT_BOOLEAN && mv.boolval
}

func (mv *Mlrval) GetNumericToFloat() (float64, bool) {
	switch mv.Type() {
	case MT_INT:
		return float64(mv.intval), true
	case MT_FLOAT:
		return mv.floatval, true
	}
	return 0, false
}

// GetBoolFromString: for data values "true"/"false"
func (mv *Mlrval) GetBoolStrict() (bool, bool) {
	t := mv.Type()
	if t == MT_BOOLEAN {
		return mv.boolval, true
	}
	if t == MT_STRING || t == MT_PENDING {
		if mv.printrep == "true" {
			return true, true
		}
		if mv.printrep == "false" {
			return false, true
		}
	}
	return false, false
}

func (mv *Mlrval) TypeName() string {
	t := mv.Type()
	return typeNames[t]
}

// ---------------------------------------------------------------- formatting

var ofmt string = ""

func formatFloat(f float64) string {
	if ofmt != "" {
		return fmtnumFloat(f, ofmt)
	}
	return strconv.FormatFloat(f, 'f', -1, 64)
}

func formatFloatNoOfmt(f float64) string {
	return strconv.FormatFloat(f, 'f', -1, 64)
}

// String returns the string representation.
func (mv *Mlrval) String() string {
	if mv.printrepValid {
		return mv.printrep
	}
	switch mv.mvtype {
	case MT_INT:
		mv.printrep = strconv.FormatInt(mv.intval, 10)
	case MT_FLOAT:
		mv.printrep = formatFloat(mv.floatval)
	case MT_BOOLEAN:
		if mv.boolval {
			mv.printrep = "true"
		} else {
			mv.printrep = "false"
		}
	case MT_MAP:
		mv.printrep = mv.mapval.ToJSONString(false, 0)
		return mv.printrep // don't cache: maps may mutate
	case MT_ARRAY:
		mv.printrep = arrayToJSONString(mv.arrayval, false, 0)
		return mv.printrep
	case MT_FUNC:
		mv.printrep = mv.funcval.name
	case MT_ERROR:
		mv.printrep = "(error)"
	default:
		mv.printrep = ""
	}
	mv.printrepValid = true
	return mv.printrep
}

// OutputString: the string used by record writers. For floats with --ofmt,
// applies formatting even to values with original string representation.
func (mv *Mlrval) OutputString() string {
	if ofmt != "" && mv.Type() == MT_FLOAT {
		return fmtnumFloat(mv.floatval, ofmt)
	}
	return mv.String()
}

// Copy makes a deep copy for collections.
func (mv *Mlrval) Copy() *Mlrval {
	switch mv.mvtype {
	case MT_MAP:
		return FromMap(mv.mapval.Copy())
	case MT_ARRAY:
		a := make([]*Mlrval, len(mv.arrayval))
		for i, e := range mv.arrayval {
			a[i] = e.Copy()
		}
		return FromArray(a)
	}
	c := *mv
	return &c
}

// ---------------------------------------------------------------- numeric helpers

// For values from data looking like numbers: decide if int or float. Used for
// sort -n etc.
func (mv *Mlrval) AsFloatForSort() (float64, bool) {
	switch mv.Type() {
	case MT_INT:
		return float64(mv.intval), true
	case MT_FLOAT:
		return mv.floatval, true
	}
	return 0, false
}

// inferTypeFromString without -S consideration, for DSL functions that infer
func inferredFromString(s string) *Mlrval {
	mv := &Mlrval{mvtype: MT_PENDING, printrep: s, printrepValid: true}
	mv.inferTypeForce(false)
	return mv
}

func isAllDigits(s string) bool {
	if s == "" {
		return false
	}
	for i := 0; i < len(s); i++ {
		if !isDecDigit(s[i]) {
			return false
		}
	}
	return true
}

func stringsIndexRune(s string, r rune) int {
	return strings.IndexRune(s, r)
}
