	for i, k := range keys {
		v := m.Get(k)
		if v == nil {
			return "", false
		}
		if v.IsAbsent() {
			return "", false
		}
		if i > 0 {
			sb.WriteByte(',')
		}
		sb.WriteString(v.String())
	}
	return sb.String(), true
