		m.Tail = e.Prev
	}
	delete(m.index, e.Key)
	m.count--
}

func (m *Mlrmap) Remove(key string) bool {
	e, ok := m.index[key]
	if !ok {
		return false
	}
	m.unlink(e)
	return true
}

func (m *Mlrmap) Clear() {
	m.Head = nil
	m.Tail = nil
	m.count = 0
	m.index = make(map[string]*MlrmapEntry)
}

// Rename renames a key in place. If the new key exists elsewhere, that entry
// is removed (the renamed one keeps its position).
func (m *Mlrmap) Rename(oldKey, newKey string) bool {
	e, ok := m.index[oldKey]
	if !ok {
		return false
	}
	if oldKey == newKey {
		return true
	}
	if other, ok := m.index[newKey]; ok {
		// Existing entry with new name: put value in its position? Miller
		// semantics: the renamed field replaces the existing one in the
		// old field's position... Actually Miller keeps position of the
		// existing new-key entry? See rename verb tests.
		other.Value = e.Value
		m.unlink(e)
		return true
	}
	delete(m.index, oldKey)
	e.Key = newKey
	m.index[newKey] = e
	return true
}

// RenameKeepingOldPosition: renames; if the new key exists, it's removed and
// the renamed entry stays in old position.
func (m *Mlrmap) RenameKeepingOldPosition(oldKey, newKey string) bool {
	e, ok := m.index[oldKey]
	if !ok {
		return false
	}
	if oldKey == newKey {
		return true
	}
	if other, ok := m.index[newKey]; ok {
		m.unlink(other)
	}
	delete(m.index, oldKey)
	e.Key = newKey
	m.index[newKey] = e
	return true
}

func (m *Mlrmap) Keys() []string {
	keys := make([]string, 0, m.count)
	for e := m.Head; e != nil; e = e.Next {
		keys = append(keys, e.Key)
	}
	return keys
}

func (m *Mlrmap) Values() []*Mlrval {
	vals := make([]*Mlrval, 0, m.count)
	for e := m.Head; e != nil; e = e.Next {
		vals = append(vals, e.Value)
	}
	return vals
}

func (m *Mlrmap) KeysJoined(sep string) string {
	return strings.Join(m.Keys(), sep)
}

// Copy makes a deep copy.
func (m *Mlrmap) Copy() *Mlrmap {
	n := NewMlrmap()
	for e := m.Head; e != nil; e = e.Next {
		n.Put(e.Key, e.Value.Copy())
	}
	return n
}

// ShallowCopy copies entries but not values.
func (m *Mlrmap) ShallowCopy() *Mlrmap {
	n := NewMlrmap()
	for e := m.Head; e != nil; e = e.Next {
		n.Put(e.Key, e.Value)
	}
	return n
}

// GetByPosition returns the entry at 1-up position, or nil.
func (m *Mlrmap) GetEntryByPosition(pos int) *MlrmapEntry {
	if pos < 1 || pos > m.count {
		return nil
	}
	i := 1
	for e := m.Head; e != nil; e = e.Next {
		if i == pos {
			return e
		}
		i++
	}
	return nil
}

// HasSameKeysAs checks keys and order.
func (m *Mlrmap) HasSameKeysAs(other *Mlrmap) bool {
	if m.count != other.count {
		return false
	}
	e := m.Head
	f := other.Head
	for e != nil && f != nil {
		if e.Key != f.Key {
			return false
		}
		e = e.Next
		f = f.Next
	}
	return true
}

func (m *Mlrmap) HasSameKeyListAs(keys []string) bool {
	if m.count != len(keys) {
		return false
	}
	i := 0
	for e := m.Head; e != nil; e = e.Next {
		if e.Key != keys[i] {
			return false
		}
		i++
	}
	return true
}

// Equals: deep equality by string representation of values.
func (m *Mlrmap) Equals(other *Mlrmap) bool {
	if m.count != other.count {
		return false
	}
	for e := m.Head; e != nil; e = e.Next {
		o := other.Get(e.Key)
		if o == nil {
			return false
		}
		if !mlrvalEquals(e.Value, o) {
			return false
		}
	}
	return true
}

func mlrvalEquals(a, b *Mlrval) bool {
	ta := a.Type()
	tb := b.Type()
	if ta == MT_MAP && tb == MT_MAP {
		return a.mapval.Equals(b.mapval)
	}
	if ta == MT_ARRAY && tb == MT_ARRAY {
		if len(a.arrayval) != len(b.arrayval) {
			return false
		}
		for i := range a.arrayval {
			if !mlrvalEquals(a.arrayval[i], b.arrayval[i]) {
				return false
			}
		}
		return true
	}
	if ta == MT_MAP || tb == MT_MAP || ta == MT_ARRAY || tb == MT_ARRAY {
		return false
	}
	return a.String() == b.String()
}

// Selected-values helpers for group-by
func (m *Mlrmap) GetSelectedValuesJoined(keys []string) (string, bool) {
	if len(keys) == 0 {
		return "", true
	}
	var sb strings.Builder
	for i, k := range keys {
		v := m.Get(k)
		if v == nil {
			return "", false
		}
		if v.IsAbsent() {
			return "", false
		}
		if i > 0 {
			sb.WriteByte(',')
		}
		sb.WriteString(v.String())
	}
	return sb.String(), true
}

func (m *Mlrmap) GetSelectedValues(keys []string) ([]*Mlrval, bool) {
	vals := make([]*Mlrval, 0, len(keys))
	for _, k := range keys {
		v := m.Get(k)
		if v == nil {
			return nil, false
		}
		vals = append(vals, v)
	}
	return vals, true
}

// SortByKey sorts entries lexically by key.
func (m *Mlrmap) SortByKey() {
	keys := m.Keys()
	sortStrings(keys)
	n := NewMlrmap()
	for _, k := range keys {
		n.Put(k, m.Get(k))
	}
	*m = *n
}

// PutNameWithPositionalIndex etc. are in DSL code.

// ToPairsString: for grep verb, DKVP-ish formatting.
func (m *Mlrmap) ToDKVPString(ofs, ops string) string {
	var sb strings.Builder
	first := true
	for e := m.Head; e != nil; e = e.Next {
		if !first {
			sb.WriteString(ofs)
		}
		first = false
		sb.WriteString(e.Key)
		sb.WriteString(ops)
		sb.WriteString(e.Value.String())
	}
	return sb.String()
}

func (m *Mlrmap) ToNIDXString(ofs string) string {
	var sb strings.Builder
	first := true
	for e := m.Head; e != nil; e = e.Next {
		if !first {
			sb.WriteString(ofs)
		}
		first = false
		sb.WriteString(e.Value.String())
	}
	return sb.String()
}
