	"unicode/utf8"
)

// ---------------------------------------------------------------- JSON encoding

func jsonEncodeString(s string) string {
	var sb strings.Builder
	sb.WriteByte('"')
	for i := 0; i < len(s); {
		c := s[i]
		switch c {
		case '"':
			sb.WriteString("\\\"")
			i++
		case '\\':
			sb.WriteString("\\\\")
			i++
		case '\n':
			sb.WriteString("\\n")
			i++
		case '\t':
			sb.WriteString("\\t")
			i++
		case '\r':
			sb.WriteString("\\r")
			i++
		case '\b':
			sb.WriteString("\\b")
			i++
		case '\f':
			sb.WriteString("\\f")
			i++
		default:
			if c < 0x20 {
				fmt.Fprintf(&sb, "\\u%04x", c)
				i++
			} else if c < 0x80 {
				sb.WriteByte(c)
				i++
			} else {
				r, size := utf8.DecodeRuneInString(s[i:])
				if r == utf8.RuneError && size == 1 {
					sb.WriteByte(c)
					i++
				} else {
					sb.WriteString(s[i : i+size])
					i += size
				}
			}
		}
	}
	sb.WriteByte('"')
	return sb.String()
}

var jvQuoteAll = false

// jsonScalarString renders a scalar value for JSON output.
func jsonScalarString(mv *Mlrval) string {
	switch mv.Type() {
	case MT_INT, MT_FLOAT:
		if jvQuoteAll {
			return jsonEncodeString(mv.OutputString())
		}
		return mv.OutputString()
	case MT_BOOLEAN:
		if jvQuoteAll {
			return jsonEncodeString(mv.String())
		}
		return mv.String()
	case MT_ABSENT:
		return jsonEncodeString("")
	case MT_ERROR:
		return "(error)"
	case MT_FUNC:
		return jsonEncodeString(mv.String())
	default:
		return jsonEncodeString(mv.String())
	}
}

func isJSONNull(mv *Mlrval) bool {
	return mv.mvtype == MT_STRING && mv.printrep == "null" && mv.isJSONNull
}

func arrayHasCollections(a []*Mlrval) bool {
	for _, e := range a {
		t := e.Type()
		if t == MT_MAP || t == MT_ARRAY {
			return true
		}
	}
	return false
}

// ToJSONString renders a map. multiline=true for vertical format.
// indent is the current indentation level (number of spaces of the enclosing
// context, where the opening brace is).
func (m *Mlrmap) ToJSONString(multiline bool, indent int) string {
	var sb strings.Builder
	writeMapJSON(&sb, m, multiline, indent)
	return sb.String()
}

func arrayToJSONString(a []*Mlrval, multiline bool, indent int) string {
	var sb strings.Builder
	writeArrayJSON(&sb, a, multiline, indent)
	return sb.String()
}

func writeValueJSON(sb *strings.Builder, mv *Mlrval, multiline bool, indent int) {
	switch mv.Type() {
	case MT_MAP:
		writeMapJSON(sb, mv.mapval, multiline, indent)
	case MT_ARRAY:
		writeArrayJSON(sb, mv.arrayval, multiline, indent)
	default:
		if isJSONNull(mv) {
			sb.WriteString("null")
		} else {
			sb.WriteString(jsonScalarString(mv))
		}
	}
}

func writeMapJSON(sb *strings.Builder, m *Mlrmap, multiline bool, indent int) {
	if m.Len() == 0 {
		sb.WriteString("{}")
		return
	}
	if !multiline {
		sb.WriteByte('{')
		first := true
		for e := m.Head; e != nil; e = e.Next {
			if !first {
				sb.WriteString(", ")
			}
			first = false
			sb.WriteString(jsonEncodeString(e.Key))
			sb.WriteString(": ")
			writeValueJSON(sb, e.Value, false, 0)
		}
		sb.WriteByte('}')
		return
	}
	sb.WriteString("{\n")
	pad := strings.Repeat(" ", indent+2)
	first := true
	for e := m.Head; e != nil; e = e.Next {
		if !first {
			sb.WriteString(",\n")
		}
		first = false
		sb.WriteString(pad)
		sb.WriteString(jsonEncodeString(e.Key))
		sb.WriteString(": ")
		writeValueJSON(sb, e.Value, true, indent+2)
	}
	sb.WriteString("\n")
	sb.WriteString(strings.Repeat(" ", indent))
	sb.WriteByte('}')
}

func writeArrayJSON(sb *strings.Builder, a []*Mlrval, multiline bool, indent int) {
	if len(a) == 0 {
		sb.WriteString("[]")
		return
	}
	if !multiline || !arrayHasCollections(a) {
		sb.WriteByte('[')
		for i, e := range a {
			if i > 0 {
				sb.WriteString(", ")
			}
			writeValueJSON(sb, e, false, 0)
		}
		sb.WriteByte(']')
		return
	}
	sb.WriteString("[\n")
	pad := strings.Repeat(" ", indent+2)
	for i, e := range a {
		if i > 0 {
			sb.WriteString(",\n")
		}
		sb.WriteString(pad)
		writeValueJSON(sb, e, true, indent+2)
	}
	sb.WriteString("\n")
	sb.WriteString(strings.Repeat(" ", indent))
	sb.WriteByte(']')
}

// ---------------------------------------------------------------- JSON decoding

type jsonParser struct {
	data []byte
	pos  int
	line int
}

type jsonError struct {
	msg string
}

func (e *jsonError) Error() string { return e.msg }

func newJSONParser(data []byte) *jsonParser {
	return &jsonParser{data: data, pos: 0, line: 1}
}

func (p *jsonParser) skipWhitespace() {
	for p.pos < len(p.data) {
		c := p.data[p.pos]
		if c == ' ' || c == '\t' || c == '\r' {
			p.pos++
		} else if c == '\n' {
			p.pos++
			p.line++
		} else {
			break
		}
	}
}

func (p *jsonParser) atEOF() bool {
	p.skipWhitespace()
	return p.pos >= len(p.data)
}

func (p *jsonParser) errorf(format string, args ...interface{}) error {
	return &jsonError{msg: fmt.Sprintf(format, args...)}
}

func (p *jsonParser) peek() (byte, bool) {
	if p.pos >= len(p.data) {
		return 0, false
	}
	return p.data[p.pos], true
}

// parseValue parses any JSON value.
func (p *jsonParser) parseValue() (*Mlrval, error) {
	p.skipWhitespace()
	c, ok := p.peek()
	if !ok {
		return nil, p.errorf("mlr: JSON parser: unexpected premature EOF")
	}
	switch {
	case c == '{':
		return p.parseObject()
	case c == '[':
		return p.parseArray()
	case c == '"':
		s, err := p.parseString()
		if err != nil {
			return nil, err
		}
		mv := FromString(s)
		if s == "" {
			mv = VOID
		}
		return mv, nil
	case c == 't':
		if err := p.expectLiteral("true"); err != nil {
			return nil, err
		}
		return TRUE, nil
	case c == 'f':
		if err := p.expectLiteral("false"); err != nil {
			return nil, err
		}
		return FALSE, nil
	case c == 'n':
		if err := p.expectLiteral("null"); err != nil {
			return nil, err
		}
		return newJSONNull(), nil
	case c == '-' || (c >= '0' && c <= '9'):
		return p.parseNumber()
	default:
		return nil, p.errorf("mlr: invalid character %s looking for beginning of value", quoteChar(c))
	}
}

func newJSONNull() *Mlrval {
	return &Mlrval{mvtype: MT_STRING, printrep: "null", printrepValid: true, isJSONNull: true}
}

func quoteChar(c byte) string {
	if c == '\'' {
		return `'\''`
	}
	if c == '"' {
		return `'"'`
	}
	return strconv.QuoteRune(rune(c))
}

func (p *jsonParser) expectLiteral(lit string) error {
	for i := 0; i < len(lit); i++ {
		if p.pos >= len(p.data) {
			return p.errorf("mlr: JSON parser: unexpected premature EOF")
		}
		if p.data[p.pos] != lit[i] {
			return p.errorf("mlr: invalid character %s in literal %s (expecting %s)", quoteChar(p.data[p.pos]), lit, quoteChar(lit[i]))
		}
		p.pos++
	}
	return nil
}

func (p *jsonParser) parseNumber() (*Mlrval, error) {
	start := p.pos
	if p.data[p.pos] == '-' {
		p.pos++
	}
	for p.pos < len(p.data) {
		c := p.data[p.pos]
		if (c >= '0' && c <= '9') || c == '.' || c == 'e' || c == 'E' || c == '+' || c == '-' {
			p.pos++
		} else {
			break
		}
	}
	s := string(p.data[start:p.pos])
	mv := &Mlrval{mvtype: MT_PENDING, printrep: s, printrepValid: true}
	mv.inferTypeForce(false)
	if mv.mvtype != MT_INT && mv.mvtype != MT_FLOAT {
		// e.g. "1.2.3" or leading zeros
		if _, err := strconv.ParseFloat(s, 64); err != nil {
			return nil, p.errorf("mlr: invalid character in number %q", s)
		}
		mv.mvtype = MT_PENDING
		mv.inferTypeForce(false)
		if mv.mvtype != MT_INT && mv.mvtype != MT_FLOAT {
			f, _ := strconv.ParseFloat(s, 64)
			return FromFloatWithRep(f, s), nil
		}
	}
	return mv, nil
}

func (p *jsonParser) parseString() (string, error) {
	// assumes current char is '"'
	p.pos++
	var sb strings.Builder
	for {
		if p.pos >= len(p.data) {
			return "", p.errorf("mlr: JSON parser: unexpected premature EOF")
		}
		c := p.data[p.pos]
		if c == '"' {
			p.pos++
			return sb.String(), nil
		}
		if c == '\\' {
			p.pos++
			if p.pos >= len(p.data) {
				return "", p.errorf("mlr: JSON parser: unexpected premature EOF")
			}
			e := p.data[p.pos]
			p.pos++
			switch e {
			case '"':
				sb.WriteByte('"')
			case '\\':
				sb.WriteByte('\\')
			case '/':
				sb.WriteByte('/')
			case 'b':
				sb.WriteByte('\b')
			case 'f':
				sb.WriteByte('\f')
			case 'n':
				sb.WriteByte('\n')
			case 'r':
				sb.WriteByte('\r')
			case 't':
				sb.WriteByte('\t')
			case 'u':
				if p.pos+4 > len(p.data) {
					return "", p.errorf("mlr: JSON parser: unexpected premature EOF")
				}
				h := string(p.data[p.pos : p.pos+4])
				p.pos += 4
				u, err := strconv.ParseUint(h, 16, 32)
				if err != nil {
					return "", p.errorf("mlr: invalid character in \\u escape")
				}
				r := rune(u)
				// surrogate pairs
				if r >= 0xD800 && r <= 0xDBFF && p.pos+6 <= len(p.data) && p.data[p.pos] == '\\' && p.data[p.pos+1] == 'u' {
					h2 := string(p.data[p.pos+2 : p.pos+6])
					u2, err2 := strconv.ParseUint(h2, 16, 32)
					if err2 == nil && u2 >= 0xDC00 && u2 <= 0xDFFF {
						r = (r-0xD800)<<10 + (rune(u2) - 0xDC00) + 0x10000
						p.pos += 6
					}
				}
				sb.WriteRune(r)
			default:
				return "", p.errorf("mlr: invalid character %s in string escape code", quoteChar(e))
			}
			continue
		}
		if c == '\n' {
			p.line++
		}
		sb.WriteByte(c)
		p.pos++
	}
}

func (p *jsonParser) parseObject() (*Mlrval, error) {
	p.pos++ // '{'
	m := NewMlrmap()
	p.skipWhitespace()
	c, ok := p.peek()
	if !ok {
		return nil, p.errorf("mlr: JSON parser: unexpected premature EOF")
	}
	if c == '}' {
		p.pos++
		return FromMap(m), nil
	}
	for {
		p.skipWhitespace()
		c, ok := p.peek()
		if !ok {
			return nil, p.errorf("mlr: JSON parser: unexpected premature EOF")
		}
		if c != '"' {
			return nil, p.errorf("mlr: invalid character %s looking for beginning of object key string", quoteChar(c))
		}
		key, err := p.parseString()
		if err != nil {
			return nil, err
		}
		p.skipWhitespace()
		c, ok = p.peek()
		if !ok {
			return nil, p.errorf("mlr: JSON parser: unexpected premature EOF")
		}
		if c != ':' {
			return nil, p.errorf("mlr: invalid character %s after object key", quoteChar(c))
		}
		p.pos++
		val, err := p.parseValue()
		if err != nil {
			return nil, err
		}
		m.Put(key, val)
		p.skipWhitespace()
		c, ok = p.peek()
		if !ok {
			return nil, p.errorf("mlr: JSON parser: unexpected premature EOF")
		}
		if c == ',' {
			p.pos++
			continue
		}
		if c == '}' {
			p.pos++
			return FromMap(m), nil
		}
		return nil, p.errorf("mlr: invalid character %s after object key:value pair", quoteChar(c))
	}
}

func (p *jsonParser) parseArray() (*Mlrval, error) {
	p.pos++ // '['
	a := make([]*Mlrval, 0)
	p.skipWhitespace()
	c, ok := p.peek()
	if !ok {
		return nil, p.errorf("mlr: JSON parser: unexpected premature EOF")
	}
	if c == ']' {
		p.pos++
		return FromArray(a), nil
	}
	for {
		val, err := p.parseValue()
		if err != nil {
			return nil, err
		}
		a = append(a, val)
		p.skipWhitespace()
		c, ok := p.peek()
		if !ok {
			return nil, p.errorf("mlr: JSON parser: unexpected premature EOF")
		}
		if c == ',' {
			p.pos++
			continue
		}
		if c == ']' {
			p.pos++
			return FromArray(a), nil
		}
		return nil, p.errorf("mlr: invalid character %s after array element", quoteChar(c))
	}
}

// ParseJSONValue parses a complete JSON text into a single value.
func ParseJSONValue(s string) (*Mlrval, error) {
	p := newJSONParser([]byte(s))
	v, err := p.parseValue()
	if err != nil {
		return nil, err
	}
	if !p.atEOF() {
		return nil, p.errorf("mlr: invalid character %s after top-level value", quoteChar(p.data[p.pos]))
	}
	return v, nil
}
