	r := &o.Reader
	w := &o.Writer
	if !r.ifsWasSpecified {
		r.IFS = defaultFS(r.InputFileFormat)
	}
	if !r.ipsWasSpecified {
		r.IPS = defaultPS(r.InputFileFormat)
	}
	if !r.irsWasSpecified {
		r.IRS = defaultRS(r.InputFileFormat)
	}
	if !r.repifsSpecified {
		r.AllowRepeatIFS = defaultRepIFS(r.InputFileFormat)
		if r.InputFileFormat == "nidx" && r.ifsWasSpecified {
			r.AllowRepeatIFS = false
		}
	}
	if !w.ofsWasSpecified {
		w.OFS = defaultFS(w.OutputFileFormat)
	}
	if !w.opsWasSpecified {
		w.OPS = defaultPS(w.OutputFileFormat)
	}
	if !w.orsWasSpecified {
		w.ORS = defaultRS(w.OutputFileFormat)
	}
	if w.OutputFileFormat == "jsonl" {
		w.JSONVStack = false
		w.JSONListWrap = false
	}
	if w.OutputFileFormat == "json" {
