var separatorRegexAliases = map[string]string{
	"spaces":     "( )+",
	"tabs":       "(\t)+",
	"whitespace": "([ \t])+",
}

// BackslashXXToRunes handles C-style escapes in separators.
func unbackslashSeparator(s string) string {
	if alias, ok := separatorAliases[s]; ok {
		return alias
	}
	return unbackslashString(s)
}

func unbackslashString(s string) string {
	if !strings.Contains(s, "\\") {
		return s
	}
	var sb strings.Builder
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == '\\' && i+1 < len(s) {
			n := s[i+1]
			switch n {
			case 't':
				sb.WriteByte('\t')
				i++
			case 'n':
				sb.WriteByte('\n')
				i++
			case 'r':
				sb.WriteByte('\r')
				i++
			case '\\':
				sb.WriteByte('\\')
				i++
			case '"':
				sb.WriteByte('"')
				i++
			case 'x':
				if i+3 < len(s) && isHexDigit(s[i+2]) && isHexDigit(s[i+3]) {
					var b byte
					fmt.Sscanf(s[i+2:i+4], "%02x", &b)
					sb.WriteByte(b)
					i += 3
				} else {
					sb.WriteByte(c)
				}
			default:
				sb.WriteByte(c)
			}
		} else {
			sb.WriteByte(c)
		}
	}
	return sb.String()
}

