package main

import (
	"bufio"
	"compress/bzip2"
	"compress/gzip"
	"compress/zlib"
	"fmt"
	"io"
	"os"
	"os/exec"
	"regexp"
	"strconv"
	"strings"
)

type Context struct {
	NR       int64
	FNR      int64
	FILENAME string
	FILENUM  int64
}

// RecordHandler is called for each record; returns false to stop reading.
type RecordHandler func(rec *Mlrmap, ctx *Context) bool

type RecordReader interface {
	// Read processes all files; ctx is updated in place.
	Read(filenames []string, ctx *Context, handler RecordHandler) error
}

var jsonInputHadList = false

// ---------------------------------------------------------------- file opening

func openInput(filename string, ropts *ReaderOptions) (io.Reader, func(), error) {
	if ropts.Prepipe != "" {
		var cmdline string
		if ropts.PrepipeIsRaw {
			cmdline = ropts.Prepipe + " " + filename
		} else {
			cmdline = ropts.Prepipe + " < '" + filename + "'"
		}
		cmd := exec.Command("/bin/sh", "-c", cmdline)
		cmd.Stderr = os.Stderr
		out, err := cmd.StdoutPipe()
		if err != nil {
			return nil, nil, err
		}
		if err := cmd.Start(); err != nil {
			return nil, nil, err
		}
		return out, func() { cmd.Wait() }, nil
	}
	var f io.Reader
	var closer func()
	if filename == "-" {
		f = os.Stdin
		closer = func() {}
	} else {
		fh, err := os.Open(filename)
		if err != nil {
			return nil, nil, err
		}
		f = fh
		closer = func() { fh.Close() }
	}
	enc := ropts.FileInputEncoding
	if enc == "" {
		if strings.HasSuffix(filename, ".gz") {
			enc = "gzip"
		} else if strings.HasSuffix(filename, ".bz2") {
			enc = "bz2"
		} else if strings.HasSuffix(filename, ".z") {
			enc = "zlib"
		}
	}
	switch enc {
	case "gzip":
		br := bufio.NewReader(f)
		// check magic
		if b, err := br.Peek(2); err == nil && b[0] == 0x1f && b[1] == 0x8b {
			gr, err := gzip.NewReader(br)
			if err != nil {
				return nil, nil, err
			}
			return gr, closer, nil
		}
		return br, closer, nil
	case "bz2":
		return bzip2.NewReader(f), closer, nil
	case "zlib":
		zr, err := zlib.NewReader(f)
		if err != nil {
			return nil, nil, err
		}
		return zr, closer, nil
	}
	// Auto-detect gzip by magic number even without suffix
	br := bufio.NewReader(f)
	if b, err := br.Peek(2); err == nil && b[0] == 0x1f && b[1] == 0x8b {
		gr, err := gzip.NewReader(br)
		if err == nil {
			return gr, closer, nil
		}
	}
	return br, closer, nil
}

// ---------------------------------------------------------------- line splitting

type lineReader struct {
	br  *bufio.Reader
	irs string
	eof bool
}

func newLineReader(r io.Reader, irs string) *lineReader {
	return &lineReader{br: bufio.NewReaderSize(r, 65536), irs: irs}
}

// readLine returns the next line without the separator. ok=false at EOF.
func (lr *lineReader) readLine() (string, bool) {
	if lr.eof {
		return "", false
	}
	if lr.irs == "\n" || lr.irs == "" {
		line, err := lr.br.ReadString('\n')
		if err != nil {
			lr.eof = true
			if line == "" {
				return "", false
			}
			return strings.TrimSuffix(line, "\r"), true
		}
		line = line[:len(line)-1]
		line = strings.TrimSuffix(line, "\r")
		return line, true
	}
	// Custom IRS: read until the separator string
	last := lr.irs[len(lr.irs)-1]
	var sb strings.Builder
	for {
		chunk, err := lr.br.ReadString(last)
		sb.WriteString(chunk)
		if err != nil {
			lr.eof = true
			s := sb.String()
			if s == "" {
				return "", false
			}
			return s, true
		}
		s := sb.String()
		if strings.HasSuffix(s, lr.irs) {
			return s[:len(s)-len(lr.irs)], true
		}
	}
}

// ---------------------------------------------------------------- comment handling

// handleComment returns true if the line was a comment and was handled.
func handleComment(line string, ropts *ReaderOptions) bool {
	if ropts.CommentHandling == 0 {
		return false
	}
	if strings.HasPrefix(line, ropts.CommentString) {
		if ropts.CommentHandling == 2 {
			stdoutWriter.WriteString(line + "\n")
			stdoutWriter.Flush()
		}
		return true
	}
	return false
}

// ---------------------------------------------------------------- field splitting

func splitString(s, sep string, repifs bool) []string {
	if s == "" {
		return []string{}
	}
	if !repifs {
		return strings.Split(s, sep)
	}
	// Repeated separators: strip leading seps, split and skip empties
	var out []string
	for len(s) > 0 && strings.HasPrefix(s, sep) {
		s = s[len(sep):]
	}
	for len(s) > 0 && strings.HasSuffix(s, sep) {
		s = s[:len(s)-len(sep)]
	}
	if s == "" {
		return []string{}
	}
	parts := strings.Split(s, sep)
	for _, p := range parts {
		if p != "" {
			out = append(out, p)
		}
	}
	return out
}

var regexCache = map[string]*regexp.Regexp{}

func getRegex(pattern string) *regexp.Regexp {
	if rx, ok := regexCache[pattern]; ok {
		return rx
	}
	rx, err := regexp.Compile(pattern)
	if err != nil {
		fmt.Fprintf(os.Stderr, "mlr: could not compile regex \"%s\"\n", pattern)
		os.Exit(1)
	}
	regexCache[pattern] = rx
	return rx
}

func splitStringRegex(s string, rx *regexp.Regexp) []string {
	if s == "" {
		return []string{}
	}
	return rx.Split(s, -1)
}

// dedupeKey handles duplicate field names: a, a_2, a_3, ...
func putWithDedupe(rec *Mlrmap, key string, value *Mlrval, dedupe bool) {
	if !dedupe || !rec.Has(key) {
		rec.Put(key, value)
		return
	}
	for i := 2; ; i++ {
		k := key + "_" + strconv.Itoa(i)
		if !rec.Has(k) {
			rec.Put(k, value)
			return
		}
	}
}

// ---------------------------------------------------------------- DKVP

type dkvpReader struct {
	ropts *ReaderOptions
}

func (r *dkvpReader) Read(filenames []string, ctx *Context, handler RecordHandler) error {
	return forEachFile(filenames, r.ropts, ctx, func(in io.Reader, ctx *Context) (bool, error) {
		lr := newLineReader(in, r.ropts.IRS)
		var ifsRx, ipsRx *regexp.Regexp
		if r.ropts.IFSRegex != "" {
			ifsRx = getRegex(r.ropts.IFSRegex)
		}
		if r.ropts.IPSRegex != "" {
			ipsRx = getRegex(r.ropts.IPSRegex)
		}
		for {
			line, ok := lr.readLine()
			if !ok {
				break
			}
			if handleComment(line, r.ropts) {
				continue
			}
			rec := recordFromDKVPLine(line, r.ropts, ifsRx, ipsRx)
			ctx.NR++
			ctx.FNR++
			if !handler(rec, ctx) {
				return false, nil
			}
		}
		return true, nil
	})
}

func recordFromDKVPLine(line string, ropts *ReaderOptions, ifsRx, ipsRx *regexp.Regexp) *Mlrmap {
	rec := NewMlrmap()
	var fields []string
	if ifsRx != nil {
		fields = splitStringRegex(line, ifsRx)
	} else {
		fields = splitString(line, ropts.IFS, ropts.AllowRepeatIFS)
	}
	keylessCounter := 0
	for i, field := range fields {
		if field == "" && ifsRx == nil && !ropts.AllowRepeatIFS {
			continue
		}
		var key, value string
		var found bool
		if ipsRx != nil {
			loc := ipsRx.FindStringIndex(field)
			if loc != nil {
				key = field[:loc[0]]
				value = field[loc[1]:]
				found = true
			}
		} else {
			idx := strings.Index(field, ropts.IPS)
			if idx >= 0 {
				key = field[:idx]
				value = field[idx+len(ropts.IPS):]
				found = true
			}
		}
		if !found {
			if ropts.IncrKey {
				keylessCounter++
				key = strconv.Itoa(keylessCounter)
			} else {
				key = strconv.Itoa(i + 1)
			}
			value = field
		}
		putWithDedupe(rec, key, FromInferredString(value), ropts.DedupeFieldNames)
	}
	return rec
}

// ---------------------------------------------------------------- NIDX

type nidxReader struct {
	ropts *ReaderOptions
}

func (r *nidxReader) Read(filenames []string, ctx *Context, handler RecordHandler) error {
	return forEachFile(filenames, r.ropts, ctx, func(in io.Reader, ctx *Context) (bool, error) {
		lr := newLineReader(in, r.ropts.IRS)
		var ifsRx *regexp.Regexp
		if r.ropts.IFSRegex != "" {
			ifsRx = getRegex(r.ropts.IFSRegex)
		}
		for {
			line, ok := lr.readLine()
			if !ok {
				break
			}
			if handleComment(line, r.ropts) {
				continue
			}
			rec := NewMlrmap()
			var fields []string
			if ifsRx != nil {
				fields = splitStringRegex(line, ifsRx)
			} else {
				fields = splitString(line, r.ropts.IFS, r.ropts.AllowRepeatIFS)
			}
			for i, field := range fields {
				rec.Put(strconv.Itoa(i+1), FromInferredString(field))
			}
			ctx.NR++
			ctx.FNR++
			if !handler(rec, ctx) {
				return false, nil
			}
		}
		return true, nil
	})
}

// ---------------------------------------------------------------- forEachFile

type fileBodyFunc func(in io.Reader, ctx *Context) (keepGoing bool, err error)

func forEachFile(filenames []string, ropts *ReaderOptions, ctx *Context, body fileBodyFunc) error {
	if len(filenames) == 0 {
		ctx.FILENAME = "(stdin)"
		ctx.FILENUM = 1
		ctx.FNR = 0
		_, err := body(os.Stdin, ctx)
		return err
	}
	for i, filename := range filenames {
		ctx.FILENAME = filename
		ctx.FILENUM = int64(i + 1)
		ctx.FNR = 0
		in, closer, err := openInput(filename, ropts)
		if err != nil {
			return fmt.Errorf("mlr: %v", err)
		}
		keepGoing, err := body(in, ctx)
		closer()
		if err != nil {
			return err
		}
		if !keepGoing {
			return nil
		}
	}
	return nil
}

// ---------------------------------------------------------------- CSV (full)

type csvReader struct {
	ropts *ReaderOptions
	lite  bool
}

type csvDataError struct{ msg string }

func (e *csvDataError) Error() string { return e.msg }

func (r *csvReader) Read(filenames []string, ctx *Context, handler RecordHandler) error {
	return forEachFile(filenames, r.ropts, ctx, func(in io.Reader, ctx *Context) (bool, error) {
		return r.readOne(in, ctx, handler)
	})
}

// csvGetRecord reads one CSV record (possibly multi-line) and returns fields.
// Returns ok=false at EOF.
func csvGetFields(lr *lineReader, ifs string, lazyQuotes bool, trimLeadingSpace bool) ([]string, bool, bool) {
	line, ok := lr.readLine()
	if !ok {
		return nil, false, false
	}
	// Fast path: no quotes
	if !strings.Contains(line, "\"") {
		if line == "" {
			return []string{""}, true, true
		}
		fields := strings.Split(line, ifs)
		if trimLeadingSpace {
			for i := range fields {
				fields[i] = strings.TrimLeft(fields[i], " ")
			}
		}
		return fields, true, false
	}
	// Slow path: handle quotes, possibly spanning lines
	var fields []string
	var sb strings.Builder
	inQuotes := false
	fieldStartedQuoted := false
	i := 0
	for {
		if i >= len(line) {
			if inQuotes {
				// field continues onto next line
				next, ok := lr.readLine()
				if !ok {
					// unterminated: take what we have
					fields = append(fields, sb.String())
					return fields, true, false
				}
				sb.WriteByte('\n')
				line = next
				i = 0
				continue
			}
			break
		}
		c := line[i]
		if inQuotes {
			if c == '"' {
				if i+1 < len(line) && line[i+1] == '"' {
					sb.WriteByte('"')
					i += 2
					continue
				}
				inQuotes = false
				i++
				continue
			}
			sb.WriteByte(c)
			i++
			continue
		}
		// not in quotes
		if strings.HasPrefix(line[i:], ifs) {
			fields = append(fields, sb.String())
			sb.Reset()
			fieldStartedQuoted = false
			i += len(ifs)
			// trim leading space
			if trimLeadingSpace {
				for i < len(line) && line[i] == ' ' {
					i++
				}
			}
			continue
		}
		if c == '"' && sb.Len() == 0 && !fieldStartedQuoted {
			inQuotes = true
			fieldStartedQuoted = true
			i++
			continue
		}
		sb.WriteByte(c)
		i++
	}
	fields = append(fields, sb.String())
	_ = lazyQuotes
	return fields, true, false
}

func (r *csvReader) readOne(in io.Reader, ctx *Context, handler RecordHandler) (bool, error) {
	lr := newLineReader(in, r.ropts.IRS)
	var header []string
	ifs := r.ropts.IFS
	rowNum := int64(0)
	for {
		fields, ok, isBlank := csvGetFields(lr, ifs, r.ropts.LazyQuotes, r.ropts.CSVTrimLeadingSpace)
		if !ok {
			break
		}
		rowNum++
		if r.ropts.CommentHandling != 0 && len(fields) > 0 && strings.HasPrefix(fields[0], r.ropts.CommentString) {
			// Comment line: re-join for pass-through
			if r.ropts.CommentHandling == 2 {
				stdoutWriter.WriteString(strings.Join(fields, ifs) + "\n")
				stdoutWriter.Flush()
			}
			rowNum--
			continue
		}
		if isBlank {
			if r.lite {
				// schema change
				header = nil
				continue
			}
			// For full CSV, a blank line is skipped if header not yet read; otherwise a data error
			if header == nil {
				continue
			}
			// data line with one empty field
		}
		if header == nil {
			if r.ropts.ImplicitHeader {
				header = make([]string, len(fields))
				for i := range fields {
					header[i] = strconv.Itoa(i + 1)
				}
			} else {
				header = fields
				// dedupe header names
				if r.ropts.DedupeFieldNames {
					header = dedupeHeader(header)
				}
				continue
			}
		}
		rec := NewMlrmap()
		if len(fields) == len(header) {
			for i, k := range header {
				rec.Put(k, FromInferredString(fields[i]))
			}
		} else if r.ropts.AllowRaggedCSV {
			if len(fields) < len(header) {
				for i := range fields {
					rec.Put(header[i], FromInferredString(fields[i]))
				}
			} else {
				for i, k := range header {
					rec.Put(k, FromInferredString(fields[i]))
				}
				for i := len(header); i < len(fields); i++ {
					rec.Put(strconv.Itoa(i+1), FromInferredString(fields[i]))
				}
			}
		} else {
			if r.lite {
				return false, &csvDataError{fmt.Sprintf("mlr: CSV header/data length mismatch %d != %d at filename %s line %d.\n", len(header), len(fields), ctx.FILENAME, rowNum)}
			}
			return false, &csvDataError{fmt.Sprintf("mlr: CSV header/data length mismatch %d != %d at filename %s row %d.\n", len(header), len(fields), ctx.FILENAME, rowNum)}
		}
		ctx.NR++
		ctx.FNR++
		if !handler(rec, ctx) {
			return false, nil
		}
	}
	return true, nil
}

func dedupeHeader(header []string) []string {
	seen := map[string]bool{}
	out := make([]string, len(header))
	for i, h := range header {
		if !seen[h] {
			out[i] = h
			seen[h] = true
			continue
		}
		for j := 2; ; j++ {
			k := h + "_" + strconv.Itoa(j)
			if !seen[k] {
				out[i] = k
				seen[k] = true
				break
			}
		}
	}
	return out
}

// ---------------------------------------------------------------- TSV

type tsvReader struct {
	ropts *ReaderOptions
	lite  bool
}

func tsvDecodeField(s string) string {
	if !strings.Contains(s, "\\") {
		return s
	}
	var sb strings.Builder
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == '\\' && i+1 < len(s) {
			switch s[i+1] {
			case 't':
				sb.WriteByte('\t')
				i++
				continue
			case 'n':
				sb.WriteByte('\n')
				i++
				continue
			case 'r':
				sb.WriteByte('\r')
				i++
				continue
			case '\\':
				sb.WriteByte('\\')
				i++
				continue
			}
		}
		sb.WriteByte(c)
	}
	return sb.String()
}

func tsvEncodeField(s string) string {
	if !strings.ContainsAny(s, "\t\n\r\\") {
		return s
	}
	var sb strings.Builder
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch c {
		case '\t':
			sb.WriteString("\\t")
		case '\n':
			sb.WriteString("\\n")
		case '\r':
			sb.WriteString("\\r")
		case '\\':
			sb.WriteString("\\\\")
		default:
			sb.WriteByte(c)
		}
	}
	return sb.String()
}

func (r *tsvReader) Read(filenames []string, ctx *Context, handler RecordHandler) error {
	return forEachFile(filenames, r.ropts, ctx, func(in io.Reader, ctx *Context) (bool, error) {
		lr := newLineReader(in, r.ropts.IRS)
		var header []string
		ifs := r.ropts.IFS
		var ifsRx *regexp.Regexp
		if r.ropts.IFSRegex != "" {
			ifsRx = getRegex(r.ropts.IFSRegex)
		}
		lineNum := int64(0)
		for {
			line, ok := lr.readLine()
			if !ok {
				break
			}
			lineNum++
			if handleComment(line, r.ropts) {
				continue
			}
			if line == "" {
				// schema change
				if r.lite || true {
					header = nil
				}
				continue
			}
			var fields []string
			if ifsRx != nil {
				fields = splitStringRegex(line, ifsRx)
			} else {
				fields = splitString(line, ifs, r.ropts.AllowRepeatIFS)
			}
			for i := range fields {
				fields[i] = tsvDecodeField(fields[i])
			}
			if header == nil {
				if r.ropts.ImplicitHeader {
					header = make([]string, len(fields))
					for i := range fields {
						header[i] = strconv.Itoa(i + 1)
					}
				} else {
					header = fields
					if r.ropts.DedupeFieldNames {
						header = dedupeHeader(header)
					}
					continue
				}
			}
			rec := NewMlrmap()
			if len(fields) == len(header) {
				for i, k := range header {
					rec.Put(k, FromInferredString(fields[i]))
				}
			} else if r.ropts.AllowRaggedCSV {
				if len(fields) < len(header) {
					for i := range fields {
						rec.Put(header[i], FromInferredString(fields[i]))
					}
				} else {
					for i, k := range header {
						rec.Put(k, FromInferredString(fields[i]))
					}
					for i := len(header); i < len(fields); i++ {
						rec.Put(strconv.Itoa(i+1), FromInferredString(fields[i]))
					}
				}
			} else {
				return false, &csvDataError{fmt.Sprintf("mlr: mlr: TSV header/data length mismatch %d != %d at filename %s line %d.\n", len(header), len(fields), ctx.FILENAME, lineNum)}
			}
			ctx.NR++
			ctx.FNR++
			if !handler(rec, ctx) {
				return false, nil
			}
		}
		return true, nil
	})
}

// ---------------------------------------------------------------- JSON

type jsonReader struct {
	ropts *ReaderOptions
}

func (r *jsonReader) Read(filenames []string, ctx *Context, handler RecordHandler) error {
	return forEachFile(filenames, r.ropts, ctx, func(in io.Reader, ctx *Context) (bool, error) {
		data, err := io.ReadAll(in)
		if err != nil {
			return false, fmt.Errorf("mlr: %v", err)
		}
		// Comment handling: strip lines starting with comment prefix
		if r.ropts.CommentHandling != 0 {
			lines := strings.Split(string(data), "\n")
			var kept []string
			for _, line := range lines {
				if strings.HasPrefix(line, r.ropts.CommentString) {
					if r.ropts.CommentHandling == 2 {
						stdoutWriter.WriteString(line + "\n")
						stdoutWriter.Flush()
					}
					continue
				}
				kept = append(kept, line)
			}
			data = []byte(strings.Join(kept, "\n"))
		}
		p := newJSONParser(data)
		for {
			if p.atEOF() {
				break
			}
			c, _ := p.peek()
			if c == '[' {
				jsonInputHadList = true
				p.pos++
				p.skipWhitespace()
				c2, ok := p.peek()
				if !ok {
					return false, &csvDataError{"mlr: JSON parser: unexpected premature EOF\n"}
				}
				if c2 == ']' {
					p.pos++
					continue
				}
				for {
					v, err := p.parseValue()
					if err != nil {
						return false, &csvDataError{err.Error() + "\n"}
					}
					if v.Type() != MT_MAP {
						return false, &csvDataError{fmt.Sprintf("mlr: valid but unmillerable JSON. Expected map (JSON object); got %s\n", jsonTypeNameForError(v))}
					}
					ctx.NR++
					ctx.FNR++
					if !handler(v.mapval, ctx) {
						return false, nil
					}
					p.skipWhitespace()
					c3, ok := p.peek()
					if !ok {
						return false, &csvDataError{"mlr: JSON parser: unexpected premature EOF\n"}
					}
					if c3 == ',' {
						p.pos++
						continue
					}
					if c3 == ']' {
						p.pos++
						break
					}
					return false, &csvDataError{fmt.Sprintf("mlr: invalid character %s after array element\n", quoteChar(c3))}
				}
				continue
			}
			v, err := p.parseValue()
			if err != nil {
				return false, &csvDataError{err.Error() + "\n"}
			}
			if v.Type() != MT_MAP {
				return false, &csvDataError{fmt.Sprintf("mlr: valid but unmillerable JSON. Expected map (JSON object); got %s\n", jsonTypeNameForError(v))}
			}
			ctx.NR++
			ctx.FNR++
			if !handler(v.mapval, ctx) {
				return false, nil
			}
		}
		return true, nil
	})
}

func jsonTypeNameForError(v *Mlrval) string {
	switch v.Type() {
	case MT_INT:
		return "int"
	case MT_FLOAT:
		return "float"
	case MT_STRING, MT_VOID:
		return "string"
	case MT_BOOLEAN:
		return "boolean"
	case MT_ARRAY:
		return "array"
	}
	return v.TypeName()
}

// ---------------------------------------------------------------- XTAB

type xtabReader struct {
	ropts *ReaderOptions
}

func (r *xtabReader) Read(filenames []string, ctx *Context, handler RecordHandler) error {
	return forEachFile(filenames, r.ropts, ctx, func(in io.Reader, ctx *Context) (bool, error) {
		lr := newLineReader(in, "\n")
		var ipsRx *regexp.Regexp
		if r.ropts.IPSRegex != "" {
			ipsRx = getRegex(r.ropts.IPSRegex)
		}
		ips := r.ropts.IPS
		rec := NewMlrmap()
		flush := func() bool {
			if rec.Len() == 0 {
				return true
			}
			ctx.NR++
			ctx.FNR++
			out := rec
			rec = NewMlrmap()
			return handler(out, ctx)
		}
		for {
			line, ok := lr.readLine()
			if !ok {
				break
			}
			if handleComment(line, r.ropts) {
				continue
			}
			if line == "" {
				if !flush() {
					return false, nil
				}
				continue
			}
			var key, value string
			if ipsRx != nil {
				loc := ipsRx.FindStringIndex(line)
				if loc != nil {
					key = line[:loc[0]]
					value = line[loc[1]:]
				} else {
					key = line
				}
			} else if ips == " " {
				idx := strings.Index(line, " ")
				if idx < 0 {
					key = line
				} else {
					key = line[:idx]
					value = strings.TrimLeft(line[idx:], " ")
				}
			} else {
				idx := strings.Index(line, ips)
				if idx < 0 {
					key = line
				} else {
					key = line[:idx]
					value = line[idx+len(ips):]
					for strings.HasPrefix(value, ips) {
						value = value[len(ips):]
					}
				}
			}
			putWithDedupe(rec, key, FromInferredString(value), r.ropts.DedupeFieldNames)
		}
		if !flush() {
			return false, nil
		}
		return true, nil
	})
}

// ---------------------------------------------------------------- PPRINT

type pprintReader struct {
	ropts *ReaderOptions
}

func (r *pprintReader) Read(filenames []string, ctx *Context, handler RecordHandler) error {
	return forEachFile(filenames, r.ropts, ctx, func(in io.Reader, ctx *Context) (bool, error) {
		lr := newLineReader(in, r.ropts.IRS)
		var header []string
		ifs := r.ropts.IFS
		lineNum := int64(0)
		for {
			line, ok := lr.readLine()
			if !ok {
				break
			}
			lineNum++
			if handleComment(line, r.ropts) {
				continue
			}
			if strings.TrimSpace(line) == "" {
				header = nil
				continue
			}
			// Barred input
			if strings.HasPrefix(line, "+") {
				continue
			}
			if strings.HasPrefix(line, "|") {
				line = strings.TrimPrefix(line, "|")
				line = strings.TrimSuffix(strings.TrimRight(line, " "), "|")
				fields := splitString(line, " ", true)
				// remove bar separators
				var clean []string
				for _, f := range fields {
					if f != "|" {
						clean = append(clean, f)
					}
				}
				fields = clean
				if header == nil {
					header = fields
					continue
				}
				if !r.pprintEmit(header, fields, ctx, handler, lineNum) {
					return false, nil
				}
				continue
			}
			fields := splitString(line, ifs, true)
			if header == nil {
				if r.ropts.ImplicitHeader {
					header = make([]string, len(fields))
					for i := range fields {
						header[i] = strconv.Itoa(i + 1)
					}
				} else {
					header = fields
					if r.ropts.DedupeFieldNames {
						header = dedupeHeader(header)
					}
					continue
				}
			}
			if len(fields) != len(header) && !r.ropts.AllowRaggedCSV {
				return false, &csvDataError{fmt.Sprintf("mlr: mlr: CSV header/data length mismatch %d != %d at filename %s line %d.\n", len(header), len(fields), ctx.FILENAME, lineNum)}
			}
			if !r.pprintEmit(header, fields, ctx, handler, lineNum) {
				return false, nil
			}
		}
		return true, nil
	})
}

func (r *pprintReader) pprintEmit(header, fields []string, ctx *Context, handler RecordHandler, lineNum int64) bool {
	rec := NewMlrmap()
	n := len(fields)
	if n > len(header) {
		n = len(header)
	}
	for i := 0; i < n; i++ {
		v := fields[i]
		if v == "-" {
			v = ""
		}
		rec.Put(header[i], FromInferredString(v))
	}
	for i := len(header); i < len(fields); i++ {
		rec.Put(strconv.Itoa(i+1), FromInferredString(fields[i]))
	}
	ctx.NR++
	ctx.FNR++
	return handler(rec, ctx)
}

// ---------------------------------------------------------------- Markdown

type markdownReader struct {
	ropts *ReaderOptions
}

func (r *markdownReader) Read(filenames []string, ctx *Context, handler RecordHandler) error {
	return forEachFile(filenames, r.ropts, ctx, func(in io.Reader, ctx *Context) (bool, error) {
		lr := newLineReader(in, r.ropts.IRS)
		var header []string
		for {
			line, ok := lr.readLine()
			if !ok {
				break
			}
			if handleComment(line, r.ropts) {
				continue
			}
			if strings.TrimSpace(line) == "" {
				header = nil
				continue
			}
			s := strings.TrimSpace(line)
			s = strings.TrimPrefix(s, "|")
			s = strings.TrimSuffix(s, "|")
			parts := strings.Split(s, "|")
			fields := make([]string, len(parts))
			for i, p := range parts {
				fields[i] = strings.TrimSpace(p)
			}
			if header == nil {
				header = fields
				continue
			}
			// separator line
			isSep := true
			for _, f := range fields {
				if strings.Trim(f, "-: ") != "" {
					isSep = false
					break
				}
			}
			if isSep {
				continue
			}
			rec := NewMlrmap()
			for i := 0; i < len(header) && i < len(fields); i++ {
				rec.Put(header[i], FromInferredString(fields[i]))
			}
			ctx.NR++
			ctx.FNR++
			if !handler(rec, ctx) {
				return false, nil
			}
		}
		return true, nil
	})
}

// ---------------------------------------------------------------- gen

type genReader struct {
	ropts *ReaderOptions
}

func (r *genReader) Read(filenames []string, ctx *Context, handler RecordHandler) error {
	ctx.FILENAME = "(stdin)"
	ctx.FILENUM = 1
	start, step, stop := r.ropts.GenStart, r.ropts.GenStep, r.ropts.GenStop
	if step == 0 {
		if start == stop {
			rec := NewMlrmap()
			rec.Put(r.ropts.GenFieldName, FromInt(start))
			ctx.NR++
			ctx.FNR++
			handler(rec, ctx)
		}
		return nil
	}
	for v := start; (step > 0 && v <= stop) || (step < 0 && v >= stop); v += step {
		rec := NewMlrmap()
		rec.Put(r.ropts.GenFieldName, FromInt(v))
		ctx.NR++
		ctx.FNR++
		if !handler(rec, ctx) {
			return nil
		}
	}
	return nil
}

// ---------------------------------------------------------------- factory

func createRecordReader(ropts *ReaderOptions) (RecordReader, error) {
	switch ropts.InputFileFormat {
	case "dkvp":
		return &dkvpReader{ropts: ropts}, nil
	case "nidx":
		return &nidxReader{ropts: ropts}, nil
	case "csv", "usv", "asv":
		return &csvReader{ropts: ropts, lite: false}, nil
	case "csvlite", "usvlite", "asvlite":
		return &csvReader{ropts: ropts, lite: true}, nil
	case "tsv":
		return &tsvReader{ropts: ropts, lite: false}, nil
	case "tsvlite":
		return &tsvReader{ropts: ropts, lite: true}, nil
	case "json", "jsonl":
		return &jsonReader{ropts: ropts}, nil
	case "xtab":
		return &xtabReader{ropts: ropts}, nil
	case "pprint":
		return &pprintReader{ropts: ropts}, nil
	case "markdown":
		return &markdownReader{ropts: ropts}, nil
	case "gen":
		return &genReader{ropts: ropts}, nil
	}
	return nil, fmt.Errorf("mlr: input file format \"%s\" not found.", ropts.InputFileFormat)
}
