package main

import (
	"bufio"
	"compress/bzip2"
	"compress/gzip"
	"compress/zlib"
	"fmt"
	"io"
	"os"
	"os/exec"
	"regexp"
	"strconv"
	"strings"
)

type Context struct {
	NR       int64
	FNR      int64
	FILENAME string
	FILENUM  int64
}

// RecordHandler is called for each record; returns false to stop reading.
type RecordHandler func(rec *Mlrmap, ctx *Context) bool

type RecordReader interface {
	// Read processes all files; ctx is updated in place.
	Read(filenames []string, ctx *Context, handler RecordHandler) error
}

var jsonInputHadList = false

// ---------------------------------------------------------------- file opening

func openInput(filename string, ropts *ReaderOptions) (io.Reader, func(), error) {
	if ropts.Prepipe != "" {
		var cmdline string
		if ropts.PrepipeIsRaw {
			cmdline = ropts.Prepipe + " " + filename
		} else {
			cmdline = ropts.Prepipe + " < '" + filename + "'"
		}
		cmd := exec.Command("/bin/sh", "-c", cmdline)
		cmd.Stderr = os.Stderr
		out, err := cmd.StdoutPipe()
		if err != nil {
			return nil, nil, err
		}
		if err := cmd.Start(); err != nil {
			return nil, nil, err
		}
		return out, func() { cmd.Wait() }, nil
	}
	var f io.Reader
	var closer func()
	if filename == "-" {
		f = os.Stdin
		closer = func() {}
	} else {
		fh, err := os.Open(filename)
		if err != nil {
			return nil, nil, err
		}
		f = fh
		closer = func() { fh.Close() }
	}
	enc := ropts.FileInputEncoding
	if enc == "" {
		if strings.HasSuffix(filename, ".gz") {
			enc = "gzip"
		} else if strings.HasSuffix(filename, ".bz2") {
			enc = "bz2"
		} else if strings.HasSuffix(filename, ".z") {
			enc = "zlib"
		}
	}
	switch enc {
	case "gzip":
		br := bufio.NewReader(f)
		// check magic
		if b, err := br.Peek(2); err == nil && b[0] == 0x1f && b[1] == 0x8b {
			gr, err := gzip.NewReader(br)
			if err != nil {
				return nil, nil, err
			}
			return gr, closer, nil
		}
		return br, closer, nil
	case "bz2":
		return bzip2.NewReader(f), closer, nil
	case "zlib":
		zr, err := zlib.NewReader(f)
		if err != nil {
			return nil, nil, err
		}
		return zr, closer, nil
	}
	// Auto-detect gzip by magic number even without suffix
	br := bufio.NewReader(f)
	if b, err := br.Peek(2); err == nil && b[0] == 0x1f && b[1] == 0x8b {
		gr, err := gzip.NewReader(br)
		if err == nil {
			return gr, closer, nil
		}
	}
	return br, closer, nil
}

// ---------------------------------------------------------------- line splitting

type lineReader struct {
	br  *bufio.Reader
	irs string
	eof bool
}

func newLineReader(r io.Reader, irs string) *lineReader {
	return &lineReader{br: bufio.NewReaderSize(r, 65536), irs: irs}
}

// readLine returns the next line without the separator. ok=false at EOF.
func (lr *lineReader) readLine() (string, bool) {
	if lr.eof {
		return "", false
	}
	if lr.irs == "\n" || lr.irs == "" {
		line, err := lr.br.ReadString('\n')
		if err != nil {
			lr.eof = true
			if line == "" {
				return "", false
			}
			return strings.TrimSuffix(line, "\r"), true
		}
		line = line[:len(line)-1]
		line = strings.TrimSuffix(line, "\r")
		return line, true
	}
	// Custom IRS: read until the separator string
	last := lr.irs[len(lr.irs)-1]
	var sb strings.Builder
	for {
		chunk, err := lr.br.ReadString(last)
		sb.WriteString(chunk)
		if err != nil {
			lr.eof = true
			s := sb.String()
			if s == "" {
				return "", false
			}
			return s, true
		}
		s := sb.String()
		if strings.HasSuffix(s, lr.irs) {
			return s[:len(s)-len(lr.irs)], true
		}
	}
}

// ---------------------------------------------------------------- comment handling

// handleComment returns true if the line was a comment and was handled.
func handleComment(line string, ropts *ReaderOptions) bool {
	if ropts.CommentHandling == 0 {
		return false
	}
	if strings.HasPrefix(line, ropts.CommentString) {
		if ropts.CommentHandling == 2 {
			stdoutWriter.WriteString(line + "\n")
			stdoutWriter.Flush()
		}
		return true
	}
	return false
}

// ---------------------------------------------------------------- field splitting

func splitString(s, sep string, repifs bool) []string {
	if s == "" {
		return []string{}
	}
	if !repifs {
		return strings.Split(s, sep)
	}
	// Repeated separators: strip leading seps, split and skip empties
	var out []string
	for len(s) > 0 && strings.HasPrefix(s, sep) {
		s = s[len(sep):]
	}
	for len(s) > 0 && strings.HasSuffix(s, sep) {
		s = s[:len(s)-len(sep)]
	}
	if s == "" {
		return []string{}
	}
	parts := strings.Split(s, sep)
	for _, p := range parts {
		if p != "" {
			out = append(out, p)
		}
	}
	return out
}

var regexCache = map[string]*regexp.Regexp{}

func getRegex(pattern string) *regexp.Regexp {
	if rx, ok := regexCache[pattern]; ok {
		return rx
	}
	rx, err := regexp.Compile(pattern)
	if err != nil {
		fmt.Fprintf(os.Stderr, "mlr: could not compile regex \"%s\"\n", pattern)
		os.Exit(1)
	}
	regexCache[pattern] = rx
	return rx
}

func splitStringRegex(s string, rx *regexp.Regexp) []string {
	if s == "" {
		return []string{}
	}
	return rx.Split(s, -1)
}

// dedupeKey handles duplicate field names: a, a_2, a_3, ...
func putWithDedupe(rec *Mlrmap, key string, value *Mlrval, dedupe bool) {
	if !dedupe || !rec.Has(key) {
		rec.Put(key, value)
		return
	}
	for i := 2; ; i++ {
		k := key + "_" + strconv.Itoa(i)
		if !rec.Has(k) {
			rec.Put(k, value)
			return
		}
	}
}

// ---------------------------------------------------------------- DKVP

type dkvpReader struct {
	ropts *ReaderOptions
}

func (r *dkvpReader) Read(filenames []string, ctx *Context, handler RecordHandler) error {
	return forEachFile(filenames, r.ropts, ctx, func(in io.Reader, ctx *Context) (bool, error) {
		lr := newLineReader(in, r.ropts.IRS)
		var ifsRx, ipsRx *regexp.Regexp
		if r.ropts.IFSRegex != "" {
			ifsRx = getRegex(r.ropts.IFSRegex)
		}
		if r.ropts.IPSRegex != "" {
			ipsRx = getRegex(r.ropts.IPSRegex)
		}
		for {
			line, ok := lr.readLine()
			if !ok {
				break
			}
			if handleComment(line, r.ropts) {
				continue
			}
			rec := recordFromDKVPLine(line, r.ropts, ifsRx, ipsRx)
			ctx.NR++
			ctx.FNR++
			if !handler(rec, ctx) {
				return false, nil
			}
		}
		return true, nil
	})
}

func recordFromDKVPLine(line string, ropts *ReaderOptions, ifsRx, ipsRx *regexp.Regexp) *Mlrmap {
	rec := NewMlrmap()
	var fields []string
	if ifsRx != nil {
		fields = splitStringRegex(line, ifsRx)
	} else {
		fields = splitString(line, ropts.IFS, ropts.AllowRepeatIFS)
	}
	keylessCounter := 0
	for i, field := range fields {
		if field == "" && ifsRx == nil && !ropts.AllowRepeatIFS {
			continue
		}
		var key, value string
		var found bool
		if ipsRx != nil {
			loc := ipsRx.FindStringIndex(field)
			if loc != nil {
				key = field[:loc[0]]
				value = field[loc[1]:]
				found = true
			}
		} else {
			idx := strings.Index(field, ropts.IPS)
			if idx >= 0 {
				key = field[:idx]
				value = field[idx+len(ropts.IPS):]
				found = true
			}
		}
		if !found {
			if ropts.IncrKey {
				keylessCounter++
				key = strconv.Itoa(keylessCounter)
			} else {
				key = strconv.Itoa(i + 1)
			}
			value = field
		}
		putWithDedupe(rec, key, FromInferredString(value), ropts.DedupeFieldNames)
	}
	return rec
}

