		if !first {
			out.WriteString(w.wopts.OFS)
		}
		first = false
		out.WriteString(e.Value.OutputString())
	}
	out.WriteString(w.wopts.ORS)
}

// ---------------------------------------------------------------- CSV

type csvWriter struct {
	wopts          *WriterOptions
	lite           bool
	justWroteEmpty bool
	headerKeys     []string
	numWritten     int64
}

func csvQuoteField(s string, ofs string, quoteAll bool) string {
	needs := quoteAll
	if !needs {
		if s == "" {
			needs = false
		} else if strings.Contains(s, ofs) || strings.Contains(s, "\"") || strings.Contains(s, "\n") || strings.Contains(s, "\r") {
			needs = true
		} else if s[0] == ' ' || s[len(s)-1] == ' ' {
			needs = false
		}
	}
	if !needs {
		return s
	}
	return "\"" + strings.ReplaceAll(s, "\"", "\"\"") + "\""
}

func (w *csvWriter) writeLine(fields []string, out *bufio.Writer) {
	for i, f := range fields {
		if i > 0 {
			out.WriteString(w.wopts.OFS)
		}
		out.WriteString(csvQuoteField(f, w.wopts.OFS, w.wopts.QuoteAll))
	}
	out.WriteString(w.wopts.ORS)
}

func (w *csvWriter) Write(rec *Mlrmap, out *bufio.Writer, isFinal bool) {
	if rec == nil {
		return
	}
	if rec.Len() == 0 {
		if !w.justWroteEmpty {
			out.WriteString(w.wopts.ORS)
		}
		w.justWroteEmpty = true
		return
	}
	keys := rec.Keys()
	if w.headerKeys == nil {
		w.headerKeys = keys
		if !w.wopts.HeaderlessOutput {
			w.writeLine(keys, out)
		}
	} else if !rec.HasSameKeyListAs(w.headerKeys) {
		if w.lite {
			// schema change: blank line and new header
			if !w.justWroteEmpty {
				out.WriteString(w.wopts.ORS)
			}
			w.headerKeys = keys
			if !w.wopts.HeaderlessOutput {
				w.writeLine(keys, out)
			}
		} else {
			// unsparsify-fill rule: allowed if one key list is a prefix of the other
			n := len(keys)
			if len(w.headerKeys) < n {
				n = len(w.headerKeys)
			}
			okPrefix := true
			for i := 0; i < n; i++ {
				if keys[i] != w.headerKeys[i] {
					okPrefix = false
					break
				}
			}
			if !okPrefix {
				fmt.Fprintf(os.Stderr, "mlr: CSV schema change: first keys \"%s\"; current keys \"%s\"\n",
					strings.Join(w.headerKeys, w.wopts.OFS), strings.Join(keys, w.wopts.OFS))
				fmt.Fprintf(os.Stderr, "mlr: exiting due to data error\n")
				out.Flush()
				os.Exit(1)
			}
			vals := make([]string, 0, len(w.headerKeys))
			for e := rec.Head; e != nil; e = e.Next {
				vals = append(vals, e.Value.OutputString())
			}
			for len(vals) < len(w.headerKeys) {
				vals = append(vals, "")
			}
			w.writeLine(vals, out)
			w.justWroteEmpty = false
			w.numWritten++
			return
		}
	}
	w.justWroteEmpty = false
	vals := make([]string, 0, rec.Len())
	for e := rec.Head; e != nil; e = e.Next {
		vals = append(vals, e.Value.OutputString())
	}
	w.writeLine(vals, out)
	w.numWritten++
}

