// ---------------------------------------------------------------- JSON

type jsonWriter struct {
	wopts      *WriterOptions
	vstack     bool
	listwrap   bool
	numWritten int64
	wroteAny   bool
}

func (w *jsonWriter) Write(rec *Mlrmap, out *bufio.Writer, isFinal bool) {
	if rec == nil {
		if w.listwrap {
			if w.numWritten > 0 {
				out.WriteString("\n]\n")
			} else if jsonInputHadList || !isFinal {
				out.WriteString("[\n]\n")
			}
		}
		return
	}
	if w.listwrap {
		if w.numWritten == 0 {
			out.WriteString("[\n")
		} else {
			out.WriteString(",\n")
		}
		out.WriteString(rec.ToJSONString(w.vstack, 0))
	} else {
		out.WriteString(rec.ToJSONString(w.vstack, 0))
		out.WriteString("\n")
	}
	w.numWritten++
}

// ---------------------------------------------------------------- XTAB

type xtabWriter struct {
	wopts      *WriterOptions
	numWritten int64
}

func (w *xtabWriter) Write(rec *Mlrmap, out *bufio.Writer, isFinal bool) {
	if rec == nil {
		return
	}
	if w.numWritten > 0 {
		out.WriteString(w.wopts.OFS)
	}
	w.numWritten++
	maxKeyLen := 0
	maxValLen := 0
	for e := rec.Head; e != nil; e = e.Next {
		kl := utf8.RuneCountInString(e.Key)
		if kl > maxKeyLen {
			maxKeyLen = kl
		}
		if w.wopts.XvRight {
			vl := utf8.RuneCountInString(e.Value.OutputString())
			if vl > maxValLen {
				maxValLen = vl
			}
		}
	}
	ops := w.wopts.OPS
	for e := rec.Head; e != nil; e = e.Next {
		out.WriteString(e.Key)
		v := e.Value.OutputString()
		if utf8.RuneCountInString(ops) == 1 {
			kl := utf8.RuneCountInString(e.Key)
			for i := kl; i < maxKeyLen; i++ {
				out.WriteString(ops)
			}
			out.WriteString(ops)
			if w.wopts.XvRight {
				vl := utf8.RuneCountInString(v)
				for i := vl; i < maxValLen; i++ {
					out.WriteString(ops)
				}
			}
		} else {
			out.WriteString(ops)
		}
		out.WriteString(v)
		out.WriteString(w.wopts.OFS)
	}
}

// ---------------------------------------------------------------- PPRINT

type pprintWriter struct {
	wopts      *WriterOptions
	batch      []*Mlrmap
	batchKeys  []string
	numBatches int
}

func (w *pprintWriter) Write(rec *Mlrmap, out *bufio.Writer, isFinal bool) {
	if rec == nil {
		w.flushBatch(out)
		return
	}
	if w.batch != nil && !rec.HasSameKeyListAs(w.batchKeys) {
		w.flushBatch(out)
	}
	if w.batch == nil {
		w.batchKeys = rec.Keys()
	}
	w.batch = append(w.batch, rec)
}

func (w *pprintWriter) flushBatch(out *bufio.Writer) {
	if w.batch == nil {
		return
	}
	if w.numBatches > 0 {
		out.WriteString(w.wopts.ORS)
	}
	w.numBatches++
	if len(w.batchKeys) == 0 {
		// empty records
		w.batch = nil
		return
	}
	if w.wopts.BarredOutput {
		w.writeBarred(out)
	} else {
		w.writePlain(out)
	}
	w.batch = nil
	w.batchKeys = nil
}

func (w *pprintWriter) cellStrings() [][]string {
	rows := make([][]string, 0, len(w.batch)+1)
	if !w.wopts.HeaderlessOutput {
		rows = append(rows, w.batchKeys)
	}
	for _, rec := range w.batch {
		row := make([]string, 0, rec.Len())
		for e := rec.Head; e != nil; e = e.Next {
			s := e.Value.OutputString()
			if s == "" && !w.wopts.BarredOutput {
				s = "-"
			}
			row = append(row, s)
		}
		rows = append(rows, row)
	}
	return rows
}

func columnWidths(rows [][]string, ncols int) []int {
	widths := make([]int, ncols)
	for _, row := range rows {
		for j, cell := range row {
			if j < ncols {
				l := utf8.RuneCountInString(cell)
				if l > widths[j] {
					widths[j] = l
				}
			}
		}
	}
	return widths
}

func (w *pprintWriter) writePlain(out *bufio.Writer) {
	rows := w.cellStrings()
	ncols := len(w.batchKeys)
	widths := columnWidths(rows, ncols)
	ofs := w.wopts.OFS
	for _, row := range rows {
		for j := 0; j < ncols; j++ {
			cell := ""
			if j < len(row) {
				cell = row[j]
			}
			l := utf8.RuneCountInString(cell)
			if w.wopts.RightAlign {
				for k := l; k < widths[j]; k++ {
					out.WriteString(ofs)
				}
				out.WriteString(cell)
				if j < ncols-1 {
					out.WriteString(ofs)
				}
			} else {
				out.WriteString(cell)
				if j < ncols-1 {
					for k := l; k < widths[j]; k++ {
						out.WriteString(ofs)
					}
					out.WriteString(ofs)
				}
			}
		}
		out.WriteString(w.wopts.ORS)
	}
}

func (w *pprintWriter) writeBarred(out *bufio.Writer) {
	rows := w.cellStrings()
	ncols := len(w.batchKeys)
	widths := columnWidths(rows, ncols)
	var sep strings.Builder
	sep.WriteString("+")
	for j := 0; j < ncols; j++ {
		sep.WriteString(strings.Repeat("-", widths[j]+2))
		sep.WriteString("+")
	}
	sepLine := sep.String()
	out.WriteString(sepLine)
	out.WriteString(w.wopts.ORS)
	for i, row := range rows {
		out.WriteString("|")
		for j := 0; j < ncols; j++ {
			cell := ""
			if j < len(row) {
				cell = row[j]
			}
			l := utf8.RuneCountInString(cell)
			out.WriteString(" ")
			if w.wopts.RightAlign {
				out.WriteString(strings.Repeat(" ", widths[j]-l))
				out.WriteString(cell)
			} else {
				out.WriteString(cell)
				out.WriteString(strings.Repeat(" ", widths[j]-l))
			}
			out.WriteString(" |")
		}
		out.WriteString(w.wopts.ORS)
		if i == 0 && !w.wopts.HeaderlessOutput {
			out.WriteString(sepLine)
			out.WriteString(w.wopts.ORS)
		}
	}
	out.WriteString(sepLine)
	out.WriteString(w.wopts.ORS)
}

// ---------------------------------------------------------------- Markdown

type markdownWriter struct {
	wopts      *WriterOptions
	headerKeys []string
	numWritten int64
}

func (w *markdownWriter) Write(rec *Mlrmap, out *bufio.Writer, isFinal bool) {
	if rec == nil {
		return
	}
	keys := rec.Keys()
	if w.headerKeys == nil || !rec.HasSameKeyListAs(w.headerKeys) {
		if w.numWritten > 0 {
			out.WriteString(w.wopts.ORS)
		}
		w.headerKeys = keys
		out.WriteString("|")
		for _, k := range keys {
			out.WriteString(" ")
			out.WriteString(k)
			out.WriteString(" |")
		}
		out.WriteString(w.wopts.ORS)
		out.WriteString("|")
		for range keys {
			out.WriteString(" --- |")
		}
		out.WriteString(w.wopts.ORS)
	}
	out.WriteString("|")
	for e := rec.Head; e != nil; e = e.Next {
		out.WriteString(" ")
		out.WriteString(strings.ReplaceAll(e.Value.OutputString(), "|", "\\|"))
		out.WriteString(" |")
	}
	out.WriteString(w.wopts.ORS)
	w.numWritten++
}
