func normalizeOfmt(f string) string {
	// Accept e.g. "%.6lf" -> "%.6f"
	f = strings.ReplaceAll(f, "lf", "f")
	f = strings.ReplaceAll(f, "le", "e")
	f = strings.ReplaceAll(f, "lg", "g")
	f = strings.ReplaceAll(f, "lld", "d")
	f = strings.ReplaceAll(f, "llx", "x")
	f = strings.ReplaceAll(f, "ld", "d")
	f = strings.ReplaceAll(f, "lx", "x")
	return f
}

func loadMlrrc(args []string) []string {
	for _, a := range args[1:] {
		if a == "--norc" {
			return nil
		}
		if !strings.HasPrefix(a, "-") {
			break
		}
	}
	env := os.Getenv("MLRRC")
	if env == "__none__" {
		return nil
	}
	var out []string
	if env != "" {
		out = append(out, loadMlrrcFile(env)...)
		return out
	}
	home := os.Getenv("HOME")
	if home != "" {
		out = append(out, loadMlrrcFile(home+"/.mlrrc")...)
	}
	out = append(out, loadMlrrcFile("./.mlrrc")...)
	return out
}

func loadMlrrcFile(path string) []string {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil
	}
	var out []string
	for _, line := range strings.Split(string(data), "\n") {
		line = strings.TrimSpace(line)
		if idx := strings.Index(line, "#"); idx >= 0 {
			line = strings.TrimSpace(line[:idx])
		}
		if line == "" {
			continue
		}
		if !strings.HasPrefix(line, "-") {
			line = "--" + line
		}
		parts := strings.SplitN(line, " ", 2)
		out = append(out, parts[0])
		if len(parts) > 1 {
			out = append(out, strings.TrimSpace(parts[1]))
		}
	}
	return out
}

// ---------------------------------------------------------------- streaming

type recordSink func(rec *Mlrmap, ctx *Context)

func runStream(opts *Options, chain []Verb) int {
	writer, err := createRecordWriter(&opts.Writer)
	if err != nil {
		fmt.Fprintf(os.Stderr, "%s\n", err.Error())
		return 1
	}
	reader, err := createRecordReader(&opts.Reader)
	if err != nil {
		fmt.Fprintf(os.Stderr, "%s\n", err.Error())
		return 1
	}

	out := stdoutWriter
	ctx := &Context{FILENAME: "(stdin)", FILENUM: 0}

	// Build the chain of sinks
	finalSink := func(rec *Mlrmap, c *Context) {
		writeRecordToWriter(rec, writer, out, &opts.Writer, false)
		if opts.Writer.FFlush {
			out.Flush()
		}
	}
	sinks := make([]recordSink, len(chain)+1)
	sinks[len(chain)] = finalSink
	for i := len(chain) - 1; i >= 0; i-- {
		verb := chain[i]
		next := sinks[i+1]
		sinks[i] = func(rec *Mlrmap, c *Context) {
			verb.Process(rec, c, next)
		}
	}

	rc := 0
	if !opts.NoInput {
		err = reader.Read(opts.FileNames, ctx, func(rec *Mlrmap, c *Context) bool {
			sinks[0](rec, c)
			if opts.NRProgressMod > 0 && c.NR%opts.NRProgressMod == 0 {
				fmt.Fprintf(os.Stderr, "NR=%d FNR=%d FILENAME=%s\n", c.NR, c.FNR, c.FILENAME)
			}
			return !chainIsDone(chain)
		})
		if err != nil {
			out.Flush()
			msg := err.Error()
			if !strings.HasSuffix(msg, "\n") {
				msg += "\n"
			}
			fmt.Fprint(os.Stderr, msg)
			rc = 1
			if _, ok := err.(*csvDataError); !ok {
				return rc
			}
			return rc
		}
	}
	// End of stream: finish each verb in order
	for i, verb := range chain {
		verb.Finish(ctx, sinks[i+1])
	}
	writer.Write(nil, out, true)
	out.Flush()
	closeAllRedirects()
	return rc
}

func chainIsDone(chain []Verb) bool {
	for _, v := range chain {
		if d, ok := v.(interface{ IsDone() bool }); ok {
			if d.IsDone() {
				return true
			}
		} else {
			return false
		}
	}
	return false
}

// writeRecordToWriter applies auto-flatten/unflatten then writes.
func writeRecordToWriter(rec *Mlrmap, writer RecordWriter, out interface{ WriteString(string) (int, error) }, wopts *WriterOptions, isFinal bool) {
	bw, _ := out.(*bufioWriter)
	_ = bw
	prepared := prepareRecordForOutput(rec, wopts)
	if w, ok := out.(interface {
		WriteString(string) (int, error)
		Flush() error
	}); ok {
		_ = w
	}
	writer.Write(prepared, outAsBufio(out), isFinal)
}

func prepareRecordForOutput(rec *Mlrmap, wopts *WriterOptions) *Mlrmap {
	if wopts.FailOnDataError {
		for e := rec.Head; e != nil; e = e.Next {
			if e.Value.Type() == MT_ERROR {
				msg := "(error)"
				if e.Value.err != nil {
					msg = e.Value.err.Error()
				}
				fmt.Fprintf(os.Stderr, "mlr: data error at NR=%d FNR=%d FILENAME=%s\n", 0, 0, "")
				fmt.Fprintf(os.Stderr, "mlr: field %s: %s\n", e.Key, msg)
				stdoutWriter.Flush()
				os.Exit(1)
			}
		}
	}
	isJSON := wopts.OutputFileFormat == "json" || wopts.OutputFileFormat == "jsonl"
	if isJSON {
		if wopts.AutoUnflatten && mainOptions != nil && !(mainOptions.Reader.InputFileFormat == "json" || mainOptions.Reader.InputFileFormat == "jsonl") {
