// flattenRecord flattens map/array-valued fields into key.subkey entries.
func flattenRecord(rec *Mlrmap, sep string) *Mlrmap {
	needs := false
	for e := rec.Head; e != nil; e = e.Next {
		if e.Value.IsCollection() {
			needs = true
			break
		}
	}
	if !needs {
		return rec
	}
	out := NewMlrmap()
	for e := rec.Head; e != nil; e = e.Next {
