	switch v.Type() {
	case MT_MAP:
		if v.mapval.Len() == 0 {
			out.Put(prefix, FromString("{}"))
			return
		}
		for e := v.mapval.Head; e != nil; e = e.Next {
			flattenInto(out, prefix+sep+e.Key, e.Value, sep)
		}
	case MT_ARRAY:
		if len(v.arrayval) == 0 {
			out.Put(prefix, FromString("[]"))
			return
		}
		for i, e := range v.arrayval {
			flattenInto(out, prefix+sep+fmt.Sprintf("%d", i+1), e, sep)
		}
