// unflattenRecord: keys containing sep become nested maps; "{}"/"[]" strings become empty collections.
func unflattenRecord(rec *Mlrmap, sep string) *Mlrmap {
	needs := false
	for e := rec.Head; e != nil; e = e.Next {
		if strings.Contains(e.Key, sep) {
			needs = true
			break
		}
		if e.Value.mvtype != MT_MAP && e.Value.mvtype != MT_ARRAY {
			s := e.Value.printrep
			if e.Value.printrepValid && (s == "{}" || s == "[]") {
				needs = true
				break
			}
		}
	}
	if !needs {
		return rec
	}
	out := NewMlrmap()
	for e := rec.Head; e != nil; e = e.Next {
		v := e.Value
		if v.printrepValid && v.mvtype != MT_MAP && v.mvtype != MT_ARRAY {
			if v.printrep == "{}" {
				v = FromEmptyMap()
			} else if v.printrep == "[]" {
				v = FromArray([]*Mlrval{})
			}
		}
		if !strings.Contains(e.Key, sep) {
			out.Put(e.Key, v)
			continue
		}
		parts := strings.Split(e.Key, sep)
		putIndexedAuto(out, parts, v)
	}
	// convert maps with keys 1..n to arrays
	for e := out.Head; e != nil; e = e.Next {
		e.Value = arrayifyValue(e.Value)
	}
	return out
