func putIndexedAuto(m *Mlrmap, parts []string, v *Mlrval) {
	cur := m
	for i, p := range parts {
		if i == len(parts)-1 {
			cur.Put(p, v)
			return
		}
		next := cur.Get(p)
		if next == nil || next.Type() != MT_MAP {
			nm := FromEmptyMap()
			cur.Put(p, nm)
			next = nm
		}
		cur = next.mapval
	}
}

// arrayifyValue converts maps with consecutive int keys "1".."n" into arrays, recursively.
func arrayifyValue(v *Mlrval) *Mlrval {
	switch v.Type() {
	case MT_MAP:
		m := v.mapval
		for e := m.Head; e != nil; e = e.Next {
			e.Value = arrayifyValue(e.Value)
		}
		if m.Len() == 0 {
			return v
		}
		i := 1
		for e := m.Head; e != nil; e = e.Next {
			if e.Key != fmt.Sprintf("%d", i) {
				return v
			}
			i++
		}
		arr := make([]*Mlrval, 0, m.Len())
		for e := m.Head; e != nil; e = e.Next {
			arr = append(arr, e.Value)
		}
		return FromArray(arr)
	case MT_ARRAY:
		for i, e := range v.arrayval {
			v.arrayval[i] = arrayifyValue(e)
		}
		return v
	}
	return v
}

// ---------------------------------------------------------------- in-place mode

func runInPlace(opts *Options, args []string) int {
	fileNames := opts.FileNames
	if len(fileNames) == 0 {
		fmt.Fprintf(os.Stderr, "mlr: -I option (in-place operation) requires input files.\n")
		return 1
