		cmdArgs := append([]string{}, baseArgs...)
		cmdArgs = append(cmdArgs, fn)
		rc := runSubprocessToFile(os.Args[0], cmdArgs, f)
		f.Close()
		if rc != 0 {
			os.Remove(tmp)
			return rc
		}
		os.Rename(tmp, fn)
	}
	return 0
}
