package main

import (
	"fmt"
	"os"
	"strings"
)

const mlrVersion = "6.16.0"

var mainOptions *Options

func main() {
	args := os.Args
	exitCode := mainEntry(args)
	stdoutWriter.Flush()
	os.Exit(exitCode)
}

func mainEntry(args []string) int {
	if len(args) >= 2 {
		switch args[1] {
		case "--version":
			fmt.Fprintf(stdoutWriter, "mlr %s\n", mlrVersion)
			return 0
		case "version":
			fmt.Fprintf(stdoutWriter, "mlr version %s for linux/amd64/go1.24.0\n", mlrVersion)
			return 0
		case "help":
			return helpMain(args[2:])
		case "regtest", "repl":
			fmt.Fprintf(os.Stderr, "mlr: %s is not supported in this build.\n", args[1])
			return 1
		case "lecat", "termcvt", "hex", "unhex", "aux-list":
			return auxMain(args[1:])
		}
	}

	opts := defaultOptions()
	mainOptions = opts

	// .mlrrc handling
	rcArgs := loadMlrrc(args)
	allArgs := append([]string{args[0]}, rcArgs...)
	allArgs = append(allArgs, args[1:]...)
	args = allArgs

	argi := 1
	for argi < len(args) {
		arg := args[argi]
		if !strings.HasPrefix(arg, "-") {
			break
		}
		if arg == "--" {
			argi++
			break
		}
		if arg == "-h" || arg == "--help" {
			fmt.Fprint(stdoutWriter, mainUsageShort())
			return 0
		}
		if arg == "-l" {
			return helpMain([]string{"list-verbs"})
		}
		if arg == "-L" {
			return helpMain([]string{"usage-verbs"})
		}
		if arg == "-f" {
			return helpMain([]string{"list-functions"})
		}
		if arg == "-F" {
			return helpMain([]string{"usage-functions"})
		}
		if arg == "-k" {
			return helpMain([]string{"list-keywords"})
		}
		if arg == "-K" {
			return helpMain([]string{"usage-keywords"})
		}
		if arg == "-g" {
			return helpMain([]string{"flags"})
		}
		if arg == "--norc" {
			argi++
			continue
		}
		if !parseMainFlag(args, &argi, opts) {
			fmt.Fprintf(os.Stderr, "mlr: option \"%s\" not recognized.\n", arg)
			fmt.Fprintf(os.Stderr, "Please run \"mlr --help\" for usage information.\n")
			return 1
		}
	}
	if argi >= len(args) {
		fmt.Fprintf(os.Stderr, "mlr: no verb supplied.\n")
		fmt.Fprint(os.Stderr, mainUsageShort())
		return 1
	}
	opts.finalize()
	ofmt = opts.OFMT
	if ofmt != "" {
		ofmt = normalizeOfmt(ofmt)
	}
	jvQuoteAll = opts.Writer.JVQuoteAll
	if opts.HaveRandSeed {
		seedRandom(opts.RandSeed)
	}

	// Parse the verb chain
	chain, err := parseVerbChain(args, &argi, opts)
	if err != nil {
		fmt.Fprint(os.Stderr, err.Error())
		return 1
	}
	// Remaining args are filenames
	for argi < len(args) {
		opts.FileNames = append(opts.FileNames, args[argi])
		argi++
	}

	if opts.DoInPlace {
		return runInPlace(opts, args)
	}
	return runStream(opts, chain)
}

func normalizeOfmt(f string) string {
	// Accept e.g. "%.6lf" -> "%.6f"
	f = strings.ReplaceAll(f, "lf", "f")
	f = strings.ReplaceAll(f, "le", "e")
	f = strings.ReplaceAll(f, "lg", "g")
	f = strings.ReplaceAll(f, "lld", "d")
	f = strings.ReplaceAll(f, "llx", "x")
	f = strings.ReplaceAll(f, "ld", "d")
	f = strings.ReplaceAll(f, "lx", "x")
	return f
}

func loadMlrrc(args []string) []string {
	for _, a := range args[1:] {
		if a == "--norc" {
			return nil
		}
		if !strings.HasPrefix(a, "-") {
			break
		}
	}
	env := os.Getenv("MLRRC")
	if env == "__none__" {
		return nil
	}
	var out []string
	if env != "" {
		out = append(out, loadMlrrcFile(env)...)
		return out
	}
	home := os.Getenv("HOME")
	if home != "" {
		out = append(out, loadMlrrcFile(home+"/.mlrrc")...)
	}
	out = append(out, loadMlrrcFile("./.mlrrc")...)
	return out
}

func loadMlrrcFile(path string) []string {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil
	}
	var out []string
	for _, line := range strings.Split(string(data), "\n") {
		line = strings.TrimSpace(line)
		if idx := strings.Index(line, "#"); idx >= 0 {
			line = strings.TrimSpace(line[:idx])
		}
		if line == "" {
			continue
		}
		if !strings.HasPrefix(line, "-") {
			line = "--" + line
		}
		parts := strings.SplitN(line, " ", 2)
		out = append(out, parts[0])
		if len(parts) > 1 {
			out = append(out, strings.TrimSpace(parts[1]))
		}
	}
	return out
}

// ---------------------------------------------------------------- streaming

type recordSink func(rec *Mlrmap, ctx *Context)

func runStream(opts *Options, chain []Verb) int {
	writer, err := createRecordWriter(&opts.Writer)
	if err != nil {
		fmt.Fprintf(os.Stderr, "%s\n", err.Error())
		return 1
	}
	reader, err := createRecordReader(&opts.Reader)
	if err != nil {
		fmt.Fprintf(os.Stderr, "%s\n", err.Error())
		return 1
	}

	out := stdoutWriter
	ctx := &Context{FILENAME: "(stdin)", FILENUM: 0}

	// Build the chain of sinks
	finalSink := func(rec *Mlrmap, c *Context) {
		writeRecordToWriter(rec, writer, out, &opts.Writer, false)
		if opts.Writer.FFlush {
			out.Flush()
		}
	}
	sinks := make([]recordSink, len(chain)+1)
	sinks[len(chain)] = finalSink
	for i := len(chain) - 1; i >= 0; i-- {
		verb := chain[i]
		next := sinks[i+1]
		sinks[i] = func(rec *Mlrmap, c *Context) {
			verb.Process(rec, c, next)
		}
	}

	rc := 0
	if !opts.NoInput {
		err = reader.Read(opts.FileNames, ctx, func(rec *Mlrmap, c *Context) bool {
			sinks[0](rec, c)
			if opts.NRProgressMod > 0 && c.NR%opts.NRProgressMod == 0 {
				fmt.Fprintf(os.Stderr, "NR=%d FNR=%d FILENAME=%s\n", c.NR, c.FNR, c.FILENAME)
			}
			return !chainIsDone(chain)
		})
		if err != nil {
			out.Flush()
			msg := err.Error()
			if !strings.HasSuffix(msg, "\n") {
				msg += "\n"
			}
			fmt.Fprint(os.Stderr, msg)
			rc = 1
			if _, ok := err.(*csvDataError); !ok {
				return rc
			}
			return rc
		}
	}
	// End of stream: finish each verb in order
	for i, verb := range chain {
		verb.Finish(ctx, sinks[i+1])
	}
	writer.Write(nil, out, true)
	out.Flush()
	closeAllRedirects()
	return rc
}

func chainIsDone(chain []Verb) bool {
	for _, v := range chain {
		if d, ok := v.(interface{ IsDone() bool }); ok {
			if d.IsDone() {
				return true
			}
		} else {
			return false
		}
	}
	return false
}

