//go:embed helpdata
var helpFS embed.FS

type Verb interface {
	Process(rec *Mlrmap, ctx *Context, out recordSink)
	Finish(ctx *Context, out recordSink)
}

type verbParser func(args []string, argi *int, opts *Options) (Verb, error)

type verbEntry struct {
	name   string
	parser verbParser
}

var verbTable []verbEntry
var verbTableIndex map[string]verbParser

func registerVerb(name string, p verbParser) {
	verbTable = append(verbTable, verbEntry{name, p})
	if verbTableIndex == nil {
		verbTableIndex = map[string]verbParser{}
	}
	verbTableIndex[name] = p
}

func lookupVerb(name string) verbParser {
	return verbTableIndex[name]
}

func verbUsage(name string) string {
	data, err := helpFS.ReadFile("helpdata/verbs/" + name + ".txt")
	if err != nil {
		return "Usage: mlr " + name + "\n"
	}
	return string(data)
}

func verbNames() []string {
	names := make([]string, 0, len(verbTable))
	for _, e := range verbTable {
		names = append(names, e.name)
	}
	return names
}

// parseVerbChain parses "verb args... then verb args..." starting at args[*argi].
func parseVerbChain(args []string, argi *int, opts *Options) ([]Verb, error) {
	var chain []Verb
	for {
		if *argi >= len(args) {
			return nil, fmt.Errorf("mlr: no verb supplied.\n%s", mainUsageShort())
		}
		name := args[*argi]
		p := lookupVerb(name)
		if p == nil {
			return nil, fmt.Errorf("mlr: verb \"%s\" not found. Please use \"mlr -l\" for a list.\n", name)
		}
		verb, err := p(args, argi, opts)
		if err != nil {
			return nil, err
		}
		chain = append(chain, verb)
		if *argi < len(args) && args[*argi] == "then" {
			*argi++
			if *argi >= len(args) {
				return nil, fmt.Errorf("mlr: missing verb after \"then\".\n")
			}
			continue
		}
		break
	}
	return chain, nil
