		stdoutWriter.Flush()
	} else {
		fmt.Fprint(os.Stderr, verbUsage(name))
	}
	os.Exit(code)
}

// isHelpFlag
func isHelpFlag(s string) bool {
	return s == "-h" || s == "--help"
}

// ---------------------------------------------------------------- group-by helpers

// groupingKey returns the joined group-by values, ok=false if any missing.
func groupingKey(rec *Mlrmap, fields []string) (string, bool) {
	return rec.GetSelectedValuesJoined(fields)
}

// ordered map of string -> interface{} for group-by accumulators
type orderedMap struct {
	keys []string
	vals map[string]interface{}
}

func newOrderedMap() *orderedMap {
	return &orderedMap{vals: map[string]interface{}{}}
}

func (om *orderedMap) Get(k string) (interface{}, bool) {
	v, ok := om.vals[k]
	return v, ok
}

func (om *orderedMap) Put(k string, v interface{}) {
	if _, ok := om.vals[k]; !ok {
		om.keys = append(om.keys, k)
	}
	om.vals[k] = v
}

func (om *orderedMap) Has(k string) bool {
	_, ok := om.vals[k]
	return ok
}

func (om *orderedMap) Len() int { return len(om.keys) }

func (om *orderedMap) Delete(k string) {
	if _, ok := om.vals[k]; !ok {
		return
	}
	delete(om.vals, k)
	for i, kk := range om.keys {
