// optParser is a small helper for verb flag parsing.
type optParser struct {
	name string
	args []string
	argi *int
}

func newOptParser(name string, args []string, argi *int) *optParser {
	*argi++ // skip verb name
	return &optParser{name: name, args: args, argi: argi}
}

// next returns the next flag (starting with '-') or "" if none.
func (p *optParser) next() string {
	if *p.argi >= len(p.args) {
		return ""
	}
	a := p.args[*p.argi]
	if !strings.HasPrefix(a, "-") || a == "-" {
		return ""
	}
	// Negative numbers are not flags
	if len(a) > 1 && (a[1] >= '0' && a[1] <= '9') {
		return ""
	}
	if isHelpFlag(a) {
		verbPrintUsageAndExit(p.name, 0)
	}
	return a
}

func (p *optParser) advance() { *p.argi++ }

func (p *optParser) str() string         { return verbGetStringArg(p.name, p.args, p.argi) }
func (p *optParser) int() int64          { return verbGetIntArg(p.name, p.args, p.argi) }
func (p *optParser) float() float64      { return verbGetFloatArg(p.name, p.args, p.argi) }
func (p *optParser) list() []string      { return verbGetStringListArg(p.name, p.args, p.argi) }
func (p *optParser) unknown(flag string) { optionNotRecognized(p.name, flag) }

func (p *optParser) positional() (string, bool) {
	if *p.argi >= len(p.args) {
		return "", false
	}
	a := p.args[*p.argi]
	*p.argi++
	return a, true
}

// ---------------------------------------------------------------- cat

type catVerb struct {
	doNumbers bool
	counterName string
	groupBy   []string
	doFilename bool
	doFilenum  bool
	counter   int64
	counters  map[string]int64
}

func parseCat(args []string, argi *int, opts *Options) (Verb, error) {
	v := &catVerb{counters: map[string]int64{}}
	p := newOptParser("cat", args, argi)
	for {
		f := p.next()
		if f == "" {
			break
		}
		switch f {
		case "-n":
			v.doNumbers = true
			v.counterName = "n"
			p.advance()
		case "-N":
			v.doNumbers = true
			v.counterName = p.str()
		case "-g":
			v.groupBy = p.list()
		case "--filename":
			v.doFilename = true
			p.advance()
		case "--filenum":
			v.doFilenum = true
			p.advance()
		default:
			p.unknown(f)
		}
	}
	return v, nil
}

func (v *catVerb) Process(rec *Mlrmap, ctx *Context, out recordSink) {
	if v.doNumbers {
		if v.groupBy == nil {
			v.counter++
			rec.PutAtStart(v.counterName, FromInt(v.counter))
		} else {
			key, ok := groupingKey(rec, v.groupBy)
			if !ok {
				return
			}
			v.counters[key]++
			rec.PutAtStart(v.counterName, FromInt(v.counters[key]))
		}
	} else if v.groupBy != nil {
		if _, ok := groupingKey(rec, v.groupBy); !ok {
			return
		}
	}
	if v.doFilenum {
		rec.PutAtStart("filenum", FromInt(ctx.FILENUM))
	}
	if v.doFilename {
		rec.PutAtStart("filename", FromString(ctx.FILENAME))
	}
	out(rec, ctx)
}

func (v *catVerb) Finish(ctx *Context, out recordSink) {}

// ---------------------------------------------------------------- nothing

