	reverse bool
}

func parseSortWithinRecords(args []string, argi *int, opts *Options) (Verb, error) {
	v := &sortWithinRecordsVerb{}
	p := newOptParser("sort-within-records", args, argi)
	for {
		f := p.next()
		if f == "" {
			break
		}
		switch f {
		case "-r":
			v.reverse = true
			p.advance()
		default:
			p.unknown(f)
		}
	}
	return v, nil
}

func (v *sortWithinRecordsVerb) Process(rec *Mlrmap, ctx *Context, out recordSink) {
	keys := rec.Keys()
	sortStrings(keys)
	if v.reverse {
		for i, j := 0, len(keys)-1; i < j; i, j = i+1, j-1 {
			keys[i], keys[j] = keys[j], keys[i]
		}
	}
	newrec := NewMlrmap()
	for _, k := range keys {
		newrec.Put(k, rec.Get(k))
	}
	out(newrec, ctx)
}
func (v *sortWithinRecordsVerb) Finish(ctx *Context, out recordSink) {}

type sortWithinRecordsValuesVerb struct {
	reverse bool
}

func parseSortWithinRecordsValues(args []string, argi *int, opts *Options) (Verb, error) {
	v := &sortWithinRecordsValuesVerb{}
	p := newOptParser("sort-within-records-values", args, argi)
	for {
		f := p.next()
		if f == "" {
			break
		}
		switch f {
		case "-r":
			v.reverse = true
			p.advance()
		default:
			p.unknown(f)
		}
	}
	return v, nil
}

func (v *sortWithinRecordsValuesVerb) Process(rec *Mlrmap, ctx *Context, out recordSink) {
	var entries []*MlrmapEntry
	for e := rec.Head; e != nil; e = e.Next {
		entries = append(entries, e)
	}
	sortSliceStable(len(entries), func(i, j int) bool {
		c := collatedCompare(entries[i].Value, entries[j].Value)
		if v.reverse {
			return c > 0
		}
		return c < 0
	}, func(i, j int) { entries[i], entries[j] = entries[j], entries[i] })
	newrec := NewMlrmap()
	for _, e := range entries {
		newrec.Put(e.Key, e.Value)
	}
	out(newrec, ctx)
}
func (v *sortWithinRecordsValuesVerb) Finish(ctx *Context, out recordSink) {}

