func (v *groupByVerb) Process(rec *Mlrmap, ctx *Context, out recordSink) {
	key, ok := groupingKey(rec, v.fields)
	if !ok {
		return
	}
	gi, ok := v.groups.Get(key)
	var g *recGroup
	if !ok {
		g = &recGroup{}
		v.groups.Put(key, g)
	} else {
		g = gi.(*recGroup)
	}
	g.recs = append(g.recs, rec)
	g.ctxs = append(g.ctxs, *ctx)
}

func (v *groupByVerb) Finish(ctx *Context, out recordSink) {
	for _, k := range v.groups.keys {
		g := v.groups.vals[k].(*recGroup)
		for i, rec := range g.recs {
			c := g.ctxs[i]
			out(rec, &c)
		}
	}
}

