type decimateVerb struct {
	n       int64
	atStart bool
	groupBy []string
	counts  map[string]int64
}

func parseDecimate(args []string, argi *int, opts *Options) (Verb, error) {
	v := &decimateVerb{n: 10, counts: map[string]int64{}}
	p := newOptParser("decimate", args, argi)
	for {
		f := p.next()
		if f == "" {
			break
		}
		switch f {
		case "-n":
			v.n = p.int()
		case "-b":
			v.atStart = true
			p.advance()
		case "-e":
			v.atStart = false
			p.advance()
		case "-g":
			v.groupBy = p.list()
		default:
			p.unknown(f)
		}
	}
	return v, nil
}

func (v *decimateVerb) Process(rec *Mlrmap, ctx *Context, out recordSink) {
	key, ok := groupingKey(rec, v.groupBy)
	if !ok {
		return
	}
	v.counts[key]++
	c := v.counts[key]
	if v.atStart {
		if c%v.n == 1 || v.n == 1 {
			out(rec, ctx)
		}
	} else {
		if c%v.n == 0 {
			out(rec, ctx)
		}
	}
	if c >= v.n {
		v.counts[key] = 0
	}
}
func (v *decimateVerb) Finish(ctx *Context, out recordSink) {}

// ---------------------------------------------------------------- fill-down

type fillDownVerb struct {
	fields       []string
	all          bool
	onlyIfBlank  bool
	onlyIfAbsent bool
	last         map[string]*Mlrval
}

func parseFillDown(args []string, argi *int, opts *Options) (Verb, error) {
	v := &fillDownVerb{last: map[string]*Mlrval{}}
	p := newOptParser("fill-down", args, argi)
	for {
		f := p.next()
		if f == "" {
			break
		}
		switch f {
		case "-f":
			v.fields = p.list()
		case "--all", "-a":
			if f == "--all" {
				v.all = true
			} else {
				v.onlyIfAbsent = true
			}
			p.advance()
		case "--only-if-absent":
			v.onlyIfAbsent = true
			p.advance()
		case "--only-if-blank":
			v.onlyIfBlank = true
			p.advance()
		default:
			p.unknown(f)
		}
	}
	if v.fields == nil && !v.all {
		fmt.Fprintf(os.Stderr, "mlr fill-down: no field names given.\n")
		fmt.Fprint(os.Stderr, verbUsage("fill-down"))
		os.Exit(1)
	}
	return v, nil
}

func (v *fillDownVerb) Process(rec *Mlrmap, ctx *Context, out recordSink) {
	fields := v.fields
	if v.all {
		fields = rec.Keys()
	}
	for _, f := range fields {
		val := rec.Get(f)
		present := val != nil
		if v.onlyIfAbsent {
			if present {
				v.last[f] = val
			} else if prev, ok := v.last[f]; ok {
				rec.Put(f, prev)
			}
		} else if v.onlyIfBlank {
			if present && val.IsVoid() {
				if prev, ok := v.last[f]; ok {
					rec.Put(f, prev)
				}
			} else if present {
				v.last[f] = val
			}
		} else {
			if !present || val.IsVoid() {
				if prev, ok := v.last[f]; ok {
					rec.Put(f, prev)
				}
			} else {
				v.last[f] = val
			}
		}
	}
	out(rec, ctx)
}
func (v *fillDownVerb) Finish(ctx *Context, out recordSink) {}

