	m := v.n
	if m < 0 {
		m = n
	}
	for i := int64(0); i < m; i++ {
		idx := randIntn(int(n))
		c := v.ctxs[idx]
		out(v.recs[idx].Copy(), &c)
	}
}

type sampleVerb struct {
	k       int64
	groupBy []string
	groups  *orderedMap
}

type sampleGroup struct {
	count int64
	recs  []*Mlrmap
	ctxs  []Context
}

func parseSample(args []string, argi *int, opts *Options) (Verb, error) {
	v := &sampleVerb{k: 1, groups: newOrderedMap()}
	p := newOptParser("sample", args, argi)
	for {
		f := p.next()
		if f == "" {
			break
		}
		switch f {
		case "-k":
			v.k = p.int()
		case "-g":
			v.groupBy = p.list()
		default:
			p.unknown(f)
		}
	}
	return v, nil
}

func (v *sampleVerb) Process(rec *Mlrmap, ctx *Context, out recordSink) {
	key, ok := groupingKey(rec, v.groupBy)
	if !ok {
		return
	}
	gi, ok := v.groups.Get(key)
	var g *sampleGroup
	if !ok {
		g = &sampleGroup{}
		v.groups.Put(key, g)
	} else {
		g = gi.(*sampleGroup)
	}
	g.count++
	if int64(len(g.recs)) < v.k {
		g.recs = append(g.recs, rec)
		g.ctxs = append(g.ctxs, *ctx)
	} else {
		r := randInt63n(g.count)
		if r < v.k {
			g.recs[r] = rec
			g.ctxs[r] = *ctx
		}
	}
}

func (v *sampleVerb) Finish(ctx *Context, out recordSink) {
	for _, k := range v.groups.keys {
		g := v.groups.vals[k].(*sampleGroup)
		for i, rec := range g.recs {
			c := g.ctxs[i]
			out(rec, &c)
		}
	}
}

