		case "--jvstack":
			v.multiline = true
			p.advance()
		case "--no-jvstack":
			v.multiline = false
			p.advance()
		default:
			p.unknown(f)
		}
	}
	return v, nil
}

func (v *jsonStringifyVerb) stringifyOne(val *Mlrval) *Mlrval {
