// ---------------------------------------------------------------- flatten / unflatten verbs

type flattenVerb struct {
	fields []string
	sep    string
}

func parseFlattenVerb(args []string, argi *int, opts *Options) (Verb, error) {
	v := &flattenVerb{sep: opts.Writer.FlatSep}
	p := newOptParser("flatten", args, argi)
	for {
		f := p.next()
		if f == "" {
			break
		}
		switch f {
		case "-f":
			v.fields = p.list()
		case "-s":
			v.sep = p.str()
		default:
			p.unknown(f)
		}
	}
	return v, nil
}

func (v *flattenVerb) Process(rec *Mlrmap, ctx *Context, out recordSink) {
	if v.fields == nil {
		out(flattenRecord(rec, v.sep), ctx)
		return
	}
	newrec := NewMlrmap()
	set := map[string]bool{}
	for _, f := range v.fields {
		set[f] = true
	}
	for e := rec.Head; e != nil; e = e.Next {
		if set[e.Key] && e.Value.IsCollection() {
			flattenInto(newrec, e.Key, e.Value, v.sep)
		} else {
			newrec.Put(e.Key, e.Value)
		}
	}
	out(newrec, ctx)
}
func (v *flattenVerb) Finish(ctx *Context, out recordSink) {}

type unflattenVerb struct {
	fields []string
	sep    string
}

func parseUnflattenVerb(args []string, argi *int, opts *Options) (Verb, error) {
	v := &unflattenVerb{sep: opts.Writer.FlatSep}
	p := newOptParser("unflatten", args, argi)
	for {
