		if f == "" {
			break
		}
		switch f {
		case "-f":
			v.fields = p.list()
		case "-s":
			v.sep = p.str()
		default:
			p.unknown(f)
		}
	}
	return v, nil
}

func (v *unflattenVerb) Process(rec *Mlrmap, ctx *Context, out recordSink) {
	if v.fields == nil {
		out(unflattenRecord(rec, v.sep), ctx)
		return
	}
	set := map[string]bool{}
	for _, f := range v.fields {
		set[f] = true
	}
	newrec := NewMlrmap()
	for e := rec.Head; e != nil; e = e.Next {
		if strings.Contains(e.Key, v.sep) {
			parts := strings.Split(e.Key, v.sep)
			if set[parts[0]] {
				putIndexedAuto(newrec, parts, e.Value)
				continue
			}
		}
		newrec.Put(e.Key, e.Value)
	}
	for e := newrec.Head; e != nil; e = e.Next {
		if set[e.Key] {
			e.Value = arrayifyValue(e.Value)
		}
	}
	out(newrec, ctx)
}
func (v *unflattenVerb) Finish(ctx *Context, out recordSink) {}

