	return &latin1Verb{toUtf8: true}, nil
}

func parseUtf8ToLatin1(args []string, argi *int, opts *Options) (Verb, error) {
	p := newOptParser("utf8-to-latin1", args, argi)
	for {
		f := p.next()
		if f == "" {
			break
		}
		p.unknown(f)
	}
	return &latin1Verb{toUtf8: false}, nil
}

func (v *latin1Verb) Process(rec *Mlrmap, ctx *Context, out recordSink) {
	newrec := NewMlrmap()
	for e := rec.Head; e != nil; e = e.Next {
		var k string
		var val *Mlrval
		if v.toUtf8 {
			k = latin1ToUtf8(e.Key)
			val = bifLatin1ToUtf8(e.Value)
		} else {
			k = utf8ToLatin1(e.Key)
			val = bifUtf8ToLatin1(e.Value)
		}
		newrec.Put(k, val)
	}
	out(newrec, ctx)
}
func (v *latin1Verb) Finish(ctx *Context, out recordSink) {}

// ---------------------------------------------------------------- tee verb

type teeVerb struct {
	filename string
	append   bool
	pipe     bool
	writer   *fileOutput
}

func parseTee(args []string, argi *int, opts *Options) (Verb, error) {
	v := &teeVerb{}
	localOpts := *opts
	wopts := localOpts.Writer
	p := newOptParser("tee", args, argi)
	for {
		f := p.next()
		if f == "" {
			break
		}
		switch f {
		case "-a":
			v.append = true
			p.advance()
		case "-p":
			v.pipe = true
			p.advance()
		default:
			// try writer options
			j := *argi
			tmp := &Options{Writer: wopts, Reader: localOpts.Reader}
			if parseMainFlag(args, &j, tmp) {
				wopts = tmp.Writer
				*argi = j
			} else {
				p.unknown(f)
			}
		}
	}
	fn, ok := p.positional()
	if !ok {
		fmt.Fprint(os.Stderr, verbUsage("tee"))
		os.Exit(1)
	}
	v.filename = fn
	wopts2 := wopts
	// finalize writer defaults for possibly-changed format
	tmpo := &Options{Writer: wopts2, Reader: opts.Reader}
	tmpo.Reader.ifsWasSpecified = true
	tmpo.Reader.ipsWasSpecified = true
	tmpo.Reader.irsWasSpecified = true
	tmpo.finalize()
	v.writer = newFileOutput(fn, v.append, v.pipe, &tmpo.Writer)
	return v, nil
}

func (v *teeVerb) Process(rec *Mlrmap, ctx *Context, out recordSink) {
	v.writer.writeRecord(rec.Copy())
	out(rec, ctx)
}

func (v *teeVerb) Finish(ctx *Context, out recordSink) {
	v.writer.close()
}
