}

func parseHead(args []string, argi *int, opts *Options) (Verb, error) {
	v := &headVerb{n: 10, counts: map[string]int64{}}
	p := newOptParser("head", args, argi)
	for {
		f := p.next()
		if f == "" {
			break
		}
		switch f {
		case "-n":
			v.n = p.int()
		case "-g":
			v.groupBy = p.list()
		default:
			p.unknown(f)
		}
	}
	return v, nil
}

func (v *headVerb) Process(rec *Mlrmap, ctx *Context, out recordSink) {
	if v.groupBy == nil {
		v.count++
		if v.count <= v.n {
			out(rec, ctx)
		}
		return
	}
	key, ok := groupingKey(rec, v.groupBy)
	if !ok {
		return
	}
	v.counts[key]++
	if v.counts[key] <= v.n {
		out(rec, ctx)
	}
}
func (v *headVerb) Finish(ctx *Context, out recordSink) {}
func (v *headVerb) IsDone() bool {
