}

type tailGroup struct {
	recs []*Mlrmap
	ctxs []Context
}

func parseTail(args []string, argi *int, opts *Options) (Verb, error) {
	v := &tailVerb{n: 10, groups: newOrderedMap()}
	p := newOptParser("tail", args, argi)
	for {
		f := p.next()
		if f == "" {
			break
		}
		switch f {
		case "-n":
			v.n = p.int()
		case "-g":
			v.groupBy = p.list()
		default:
			p.unknown(f)
		}
	}
	return v, nil
}

func (v *tailVerb) Process(rec *Mlrmap, ctx *Context, out recordSink) {
	key, ok := groupingKey(rec, v.groupBy)
	if !ok {
		return
	}
	gi, ok := v.groups.Get(key)
	var g *tailGroup
	if !ok {
		g = &tailGroup{}
		v.groups.Put(key, g)
	} else {
		g = gi.(*tailGroup)
	}
	g.recs = append(g.recs, rec)
	g.ctxs = append(g.ctxs, *ctx)
	if int64(len(g.recs)) > v.n {
		g.recs = g.recs[1:]
		g.ctxs = g.ctxs[1:]
	}
}

func (v *tailVerb) Finish(ctx *Context, out recordSink) {
	for _, k := range v.groups.keys {
		g := v.groups.vals[k].(*tailGroup)
		for i, rec := range g.recs {
			c := g.ctxs[i]
			out(rec, &c)
		}
	}
}

