// ---------------------------------------------------------------- cut

type cutVerb struct {
	fields     []string
	fieldSet   map[string]bool
	doArgOrder bool
	doComplement bool
	doRegex    bool
	regexes    []*regexp.Regexp
}

func parseCut(args []string, argi *int, opts *Options) (Verb, error) {
	v := &cutVerb{fieldSet: map[string]bool{}}
	p := newOptParser("cut", args, argi)
	for {
		f := p.next()
		if f == "" {
			break
		}
		switch f {
		case "-f":
			v.fields = p.list()
		case "-o":
			v.doArgOrder = true
			p.advance()
		case "-x", "--complement":
			v.doComplement = true
			p.advance()
		case "-r":
			v.doRegex = true
			p.advance()
		default:
			p.unknown(f)
		}
	}
	if v.fields == nil {
		fmt.Fprintf(os.Stderr, "mlr cut: option -f is required.\n")
		fmt.Fprint(os.Stderr, verbUsage("cut"))
		os.Exit(1)
	}
	for _, f := range v.fields {
		v.fieldSet[f] = true
	}
	if v.doRegex {
		for _, f := range v.fields {
			v.regexes = append(v.regexes, compileMillerRegexOrDie(f))
		}
	}
	return v, nil
}

// compileMillerRegex handles "..."i case-insensitive syntax.
func compileMillerRegex(s string) (*regexp.Regexp, error) {
	if len(s) >= 3 && s[0] == '"' && strings.HasSuffix(s, "\"i") {
		return regexp.Compile("(?i)" + s[1:len(s)-2])
	}
	if len(s) >= 2 && s[0] == '"' && s[len(s)-1] == '"' {
		return regexp.Compile(s[1 : len(s)-1])
	}
	return regexp.Compile(s)
}

func compileMillerRegexOrDie(s string) *regexp.Regexp {
	rx, err := compileMillerRegex(s)
	if err != nil {
		fmt.Fprintf(os.Stderr, "mlr: could not compile regex \"%s\"\n", s)
		os.Exit(1)
	}
	return rx
}

func (v *cutVerb) Process(rec *Mlrmap, ctx *Context, out recordSink) {
	if v.doRegex {
		newrec := NewMlrmap()
		for e := rec.Head; e != nil; e = e.Next {
			matched := false
			for _, rx := range v.regexes {
				if rx.MatchString(e.Key) {
					matched = true
					break
				}
			}
			if matched != v.doComplement {
				newrec.Put(e.Key, e.Value)
			}
		}
		out(newrec, ctx)
		return
	}
	if v.doComplement {
		for _, f := range v.fields {
			rec.Remove(f)
		}
		out(rec, ctx)
		return
	}
	if v.doArgOrder {
		newrec := NewMlrmap()
		for _, f := range v.fields {
			if val := rec.Get(f); val != nil {
				newrec.Put(f, val)
			}
		}
		out(newrec, ctx)
		return
	}
	newrec := NewMlrmap()
	for e := rec.Head; e != nil; e = e.Next {
		if v.fieldSet[e.Key] {
			newrec.Put(e.Key, e.Value)
		}
	}
	out(newrec, ctx)
}
func (v *cutVerb) Finish(ctx *Context, out recordSink) {}

// ---------------------------------------------------------------- having-fields

type havingFieldsVerb struct {
	mode   string
	fields []string
	set    map[string]bool
	rx     *regexp.Regexp
}

func parseHavingFields(args []string, argi *int, opts *Options) (Verb, error) {
	v := &havingFieldsVerb{set: map[string]bool{}}
	p := newOptParser("having-fields", args, argi)
	for {
		f := p.next()
		if f == "" {
			break
		}
		switch f {
		case "--at-least", "--which-are", "--at-most", "--all-defined", "--any-defined":
			v.mode = f
			v.fields = p.list()
		case "--all-matching", "--any-matching", "--none-matching":
			v.mode = f
			v.rx = compileMillerRegexOrDie(p.str())
		default:
			p.unknown(f)
		}
	}
	if v.mode == "" {
		fmt.Fprint(os.Stderr, verbUsage("having-fields"))
		os.Exit(1)
	}
	for _, f := range v.fields {
		v.set[f] = true
	}
	return v, nil
}

func (v *havingFieldsVerb) Process(rec *Mlrmap, ctx *Context, out recordSink) {
	switch v.mode {
	case "--at-least":
		for _, f := range v.fields {
			if !rec.Has(f) {
				return
			}
		}
		out(rec, ctx)
	case "--which-are":
		if rec.Len() != len(v.fields) {
			return
		}
		for _, f := range v.fields {
			if !rec.Has(f) {
				return
			}
		}
		out(rec, ctx)
	case "--at-most":
		for e := rec.Head; e != nil; e = e.Next {
			if !v.set[e.Key] {
				return
			}
		}
		out(rec, ctx)
	case "--all-defined":
		for _, f := range v.fields {
			val := rec.Get(f)
			if val == nil || val.IsVoid() {
				return
			}
		}
		out(rec, ctx)
	case "--any-defined":
		for _, f := range v.fields {
			val := rec.Get(f)
			if val != nil && !val.IsVoid() {
				out(rec, ctx)
				return
			}
		}
	case "--all-matching":
		if rec.Len() == 0 {
			return
		}
		for e := rec.Head; e != nil; e = e.Next {
			if !v.rx.MatchString(e.Key) {
				return
			}
		}
		out(rec, ctx)
	case "--any-matching":
		for e := rec.Head; e != nil; e = e.Next {
			if v.rx.MatchString(e.Key) {
				out(rec, ctx)
				return
			}
		}
	case "--none-matching":
		for e := rec.Head; e != nil; e = e.Next {
			if v.rx.MatchString(e.Key) {
				return
			}
		}
		out(rec, ctx)
	}
}
func (v *havingFieldsVerb) Finish(ctx *Context, out recordSink) {}

// ---------------------------------------------------------------- label

type labelVerb struct {
	names []string
}

func parseLabel(args []string, argi *int, opts *Options) (Verb, error) {
	p := newOptParser("label", args, argi)
	for {
		f := p.next()
		if f == "" {
			break
		}
		p.unknown(f)
	}
	s, ok := p.positional()
	if !ok {
		fmt.Fprint(os.Stderr, verbUsage("label"))
		os.Exit(1)
	}
	names := splitFieldNames(s)
	// check duplicates
	seen := map[string]bool{}
	for _, n := range names {
		if seen[n] {
			fmt.Fprintf(os.Stderr, "mlr label: labels must be unique; got \"%s\"\n", s)
			os.Exit(1)
		}
		seen[n] = true
	}
	return &labelVerb{names: names}, nil
}

func (v *labelVerb) Process(rec *Mlrmap, ctx *Context, out recordSink) {
	// Rename first n fields; if a new name collides with a later field, that later field is removed.
	newrec := NewMlrmap()
	i := 0
	var entries []*MlrmapEntry
	for e := rec.Head; e != nil; e = e.Next {
		entries = append(entries, e)
	}
	for _, e := range entries {
		if i < len(v.names) {
			newrec.Put(v.names[i], e.Value)
			i++
		} else {
			if !newrec.Has(e.Key) {
				newrec.Put(e.Key, e.Value)
			}
		}
	}
	out(newrec, ctx)
}
func (v *labelVerb) Finish(ctx *Context, out recordSink) {}

// ---------------------------------------------------------------- rename

type renameVerb struct {
	pairs   [][2]string
	doRegex bool
	doGsub  bool
	regexes []*regexp.Regexp
}

func parseRename(args []string, argi *int, opts *Options) (Verb, error) {
	v := &renameVerb{}
	p := newOptParser("rename", args, argi)
	for {
		f := p.next()
		if f == "" {
			break
		}
		switch f {
		case "-r":
			v.doRegex = true
			p.advance()
		case "-g":
			v.doRegex = true
			v.doGsub = true
			p.advance()
		default:
			p.unknown(f)
		}
	}
	s, ok := p.positional()
	if !ok {
		fmt.Fprint(os.Stderr, verbUsage("rename"))
		os.Exit(1)
	}
	names := splitFieldNames(s)
	if len(names)%2 != 0 {
		fmt.Fprintf(os.Stderr, "mlr rename: name-list must have even length; got \"%s\".\n", s)
		os.Exit(1)
	}
	for i := 0; i < len(names); i += 2 {
		v.pairs = append(v.pairs, [2]string{names[i], names[i+1]})
		if v.doRegex {
			v.regexes = append(v.regexes, compileMillerRegexOrDie(names[i]))
		}
	}
	return v, nil
}

func (v *renameVerb) Process(rec *Mlrmap, ctx *Context, out recordSink) {
	if !v.doRegex {
		for _, pair := range v.pairs {
			if rec.Has(pair[0]) {
				rec.Rename(pair[0], pair[1])
			}
		}
		out(rec, ctx)
		return
	}
	for i, pair := range v.pairs {
		rx := v.regexes[i]
		replacement := pair[1]
		var entries []*MlrmapEntry
		for e := rec.Head; e != nil; e = e.Next {
			entries = append(entries, e)
		}
		for _, e := range entries {
			if !rx.MatchString(e.Key) {
				continue
			}
			var newKey string
			if v.doGsub {
				newKey = regexGsubWithCaptures(e.Key, rx, replacement)
			} else {
				newKey = regexSubWithCaptures(e.Key, rx, replacement)
			}
			if newKey != e.Key {
				rec.Rename(e.Key, newKey)
			}
		}
	}
	out(rec, ctx)
}
func (v *renameVerb) Finish(ctx *Context, out recordSink) {}

// regexSubWithCaptures replaces the first match, with \1..\9 captures.
func regexSubWithCaptures(input string, rx *regexp.Regexp, replacement string) string {
	loc := rx.FindStringSubmatchIndex(input)
	if loc == nil {
		return input
	}
	repl := expandCaptures(replacement, input, loc)
	return input[:loc[0]] + repl + input[loc[1]:]
}

func regexGsubWithCaptures(input string, rx *regexp.Regexp, replacement string) string {
	var sb strings.Builder
	pos := 0
	for pos <= len(input) {
		loc := rx.FindStringSubmatchIndex(input[pos:])
		if loc == nil {
			break
		}
		for i := range loc {
			if loc[i] >= 0 {
				loc[i] += pos
			}
		}
		sb.WriteString(input[pos:loc[0]])
		sb.WriteString(expandCaptures(replacement, input, loc))
		if loc[1] == loc[0] {
			if loc[0] < len(input) {
				sb.WriteByte(input[loc[0]])
			}
			pos = loc[0] + 1
		} else {
			pos = loc[1]
		}
	}
	if pos <= len(input) {
		sb.WriteString(input[pos:])
	}
	return sb.String()
}

// expandCaptures replaces \0..\9 in replacement with the captures.
func expandCaptures(replacement string, input string, loc []int) string {
	if !strings.Contains(replacement, "\\") {
		return replacement
	}
	var sb strings.Builder
	for i := 0; i < len(replacement); i++ {
		c := replacement[i]
		if c == '\\' && i+1 < len(replacement) && replacement[i+1] >= '0' && replacement[i+1] <= '9' {
			idx := int(replacement[i+1] - '0')
			if 2*idx+1 < len(loc) && loc[2*idx] >= 0 {
				sb.WriteString(input[loc[2*idx]:loc[2*idx+1]])
			}
			i++
			continue
		}
		sb.WriteByte(c)
	}
	return sb.String()
}

