type regularizeVerb struct {
	sortedToOriginal map[string][]string
}

func parseRegularize(args []string, argi *int, opts *Options) (Verb, error) {
	p := newOptParser("regularize", args, argi)
	for {
		f := p.next()
		if f == "" {
			break
