		p.unknown(f)
	}
	return &regularizeVerb{sortedToOriginal: map[string][]string{}}, nil
}

func (v *regularizeVerb) Process(rec *Mlrmap, ctx *Context, out recordSink) {
	keys := rec.Keys()
	sorted := make([]string, len(keys))
	copy(sorted, keys)
	sortStrings(sorted)
	sk := strings.Join(sorted, ",")
	if orig, ok := v.sortedToOriginal[sk]; ok {
		newrec := NewMlrmap()
		for _, k := range orig {
			newrec.Put(k, rec.Get(k))
		}
		out(newrec, ctx)
	} else {
		v.sortedToOriginal[sk] = keys
		out(rec, ctx)
	}
}
func (v *regularizeVerb) Finish(ctx *Context, out recordSink) {}

