type reorderVerb struct {
	fields []string
	toEnd  bool
}

func parseReorder(args []string, argi *int, opts *Options) (Verb, error) {
	v := &reorderVerb{}
	p := newOptParser("reorder", args, argi)
	for {
		f := p.next()
		if f == "" {
			break
		}
		switch f {
		case "-f":
			v.fields = p.list()
		case "-e":
			v.toEnd = true
			p.advance()
		default:
			p.unknown(f)
		}
	}
	if v.fields == nil {
		fmt.Fprint(os.Stderr, verbUsage("reorder"))
		os.Exit(1)
	}
	return v, nil
}

func (v *reorderVerb) Process(rec *Mlrmap, ctx *Context, out recordSink) {
	if v.toEnd {
		for _, f := range v.fields {
			if val := rec.Get(f); val != nil {
				rec.PutAtEnd(f, val)
			}
		}
	} else {
		for i := len(v.fields) - 1; i >= 0; i-- {
			f := v.fields[i]
			if val := rec.Get(f); val != nil {
				rec.PutAtStart(f, val)
			}
		}
	}
	out(rec, ctx)
}
func (v *reorderVerb) Finish(ctx *Context, out recordSink) {}

