// ---------------------------------------------------------------- unsparsify

type unsparsifyVerb struct {
	fillWith  *Mlrval
	fields    []string
	fieldSet  map[string]bool
	recs      []*Mlrmap
	ctxs      []Context
	keyOrder  []string
	keySeen   map[string]bool
}

func parseUnsparsify(args []string, argi *int, opts *Options) (Verb, error) {
	v := &unsparsifyVerb{fillWith: VOID, keySeen: map[string]bool{}, fieldSet: map[string]bool{}}
	p := newOptParser("unsparsify", args, argi)
	for {
		f := p.next()
		if f == "" {
			break
		}
		switch f {
		case "--fill-with":
			v.fillWith = inferredFromString(p.str())
		case "-f":
			v.fields = append(v.fields, p.list()...)
		default:
			p.unknown(f)
		}
	}
	for _, f := range v.fields {
		v.fieldSet[f] = true
	}
	return v, nil
}

func (v *unsparsifyVerb) Process(rec *Mlrmap, ctx *Context, out recordSink) {
	if v.fields != nil {
		for _, f := range v.fields {
			if !rec.Has(f) {
				rec.Put(f, v.fillWith)
			}
		}
		out(rec, ctx)
		return
	}
	for e := rec.Head; e != nil; e = e.Next {
		if !v.keySeen[e.Key] {
			v.keySeen[e.Key] = true
			v.keyOrder = append(v.keyOrder, e.Key)
		}
	}
	v.recs = append(v.recs, rec)
	v.ctxs = append(v.ctxs, *ctx)
}

func (v *unsparsifyVerb) Finish(ctx *Context, out recordSink) {
	if v.fields != nil {
		return
	}
	for i, rec := range v.recs {
		newrec := NewMlrmap()
		for _, k := range v.keyOrder {
			val := rec.Get(k)
			if val == nil {
				val = v.fillWith
			}
			newrec.Put(k, val)
		}
		c := v.ctxs[i]
		out(newrec, &c)
	}
}

