type sparsifyVerb struct {
	filler string
	fields []string
}

func parseSparsify(args []string, argi *int, opts *Options) (Verb, error) {
	v := &sparsifyVerb{}
	p := newOptParser("sparsify", args, argi)
	for {
		f := p.next()
		if f == "" {
			break
		}
		switch f {
		case "-s":
			v.filler = p.str()
		case "-f":
			v.fields = p.list()
		default:
			p.unknown(f)
		}
	}
	return v, nil
}

func (v *sparsifyVerb) Process(rec *Mlrmap, ctx *Context, out recordSink) {
	if v.fields == nil {
		newrec := NewMlrmap()
		for e := rec.Head; e != nil; e = e.Next {
			if e.Value.String() != v.filler {
				newrec.Put(e.Key, e.Value)
			}
		}
		out(newrec, ctx)
		return
	}
	for _, f := range v.fields {
		val := rec.Get(f)
		if val != nil && val.String() == v.filler {
			rec.Remove(f)
		}
	}
	out(rec, ctx)
}
func (v *sparsifyVerb) Finish(ctx *Context, out recordSink) {}

// ---------------------------------------------------------------- gap

type gapVerb struct {
	n       int64
	groupBy []string
	count   int64
	lastKey string
	first   bool
}

func parseGap(args []string, argi *int, opts *Options) (Verb, error) {
	v := &gapVerb{first: true}
	p := newOptParser("gap", args, argi)
	for {
		f := p.next()
		if f == "" {
			break
		}
		switch f {
		case "-n":
			v.n = p.int()
		case "-g":
			v.groupBy = p.list()
		default:
			p.unknown(f)
		}
	}
	if v.n <= 0 && v.groupBy == nil {
		fmt.Fprint(os.Stderr, verbUsage("gap"))
		os.Exit(1)
	}
	return v, nil
}

func (v *gapVerb) Process(rec *Mlrmap, ctx *Context, out recordSink) {
	if v.groupBy != nil {
		key, _ := groupingKey(rec, v.groupBy)
		if !v.first && key != v.lastKey {
			out(NewMlrmap(), ctx)
		}
		v.lastKey = key
		v.first = false
		out(rec, ctx)
		return
	}
	if v.count > 0 && v.count%v.n == 0 {
		out(NewMlrmap(), ctx)
	}
	v.count++
	out(rec, ctx)
}
func (v *gapVerb) Finish(ctx *Context, out recordSink) {}

// ---------------------------------------------------------------- grep

type grepVerb struct {
	rx         *regexp.Regexp
	invert     bool
	valuesOnly bool
}

func parseGrep(args []string, argi *int, opts *Options) (Verb, error) {
	v := &grepVerb{}
	ignoreCase := false
	p := newOptParser("grep", args, argi)
	for {
		f := p.next()
		if f == "" {
			break
		}
		switch f {
		case "-i":
			ignoreCase = true
			p.advance()
		case "-v":
			v.invert = true
			p.advance()
		case "-a":
			v.valuesOnly = true
			p.advance()
		default:
			p.unknown(f)
		}
	}
	s, ok := p.positional()
	if !ok {
		fmt.Fprint(os.Stderr, verbUsage("grep"))
		os.Exit(1)
	}
	if ignoreCase {
		s = "(?i)" + s
	}
	rx, err := regexp.Compile(s)
	if err != nil {
		fmt.Fprintf(os.Stderr, "mlr grep: could not compile regex \"%s\"\n", s)
		os.Exit(1)
	}
	v.rx = rx
	return v, nil
}

func (v *grepVerb) Process(rec *Mlrmap, ctx *Context, out recordSink) {
	var s string
	if v.valuesOnly {
		s = rec.ToNIDXString(" ")
	} else {
		s = rec.ToDKVPString(",", "=")
	}
	matched := v.rx.MatchString(s)
	if matched != v.invert {
		out(rec, ctx)
	}
}
func (v *grepVerb) Finish(ctx *Context, out recordSink) {}

// ---------------------------------------------------------------- sec2gmt / sec2gmtdate

type sec2gmtVerb struct {
	fields    []string
	numDecimals int
	divisor   int64
	dateOnly  bool
}

func parseSec2GMT(args []string, argi *int, opts *Options) (Verb, error) {
	v := &sec2gmtVerb{divisor: 1}
	p := newOptParser("sec2gmt", args, argi)
	for {
		f := p.next()
		if f == "" {
			break
		}
		switch f {
		case "-1", "-2", "-3", "-4", "-5", "-6", "-7", "-8", "-9":
			v.numDecimals = int(f[1] - '0')
			p.advance()
		case "--millis2gmt":
			v.divisor = 1000
			p.advance()
		case "--micros2gmt":
			v.divisor = 1000000
			p.advance()
		case "--nanos2gmt":
			v.divisor = 1000000000
			p.advance()
		default:
			p.unknown(f)
		}
	}
	s, ok := p.positional()
	if !ok {
		fmt.Fprint(os.Stderr, verbUsage("sec2gmt"))
		os.Exit(1)
	}
	v.fields = splitFieldNames(s)
	return v, nil
}

func parseSec2GMTDate(args []string, argi *int, opts *Options) (Verb, error) {
	v := &sec2gmtVerb{divisor: 1, dateOnly: true}
	p := newOptParser("sec2gmtdate", args, argi)
	for {
		f := p.next()
		if f == "" {
			break
		}
		p.unknown(f)
	}
	s, ok := p.positional()
	if !ok {
		fmt.Fprint(os.Stderr, verbUsage("sec2gmtdate"))
		os.Exit(1)
	}
	v.fields = splitFieldNames(s)
	return v, nil
}

func (v *sec2gmtVerb) Process(rec *Mlrmap, ctx *Context, out recordSink) {
	for _, f := range v.fields {
		val := rec.Get(f)
		if val == nil {
			continue
		}
		if v.dateOnly {
			rec.Put(f, bifSec2GMTDate(val))
			continue
		}
		if v.divisor != 1 {
			if val.IsNumeric() {
				fv, _ := val.GetNumericToFloat()
				val = FromFloat(fv / float64(v.divisor))
			}
		}
		rec.Put(f, bifSec2GMT(val, v.numDecimals))
	}
	out(rec, ctx)
}
func (v *sec2gmtVerb) Finish(ctx *Context, out recordSink) {}

