type unspaceVerb struct {
	fill   string
	keys   bool
	values bool
}

func parseUnspace(args []string, argi *int, opts *Options) (Verb, error) {
	v := &unspaceVerb{fill: "_", keys: true, values: true}
	p := newOptParser("unspace", args, argi)
	for {
		f := p.next()
		if f == "" {
			break
		}
		switch f {
		case "-f":
			v.fill = p.str()
		case "-k":
			v.keys = true
			v.values = false
			p.advance()
		case "-v":
			v.keys = false
			v.values = true
			p.advance()
		default:
			p.unknown(f)
		}
	}
	return v, nil
}

func (v *unspaceVerb) Process(rec *Mlrmap, ctx *Context, out recordSink) {
	newrec := NewMlrmap()
	for e := rec.Head; e != nil; e = e.Next {
		k := e.Key
		val := e.Value
		if v.keys {
			k = strings.ReplaceAll(k, " ", v.fill)
		}
		if v.values {
			s := val.String()
			if strings.Contains(s, " ") {
				val = inferredFromString(strings.ReplaceAll(s, " ", v.fill))
			}
		}
		newrec.Put(k, val)
	}
	out(newrec, ctx)
}
func (v *unspaceVerb) Finish(ctx *Context, out recordSink) {}

// ---------------------------------------------------------------- template

type templateVerb struct {
	fields   []string
	fillWith *Mlrval
}

func parseTemplate(args []string, argi *int, opts *Options) (Verb, error) {
	v := &templateVerb{fillWith: VOID}
	p := newOptParser("template", args, argi)
	for {
		f := p.next()
		if f == "" {
			break
		}
		switch f {
		case "-f":
			v.fields = append(v.fields, p.list()...)
		case "-t":
			fn := p.str()
			data, err := os.ReadFile(fn)
			if err != nil {
				fmt.Fprintf(os.Stderr, "mlr template: cannot open template file \"%s\".\n", fn)
				os.Exit(1)
			}
			lines := strings.Split(strings.TrimRight(string(data), "\n"), "\n")
			if len(lines) > 0 {
				v.fields = append(v.fields, splitFieldNames(strings.TrimRight(lines[0], "\r"))...)
			}
		case "--fill-with":
			v.fillWith = inferredFromString(p.str())
		default:
			p.unknown(f)
		}
	}
	if v.fields == nil {
		fmt.Fprint(os.Stderr, verbUsage("template"))
		os.Exit(1)
	}
	return v, nil
}

func (v *templateVerb) Process(rec *Mlrmap, ctx *Context, out recordSink) {
	newrec := NewMlrmap()
	for _, f := range v.fields {
		val := rec.Get(f)
		if val == nil {
			val = v.fillWith
		}
		newrec.Put(f, val)
	}
	for e := rec.Head; e != nil; e = e.Next {
		if !newrec.Has(e.Key) {
			newrec.Put(e.Key, e.Value)
		}
	}
	out(newrec, ctx)
}
func (v *templateVerb) Finish(ctx *Context, out recordSink) {}

