// ---------------------------------------------------------------- seqgen

type seqgenVerb struct {
	field string
	start *Mlrval
	stop  *Mlrval
	step  *Mlrval
}

func parseSeqgen(args []string, argi *int, opts *Options) (Verb, error) {
	v := &seqgenVerb{field: "i"}
	startS, stopS, stepS := "1", "100", "1"
	p := newOptParser("seqgen", args, argi)
	for {
		f := p.next()
		if f == "" {
			break
		}
		switch f {
		case "-f":
			v.field = p.str()
		case "--start":
			startS = p.str()
		case "--stop":
			stopS = p.str()
		case "--step":
			stepS = p.str()
		default:
			p.unknown(f)
		}
	}
	v.start = inferredFromString(startS)
	v.stop = inferredFromString(stopS)
	v.step = inferredFromString(stepS)
	for _, pair := range [][2]interface{}{{v.start, startS}, {v.stop, stopS}, {v.step, stepS}} {
		if !pair[0].(*Mlrval).IsNumeric() {
			fmt.Fprintf(os.Stderr, "mlr seqgen: start, stop, and step must be numeric; got \"%s\".\n", pair[1].(string))
			os.Exit(1)
		}
	}
	return v, nil
}

func (v *seqgenVerb) Process(rec *Mlrmap, ctx *Context, out recordSink) {}

func (v *seqgenVerb) Finish(ctx *Context, out recordSink) {
	stepF, _ := v.step.GetNumericToFloat()
	startF, _ := v.start.GetNumericToFloat()
	stopF, _ := v.stop.GetNumericToFloat()
	if stepF == 0 {
		if startF == stopF {
			rec := NewMlrmap()
			rec.Put(v.field, v.start)
			c := *ctx
			c.NR = 1
			c.FNR = 1
			out(rec, &c)
		} else {
			fmt.Fprintf(os.Stderr, "mlr seqgen: step must not be zero unless start == stop.\n")
			os.Exit(1)
		}
		return
	}
	cur := v.start
	nr := int64(0)
	for {
		cf, _ := cur.GetNumericToFloat()
		if stepF > 0 && cf > stopF {
			break
		}
		if stepF < 0 && cf < stopF {
			break
		}
		nr++
		rec := NewMlrmap()
		rec.Put(v.field, cur)
		c := *ctx
		c.NR = nr
		c.FNR = nr
		out(rec, &c)
		cur = binaryOpPlus(cur, v.step)
	}
}

