func (v *jsonParseVerb) parseOne(val *Mlrval) *Mlrval {
	parsed, err := ParseJSONValue(val.String())
	if err != nil {
		if v.keepOnFail {
			return val
		}
		return NewError(err.Error())
	}
	return parsed
}

func (v *jsonParseVerb) Process(rec *Mlrmap, ctx *Context, out recordSink) {
	if v.fields == nil {
		for e := rec.Head; e != nil; e = e.Next {
			e.Value = v.parseOne(e.Value)
		}
	} else {
		for _, f := range v.fields {
			if e := rec.GetEntry(f); e != nil {
				e.Value = v.parseOne(e.Value)
			}
		}
	}
	out(rec, ctx)
}
