		}
		if cs != ct {
			if cs < ct {
				return -1
			}
			return 1
		}
		i++
		j++
	}
	if len(s)-i < len(t)-j {
		return -1
	}
	if len(s)-i > len(t)-j {
		return 1
	}
	return 0
}

