package main

import (
	"fmt"
	"strings"
)

type TokenType int

const (
	TK_EOF TokenType = iota
	TK_IDENT          // identifiers and keywords
	TK_NUMBER         // numeric literal
	TK_STRING         // "..." string literal (raw contents, without quotes)
	TK_REGEXI         // "..."i
	TK_FIELD          // $name or ${name}
	TK_FULL_SREC      // $*
	TK_FIELD_INDIRECT // $[  (then expression then ])
	TK_FIELD_POSNAME  // $[[
	TK_FIELD_POSVALUE // $[[[
	TK_OOSVAR         // @name or @{name}
	TK_FULL_OOSVAR    // @*
	TK_OOSVAR_INDIRECT // @[
	TK_PUNCT          // operators and punctuation
)

type Token struct {
	typ  TokenType
	text string
	line int
	col  int
}

type Lexer struct {
	src    string
	pos    int
	line   int
	col    int
	tokens []Token
}

type DSLParseError struct {
	msg string
}

func (e *DSLParseError) Error() string { return e.msg }

func (lx *Lexer) errorf(tok string, line, col int) error {
	return &DSLParseError{msg: fmt.Sprintf("mlr: cannot parse DSL expression.\nmlr: Parse error on token \"%s\" at line %d column %d.\n", tok, line, col)}
}

// Multi-char operators, longest first.
var dslOperators = []string{
	">>>=", "???=", "!=~", "<=>", ">>>", "**=", "//=", "<<=", ">>=", "&&=", "||=", "^^=", "??=", ".//",
	"**", "//", "==", "!=", "<=", ">=", "=~", "&&", "||", "^^", "<<", ">>", "??", ".+", ".-", ".*", "./",
	"+=", "-=", "*=", "/=", "%=", ".=", "&=", "|=", "^=",
	"+", "-", "*", "/", "%", ".", "<", ">", "=", "!", "~", "&", "|", "^", "?", ":", ",", ";", "(", ")", "{", "}", "[", "]",
}

func isIdentStart(c byte) bool {
	return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c == '_'
}
func isIdentChar(c byte) bool {
	return isIdentStart(c) || (c >= '0' && c <= '9')
}

func lexDSL(src string) ([]Token, error) {
	lx := &Lexer{src: src, line: 1, col: 1}
	for {
		tok, err := lx.next()
		if err != nil {
			return nil, err
		}
		lx.tokens = append(lx.tokens, tok)
		if tok.typ == TK_EOF {
			break
		}
	}
	return lx.tokens, nil
}

func (lx *Lexer) advance(n int) {
	for i := 0; i < n && lx.pos < len(lx.src); i++ {
		if lx.src[lx.pos] == '\n' {
			lx.line++
			lx.col = 1
		} else {
			lx.col++
		}
		lx.pos++
	}
}

func (lx *Lexer) peekByte(off int) byte {
	if lx.pos+off < len(lx.src) {
		return lx.src[lx.pos+off]
	}
	return 0
}

func (lx *Lexer) skipWhitespaceAndComments() {
	for lx.pos < len(lx.src) {
		c := lx.src[lx.pos]
		if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
			lx.advance(1)
		} else if c == '#' {
			for lx.pos < len(lx.src) && lx.src[lx.pos] != '\n' {
				lx.advance(1)
			}
		} else {
			break
		}
	}
}

func (lx *Lexer) next() (Token, error) {
	lx.skipWhitespaceAndComments()
	if lx.pos >= len(lx.src) {
		return Token{typ: TK_EOF, line: lx.line, col: lx.col}, nil
	}
	line, col := lx.line, lx.col
	c := lx.src[lx.pos]
	start := lx.pos

	// Field references
	if c == '$' {
		if lx.peekByte(1) == '*' {
			lx.advance(2)
			return Token{TK_FULL_SREC, "$*", line, col}, nil
		}
		if lx.peekByte(1) == '[' {
			if lx.peekByte(2) == '[' {
				if lx.peekByte(3) == '[' {
					lx.advance(4)
					return Token{TK_FIELD_POSVALUE, "$[[[", line, col}, nil
				}
				lx.advance(3)
				return Token{TK_FIELD_POSNAME, "$[[", line, col}, nil
			}
			lx.advance(2)
			return Token{TK_FIELD_INDIRECT, "$[", line, col}, nil
		}
		if lx.peekByte(1) == '{' {
			end := strings.IndexByte(lx.src[lx.pos:], '}')
			if end < 0 {
				return Token{}, lx.errorf(lx.src[start:], line, col)
			}
			name := lx.src[lx.pos+2 : lx.pos+end]
			lx.advance(end + 1)
			return Token{TK_FIELD, name, line, col}, nil
		}
		lx.advance(1)
		s := lx.pos
		for lx.pos < len(lx.src) && isIdentChar(lx.src[lx.pos]) {
			lx.advance(1)
		}
		if lx.pos == s {
			return Token{}, lx.errorf("$", line, col)
		}
		return Token{TK_FIELD, lx.src[s:lx.pos], line, col}, nil
	}
	if c == '@' {
		if lx.peekByte(1) == '*' {
			lx.advance(2)
			return Token{TK_FULL_OOSVAR, "@*", line, col}, nil
		}
		if lx.peekByte(1) == '[' {
			lx.advance(2)
			return Token{TK_OOSVAR_INDIRECT, "@[", line, col}, nil
		}
		if lx.peekByte(1) == '{' {
			end := strings.IndexByte(lx.src[lx.pos:], '}')
			if end < 0 {
				return Token{}, lx.errorf(lx.src[start:], line, col)
			}
			name := lx.src[lx.pos+2 : lx.pos+end]
			lx.advance(end + 1)
			return Token{TK_OOSVAR, name, line, col}, nil
		}
		lx.advance(1)
		s := lx.pos
		for lx.pos < len(lx.src) && isIdentChar(lx.src[lx.pos]) {
			lx.advance(1)
		}
		if lx.pos == s {
			return Token{}, lx.errorf("@", line, col)
		}
		return Token{TK_OOSVAR, lx.src[s:lx.pos], line, col}, nil
	}

	// String literal
	if c == '"' {
		lx.advance(1)
		var sb strings.Builder
		for {
			if lx.pos >= len(lx.src) {
				return Token{}, lx.errorf(lx.src[start:], line, col)
			}
			ch := lx.src[lx.pos]
			if ch == '"' {
				lx.advance(1)
				break
			}
			if ch == '\\' && lx.pos+1 < len(lx.src) {
				sb.WriteByte(ch)
				sb.WriteByte(lx.src[lx.pos+1])
