				lx.advance(1)
			}
			return Token{TK_NUMBER, lx.src[s:lx.pos], line, col}, nil
		}
		if c == '0' && (lx.peekByte(1) == 'b' || lx.peekByte(1) == 'B') {
			lx.advance(2)
			for lx.pos < len(lx.src) && (lx.src[lx.pos] == '0' || lx.src[lx.pos] == '1') {
				lx.advance(1)
			}
			return Token{TK_NUMBER, lx.src[s:lx.pos], line, col}, nil
		}
		if c == '0' && (lx.peekByte(1) == 'o' || lx.peekByte(1) == 'O') {
			lx.advance(2)
			for lx.pos < len(lx.src) && lx.src[lx.pos] >= '0' && lx.src[lx.pos] <= '7' {
				lx.advance(1)
			}
			return Token{TK_NUMBER, lx.src[s:lx.pos], line, col}, nil
		}
		for lx.pos < len(lx.src) && isDecDigit(lx.src[lx.pos]) {
			lx.advance(1)
		}
