			save := lx.pos
			saveLine, saveCol := lx.line, lx.col
			lx.advance(1)
			if lx.pos < len(lx.src) && (lx.src[lx.pos] == '+' || lx.src[lx.pos] == '-') {
				lx.advance(1)
			}
			if lx.pos < len(lx.src) && isDecDigit(lx.src[lx.pos]) {
				for lx.pos < len(lx.src) && isDecDigit(lx.src[lx.pos]) {
					lx.advance(1)
				}
			} else {
				lx.pos = save
				lx.line, lx.col = saveLine, saveCol
			}
		}
		text := lx.src[s:lx.pos]
		// A trailing identifier char makes this invalid (e.g. 1_000)
		if lx.pos < len(lx.src) && isIdentChar(lx.src[lx.pos]) {
			s2 := lx.pos
			for lx.pos < len(lx.src) && isIdentChar(lx.src[lx.pos]) {
				lx.advance(1)
			}
			return Token{}, &DSLParseError{msg: fmt.Sprintf("mlr: cannot parse DSL expression.\nmlr: Parse error on token \"%s\" at line %d column %d.\nPlease check for missing semicolon.\n", lx.src[s2:lx.pos], line, col+(s2-s))}
