		}
	}
	return Token{}, lx.errorf(string(c), line, col)
}

// unescapeStringLiteral handles backslash escapes for non-regex string use.
func unescapeStringLiteral(s string) string {
	if !strings.Contains(s, "\\") {
		return s
	}
	var sb strings.Builder
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c != '\\' || i+1 >= len(s) {
			sb.WriteByte(c)
			continue
		}
		n := s[i+1]
		switch n {
		case 't':
			sb.WriteByte('\t')
			i++
		case 'n':
			sb.WriteByte('\n')
			i++
		case 'r':
			sb.WriteByte('\r')
			i++
		case '"':
			sb.WriteByte('"')
			i++
		case '\\':
			sb.WriteByte('\\')
			i++
		case 'b':
			sb.WriteByte('\b')
			i++
		case 'f':
			sb.WriteByte('\f')
			i++
		case 'v':
			sb.WriteByte('\v')
			i++
		case 'a':
			sb.WriteByte('\a')
			i++
		case 'x':
			if i+3 < len(s) && isHexDigit(s[i+2]) && isHexDigit(s[i+3]) {
				var b byte
				fmt.Sscanf(s[i+2:i+4], "%02x", &b)
				sb.WriteByte(b)
				i += 3
			} else {
				sb.WriteByte(c)
			}
		case 'u':
			if i+5 < len(s) && isHexDigit(s[i+2]) && isHexDigit(s[i+3]) && isHexDigit(s[i+4]) && isHexDigit(s[i+5]) {
				var r uint32
				fmt.Sscanf(s[i+2:i+6], "%04x", &r)
				sb.WriteRune(rune(r))
				i += 5
			} else {
				sb.WriteByte(c)
			}
		default:
			sb.WriteByte(c)
		}
	}
	return sb.String()
}

// unescapeForRegex: for regex use, keep regex escapes but convert \t etc.
func unescapeForRegex(s string) string {
	if !strings.Contains(s, "\\") {
		return s
	}
	var sb strings.Builder
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c != '\\' || i+1 >= len(s) {
			sb.WriteByte(c)
			continue
		}
		n := s[i+1]
		switch n {
		case '"':
			sb.WriteByte('"')
			i++
		default:
			sb.WriteByte(c)
		}
	}
	return sb.String()
}
