		}
		return Token{TK_FIELD, lx.src[s:lx.pos], line, col}, nil
	}
	if c == '@' {
		if lx.peekByte(1) == '*' {
			lx.advance(2)
			return Token{TK_FULL_OOSVAR, "@*", line, col}, nil
		}
		if lx.peekByte(1) == '[' {
			lx.advance(2)
			return Token{TK_OOSVAR_INDIRECT, "@[", line, col}, nil
		}
		if lx.peekByte(1) == '{' {
			end := strings.IndexByte(lx.src[lx.pos:], '}')
			if end < 0 {
				return Token{}, lx.errorf(lx.src[start:], line, col)
			}
			name := lx.src[lx.pos+2 : lx.pos+end]
			lx.advance(end + 1)
			return Token{TK_OOSVAR, name, line, col}, nil
		}
		lx.advance(1)
		s := lx.pos
		for lx.pos < len(lx.src) && isIdentChar(lx.src[lx.pos]) {
			lx.advance(1)
		}
		if lx.pos == s {
