		for {
			if lx.pos >= len(lx.src) {
				return Token{}, lx.errorf(lx.src[start:], line, col)
			}
			ch := lx.src[lx.pos]
			if ch == '"' {
				lx.advance(1)
				break
			}
			if ch == '\\' && lx.pos+1 < len(lx.src) {
				sb.WriteByte(ch)
