			}
			return Token{TK_NUMBER, lx.src[s:lx.pos], line, col}, nil
		}
		for lx.pos < len(lx.src) && isDecDigit(lx.src[lx.pos]) {
			lx.advance(1)
		}
		if lx.pos < len(lx.src) && lx.src[lx.pos] == '.' {
