package main

import (
	"fmt"
	"strings"
)

type ASTNode struct {
	typ      string
	text     string
	children []*ASTNode
	// cached values for evaluation
	mv       *Mlrval // for literals
	tok      Token
}

func newNode(typ, text string, children ...*ASTNode) *ASTNode {
	return &ASTNode{typ: typ, text: text, children: children}
}

// Print in Miller's parex-indented format.
func (n *ASTNode) printIndented(sb *strings.Builder, depth int) {
	sb.WriteString(strings.Repeat("    ", depth))
	sb.WriteString("* ")
	sb.WriteString(n.typ)
	if n.text != "" || n.hasText() {
		sb.WriteString(" \"")
		sb.WriteString(n.text)
		sb.WriteString("\"")
	}
	sb.WriteString("\n")
	for _, c := range n.children {
		c.printIndented(sb, depth+1)
	}
}

// Node types which always print their text (even if empty).
func (n *ASTNode) hasText() bool {
	switch n.typ {
	case "string literal", "direct field value", "direct oosvar value", "local variable":
		return true
	}
	return false
}

func (n *ASTNode) String() string {
	var sb strings.Builder
	n.printIndented(&sb, 0)
	return sb.String()
}

// Parenthesized formats (-d and -D)
func (n *ASTNode) printParex(sb *strings.Builder, depth int) {
	pad := strings.Repeat("    ", depth)
	if len(n.children) == 0 {
		sb.WriteString(pad)
		sb.WriteString(n.parexText())
		sb.WriteString("\n")
		return
	}
	sb.WriteString(pad)
	sb.WriteString("(")
	sb.WriteString(n.parexText())
