	for _, c := range n.children {
		c.printParex(sb, depth+1)
	}
	sb.WriteString(pad)
	sb.WriteString(")\n")
}

func (n *ASTNode) parexText() string {
	if n.text != "" {
		return n.text
	}
	return n.typ
}

func (n *ASTNode) printParexOneLine(sb *strings.Builder) {
	if len(n.children) == 0 {
		sb.WriteString(n.parexText())
		return
	}
	sb.WriteString("(")
	sb.WriteString(n.parexText())
	for _, c := range n.children {
		sb.WriteString(" ")
		c.printParexOneLine(sb)
	}
	sb.WriteString(")")
}

func (n *ASTNode) ParexString() string {
