package main

import (
	"fmt"
	"strings"
)

type Parser struct {
	tokens []Token
	pos    int
	src    string
}

func (p *Parser) peek() Token {
	return p.tokens[p.pos]
}

func (p *Parser) peekAt(off int) Token {
	if p.pos+off < len(p.tokens) {
		return p.tokens[p.pos+off]
	}
	return p.tokens[len(p.tokens)-1]
}

func (p *Parser) advance() Token {
	t := p.tokens[p.pos]
	if p.pos < len(p.tokens)-1 {
		p.pos++
	}
	return t
}

func (p *Parser) isPunct(s string) bool {
	t := p.peek()
	return t.typ == TK_PUNCT && t.text == s
}

func (p *Parser) isIdent(s string) bool {
	t := p.peek()
	return t.typ == TK_IDENT && t.text == s
}

func (p *Parser) errorAtToken(t Token) error {
	text := t.text
	if t.typ == TK_EOF {
		text = "␚"
	} else if t.typ == TK_STRING {
		text = "\"" + t.text + "\""
	}
	return &DSLParseError{msg: fmt.Sprintf("mlr: cannot parse DSL expression.\nmlr: Parse error on token \"%s\" at line %d column %d.\nPlease check for missing semicolon.\n", text, t.line, t.col)}
}

func (p *Parser) expectPunct(s string) error {
	if !p.isPunct(s) {
		return p.errorAtToken(p.peek())
	}
	p.advance()
	return nil
}

func (p *Parser) expectIdent(s string) error {
	if !p.isIdent(s) {
		return p.errorAtToken(p.peek())
	}
	p.advance()
	return nil
}

// ParseDSL parses a full DSL program.
func ParseDSL(src string) (*ASTNode, error) {
	tokens, err := lexDSL(src)
	if err != nil {
		return nil, err
	}
	p := &Parser{tokens: tokens, src: src}
	root, err := p.parseStatementBlock(true)
	if err != nil {
		return nil, err
	}
	if p.peek().typ != TK_EOF {
		return nil, p.errorAtToken(p.peek())
	}
	return root, nil
}

// parseStatementBlock parses statements until EOF or '}'.
func (p *Parser) parseStatementBlock(topLevel bool) (*ASTNode, error) {
	block := newNode("statement block", "")
	for {
		// skip empty statements
		for p.isPunct(";") {
			p.advance()
		}
		t := p.peek()
		if t.typ == TK_EOF {
			break
		}
		if t.typ == TK_PUNCT && t.text == "}" {
			break
		}
		stmt, endsWithBrace, err := p.parseStatement(topLevel)
		if err != nil {
			return nil, err
		}
		if stmt != nil {
			block.children = append(block.children, stmt)
		}
		// Separator handling
		t = p.peek()
		if t.typ == TK_EOF || (t.typ == TK_PUNCT && t.text == "}") {
			continue
		}
		if t.typ == TK_PUNCT && t.text == ";" {
			continue
		}
		if endsWithBrace {
			continue
		}
		return nil, p.errorAtToken(t)
	}
	return block, nil
}

func (p *Parser) parseBracedBlock() (*ASTNode, error) {
	if err := p.expectPunct("{"); err != nil {
		return nil, err
	}
	block, err := p.parseStatementBlock(false)
	if err != nil {
		return nil, err
	}
	if err := p.expectPunct("}"); err != nil {
		return nil, err
	}
	return block, nil
}

var typeDeclKeywords = map[string]bool{
	"var": true, "str": true, "num": true, "int": true, "float": true, "bool": true, "map": true, "arr": true, "funct": true,
}

var assignmentOps = map[string]string{
	"=": "", "+=": "+", "-=": "-", "*=": "*", "/=": "/", "//=": "//", "%=": "%", "**=": "**", ".=": ".",
	"<<=": "<<", ">>=": ">>", ">>>=": ">>>", "&=": "&", "|=": "|", "^=": "^", "&&=": "&&", "||=": "||", "^^=": "^^",
	"??=": "??", "???=": "???",
}

// parseStatement returns the statement node and whether it ended with a '}' (so no ';' needed).
func (p *Parser) parseStatement(topLevel bool) (*ASTNode, bool, error) {
	t := p.peek()
	if t.typ == TK_IDENT {
		switch t.text {
		case "begin", "end":
			p.advance()
			block, err := p.parseBracedBlock()
			if err != nil {
				return nil, false, err
			}
			return newNode(t.text+" block", "", block), true, nil
		case "func":
			// function definition (named) vs function literal (unnamed) in expression context
			if p.peekAt(1).typ == TK_IDENT {
				return p.parseFuncDef()
			}
		case "subr":
			return p.parseSubrDef()
		case "call":
			p.advance()
			nameTok := p.advance()
			if nameTok.typ != TK_IDENT {
				return nil, false, p.errorAtToken(nameTok)
			}
			args, err := p.parseArgList()
			if err != nil {
				return nil, false, err
			}
			n := newNode("subroutine callsite", nameTok.text)
			n.children = args
			return n, false, nil
		case "if":
			return p.parseIf()
		case "while":
			p.advance()
			if err := p.expectPunct("("); err != nil {
				return nil, false, err
			}
			cond, err := p.parseExpr()
			if err != nil {
				return nil, false, err
			}
			if err := p.expectPunct(")"); err != nil {
				return nil, false, err
			}
			block, err := p.parseBracedBlock()
			if err != nil {
				return nil, false, err
			}
			return newNode("while loop", "while", cond, block), true, nil
		case "do":
			p.advance()
			block, err := p.parseBracedBlock()
			if err != nil {
				return nil, false, err
			}
			if err := p.expectIdent("while"); err != nil {
				return nil, false, err
			}
			if err := p.expectPunct("("); err != nil {
				return nil, false, err
			}
			cond, err := p.parseExpr()
			if err != nil {
				return nil, false, err
			}
			if err := p.expectPunct(")"); err != nil {
				return nil, false, err
			}
			return newNode("do-while`loop", "do", block, cond), false, nil
		case "for":
			return p.parseFor()
		case "break":
			p.advance()
			return newNode("break", "break"), false, nil
		case "continue":
			p.advance()
			return newNode("continue", "continue"), false, nil
		case "return":
			p.advance()
			nt := p.peek()
			if nt.typ == TK_EOF || (nt.typ == TK_PUNCT && (nt.text == ";" || nt.text == "}")) {
				return newNode("return", "return"), false, nil
			}
			e, err := p.parseExpr()
			if err != nil {
				return nil, false, err
			}
			return newNode("return", "return", e), false, nil
		case "unset":
			p.advance()
			n := newNode("unset", "unset")
			for {
				if p.isIdent("all") {
					p.advance()
					n.children = append(n.children, newNode("full oosvar", "all"))
				} else {
					e, err := p.parseExpr()
					if err != nil {
						return nil, false, err
					}
					n.children = append(n.children, e)
				}
				if p.isPunct(",") {
					p.advance()
					continue
				}
				break
			}
			return n, false, nil
		case "filter":
			p.advance()
			e, err := p.parseExpr()
			if err != nil {
				return nil, false, err
			}
			return newNode("filter statement", "filter", e), false, nil
		case "emit1":
			p.advance()
			e, err := p.parseExpr()
			if err != nil {
				return nil, false, err
			}
			return newNode("emit1 statement", "emit1", e), false, nil
		case "emit", "emitp":
			return p.parseEmit(t.text)
		case "emitf":
			return p.parseEmitf()
		case "tee":
			p.advance()
			redirect, err := p.parseRedirect()
			if err != nil {
				return nil, false, err
			}
			if redirect == nil {
				return nil, false, p.errorAtToken(p.peek())
			}
			if err := p.expectPunct(","); err != nil {
				return nil, false, err
			}
			e, err := p.parseExpr()
			if err != nil {
				return nil, false, err
			}
			return newNode("tee statement", "tee", e, redirect), false, nil
		case "print", "printn", "eprint", "eprintn":
			return p.parsePrint(t.text)
		case "dump", "edump":
			return p.parseDump(t.text)
		case "elif", "else":
			return nil, false, p.errorAtToken(t)
		}
		// Typed local declaration
		if typeDeclKeywords[t.text] && p.peekAt(1).typ == TK_IDENT {
			p.advance()
			nameTok := p.advance()
			lhs := newNode("local variable", nameTok.text, newNode("type declaration", t.text))
			if !p.isPunct("=") {
				return nil, false, p.errorAtToken(p.peek())
			}
			p.advance()
			rhs, err := p.parseExpr()
			if err != nil {
				return nil, false, err
			}
			return newNode("assignment", "=", lhs, rhs), false, nil
		}
	}

	// Expression-based: assignment, bare boolean, or cond block
	lhs, err := p.parseExpr()
	if err != nil {
		return nil, false, err
	}
	nt := p.peek()
	if nt.typ == TK_PUNCT {
		if op, ok := assignmentOps[nt.text]; ok {
			if !isAssignable(lhs) {
				return nil, false, p.errorAtToken(nt)
			}
			p.advance()
			rhs, err := p.parseExpr()
			if err != nil {
				return nil, false, err
			}
			if op == "" {
				return newNode("assignment", "=", lhs, rhs), false, nil
			}
			var opnode *ASTNode
			if op == "." {
				opnode = newNode("dot operator", ".", lhs, rhs)
			} else {
				opnode = newNode("operator", op, lhs, rhs)
			}
			return newNode("assignment", "=", lhs, opnode), false, nil
		}
		if nt.text == "{" {
			block, err := p.parseBracedBlock()
			if err != nil {
				return nil, false, err
			}
			return newNode("cond block", "", lhs, block), true, nil
		}
	}
	return newNode("bare boolean", "", lhs), false, nil
}

func isAssignable(n *ASTNode) bool {
	switch n.typ {
	case "direct field value", "indirect field value", "full record", "direct oosvar value", "indirect oosvar value",
		"full oosvar", "local variable", "positionally-indexed field name", "positionally-indexed field value",
		"array or map index access", "environment variable":
		return true
	}
	return false
}

func (p *Parser) parseFuncDef() (*ASTNode, bool, error) {
	p.advance() // func
	nameTok := p.advance()
	params, err := p.parseParamList()
	if err != nil {
		return nil, false, err
	}
	var retType *ASTNode
	if p.isPunct(":") {
		p.advance()
		tt := p.advance()
		if tt.typ != TK_IDENT {
			return nil, false, p.errorAtToken(tt)
		}
		retType = newNode("type declaration", tt.text)
	}
	block, err := p.parseBracedBlock()
	if err != nil {
		return nil, false, err
	}
	n := newNode("function definition", nameTok.text, params, block)
	if retType != nil {
		n.children = append(n.children, retType)
	}
	return n, true, nil
}

func (p *Parser) parseSubrDef() (*ASTNode, bool, error) {
	p.advance() // subr
	nameTok := p.advance()
	if nameTok.typ != TK_IDENT {
		return nil, false, p.errorAtToken(nameTok)
	}
	params, err := p.parseParamList()
	if err != nil {
		return nil, false, err
	}
	block, err := p.parseBracedBlock()
	if err != nil {
		return nil, false, err
	}
	return newNode("subroutine definition", nameTok.text, params, block), true, nil
}

func (p *Parser) parseParamList() (*ASTNode, error) {
	if err := p.expectPunct("("); err != nil {
		return nil, err
	}
	list := newNode("parameter list", "")
	if p.isPunct(")") {
		p.advance()
		return list, nil
	}
	for {
		t := p.advance()
		if t.typ != TK_IDENT {
			return nil, p.errorAtToken(t)
		}
		var param *ASTNode
		if typeDeclKeywords[t.text] && p.peek().typ == TK_IDENT {
			nameTok := p.advance()
			param = newNode("parameter", "", newNode("parameter name", nameTok.text, newNode("type declaration", t.text)))
		} else {
			param = newNode("parameter", "", newNode("parameter name", t.text))
		}
		list.children = append(list.children, param)
		if p.isPunct(",") {
			p.advance()
			continue
		}
		if err := p.expectPunct(")"); err != nil {
			return nil, err
		}
		return list, nil
	}
}

func (p *Parser) parseArgList() ([]*ASTNode, error) {
	if err := p.expectPunct("("); err != nil {
		return nil, err
	}
	var args []*ASTNode
	if p.isPunct(")") {
		p.advance()
		return args, nil
	}
	for {
		e, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		args = append(args, e)
		if p.isPunct(",") {
			p.advance()
			if p.isPunct(")") {
				p.advance()
				return args, nil
			}
			continue
		}
		if err := p.expectPunct(")"); err != nil {
			return nil, err
		}
		return args, nil
	}
}

func (p *Parser) parseIf() (*ASTNode, bool, error) {
	chain := newNode("if-chain", "")
	p.advance() // if
	if err := p.expectPunct("("); err != nil {
		return nil, false, err
	}
	cond, err := p.parseExpr()
	if err != nil {
		return nil, false, err
	}
	if err := p.expectPunct(")"); err != nil {
		return nil, false, err
	}
	block, err := p.parseBracedBlock()
	if err != nil {
		return nil, false, err
	}
	chain.children = append(chain.children, newNode("if-item", "if", cond, block))
	for {
		if p.isIdent("elif") {
			p.advance()
			if err := p.expectPunct("("); err != nil {
				return nil, false, err
			}
			cond, err := p.parseExpr()
			if err != nil {
				return nil, false, err
			}
			if err := p.expectPunct(")"); err != nil {
				return nil, false, err
			}
			block, err := p.parseBracedBlock()
			if err != nil {
				return nil, false, err
			}
			chain.children = append(chain.children, newNode("if-item", "elif", cond, block))
			continue
		}
		if p.isIdent("else") {
			p.advance()
			block, err := p.parseBracedBlock()
			if err != nil {
				return nil, false, err
			}
			chain.children = append(chain.children, newNode("if-item", "else", block))
		}
		break
	}
	return chain, true, nil
}

func (p *Parser) parseFor() (*ASTNode, bool, error) {
	p.advance() // for
	if err := p.expectPunct("("); err != nil {
		return nil, false, err
	}
	// Multi-key: for ((k1, k2), v in ...)
	if p.isPunct("(") {
		p.advance()
		keys := newNode("parameter list", "")
		for {
			t := p.advance()
			if t.typ != TK_IDENT {
				return nil, false, p.errorAtToken(t)
			}
			keys.children = append(keys.children, newNode("local variable", t.text))
			if p.isPunct(",") {
				p.advance()
				continue
			}
			break
		}
		if err := p.expectPunct(")"); err != nil {
			return nil, false, err
		}
		if err := p.expectPunct(","); err != nil {
			return nil, false, err
		}
		vt := p.advance()
		if vt.typ != TK_IDENT {
			return nil, false, p.errorAtToken(vt)
		}
		if err := p.expectIdent("in"); err != nil {
			return nil, false, err
		}
		coll, err := p.parseExpr()
		if err != nil {
			return nil, false, err
		}
		if err := p.expectPunct(")"); err != nil {
			return nil, false, err
		}
		block, err := p.parseBracedBlock()
		if err != nil {
			return nil, false, err
		}
		return newNode("multi-variable for-loop", "for", keys, newNode("local variable", vt.text), coll, block), true, nil
	}
	// Key-value or single-variable: for (k, v in ...) / for (e in ...)
	if p.peek().typ == TK_IDENT && !typeDeclKeywords[p.peek().text] {
		t1 := p.peek()
		t2 := p.peekAt(1)
		if t2.typ == TK_PUNCT && t2.text == "," && p.peekAt(2).typ == TK_IDENT && p.peekAt(3).typ == TK_IDENT && p.peekAt(3).text == "in" {
			p.advance()
			p.advance()
			vt := p.advance()
			p.advance() // in
			coll, err := p.parseExpr()
			if err != nil {
				return nil, false, err
			}
			if err := p.expectPunct(")"); err != nil {
				return nil, false, err
			}
			block, err := p.parseBracedBlock()
			if err != nil {
				return nil, false, err
			}
			return newNode("double-variable for-loop", "for", newNode("local variable", t1.text), newNode("local variable", vt.text), coll, block), true, nil
		}
		if t2.typ == TK_IDENT && t2.text == "in" {
			p.advance()
			p.advance()
			coll, err := p.parseExpr()
			if err != nil {
				return nil, false, err
			}
			if err := p.expectPunct(")"); err != nil {
				return nil, false, err
			}
			block, err := p.parseBracedBlock()
			if err != nil {
				return nil, false, err
			}
			return newNode("single-variable for-loop", "for", newNode("local variable", t1.text), coll, block), true, nil
		}
	}
	// Triple-for
	initBlock := newNode("statement block", "")
	if !p.isPunct(";") {
		for {
			stmt, _, err := p.parseStatement(false)
			if err != nil {
				return nil, false, err
			}
			initBlock.children = append(initBlock.children, stmt)
			if p.isPunct(",") {
				p.advance()
				continue
			}
			break
		}
	}
	if err := p.expectPunct(";"); err != nil {
		return nil, false, err
	}
	condBlock := newNode("statement block", "")
	if !p.isPunct(";") {
		cond, err := p.parseExpr()
		if err != nil {
			return nil, false, err
		}
		condBlock.children = append(condBlock.children, newNode("bare boolean", "", cond))
	}
	if err := p.expectPunct(";"); err != nil {
		return nil, false, err
	}
	updateBlock := newNode("statement block", "")
	if !p.isPunct(")") {
		for {
			stmt, _, err := p.parseStatement(false)
			if err != nil {
				return nil, false, err
			}
			updateBlock.children = append(updateBlock.children, stmt)
			if p.isPunct(",") {
				p.advance()
				continue
			}
			break
		}
	}
	if err := p.expectPunct(")"); err != nil {
		return nil, false, err
	}
	body, err := p.parseBracedBlock()
	if err != nil {
		return nil, false, err
	}
	return newNode("triple-for loop", "for", initBlock, condBlock, updateBlock, body), true, nil
}

// parseRedirect parses an optional "> target", ">> target", "| target".
func (p *Parser) parseRedirect() (*ASTNode, error) {
	t := p.peek()
	if t.typ != TK_PUNCT {
		return nil, nil
	}
	var typ string
	switch t.text {
	case ">":
		typ = "redirect write"
	case ">>":
		typ = "redirect append"
	case "|":
		typ = "redirect pipe"
	default:
		return nil, nil
	}
	p.advance()
	var target *ASTNode
	if p.isIdent("stderr") {
		p.advance()
		target = newNode("stderr redirect target", "stderr")
	} else if p.isIdent("stdout") {
		p.advance()
		target = newNode("stdout redirect target", "stdout")
	} else {
		e, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		target = e
	}
	return newNode(typ, t.text, target), nil
}

func noOp() *ASTNode { return newNode("no-op", "") }

func (p *Parser) parseEmit(kw string) (*ASTNode, bool, error) {
	p.advance()
	redirect, err := p.parseRedirect()
	if err != nil {
		return nil, false, err
	}
	if redirect != nil {
		if err := p.expectPunct(","); err != nil {
			return nil, false, err
		}
	}
	emittables := newNode("emittable list", "")
	if p.isPunct("(") {
		// lashed
		p.advance()
		for {
			e, err := p.parseEmittable()
			if err != nil {
				return nil, false, err
			}
			emittables.children = append(emittables.children, e)
			if p.isPunct(",") {
				p.advance()
				continue
			}
			break
		}
		if err := p.expectPunct(")"); err != nil {
			return nil, false, err
		}
	} else {
		e, err := p.parseEmittable()
		if err != nil {
			return nil, false, err
		}
		emittables.children = append(emittables.children, e)
	}
	var keys *ASTNode
	if p.isPunct(",") {
		p.advance()
		keys = newNode("emit keys", "")
		for {
			e, err := p.parseExpr()
			if err != nil {
				return nil, false, err
			}
			keys.children = append(keys.children, e)
			if p.isPunct(",") {
				p.advance()
				continue
			}
			break
		}
	}
	n := newNode(kw+" statement", kw, emittables)
	if keys != nil {
		n.children = append(n.children, keys)
	} else {
		n.children = append(n.children, noOp())
	}
	if redirect != nil {
		n.children = append(n.children, redirect)
	} else {
		n.children = append(n.children, noOp())
	}
	return n, false, nil
}

func (p *Parser) parseEmittable() (*ASTNode, error) {
	if p.isIdent("all") {
		p.advance()
		return newNode("full oosvar", "all"), nil
	}
	t := p.peek()
	if t.typ == TK_IDENT && p.peekAt(1).typ == TK_PUNCT && p.peekAt(1).text == "(" {
		// function call: not an emittable in Miller, but allow for mapsum etc.
		return nil, p.errorAtToken(p.peekAt(1))
	}
	e, err := p.parsePostfix()
	if err != nil {
		return nil, err
	}
	switch e.typ {
	case "direct oosvar value", "indirect oosvar value", "full oosvar", "full record", "local variable", "map literal", "array or map index access", "direct field value", "indirect field value":
		return e, nil
	}
	return nil, p.errorAtToken(t)
}

func (p *Parser) parseEmitf() (*ASTNode, bool, error) {
	p.advance()
	redirect, err := p.parseRedirect()
	if err != nil {
		return nil, false, err
	}
	if redirect != nil {
		if err := p.expectPunct(","); err != nil {
			return nil, false, err
		}
	}
	emittables := newNode("emittable list", "")
	for {
		e, err := p.parsePostfix()
		if err != nil {
			return nil, false, err
		}
		emittables.children = append(emittables.children, e)
		if p.isPunct(",") {
			p.advance()
			continue
		}
		break
	}
	n := newNode("emitf statement", "emitf", emittables)
	if redirect != nil {
		n.children = append(n.children, redirect)
	} else {
		n.children = append(n.children, noOp())
	}
	return n, false, nil
}

func (p *Parser) parsePrint(kw string) (*ASTNode, bool, error) {
	p.advance()
	redirect, err := p.parseRedirect()
	if err != nil {
		return nil, false, err
	}
	if redirect != nil {
		if err := p.expectPunct(","); err != nil {
			return nil, false, err
		}
	}
	callsite := newNode("function callsite", "")
	nt := p.peek()
	if !(nt.typ == TK_EOF || (nt.typ == TK_PUNCT && (nt.text == ";" || nt.text == "}"))) {
		for {
			e, err := p.parseExpr()
			if err != nil {
				return nil, false, err
			}
			callsite.children = append(callsite.children, e)
			if p.isPunct(",") {
				p.advance()
				continue
			}
			break
		}
	}
	n := newNode(kw+" statement", kw, callsite)
	if redirect != nil {
		n.children = append(n.children, redirect)
	} else {
		n.children = append(n.children, noOp())
	}
	return n, false, nil
}

func (p *Parser) parseDump(kw string) (*ASTNode, bool, error) {
	p.advance()
	redirect, err := p.parseRedirect()
	if err != nil {
		return nil, false, err
	}
	if redirect != nil {
		if err := p.expectPunct(","); err != nil {
			return nil, false, err
		}
	}
	n := newNode(kw+" statement", kw)
	nt := p.peek()
	if !(nt.typ == TK_EOF || (nt.typ == TK_PUNCT && (nt.text == ";" || nt.text == "}"))) {
		e, err := p.parseExpr()
		if err != nil {
			return nil, false, err
		}
		n.children = append(n.children, newNode("function callsite", "", e))
	} else {
		n.children = append(n.children, noOp())
	}
	if redirect != nil {
		n.children = append(n.children, redirect)
	} else {
		n.children = append(n.children, noOp())
	}
	return n, false, nil
}

// ---------------------------------------------------------------- expressions

func (p *Parser) parseExpr() (*ASTNode, error) {
	return p.parseTernary()
}

func (p *Parser) parseTernary() (*ASTNode, error) {
	cond, err := p.parseLogicalOr()
	if err != nil {
		return nil, err
	}
	if p.isPunct("?") {
		p.advance()
		a, err := p.parseTernary()
		if err != nil {
			return nil, err
		}
		if err := p.expectPunct(":"); err != nil {
			return nil, err
		}
		b, err := p.parseTernary()
		if err != nil {
			return nil, err
		}
		return newNode("operator", "?:", cond, a, b), nil
	}
	return cond, nil
}

func (p *Parser) parseBinaryLevel(ops []string, next func() (*ASTNode, error)) (*ASTNode, error) {
	lhs, err := next()
	if err != nil {
		return nil, err
	}
	for {
		t := p.peek()
		if t.typ != TK_PUNCT {
			return lhs, nil
		}
		matched := false
		for _, op := range ops {
			if t.text == op {
				matched = true
				break
			}
		}
		if !matched {
			return lhs, nil
		}
		p.advance()
		rhs, err := next()
		if err != nil {
			return nil, err
		}
		if t.text == "." {
			lhs = newNode("dot operator", ".", lhs, rhs)
		} else {
			lhs = newNode("operator", t.text, lhs, rhs)
		}
	}
}

func (p *Parser) parseLogicalOr() (*ASTNode, error) {
	return p.parseBinaryLevel([]string{"||"}, p.parseLogicalXor)
}
func (p *Parser) parseLogicalXor() (*ASTNode, error) {
	return p.parseBinaryLevel([]string{"^^"}, p.parseLogicalAnd)
}
func (p *Parser) parseLogicalAnd() (*ASTNode, error) {
	return p.parseBinaryLevel([]string{"&&"}, p.parseEquality)
}
func (p *Parser) parseEquality() (*ASTNode, error) {
	return p.parseBinaryLevel([]string{"==", "!=", "=~", "!=~", "<=>"}, p.parseRelational)
}
func (p *Parser) parseRelational() (*ASTNode, error) {
	return p.parseBinaryLevel([]string{"<", "<=", ">", ">="}, p.parseBitOr)
}
func (p *Parser) parseBitOr() (*ASTNode, error) {
	return p.parseBinaryLevel([]string{"|"}, p.parseBitXor)
}
func (p *Parser) parseBitXor() (*ASTNode, error) {
	return p.parseBinaryLevel([]string{"^"}, p.parseBitAnd)
}
func (p *Parser) parseBitAnd() (*ASTNode, error) {
	return p.parseBinaryLevel([]string{"&"}, p.parseShift)
}
func (p *Parser) parseShift() (*ASTNode, error) {
	return p.parseBinaryLevel([]string{"<<", ">>", ">>>"}, p.parseAdditive)
}
func (p *Parser) parseAdditive() (*ASTNode, error) {
	return p.parseBinaryLevel([]string{"+", "-", ".+", ".-"}, p.parseMultiplicative)
}
func (p *Parser) parseMultiplicative() (*ASTNode, error) {
	return p.parseBinaryLevel([]string{"*", "/", "//", "%", ".*", "./", ".//"}, p.parseDot)
}
func (p *Parser) parseDot() (*ASTNode, error) {
	return p.parseBinaryLevel([]string{"."}, p.parseUnary)
}

func (p *Parser) parseUnary() (*ASTNode, error) {
	t := p.peek()
	if t.typ == TK_PUNCT && (t.text == "!" || t.text == "~" || t.text == "+" || t.text == "-") {
		p.advance()
		operand, err := p.parseUnary()
		if err != nil {
			return nil, err
		}
		return newNode("operator", t.text, operand), nil
	}
	return p.parseCoalesce()
}

func (p *Parser) parseCoalesce() (*ASTNode, error) {
	return p.parseBinaryLevel([]string{"??", "???"}, p.parsePower)
}

func (p *Parser) parsePower() (*ASTNode, error) {
	lhs, err := p.parsePostfix()
	if err != nil {
		return nil, err
	}
	if p.isPunct("**") {
		p.advance()
		rhs, err := p.parsePowerRHS()
		if err != nil {
			return nil, err
		}
		return newNode("operator", "**", lhs, rhs), nil
	}
	return lhs, nil
}

func (p *Parser) parsePowerRHS() (*ASTNode, error) {
	t := p.peek()
	if t.typ == TK_PUNCT && (t.text == "!" || t.text == "~" || t.text == "+" || t.text == "-") {
		p.advance()
		operand, err := p.parsePowerRHS()
		if err != nil {
			return nil, err
		}
		return newNode("operator", t.text, operand), nil
	}
	return p.parsePower()
}

func (p *Parser) parsePostfix() (*ASTNode, error) {
	n, err := p.parsePrimary()
	if err != nil {
		return nil, err
	}
	for {
		if p.isPunct("[") {
			p.advance()
			// slice with empty start: [:n]
			if p.isPunct(":") {
				p.advance()
				var hi *ASTNode
				if p.isPunct("]") {
					hi = newNode("int literal", "")
					hi.mv = ABSENT
				} else {
					hi, err = p.parseExpr()
					if err != nil {
						return nil, err
					}
				}
				if err := p.expectPunct("]"); err != nil {
					return nil, err
				}
				lo := newNode("int literal", "")
				lo.mv = ABSENT
				n = newNode("array-slice access", "[]", n, lo, hi)
				continue
			}
			idx, err := p.parseExpr()
			if err != nil {
				return nil, err
			}
			if p.isPunct(":") {
				p.advance()
				var hi *ASTNode
				if p.isPunct("]") {
					hi = newNode("int literal", "")
					hi.mv = ABSENT
				} else {
					hi, err = p.parseExpr()
					if err != nil {
						return nil, err
					}
				}
				if err := p.expectPunct("]"); err != nil {
					return nil, err
				}
				n = newNode("array-slice access", "[]", n, idx, hi)
				continue
			}
			if err := p.expectPunct("]"); err != nil {
				return nil, err
			}
			n = newNode("array or map index access", "[]", n, idx)
			continue
		}
		break
	}
	return n, nil
}

var contextVarNames = map[string]bool{
	"NR": true, "FNR": true, "NF": true, "FILENAME": true, "FILENUM": true,
	"IPS": true, "IFS": true, "IRS": true, "OPS": true, "OFS": true, "ORS": true, "FLATSEP": true,
}

func (p *Parser) parsePrimary() (*ASTNode, error) {
	t := p.peek()
	switch t.typ {
	case TK_NUMBER:
		p.advance()
		mv := FromDSLNumberLiteral(t.text)
		var n *ASTNode
		if mv.Type() == MT_INT {
			n = newNode("int literal", t.text)
		} else if mv.Type() == MT_FLOAT {
			n = newNode("float literal", t.text)
		} else {
			return nil, p.errorAtToken(t)
		}
		n.mv = mv
		return n, nil
	case TK_STRING:
		p.advance()
		n := newNode("string literal", t.text)
		return n, nil
	case TK_REGEXI:
		p.advance()
		n := newNode("case-insensitive regular expression", "\""+t.text+"\"i")
		return n, nil
	case TK_FIELD:
		p.advance()
		return newNode("direct field value", t.text), nil
	case TK_FULL_SREC:
		p.advance()
		return newNode("full record", "$*"), nil
	case TK_FIELD_INDIRECT:
		p.advance()
		e, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		if err := p.expectPunct("]"); err != nil {
			return nil, err
		}
		return newNode("indirect field value", "$[]", e), nil
	case TK_FIELD_POSNAME:
		p.advance()
		e, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		if err := p.expectPunct("]"); err != nil {
			return nil, err
		}
		if err := p.expectPunct("]"); err != nil {
			return nil, err
		}
		return newNode("positionally-indexed field name", "$[]", e), nil
	case TK_FIELD_POSVALUE:
		p.advance()
		e, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		for i := 0; i < 3; i++ {
			if err := p.expectPunct("]"); err != nil {
				return nil, err
			}
		}
		return newNode("positionally-indexed field value", "$[]", e), nil
	case TK_OOSVAR:
		p.advance()
		return newNode("direct oosvar value", t.text), nil
	case TK_FULL_OOSVAR:
		p.advance()
		return newNode("full oosvar", "@*"), nil
	case TK_OOSVAR_INDIRECT:
		p.advance()
		e, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		if err := p.expectPunct("]"); err != nil {
			return nil, err
		}
		return newNode("indirect oosvar value", "@[]", e), nil
	case TK_PUNCT:
		switch t.text {
		case "(":
			p.advance()
			e, err := p.parseExpr()
			if err != nil {
				return nil, err
			}
			if err := p.expectPunct(")"); err != nil {
				return nil, err
			}
			return e, nil
		case "{":
			return p.parseMapLiteral()
		case "[":
			return p.parseArrayLiteral()
		}
		return nil, p.errorAtToken(t)
	case TK_IDENT:
		switch t.text {
		case "true", "false":
			p.advance()
			n := newNode("bool literal", t.text)
			n.mv = FromBool(t.text == "true")
			return n, nil
		case "null":
			p.advance()
			n := newNode("null literal", "null")
			return n, nil
		case "Inf":
			p.advance()
			n := newNode("float literal", "Inf")
			n.mv = FromFloatWithRep(posInf(), "+Inf")
			return n, nil
		case "NaN":
			p.advance()
			n := newNode("float literal", "NaN")
			n.mv = FromFloatWithRep(nanValue(), "NaN")
			return n, nil
		case "M_PI", "M_E":
			p.advance()
			return newNode("mathematical constant", t.text), nil
		case "ENV":
			p.advance()
			if p.isPunct("[") {
				p.advance()
				e, err := p.parseExpr()
				if err != nil {
					return nil, err
				}
				if err := p.expectPunct("]"); err != nil {
					return nil, err
				}
				return newNode("environment variable", "ENV", e), nil
			}
			return newNode("environment variable", "ENV"), nil
		case "all":
			p.advance()
			return newNode("full oosvar", "all"), nil
		case "func":
			p.advance()
			params, err := p.parseParamList()
			if err != nil {
				return nil, err
			}
			var retType *ASTNode
			if p.isPunct(":") {
				p.advance()
				tt := p.advance()
				retType = newNode("type declaration", tt.text)
			}
			block, err := p.parseBracedBlock()
			if err != nil {
				return nil, err
			}
			n := newNode("function literal", "func", params, block)
			if retType != nil {
				n.children = append(n.children, retType)
			}
			return n, nil
		}
		if contextVarNames[t.text] {
			p.advance()
			return newNode("context variable", t.text), nil
		}
		p.advance()
		if p.isPunct("(") {
			args, err := p.parseArgList()
			if err != nil {
				return nil, err
			}
			n := newNode("function callsite", t.text)
			n.children = args
			return n, nil
		}
		return newNode("local variable", t.text), nil
	}
	return nil, p.errorAtToken(t)
}

func (p *Parser) parseMapLiteral() (*ASTNode, error) {
	p.advance() // {
	n := newNode("map literal", "{}")
	if p.isPunct("}") {
		p.advance()
		return n, nil
	}
	for {
		k, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		if err := p.expectPunct(":"); err != nil {
			return nil, err
		}
		v, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		n.children = append(n.children, newNode("map-literal key-value pair", ":", k, v))
		if p.isPunct(",") {
			p.advance()
			if p.isPunct("}") {
				p.advance()
				return n, nil
			}
			continue
		}
		if err := p.expectPunct("}"); err != nil {
			return nil, err
		}
		return n, nil
	}
}

func (p *Parser) parseArrayLiteral() (*ASTNode, error) {
	p.advance() // [
	n := newNode("array literal", "[]")
	if p.isPunct("]") {
		p.advance()
		return n, nil
	}
	for {
		e, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		n.children = append(n.children, e)
		if p.isPunct(",") {
			p.advance()
			if p.isPunct("]") {
				p.advance()
				return n, nil
			}
			continue
		}
		if err := p.expectPunct("]"); err != nil {
			return nil, err
		}
		return n, nil
	}
}

func stripQuotes(s string) string {
	return strings.TrimSuffix(strings.TrimPrefix(s, "\""), "\"")
}
