package main

import (
	"math"
	"strings"
)

func posInf() float64  { return math.Inf(1) }
func nanValue() float64 { return math.NaN() }

// ---------------------------------------------------------------- helpers

// numeric pair extraction
func bothInts(a, b *Mlrval) bool { return a.Type() == MT_INT && b.Type() == MT_INT }

func asFloat(v *Mlrval) float64 {
	if v.Type() == MT_INT {
		return float64(v.intval)
	}
	return v.floatval
}

// dispositionCommon handles error/absent/void for binary arithmetic. Returns
// (result, handled).
func arithPrelude(a, b *Mlrval) (*Mlrval, bool) {
	ta := a.Type()
	tb := b.Type()
	if ta == MT_ERROR || tb == MT_ERROR {
		return ERROR, true
	}
	aNum := ta == MT_INT || ta == MT_FLOAT
	bNum := tb == MT_INT || tb == MT_FLOAT
	if aNum && bNum {
		return nil, false
	}
	// absent/void combos
	if ta == MT_ABSENT {
		if tb == MT_ABSENT || tb == MT_VOID {
			return ABSENT, true
		}
		if bNum {
			return b, true
		}
		return ERROR, true
	}
	if tb == MT_ABSENT {
		if ta == MT_VOID {
			return ABSENT, true
		}
		if aNum {
			return a, true
		}
		return ERROR, true
	}
	if ta == MT_VOID {
		if tb == MT_VOID {
			return VOID, true
		}
		if bNum {
			return b, true
		}
		return ERROR, true
	}
	if tb == MT_VOID {
		if aNum {
			return a, true
		}
		return ERROR, true
	}
	return ERROR, true
}

// ---------------------------------------------------------------- + - *

func binaryOpPlus(a, b *Mlrval) *Mlrval {
	if r, ok := arithPrelude(a, b); ok {
		return r
	}
	if bothInts(a, b) {
		x, y := a.intval, b.intval
		s := x + y
		// overflow check
		if (x >= 0 && y >= 0 && s < 0) || (x < 0 && y < 0 && s >= 0) {
			return FromFloat(float64(x) + float64(y))
		}
		return FromInt(s)
	}
	return FromFloat(asFloat(a) + asFloat(b))
}

func binaryOpMinus(a, b *Mlrval) *Mlrval {
	ta, tb := a.Type(), b.Type()
	if ta == MT_VOID && (tb == MT_INT || tb == MT_FLOAT) {
		return unaryOpMinus(b)
	}
	if r, ok := arithPrelude(a, b); ok {
		return r
	}
	if bothInts(a, b) {
		x, y := a.intval, b.intval
		s := x - y
		if (x >= 0 && y < 0 && s < 0) || (x < 0 && y >= 0 && s >= 0) {
			return FromFloat(float64(x) - float64(y))
		}
		return FromInt(s)
	}
	return FromFloat(asFloat(a) - asFloat(b))
}

func binaryOpTimes(a, b *Mlrval) *Mlrval {
	if r, ok := arithPrelude(a, b); ok {
		return r
	}
	if bothInts(a, b) {
		x, y := a.intval, b.intval
		p := x * y
		// overflow check via float
		fp := float64(x) * float64(y)
		if x != 0 && (p/x != y || math.Abs(fp) >= 9.223372036854775807e18) {
			return FromFloat(fp)
		}
		return FromInt(p)
	}
	return FromFloat(asFloat(a) * asFloat(b))
}

// Dot-operators: integer-preserving
func binaryOpDotPlus(a, b *Mlrval) *Mlrval {
	if r, ok := arithPrelude(a, b); ok {
		return r
	}
	if bothInts(a, b) {
		return FromInt(a.intval + b.intval)
	}
	return FromFloat(asFloat(a) + asFloat(b))
}

func binaryOpDotMinus(a, b *Mlrval) *Mlrval {
	if r, ok := arithPrelude(a, b); ok {
		return r
	}
	if bothInts(a, b) {
		return FromInt(a.intval - b.intval)
	}
	return FromFloat(asFloat(a) - asFloat(b))
}

func binaryOpDotTimes(a, b *Mlrval) *Mlrval {
	if r, ok := arithPrelude(a, b); ok {
		return r
	}
	if bothInts(a, b) {
		return FromInt(a.intval * b.intval)
	}
	return FromFloat(asFloat(a) * asFloat(b))
}

func binaryOpDotDivide(a, b *Mlrval) *Mlrval {
	if r, ok := divPrelude(a, b); ok {
		return r
	}
	if bothInts(a, b) {
		if b.intval == 0 {
			return FromFloat(float64(a.intval) / float64(b.intval))
		}
		return FromInt(a.intval / b.intval)
	}
	return FromFloat(asFloat(a) / asFloat(b))
}

// For / ** % //: absent on left with number on right gives int 0 (Miller quirk);
// void yields void.
func divPrelude(a, b *Mlrval) (*Mlrval, bool) {
	ta, tb := a.Type(), b.Type()
	if ta == MT_ERROR || tb == MT_ERROR {
		return ERROR, true
	}
	aNum := ta == MT_INT || ta == MT_FLOAT
	bNum := tb == MT_INT || tb == MT_FLOAT
	if aNum && bNum {
		return nil, false
	}
	if ta == MT_ABSENT {
		if tb == MT_ABSENT {
			return ABSENT, true
		}
		if tb == MT_VOID {
			return ABSENT, true
		}
		if bNum {
			return FromInt(0), true
		}
		return ERROR, true
	}
	if tb == MT_ABSENT {
		if ta == MT_VOID {
			return ABSENT, true
		}
		if aNum {
			return a, true
		}
		return ERROR, true
	}
	if ta == MT_VOID {
		if tb == MT_VOID || bNum {
			return VOID, true
		}
		return ERROR, true
	}
	if tb == MT_VOID {
		if aNum {
			return VOID, true
		}
		return ERROR, true
	}
	return ERROR, true
}

func binaryOpDivide(a, b *Mlrval) *Mlrval {
	if r, ok := divPrelude(a, b); ok {
		return r
	}
	if bothInts(a, b) {
		x, y := a.intval, b.intval
		if y == 0 {
			return FromFloat(float64(x) / float64(y))
		}
		if x%y == 0 {
			return FromInt(x / y)
		}
		return FromFloat(float64(x) / float64(y))
	}
	return FromFloat(asFloat(a) / asFloat(b))
}

func binaryOpIntDivide(a, b *Mlrval) *Mlrval {
	if r, ok := divPrelude(a, b); ok {
		return r
	}
	if bothInts(a, b) {
		x, y := a.intval, b.intval
		if y == 0 {
			return FromFloat(math.Floor(float64(x) / float64(y)))
		}
		q := x / y
		if (x%y != 0) && ((x < 0) != (y < 0)) {
			q--
		}
		return FromInt(q)
	}
	return FromFloat(math.Floor(asFloat(a) / asFloat(b)))
}

func binaryOpModulus(a, b *Mlrval) *Mlrval {
	if r, ok := divPrelude(a, b); ok {
		return r
	}
	if bothInts(a, b) {
		x, y := a.intval, b.intval
		if y == 0 {
			return FromFloat(math.NaN())
		}
		m := x % y
		if m != 0 && ((m < 0) != (y < 0)) {
			m += y
		}
		return FromInt(m)
	}
	x, y := asFloat(a), asFloat(b)
	m := math.Mod(x, y)
	if m != 0 && ((m < 0) != (y < 0)) {
		m += y
	}
	return FromFloat(m)
}

func binaryOpPow(a, b *Mlrval) *Mlrval {
	if r, ok := divPrelude(a, b); ok {
		return r
	}
	if bothInts(a, b) {
		x, y := a.intval, b.intval
		if y >= 0 {
			// integer power with overflow detection
			result := int64(1)
			base := x
			e := y
			overflow := false
			for e > 0 {
				if e&1 == 1 {
					r := result * base
					if base != 0 && r/base != result {
						overflow = true
						break
					}
					result = r
				}
				e >>= 1
				if e > 0 {
					nb := base * base
					if base != 0 && nb/base != base {
						overflow = true
						break
					}
					base = nb
				}
			}
			if !overflow {
				fp := math.Pow(float64(x), float64(y))
				if math.Abs(fp) < 9.223372036854775807e18 {
					return FromInt(result)
				}
			}
			return FromFloat(math.Pow(float64(x), float64(y)))
		}
		return FromFloat(math.Pow(float64(x), float64(y)))
	}
	return FromFloat(math.Pow(asFloat(a), asFloat(b)))
}

// ---------------------------------------------------------------- unary

func unaryOpMinus(a *Mlrval) *Mlrval {
	switch a.Type() {
	case MT_INT:
		return FromInt(-a.intval)
	case MT_FLOAT:
		return FromFloat(-a.floatval)
	case MT_ABSENT:
		return ABSENT
	case MT_VOID:
		return FromInt(0)
	}
	return ERROR
}

func unaryOpPlus(a *Mlrval) *Mlrval {
	switch a.Type() {
	case MT_INT, MT_FLOAT:
		return a
	case MT_ABSENT:
		return ABSENT
	case MT_VOID:
		return FromInt(0)
	}
	return ERROR
}

func unaryOpBitNot(a *Mlrval) *Mlrval {
	switch a.Type() {
	case MT_INT:
		return FromInt(^a.intval)
	case MT_ABSENT:
		return ABSENT
	case MT_VOID:
		return VOID
	}
	return ERROR
}

func unaryOpLogicalNot(a *Mlrval) *Mlrval {
	if a.Type() == MT_BOOLEAN {
		return FromBool(!a.boolval)
	}
	return ERROR
}

// ---------------------------------------------------------------- bitwise

func bitPrelude(a, b *Mlrval) (*Mlrval, bool) {
	ta, tb := a.Type(), b.Type()
	if ta == MT_ERROR || tb == MT_ERROR {
		return ERROR, true
	}
	if ta == MT_INT && tb == MT_INT {
		return nil, false
	}
	if ta == MT_ABSENT {
		if tb == MT_ABSENT {
			return ABSENT, true
		}
		if tb == MT_INT {
			return b, true
		}
		if tb == MT_VOID {
			return ABSENT, true
		}
		return ERROR, true
	}
	if tb == MT_ABSENT {
		if ta == MT_INT {
			return a, true
		}
		if ta == MT_VOID {
			return ABSENT, true
		}
		return ERROR, true
	}
	if ta == MT_VOID {
		if tb == MT_VOID || tb == MT_INT {
			return VOID, true
		}
		return ERROR, true
	}
	if tb == MT_VOID {
		if ta == MT_INT {
			return VOID, true
		}
		return ERROR, true
	}
	return ERROR, true
}

func binaryOpBitAnd(a, b *Mlrval) *Mlrval {
	if r, ok := bitPrelude(a, b); ok {
		return r
	}
	return FromInt(a.intval & b.intval)
}
func binaryOpBitOr(a, b *Mlrval) *Mlrval {
	if r, ok := bitPrelude(a, b); ok {
		return r
	}
	return FromInt(a.intval | b.intval)
}
func binaryOpBitXor(a, b *Mlrval) *Mlrval {
	if r, ok := bitPrelude(a, b); ok {
		return r
	}
	return FromInt(a.intval ^ b.intval)
}
func binaryOpLeftShift(a, b *Mlrval) *Mlrval {
	if r, ok := bitPrelude(a, b); ok {
		return r
	}
	return FromInt(a.intval << uint64(b.intval))
}
func binaryOpSignedRightShift(a, b *Mlrval) *Mlrval {
	if r, ok := bitPrelude(a, b); ok {
		return r
	}
	return FromInt(a.intval >> uint64(b.intval))
}
func binaryOpUnsignedRightShift(a, b *Mlrval) *Mlrval {
	if r, ok := bitPrelude(a, b); ok {
		return r
	}
	return FromInt(int64(uint64(a.intval) >> uint64(b.intval)))
}

// ---------------------------------------------------------------- dot

func binaryOpDot(a, b *Mlrval) *Mlrval {
	ta, tb := a.Type(), b.Type()
	if ta == MT_ERROR || tb == MT_ERROR {
		return ERROR
	}
	if ta == MT_ARRAY || tb == MT_ARRAY {
		return ERROR
	}
	if tb == MT_ABSENT || tb == MT_VOID {
		if ta == MT_ABSENT && tb == MT_VOID {
			return VOID
		}
		return a
	}
	if ta == MT_ABSENT || ta == MT_VOID {
		return b
	}
	if ta == MT_MAP || tb == MT_MAP {
		return VOID
	}
	return FromString(a.String() + b.String())
}

// ---------------------------------------------------------------- comparisons

// compareForOperator returns (cmp, ok). ok=false means absent result.
// kind: 0 for ordering ops, 1 for equality ops
func binaryOpCompare(op string, a, b *Mlrval) *Mlrval {
	ta, tb := a.Type(), b.Type()
	if ta == MT_ERROR || tb == MT_ERROR {
		return ERROR
	}
	if ta == MT_ABSENT || tb == MT_ABSENT {
		return ABSENT
	}
	aNum := ta == MT_INT || ta == MT_FLOAT
	bNum := tb == MT_INT || tb == MT_FLOAT
	var c int
	switch {
	case aNum && bNum:
		if ta == MT_INT && tb == MT_INT {
			if a.intval < b.intval {
				c = -1
			} else if a.intval > b.intval {
				c = 1
			}
		} else {
			fa, fb := asFloat(a), asFloat(b)
			if fa < fb {
				c = -1
			} else if fa > fb {
				c = 1
			} else if fa == fb {
				c = 0
			} else {
				// NaN
				switch op {
				case "==", "<", "<=", ">", ">=":
					return FALSE
				case "!=":
					return TRUE
				}
				return FromInt(0)
			}
		}
	case ta == MT_BOOLEAN && tb == MT_BOOLEAN:
		ia, ib := 0, 0
		if a.boolval {
			ia = 1
		}
		if b.boolval {
			ib = 1
		}
		c = ia - ib
	case ta == MT_BOOLEAN || tb == MT_BOOLEAN:
		switch op {
		case "!=":
			return TRUE
		case "<=>":
			if ta == MT_BOOLEAN {
				return FromInt(1)
			}
			return FromInt(-1)
		}
		return FALSE
	case ta == MT_MAP || tb == MT_MAP || ta == MT_ARRAY || tb == MT_ARRAY:
		switch op {
		case "==":
			return FromBool(mlrvalEquals(a, b))
		case "!=":
			return FromBool(!mlrvalEquals(a, b))
		case "<=>":
			return ERROR
		}
		return FALSE
	default:
		c = strings.Compare(a.String(), b.String())
	}
	switch op {
	case "==":
		return FromBool(c == 0)
	case "!=":
		return FromBool(c != 0)
	case "<":
		return FromBool(c < 0)
	case "<=":
		return FromBool(c <= 0)
	case ">":
		return FromBool(c > 0)
	case ">=":
		return FromBool(c >= 0)
	case "<=>":
		return FromInt(int64(c))
	}
	return ERROR
}

// ---------------------------------------------------------------- logical

func logicalKind(v *Mlrval) int {
	// 0 true, 1 false, 2 other(error-ish), 3 void, 4 absent, 5 error
	switch v.Type() {
	case MT_BOOLEAN:
		if v.boolval {
			return 0
		}
		return 1
	case MT_VOID:
		return 3
	case MT_ABSENT:
		return 4
	case MT_ERROR:
		return 5
	}
	return 2
}

// Tables indexed [a][b] with entries: T=true F=false E=error A=absent
var andTable = [6][6]byte{
	//        T    F    3    void abs  err
	/*T*/ {'T', 'F', 'E', 'E', 'A', 'E'},
	/*F*/ {'F', 'F', 'F', 'F', 'F', 'F'},
	/*3*/ {'E', 'E', 'E', 'E', 'A', 'E'},
	/*v*/ {'T', 'F', 'E', 'E', 'A', 'E'},
	/*a*/ {'T', 'F', 'E', 'A', 'A', 'E'},
	/*e*/ {'E', 'E', 'E', 'E', 'E', 'E'},
}

var orTable = [6][6]byte{
	//        T    F    3    void abs  err
	/*T*/ {'T', 'T', 'T', 'T', 'T', 'T'},
	/*F*/ {'T', 'F', 'E', 'E', 'A', 'E'},
	/*3*/ {'E', 'E', 'E', 'E', 'A', 'E'},
	/*v*/ {'T', 'F', 'E', 'E', 'A', 'E'},
	/*a*/ {'T', 'F', 'E', 'A', 'A', 'E'},
	/*e*/ {'E', 'E', 'E', 'E', 'E', 'E'},
}

func tableResult(c byte) *Mlrval {
	switch c {
	case 'T':
		return TRUE
	case 'F':
		return FALSE
	case 'A':
		return ABSENT
	}
	return ERROR
}

func binaryOpLogicalXor(a, b *Mlrval) *Mlrval {
	if a.Type() == MT_BOOLEAN && b.Type() == MT_BOOLEAN {
		return FromBool(a.boolval != b.boolval)
	}
	if a.Type() == MT_ABSENT && b.Type() == MT_ABSENT {
		return ABSENT
	}
	return ERROR
}

// ---------------------------------------------------------------- dispatch

func evalBinaryOperator(op string, a, b *Mlrval) *Mlrval {
	switch op {
	case "+":
		return binaryOpPlus(a, b)
	case "-":
		return binaryOpMinus(a, b)
	case "*":
		return binaryOpTimes(a, b)
	case "/":
		return binaryOpDivide(a, b)
	case "//":
		return binaryOpIntDivide(a, b)
	case "%":
		return binaryOpModulus(a, b)
	case "**":
		return binaryOpPow(a, b)
	case ".+":
		return binaryOpDotPlus(a, b)
	case ".-":
		return binaryOpDotMinus(a, b)
	case ".*":
		return binaryOpDotTimes(a, b)
	case "./":
		return binaryOpDotDivide(a, b)
	case ".//":
		return binaryOpIntDivide(a, b)
	case ".":
		return binaryOpDot(a, b)
	case "&":
		return binaryOpBitAnd(a, b)
	case "|":
		return binaryOpBitOr(a, b)
	case "^":
		return binaryOpBitXor(a, b)
	case "<<":
		return binaryOpLeftShift(a, b)
	case ">>":
		return binaryOpSignedRightShift(a, b)
	case ">>>":
		return binaryOpUnsignedRightShift(a, b)
	case "==", "!=", "<", "<=", ">", ">=", "<=>":
		return binaryOpCompare(op, a, b)
	case "^^":
		return binaryOpLogicalXor(a, b)
	case "??":
		if a.Type() == MT_ABSENT {
			return b
		}
		return a
	case "???":
		t := a.Type()
		if t == MT_ABSENT || t == MT_VOID {
			return b
		}
		return a
	}
	return ERROR
}
