func funcFromDefNode(n *ASTNode, isSubr bool) *FuncValue {
	fv := &FuncValue{name: n.text, isSubr: isSubr}
	params := n.children[0]
	for _, p := range params.children {
		pn := p.children[0]
		ps := paramSpec{name: pn.text}
		if len(pn.children) > 0 {
			ps.typ = pn.children[0].text
		}
		fv.params = append(fv.params, ps)
	}
	fv.body = n.children[1]
	if len(n.children) > 2 {
		fv.retType = n.children[2].text
	}
	return fv
}

func (in *Interp) checkCallsites(n *ASTNode) error {
	if n.typ == "function callsite" && n.text != "" {
		name := n.text
		if _, ok := in.funcs[name]; !ok {
			if !builtinExists(name) {
				// could be a local variable holding a function; check later at runtime
				if !in.isLocalFuncName(name) {
					return fmt.Errorf("mlr: function name not found: %s", name)
				}
			} else {
				if err := checkBuiltinArity(name, len(n.children)); err != nil {
					return err
				}
			}
		} else {
			f := in.funcs[name]
			if len(f.params) != len(n.children) {
				return fmt.Errorf("mlr: function %s invoked with %d argument%s; expected %d", name, len(n.children), plural(len(n.children)), len(f.params))
			}
		}
	}
	if n.typ == "subroutine callsite" {
		if _, ok := in.subrs[n.text]; !ok {
			return fmt.Errorf("mlr: subroutine name not found: %s", n.text)
		}
	}
	for _, c := range n.children {
		if err := in.checkCallsites(c); err != nil {
			return err
		}
	}
	return nil
}

// isLocalFuncName: whether the name appears as a local variable / parameter anywhere (so f(x) could be calling a funct-typed local).
func (in *Interp) isLocalFuncName(name string) bool {
	found := false
	var walk func(n *ASTNode)
	walk = func(n *ASTNode) {
		if found {
			return
		}
		if (n.typ == "local variable" || n.typ == "parameter name") && n.text == name {
			found = true
			return
		}
		for _, c := range n.children {
			walk(c)
		}
	}
	walk(in.root)
	return found
}

func plural(n int) string {
	if n == 1 {
		return ""
	}
	return "s"
}

// ---------------------------------------------------------------- frames

func (in *Interp) curFrame() *scopeFrame {
	return in.frames[len(in.frames)-1]
