package main

import (
	"fmt"
	"os"
	"strconv"
	"strings"
)

type paramSpec struct {
	name string
	typ  string
}

type FuncValue struct {
	name    string
	params  []paramSpec
	body    *ASTNode
	retType string
	isSubr  bool
	// For closures (function literals): captured scope
	closure *scopeFrame
}

type localVar struct {
	value *Mlrval
	typ   string
}

type scope struct {
	vars map[string]*localVar
}

type scopeFrame struct {
	scopes []*scope
}

func newScopeFrame() *scopeFrame {
	return &scopeFrame{scopes: []*scope{{vars: map[string]*localVar{}}}}
}

func (f *scopeFrame) push() {
	f.scopes = append(f.scopes, &scope{vars: map[string]*localVar{}})
}

func (f *scopeFrame) pop() {
	f.scopes = f.scopes[:len(f.scopes)-1]
}

func (f *scopeFrame) lookup(name string) *localVar {
	for i := len(f.scopes) - 1; i >= 0; i-- {
		if v, ok := f.scopes[i].vars[name]; ok {
			return v
		}
	}
	return nil
}

func (f *scopeFrame) defineInCurrent(name string, lv *localVar) {
	f.scopes[len(f.scopes)-1].vars[name] = lv
}

type execStatus int

const (
	stNormal execStatus = iota
	stBreak
	stContinue
	stReturn
)

type Interp struct {
	root        *ASTNode
	beginBlocks []*ASTNode
	mainBlock   *ASTNode
	endBlocks   []*ASTNode
	funcs       map[string]*FuncValue
	subrs       map[string]*FuncValue

	oosvars *Mlrmap
	inrec   *Mlrmap
	ctx     *Context

	frames []*scopeFrame

	captures    []string
	capturesSet bool

	filterResult bool
	filterSet    bool
	retval       *Mlrval

	emitted []*Mlrmap

	opts         *Options
	isFilter     bool
	suppressOutput bool
	invertFilter bool
	inBeginOrEnd bool

	redirects map[string]*fileOutput

	// runtime error reporting
	warnings bool
}

func newInterp(root *ASTNode, opts *Options, isFilter bool) (*Interp, error) {
	in := &Interp{
		root:      root,
		funcs:     map[string]*FuncValue{},
		subrs:     map[string]*FuncValue{},
		oosvars:   NewMlrmap(),
		opts:      opts,
		isFilter:  isFilter,
		redirects: map[string]*fileOutput{},
	}
	in.mainBlock = newNode("statement block", "")
	for _, stmt := range root.children {
		switch stmt.typ {
		case "begin block":
			in.beginBlocks = append(in.beginBlocks, stmt.children[0])
		case "end block":
			in.endBlocks = append(in.endBlocks, stmt.children[0])
		case "function definition":
			name := stmt.text
			if builtinExists(name) {
				return nil, fmt.Errorf("mlr: function named \"%s\" must not override a built-in function of the same name", name)
			}
			if _, ok := in.funcs[name]; ok {
				return nil, fmt.Errorf("mlr: function named \"%s\" has already been defined", name)
			}
			in.funcs[name] = funcFromDefNode(stmt, false)
		case "subroutine definition":
			name := stmt.text
			if _, ok := in.subrs[name]; ok {
				return nil, fmt.Errorf("mlr: subroutine named \"%s\" has already been defined", name)
			}
			in.subrs[name] = funcFromDefNode(stmt, true)
		default:
			in.mainBlock.children = append(in.mainBlock.children, stmt)
		}
	}
	in.frames = []*scopeFrame{newScopeFrame()}
	// Static checks: function names exist
	if err := in.checkCallsites(root); err != nil {
		return nil, err
	}
	return in, nil
}

func funcFromDefNode(n *ASTNode, isSubr bool) *FuncValue {
	fv := &FuncValue{name: n.text, isSubr: isSubr}
	params := n.children[0]
	for _, p := range params.children {
		pn := p.children[0]
		ps := paramSpec{name: pn.text}
		if len(pn.children) > 0 {
			ps.typ = pn.children[0].text
		}
		fv.params = append(fv.params, ps)
	}
	fv.body = n.children[1]
	if len(n.children) > 2 {
		fv.retType = n.children[2].text
	}
	return fv
}

func (in *Interp) checkCallsites(n *ASTNode) error {
	if n.typ == "function callsite" && n.text != "" {
		name := n.text
		if _, ok := in.funcs[name]; !ok {
			if !builtinExists(name) {
				// could be a local variable holding a function; check later at runtime
				if !in.isLocalFuncName(name) {
					return fmt.Errorf("mlr: function name not found: %s", name)
				}
			} else {
				if err := checkBuiltinArity(name, len(n.children)); err != nil {
					return err
				}
			}
		} else {
			f := in.funcs[name]
			if len(f.params) != len(n.children) {
				return fmt.Errorf("mlr: function %s invoked with %d argument%s; expected %d", name, len(n.children), plural(len(n.children)), len(f.params))
			}
		}
	}
	if n.typ == "subroutine callsite" {
		if _, ok := in.subrs[n.text]; !ok {
			return fmt.Errorf("mlr: subroutine name not found: %s", n.text)
		}
	}
	for _, c := range n.children {
		if err := in.checkCallsites(c); err != nil {
			return err
		}
	}
	return nil
}

// isLocalFuncName: whether the name appears as a local variable / parameter anywhere (so f(x) could be calling a funct-typed local).
func (in *Interp) isLocalFuncName(name string) bool {
	found := false
	var walk func(n *ASTNode)
	walk = func(n *ASTNode) {
		if found {
			return
		}
		if (n.typ == "local variable" || n.typ == "parameter name") && n.text == name {
			found = true
			return
		}
		for _, c := range n.children {
			walk(c)
		}
	}
	walk(in.root)
	return found
}

func plural(n int) string {
	if n == 1 {
		return ""
	}
	return "s"
}

// ---------------------------------------------------------------- frames

func (in *Interp) curFrame() *scopeFrame {
	return in.frames[len(in.frames)-1]
}

func (in *Interp) pushFrame(f *scopeFrame) {
	in.frames = append(in.frames, f)
}

func (in *Interp) popFrame() {
	in.frames = in.frames[:len(in.frames)-1]
}

// ---------------------------------------------------------------- runtime errors

type runtimeError struct {
	msg string
}

func (e *runtimeError) Error() string { return e.msg }

func (in *Interp) fatal(format string, args ...interface{}) {
	panic(&runtimeError{msg: fmt.Sprintf(format, args...)})
}

// ---------------------------------------------------------------- top-level execution

// runBlockCatching executes a block, converting runtime errors to os.Exit(1).
func (in *Interp) runBlockCatching(block *ASTNode) {
	defer func() {
		if r := recover(); r != nil {
			if re, ok := r.(*runtimeError); ok {
				stdoutWriter.Flush()
				msg := re.msg
				if !strings.HasSuffix(msg, "\n") {
					msg += "\n"
				}
				fmt.Fprint(os.Stderr, msg)
				os.Exit(1)
			}
			panic(r)
		}
	}()
	in.execBlock(block, true)
}

func (in *Interp) runBegin(ctx *Context) {
	in.ctx = ctx
	in.inrec = nil
	in.inBeginOrEnd = true
	for _, b := range in.beginBlocks {
		in.runBlockCatching(b)
	}
	in.inBeginOrEnd = false
}

func (in *Interp) runEnd(ctx *Context) {
	in.ctx = ctx
	in.inrec = nil
	in.inBeginOrEnd = true
	for _, b := range in.endBlocks {
		in.runBlockCatching(b)
	}
	in.inBeginOrEnd = false
}

// runMain processes one record; returns whether the record passes the filter.
func (in *Interp) runMain(rec *Mlrmap, ctx *Context) bool {
	in.ctx = ctx
	in.inrec = rec
	in.filterResult = true
	in.filterSet = false
	in.captures = nil
	in.capturesSet = false
	in.runBlockCatching(in.mainBlock)
	return in.filterResult
}

// execBlock executes statements in a new scope.
func (in *Interp) execBlock(block *ASTNode, newScope bool) execStatus {
	if newScope {
		in.curFrame().push()
		defer in.curFrame().pop()
	}
	for _, stmt := range block.children {
		st := in.execStatement(stmt)
		if st != stNormal {
			return st
		}
	}
	return stNormal
}

func (in *Interp) execStatement(stmt *ASTNode) execStatus {
	switch stmt.typ {
	case "assignment":
		in.execAssignment(stmt)
	case "bare boolean":
		v := in.eval(stmt.children[0])
		if v.Type() == MT_BOOLEAN {
			in.filterResult = v.boolval
			in.filterSet = true
		} else if in.isFilter {
			// non-boolean bare: in filter, only booleans count
			if v.Type() == MT_ABSENT {
				// absent: keep as is
			} else {
				in.filterResult = false
				in.filterSet = true
				if v.Type() != MT_ABSENT {
					in.fatal("mlr: filter statement requires boolean; got %s.", v.TypeName())
				}
			}
		}
	case "filter statement":
		v := in.eval(stmt.children[0])
		if v.Type() == MT_BOOLEAN {
			in.filterResult = v.boolval
			in.filterSet = true
		} else if v.Type() == MT_ABSENT {
		} else {
			in.fatal("mlr: filter statement requires boolean; got %s.", v.TypeName())
		}
	case "cond block":
		v := in.eval(stmt.children[0])
		if v.Type() == MT_BOOLEAN {
			if v.boolval {
				return in.execBlock(stmt.children[1], true)
			}
		} else if v.Type() == MT_ABSENT {
		} else {
			in.fatal("mlr: conditional expression did not evaluate to boolean.")
		}
	case "if-chain":
		for _, item := range stmt.children {
			if item.text == "else" {
				return in.execBlock(item.children[0], true)
			}
			v := in.eval(item.children[0])
			if v.Type() == MT_BOOLEAN {
				if v.boolval {
					return in.execBlock(item.children[1], true)
				}
			} else if v.Type() == MT_ABSENT {
				// treated as false
			} else {
				in.fatal("mlr: conditional expression did not evaluate to boolean.")
			}
		}
	case "while loop":
		for {
			v := in.eval(stmt.children[0])
			if v.Type() != MT_BOOLEAN {
				if v.Type() == MT_ABSENT {
					break
				}
				in.fatal("mlr: conditional expression did not evaluate to boolean.")
			}
			if !v.boolval {
				break
			}
			st := in.execBlock(stmt.children[1], true)
			if st == stBreak {
				break
			}
			if st == stReturn {
				return st
			}
		}
	case "do-while`loop":
		for {
			st := in.execBlock(stmt.children[0], true)
			if st == stBreak {
				break
			}
			if st == stReturn {
				return st
			}
			v := in.eval(stmt.children[1])
			if v.Type() != MT_BOOLEAN {
				if v.Type() == MT_ABSENT {
					break
				}
				in.fatal("mlr: conditional expression did not evaluate to boolean.")
			}
			if !v.boolval {
				break
			}
		}
	case "single-variable for-loop":
		return in.execForSingle(stmt)
	case "double-variable for-loop":
		return in.execForDouble(stmt)
	case "multi-variable for-loop":
		return in.execForMulti(stmt)
	case "triple-for loop":
		return in.execForTriple(stmt)
	case "break":
		return stBreak
	case "continue":
		return stContinue
	case "return":
		if len(stmt.children) > 0 {
			in.retval = in.eval(stmt.children[0])
		} else {
			in.retval = ABSENT
		}
		return stReturn
	case "unset":
		for _, c := range stmt.children {
			in.execUnset(c)
		}
	case "emit1 statement":
		v := in.eval(stmt.children[0])
		if v.Type() == MT_MAP {
			in.emitRecord(v.mapval.Copy(), nil)
		}
	case "emit statement", "emitp statement":
		in.execEmit(stmt)
	case "emitf statement":
		in.execEmitf(stmt)
	case "tee statement":
		in.execTee(stmt)
	case "print statement", "printn statement", "eprint statement", "eprintn statement":
		in.execPrint(stmt)
	case "dump statement", "edump statement":
		in.execDump(stmt)
	case "subroutine callsite":
		in.execSubrCall(stmt)
	case "function definition", "subroutine definition", "begin block", "end block":
		// handled at setup
	default:
		in.fatal("mlr: unhandled statement type %s", stmt.typ)
	}
	return stNormal
}

// ---------------------------------------------------------------- for loops

func (in *Interp) execForSingle(stmt *ASTNode) execStatus {
	varName := stmt.children[0].text
	coll := in.eval(stmt.children[1])
	body := stmt.children[2]
	switch coll.Type() {
	case MT_MAP:
		keys := coll.mapval.Keys()
		for _, k := range keys {
			in.curFrame().push()
			in.curFrame().defineInCurrent(varName, &localVar{value: inferredFromString(k)})
			st := in.execBlock(body, true)
			in.curFrame().pop()
			if st == stBreak {
				break
			}
			if st == stReturn {
				return st
			}
		}
	case MT_ARRAY:
		arr := make([]*Mlrval, len(coll.arrayval))
		copy(arr, coll.arrayval)
		for _, e := range arr {
			in.curFrame().push()
			in.curFrame().defineInCurrent(varName, &localVar{value: e})
			st := in.execBlock(body, true)
			in.curFrame().pop()
			if st == stBreak {
				break
			}
			if st == stReturn {
				return st
			}
		}
	case MT_ABSENT:
	default:
		in.fatal("mlr: looped-over item is not a map or array; got %s", coll.TypeName())
	}
	return stNormal
}

func (in *Interp) execForDouble(stmt *ASTNode) execStatus {
	kName := stmt.children[0].text
	vName := stmt.children[1].text
	coll := in.eval(stmt.children[2])
	body := stmt.children[3]
	switch coll.Type() {
	case MT_MAP:
		// iterate over a copy of the entries
		var keys []string
		var vals []*Mlrval
		for e := coll.mapval.Head; e != nil; e = e.Next {
			keys = append(keys, e.Key)
			vals = append(vals, e.Value)
		}
		for i := range keys {
			in.curFrame().push()
			in.curFrame().defineInCurrent(kName, &localVar{value: inferredFromString(keys[i])})
			in.curFrame().defineInCurrent(vName, &localVar{value: vals[i]})
			st := in.execBlock(body, true)
			in.curFrame().pop()
			if st == stBreak {
				break
			}
			if st == stReturn {
				return st
			}
		}
	case MT_ARRAY:
		arr := make([]*Mlrval, len(coll.arrayval))
		copy(arr, coll.arrayval)
		for i, e := range arr {
			in.curFrame().push()
			in.curFrame().defineInCurrent(kName, &localVar{value: FromInt(int64(i + 1))})
			in.curFrame().defineInCurrent(vName, &localVar{value: e})
			st := in.execBlock(body, true)
			in.curFrame().pop()
			if st == stBreak {
				break
			}
			if st == stReturn {
				return st
			}
		}
	case MT_ABSENT:
	default:
		in.fatal("mlr: looped-over item is not a map or array; got %s", coll.TypeName())
	}
	return stNormal
}

func (in *Interp) execForMulti(stmt *ASTNode) execStatus {
	keyNames := []string{}
	for _, c := range stmt.children[0].children {
		keyNames = append(keyNames, c.text)
	}
	vName := stmt.children[1].text
	coll := in.eval(stmt.children[2])
	body := stmt.children[3]
	if coll.Type() == MT_ABSENT {
		return stNormal
	}
	if coll.Type() != MT_MAP {
		in.fatal("mlr: looped-over item is not a map; got %s", coll.TypeName())
	}
	var walk func(m *Mlrmap, depth int, keys []*Mlrval) execStatus
	walk = func(m *Mlrmap, depth int, keys []*Mlrval) execStatus {
		var ks []string
		var vs []*Mlrval
		for e := m.Head; e != nil; e = e.Next {
			ks = append(ks, e.Key)
			vs = append(vs, e.Value)
		}
		for i := range ks {
			newKeys := append(append([]*Mlrval{}, keys...), inferredFromString(ks[i]))
			if depth+1 < len(keyNames) {
				if vs[i].Type() == MT_MAP {
					st := walk(vs[i].mapval, depth+1, newKeys)
					if st == stBreak || st == stReturn {
						return st
					}
				}
				continue
			}
			in.curFrame().push()
			for j, kn := range keyNames {
				in.curFrame().defineInCurrent(kn, &localVar{value: newKeys[j]})
			}
			in.curFrame().defineInCurrent(vName, &localVar{value: vs[i]})
			st := in.execBlock(body, true)
			in.curFrame().pop()
			if st == stBreak {
				return stBreak
			}
			if st == stReturn {
				return st
			}
		}
		return stNormal
	}
	st := walk(coll.mapval, 0, nil)
	if st == stReturn {
		return st
	}
	return stNormal
}

func (in *Interp) execForTriple(stmt *ASTNode) execStatus {
	initBlock := stmt.children[0]
	condBlock := stmt.children[1]
	updateBlock := stmt.children[2]
	body := stmt.children[3]
	in.curFrame().push()
	defer in.curFrame().pop()
	for _, s := range initBlock.children {
		in.execStatement(s)
	}
	for {
		if len(condBlock.children) > 0 {
			c := condBlock.children[0]
			var v *Mlrval
			if c.typ == "bare boolean" {
				v = in.eval(c.children[0])
			} else {
				v = in.eval(c)
			}
			if v.Type() != MT_BOOLEAN {
				in.fatal("mlr: for-loop condition did not evaluate to boolean.")
			}
			if !v.boolval {
				break
			}
		}
		st := in.execBlock(body, true)
		if st == stBreak {
			break
		}
		if st == stReturn {
			return st
		}
		for _, s := range updateBlock.children {
			in.execStatement(s)
		}
	}
	return stNormal
}

// ---------------------------------------------------------------- function calls

func (in *Interp) callUserFunc(f *FuncValue, args []*Mlrval) *Mlrval {
	if len(args) != len(f.params) {
		in.fatal("mlr: function %s invoked with %d argument%s; expected %d", f.name, len(args), plural(len(args)), len(f.params))
	}
	var frame *scopeFrame
	if f.closure != nil {
		// closure: new scope on top of captured frame
		frame = &scopeFrame{scopes: append([]*scope{}, f.closure.scopes...)}
		frame.push()
	} else {
		frame = newScopeFrame()
	}
	for i, p := range f.params {
		if p.typ != "" {
			if !typeGateOK(p.typ, args[i]) {
				in.fatal("mlr: couldn't assign variable %s %s from value %s %s", p.typ, p.name, args[i].TypeName(), args[i].String())
			}
		}
		frame.defineInCurrent(p.name, &localVar{value: args[i], typ: p.typ})
	}
	in.pushFrame(frame)
	in.retval = ABSENT
	st := in.execBlock(f.body, false)
	in.popFrame()
	ret := ABSENT
	if st == stReturn {
		ret = in.retval
	}
	in.retval = ABSENT
	if f.retType != "" && !typeGateOK(f.retType, ret) {
		in.fatal("mlr: couldn't assign variable %s function return value from value %s %s", f.retType, ret.TypeName(), ret.String())
	}
	return ret
}

func (in *Interp) execSubrCall(stmt *ASTNode) {
	s := in.subrs[stmt.text]
	if s == nil {
		in.fatal("mlr: subroutine name not found: %s", stmt.text)
	}
	args := make([]*Mlrval, len(stmt.children))
	for i, c := range stmt.children {
		args[i] = in.eval(c)
	}
	if len(args) != len(s.params) {
		in.fatal("mlr: subroutine %s invoked with %d argument%s; expected %d", s.name, len(args), plural(len(args)), len(s.params))
	}
	frame := newScopeFrame()
	for i, p := range s.params {
		if p.typ != "" && !typeGateOK(p.typ, args[i]) {
			in.fatal("mlr: couldn't assign variable %s %s from value %s %s", p.typ, p.name, args[i].TypeName(), args[i].String())
		}
		frame.defineInCurrent(p.name, &localVar{value: args[i], typ: p.typ})
	}
	in.pushFrame(frame)
	in.execBlock(s.body, false)
	in.popFrame()
}

func typeGateOK(typ string, v *Mlrval) bool {
	t := v.Type()
	if t == MT_ABSENT {
		return true
	}
	switch typ {
	case "var", "any":
		return true
	case "str":
		return t == MT_STRING || t == MT_VOID
	case "num":
		return t == MT_INT || t == MT_FLOAT
	case "int":
		return t == MT_INT
	case "float":
		return t == MT_FLOAT
	case "bool":
		return t == MT_BOOLEAN
	case "map":
		return t == MT_MAP
	case "arr":
		return t == MT_ARRAY
	case "funct":
		return t == MT_FUNC
	}
	return true
}

// ---------------------------------------------------------------- unset

func (in *Interp) execUnset(n *ASTNode) {
	switch n.typ {
	case "direct field value":
		if in.inrec != nil {
			in.inrec.Remove(n.text)
		}
	case "indirect field value":
		if in.inrec != nil {
			k := in.eval(n.children[0])
			in.inrec.Remove(k.String())
		}
	case "positionally-indexed field name", "positionally-indexed field value":
		if in.inrec != nil {
			idx := in.eval(n.children[0])
			if idx.Type() == MT_INT {
				e := in.inrec.GetEntryByPosition(int(idx.intval))
				if e != nil {
					in.inrec.Remove(e.Key)
				}
			}
		}
	case "full record":
		if in.inrec != nil {
			in.inrec.Clear()
		}
	case "direct oosvar value":
		in.oosvars.Remove(n.text)
	case "indirect oosvar value":
		k := in.eval(n.children[0])
		in.oosvars.Remove(k.String())
	case "full oosvar":
		in.oosvars.Clear()
	case "local variable":
		lv := in.curFrame().lookup(n.text)
		if lv != nil {
			lv.value = ABSENT
		}
	case "array or map index access":
		// unset nested
		base, indices := flattenIndexChain(n)
		var container *Mlrval
		switch base.typ {
		case "direct field value":
			if in.inrec == nil {
				return
			}
			container = in.inrec.Get(base.text)
			if container == nil {
				return
			}
		case "full record":
			if in.inrec == nil {
				return
			}
			container = FromMap(in.inrec)
		case "direct oosvar value":
			container = in.oosvars.Get(base.text)
			if container == nil {
				return
			}
		case "full oosvar":
			container = FromMap(in.oosvars)
		case "local variable":
			lv := in.curFrame().lookup(base.text)
			if lv == nil {
				return
			}
			container = lv.value
		case "indirect field value":
			if in.inrec == nil {
				return
			}
			container = in.inrec.Get(in.eval(base.children[0]).String())
			if container == nil {
				return
			}
		case "indirect oosvar value":
			container = in.oosvars.Get(in.eval(base.children[0]).String())
			if container == nil {
				return
			}
		default:
			return
		}
		idxVals := make([]*Mlrval, len(indices))
		for i, ix := range indices {
			idxVals[i] = in.eval(ix)
		}
		for i := 0; i < len(idxVals)-1; i++ {
			container = indexValue(container, idxVals[i])
			if container == nil || container.IsAbsent() {
				return
			}
		}
		last := idxVals[len(idxVals)-1]
		switch container.Type() {
		case MT_MAP:
			container.mapval.Remove(last.String())
		case MT_ARRAY:
			if last.Type() == MT_INT {
				i, ok := arrayIndexResolve(len(container.arrayval), last.intval)
				if ok {
					container.arrayval = append(container.arrayval[:i], container.arrayval[i+1:]...)
				}
			}
		}
	}
}

// flattenIndexChain: for a[1][2][3], returns base node and list of index nodes.
func flattenIndexChain(n *ASTNode) (*ASTNode, []*ASTNode) {
	var indices []*ASTNode
	cur := n
	for cur.typ == "array or map index access" {
		indices = append([]*ASTNode{cur.children[1]}, indices...)
		cur = cur.children[0]
	}
	return cur, indices
}

// arrayIndexResolve converts 1-up / negative index to 0-up; ok=false if out of bounds.
func arrayIndexResolve(n int, idx int64) (int, bool) {
	if idx >= 1 && idx <= int64(n) {
		return int(idx - 1), true
	}
	if idx < 0 && -idx <= int64(n) {
		return int(int64(n) + idx), true
	}
	return 0, false
}

// indexValue returns container[idx] or ABSENT.
func indexValue(container *Mlrval, idx *Mlrval) *Mlrval {
	switch container.Type() {
	case MT_MAP:
		if idx.Type() == MT_MAP || idx.Type() == MT_ARRAY {
			return ERROR
		}
		v := container.mapval.Get(idx.String())
		if v == nil {
			return ABSENT
		}
		return v
	case MT_ARRAY:
		if idx.Type() != MT_INT {
			if idx.Type() == MT_ABSENT {
				return ABSENT
			}
			return ERROR
		}
		i, ok := arrayIndexResolve(len(container.arrayval), idx.intval)
		if !ok {
			return ABSENT
		}
		return container.arrayval[i]
	case MT_STRING, MT_VOID, MT_INT, MT_FLOAT:
		// string indexing: 1-up character
		if idx.Type() != MT_INT {
			return ERROR
		}
		s := container.String()
		runes := []rune(s)
		i, ok := arrayIndexResolve(len(runes), idx.intval)
		if !ok {
			return ERROR
		}
		return FromString(string(runes[i]))
	case MT_ABSENT:
		return ABSENT
	}
	return ERROR
}

// ---------------------------------------------------------------- print / dump / tee

func (in *Interp) execPrint(stmt *ASTNode) {
	kw := stmt.text
	callsite := stmt.children[0]
	var sb strings.Builder
	for i, c := range callsite.children {
		if i > 0 {
			sb.WriteString(" ")
		}
		v := in.eval(c)
		sb.WriteString(in.printableString(v))
	}
	if kw == "print" || kw == "eprint" {
		sb.WriteString("\n")
	}
	s := sb.String()
	redirect := stmt.children[1]
	if redirect.typ == "no-op" {
		if kw == "print" || kw == "printn" {
			stdoutWriter.WriteString(s)
		} else {
			stdoutWriter.Flush()
			fmt.Fprint(os.Stderr, s)
		}
		return
	}
	in.writeToRedirect(redirect, s, nil)
}

// printableString: for print, maps/arrays are multi-line JSON.
func (in *Interp) printableString(v *Mlrval) string {
	switch v.Type() {
	case MT_MAP:
		return v.mapval.ToJSONString(true, 0)
	case MT_ARRAY:
		return arrayToJSONString(v.arrayval, true, 0)
	}
	return v.String()
}

func (in *Interp) execDump(stmt *ASTNode) {
	kw := stmt.text
	var s string
	target := stmt.children[0]
	if target.typ == "no-op" {
		s = in.oosvars.ToJSONString(true, 0) + "\n"
	} else {
		v := in.eval(target.children[0])
		switch v.Type() {
		case MT_MAP:
			s = v.mapval.ToJSONString(true, 0) + "\n"
		case MT_ARRAY:
			s = arrayToJSONString(v.arrayval, true, 0) + "\n"
		case MT_ABSENT:
			s = ""
		default:
			s = v.String() + "\n"
		}
	}
	redirect := stmt.children[1]
	if redirect.typ == "no-op" {
		if kw == "dump" {
			stdoutWriter.WriteString(s)
		} else {
			stdoutWriter.Flush()
			fmt.Fprint(os.Stderr, s)
		}
		return
	}
	in.writeToRedirect(redirect, s, nil)
}

func (in *Interp) execTee(stmt *ASTNode) {
	v := in.eval(stmt.children[0])
	if v.Type() != MT_MAP {
		in.fatal("mlr: tee: expression does not evaluate to a map.")
	}
	redirect := stmt.children[1]
	in.writeToRedirect(redirect, "", v.mapval.Copy())
}

// writeToRedirect writes text or a record to the redirect target.
func (in *Interp) writeToRedirect(redirect *ASTNode, text string, rec *Mlrmap) {
	target := redirect.children[0]
	var fo *fileOutput
	switch target.typ {
	case "stdout redirect target":
		fo = in.getRedirect("(stdout)", redirect.text, true)
	case "stderr redirect target":
		fo = in.getRedirect("(stderr)", redirect.text, true)
	default:
		name := in.eval(target).String()
		fo = in.getRedirect(name, redirect.text, false)
	}
	if rec != nil {
		fo.writeRecord(rec)
	} else {
		fo.writeString(text)
	}
}

func (in *Interp) getRedirect(name string, mode string, isStd bool) *fileOutput {
	key := mode + ":" + name
	if fo, ok := in.redirects[key]; ok {
		return fo
	}
	var fo *fileOutput
	wopts := in.opts.Writer
	if isStd {
		fo = newStdFileOutput(name == "(stderr)", &wopts)
	} else {
		fo = newFileOutput(name, mode == ">>", mode == "|", &wopts)
	}
	in.redirects[key] = fo
	allRedirects = append(allRedirects, fo)
	return fo
}

// ---------------------------------------------------------------- emit

func (in *Interp) emitRecord(rec *Mlrmap, redirect *ASTNode) {
	if redirect != nil && redirect.typ != "no-op" {
		in.writeToRedirect(redirect, "", rec)
		return
	}
	in.emitted = append(in.emitted, rec)
}

func (in *Interp) execEmitf(stmt *ASTNode) {
	rec := NewMlrmap()
	for _, c := range stmt.children[0].children {
		v := in.eval(c)
		var name string
		switch c.typ {
		case "direct oosvar value", "direct field value", "local variable":
			name = c.text
		case "indirect oosvar value", "indirect field value":
			name = in.eval(c.children[0]).String()
		default:
			name = c.text
		}
		if v.Type() == MT_ABSENT {
			continue
		}
		rec.Put(name, v)
	}
	if rec.Len() == 0 {
		return
	}
	in.emitRecord(rec, stmt.children[1])
}

// emittable name for emit/emitp prefixing
func emittableName(c *ASTNode, in *Interp) string {
	switch c.typ {
	case "direct oosvar value", "direct field value", "local variable":
		return c.text
	case "indirect oosvar value", "indirect field value":
		return in.eval(c.children[0]).String()
	case "full oosvar":
		return "_"
	case "full record":
		return "_"
	case "map literal":
		return "_"
	case "array or map index access":
		base, indices := flattenIndexChain(c)
		name := emittableName(base, in)
		for _, ix := range indices {
			name += ":" + in.eval(ix).String()
		}
		return name
	}
	return "_"
}

func (in *Interp) execEmit(stmt *ASTNode) {
	isEmitP := stmt.text == "emitp"
	emittables := stmt.children[0].children
	keysNode := stmt.children[1]
	redirect := stmt.children[2]
	var keyVals []*Mlrval
	if keysNode.typ != "no-op" {
		for _, k := range keysNode.children {
			keyVals = append(keyVals, in.eval(k))
		}
	}
	// Evaluate emittables
	var values []*Mlrval
	var names []string
	for _, e := range emittables {
		v := in.eval(e)
		if e.typ == "full oosvar" || (e.typ == "full record") {
			// emit @* is shorthand for emit mapexcept... : emit each top-level oosvar separately
			if len(emittables) == 1 && !isEmitP {
				if v.Type() == MT_MAP {
					if e.typ == "full oosvar" {
						// emit @* : for each oosvar, emit it
						for me := v.mapval.Head; me != nil; me = me.Next {
							in.emitOne(isEmitP, []*Mlrval{me.Value}, []string{me.Key}, keyVals, redirect)
						}
						return
					}
				}
			}
		}
		values = append(values, v)
		names = append(names, emittableName(e, in))
	}
	in.emitOne(isEmitP, values, names, keyVals, redirect)
}

// emitOne implements emit/emitp semantics for (possibly lashed) emittables.
func (in *Interp) emitOne(isEmitP bool, values []*Mlrval, names []string, keyVals []*Mlrval, redirect *ASTNode) {
	// Filter out absents
	var vs []*Mlrval
	var ns []string
	for i, v := range values {
		if v.Type() == MT_ABSENT {
			continue
		}
		vs = append(vs, v)
		ns = append(ns, names[i])
	}
	if len(vs) == 0 {
		return
	}
	// Non-map emittables: emit as single-field record
	allMaps := true
	for _, v := range vs {
		if v.Type() != MT_MAP {
			allMaps = false
		}
	}
	if !allMaps {
		if len(vs) == 1 {
			rec := NewMlrmap()
			rec.Put(ns[0], vs[0])
			in.emitRecord(rec, redirect)
		} else {
			rec := NewMlrmap()
			for i, v := range vs {
				if v.Type() != MT_MAP {
					rec.Put(ns[i], v)
				}
			}
			if rec.Len() > 0 {
				in.emitRecord(rec, redirect)
			}
		}
		return
	}
	maps := make([]*Mlrmap, len(vs))
	for i, v := range vs {
		maps[i] = v.mapval
	}
	in.emitWalk(isEmitP, maps, ns, keyVals, 0, NewMlrmap(), redirect)
}

// emitWalk recurses over emit keys.
func (in *Interp) emitWalk(isEmitP bool, maps []*Mlrmap, prefixes []string, keyVals []*Mlrval, depth int, templ *Mlrmap, redirect *ASTNode) {
	if depth < len(keyVals) {
		keyName := keyVals[depth].String()
		// iterate over keys of the first map; lashed maps must have the same keys
		lead := maps[0]
		for e := lead.Head; e != nil; e = e.Next {
			if e.Value.Type() != MT_MAP {
				// non-map at this level: emit what we have?
				continue
			}
			subs := make([]*Mlrmap, 0, len(maps))
			newPrefixes := make([]string, 0, len(maps))
			ok := true
			for i, m := range maps {
				sv := m.Get(e.Key)
				if sv == nil || sv.Type() != MT_MAP {
					ok = false
					break
				}
				subs = append(subs, sv.mapval)
				if isEmitP {
					newPrefixes = append(newPrefixes, prefixes[i]+":"+e.Key)
				} else {
					newPrefixes = append(newPrefixes, prefixes[i])
				}
			}
			if !ok {
				continue
			}
			nt := templ.ShallowCopy()
			nt.Put(keyName, inferredFromString(e.Key))
			in.emitWalk(isEmitP, subs, newPrefixes, keyVals, depth+1, nt, redirect)
		}
		return
	}
	// Leaf level: build record from the maps
	rec := templ.ShallowCopy()
	if isEmitP {
		for i, m := range maps {
			for e := m.Head; e != nil; e = e.Next {
				if e.Value.Type() == MT_MAP {
					flattenEmitP(rec, prefixes[i]+":"+e.Key, e.Value)
				} else {
					rec.Put(prefixes[i]+":"+e.Key, e.Value)
				}
			}
		}
		in.emitRecord(rec, redirect)
		return
	}
	// emit (non-p): if the map's values are all maps (and no more keys), split into one record per entry
	anyNonMap := false
	for _, m := range maps {
		for e := m.Head; e != nil; e = e.Next {
			if e.Value.Type() != MT_MAP {
				anyNonMap = true
				break
			}
		}
	}
	if !anyNonMap && maps[0].Len() > 0 {
		// recurse into each submap, emitting one record per key (without adding key column)
		lead := maps[0]
		for e := lead.Head; e != nil; e = e.Next {
			subs := make([]*Mlrmap, 0, len(maps))
			ok := true
			for _, m := range maps {
				sv := m.Get(e.Key)
				if sv == nil || sv.Type() != MT_MAP {
					ok = false
					break
				}
				subs = append(subs, sv.mapval)
			}
			if !ok {
				continue
			}
			in.emitWalk(false, subs, prefixes, keyVals, depth, templ, redirect)
		}
		return
	}
	for _, m := range maps {
		for e := m.Head; e != nil; e = e.Next {
			rec.Put(e.Key, e.Value)
		}
	}
	in.emitRecord(rec, redirect)
}

func flattenEmitP(rec *Mlrmap, prefix string, v *Mlrval) {
	if v.Type() != MT_MAP {
		rec.Put(prefix, v)
		return
	}
	for e := v.mapval.Head; e != nil; e = e.Next {
		flattenEmitP(rec, prefix+":"+e.Key, e.Value)
	}
}

