// eval evaluates an expression node.
func (in *Interp) eval(n *ASTNode) *Mlrval {
	switch n.typ {
	case "int literal", "float literal", "bool literal":
		return n.mv
	case "string literal":
		return in.evalStringLiteral(n)
	case "case-insensitive regular expression":
		return FromString(n.text)
	case "null literal":
		return newJSONNullValue()
	case "direct field value":
		if in.inrec == nil {
			if in.inBeginOrEnd {
				in.fatal("mlr: begin/end blocks cannot refer to records via $x, $*, etc")
			}
			return ABSENT
		}
		v := in.inrec.Get(n.text)
		if v == nil {
			return ABSENT
		}
		return v
	case "indirect field value":
		if in.inrec == nil {
			if in.inBeginOrEnd {
				in.fatal("mlr: begin/end blocks cannot refer to records via $x, $*, etc")
			}
			return ABSENT
		}
		k := in.eval(n.children[0])
		v := in.inrec.Get(k.String())
		if v == nil {
			return ABSENT
		}
		return v
	case "full record":
		if in.inrec == nil {
			if in.inBeginOrEnd {
				in.fatal("mlr: begin/end blocks cannot refer to records via $x, $*, etc")
			}
			return ABSENT
		}
		return FromMap(in.inrec)
	case "positionally-indexed field name":
		if in.inrec == nil {
			return ABSENT
		}
		idx := in.eval(n.children[0])
		if idx.Type() != MT_INT {
			return ABSENT
		}
		e := in.inrec.GetEntryByPosition(int(idx.intval))
		if e == nil {
			return ABSENT
		}
		return FromString(e.Key)
	case "positionally-indexed field value":
		if in.inrec == nil {
			return ABSENT
		}
		idx := in.eval(n.children[0])
		if idx.Type() != MT_INT {
			return ABSENT
		}
		e := in.inrec.GetEntryByPosition(int(idx.intval))
		if e == nil {
			return ABSENT
		}
		return e.Value
	case "direct oosvar value":
		v := in.oosvars.Get(n.text)
		if v == nil {
			return ABSENT
		}
		return v
	case "indirect oosvar value":
		k := in.eval(n.children[0])
		v := in.oosvars.Get(k.String())
		if v == nil {
			return ABSENT
		}
		return v
	case "full oosvar":
		return FromMap(in.oosvars)
	case "local variable":
		lv := in.curFrame().lookup(n.text)
		if lv == nil {
			// Maybe a named user function used as a value
			if f, ok := in.funcs[n.text]; ok {
				return FromFunc(f)
			}
			return ABSENT
		}
		return lv.value
	case "context variable":
		return in.evalContextVar(n.text)
	case "mathematical constant":
		if n.text == "M_PI" {
			return FromFloat(math.Pi)
		}
		return FromFloat(math.E)
	case "environment variable":
		if len(n.children) == 0 {
			m := NewMlrmap()
			for _, kv := range os.Environ() {
				idx := strings.Index(kv, "=")
				if idx > 0 {
					m.Put(kv[:idx], inferredFromString(kv[idx+1:]))
				}
			}
			return FromMap(m)
		}
		k := in.eval(n.children[0])
		v, ok := os.LookupEnv(k.String())
		if !ok {
			return ABSENT
		}
		return inferredFromString(v)
	case "map literal":
		m := NewMlrmap()
		for _, kv := range n.children {
			k := in.eval(kv.children[0])
			v := in.eval(kv.children[1])
			if k.Type() == MT_ABSENT {
				continue
			}
			if v.Type() == MT_ABSENT {
				continue
			}
			m.Put(k.String(), v.Copy())
		}
		return FromMap(m)
	case "array literal":
		arr := make([]*Mlrval, 0, len(n.children))
		for _, c := range n.children {
			v := in.eval(c)
			arr = append(arr, v.Copy())
		}
		return FromArray(arr)
	case "function literal":
		fv := &FuncValue{name: "function-literal", body: n.children[1]}
		for _, p := range n.children[0].children {
			pn := p.children[0]
			ps := paramSpec{name: pn.text}
			if len(pn.children) > 0 {
				ps.typ = pn.children[0].text
			}
			fv.params = append(fv.params, ps)
		}
		if len(n.children) > 2 {
			fv.retType = n.children[2].text
		}
		// capture current frame (closure)
		cur := in.curFrame()
		fv.closure = &scopeFrame{scopes: append([]*scope{}, cur.scopes...)}
		return FromFunc(fv)
	case "operator":
		return in.evalOperator(n)
	case "dot operator":
		a := in.eval(n.children[0])
		b := in.eval(n.children[1])
		return binaryOpDot(a, b)
	case "array or map index access":
		base := in.eval(n.children[0])
		idx := in.eval(n.children[1])
		if base.Type() == MT_ABSENT {
			return ABSENT
		}
		return indexValue(base, idx)
	case "array-slice access":
		return in.evalSlice(n)
	case "function callsite":
		return in.evalFunctionCall(n)
	}
	in.fatal("mlr: unhandled expression node type %s", n.typ)
	return ERROR
}

func newJSONNullValue() *Mlrval {
	return &Mlrval{mvtype: MT_VOID, printrep: "null", printrepValid: true, isJSONNull: true}
}

func (in *Interp) evalContextVar(name string) *Mlrval {
	ctx := in.ctx
	switch name {
	case "NR":
		return FromInt(ctx.NR)
	case "FNR":
		return FromInt(ctx.FNR)
	case "NF":
		if in.inrec == nil {
			return ABSENT
		}
		return FromInt(int64(in.inrec.Len()))
	case "FILENAME":
		return FromString(ctx.FILENAME)
	case "FILENUM":
		return FromInt(ctx.FILENUM)
	case "IPS":
		return FromString(in.opts.Reader.IPS)
	case "IFS":
		return FromString(in.opts.Reader.IFS)
	case "IRS":
		return FromString(in.opts.Reader.IRS)
	case "OPS":
		return FromString(in.opts.Writer.OPS)
	case "OFS":
		return FromString(in.opts.Writer.OFS)
	case "ORS":
		return FromString(in.opts.Writer.ORS)
	case "FLATSEP":
		return FromString(in.opts.Writer.FlatSep)
	}
	return ABSENT
}

func (in *Interp) evalStringLiteral(n *ASTNode) *Mlrval {
	s := n.text
	if in.capturesSet && strings.Contains(s, "\\") {
		s = applyCaptures(s, in.captures)
	}
	return FromString(unescapeStringLiteral(s))
}

// applyCaptures replaces \0..\9 with capture strings.
func applyCaptures(s string, captures []string) string {
	var sb strings.Builder
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == '\\' && i+1 < len(s) && s[i+1] >= '0' && s[i+1] <= '9' {
			idx := int(s[i+1] - '0')
			if idx < len(captures) {
				sb.WriteString(captures[idx])
			}
			i++
			continue
		}
		sb.WriteByte(c)
	}
	return sb.String()
}

// regexString returns the regex source for a node (string literal with regex escapes preserved).
func (in *Interp) regexFromNode(n *ASTNode) (*regexp.Regexp, bool) {
	if n.typ == "case-insensitive regular expression" {
		// text is "..."i
		src := n.text
		src = strings.TrimSuffix(src, "i")
		src = strings.TrimSuffix(strings.TrimPrefix(src, "\""), "\"")
		return compileRegexCached("(?i)" + unescapeForRegex(src)), true
	}
	if n.typ == "string literal" {
		s := n.text
		if in.capturesSet && strings.Contains(s, "\\") {
			s = applyCaptures(s, in.captures)
		}
		return compileRegexCached(unescapeForRegex(s)), true
	}
	v := in.eval(n)
	return compileRegexCached(regexStringFromValue(v.String())), false
}

// regexStringFromValue handles "..."i form at runtime.
func regexStringFromValue(s string) string {
	if len(s) >= 3 && s[0] == '"' && strings.HasSuffix(s, "\"i") {
		return "(?i)" + s[1:len(s)-2]
	}
	return s
}

var compiledRegexCache = map[string]*regexp.Regexp{}

func compileRegexCached(s string) *regexp.Regexp {
	if rx, ok := compiledRegexCache[s]; ok {
		return rx
	}
	rx, err := regexp.Compile(s)
	if err != nil {
		// Try with the "i" suffix handling or report
		stdoutWriter.Flush()
		os.Stderr.WriteString("mlr: could not compile regex \"" + s + "\"\n")
		os.Exit(1)
	}
	compiledRegexCache[s] = rx
	return rx
}

func (in *Interp) evalOperator(n *ASTNode) *Mlrval {
	op := n.text
	switch len(n.children) {
	case 1:
		a := in.eval(n.children[0])
		switch op {
		case "-":
			return unaryOpMinus(a)
		case "+":
			return unaryOpPlus(a)
		case "!":
			return unaryOpLogicalNot(a)
		case "~":
			return unaryOpBitNot(a)
		}
	case 2:
		switch op {
		case "&&":
			a := in.eval(n.children[0])
			ka := logicalKind(a)
			if ka == 1 {
				return FALSE
			}
			if ka == 5 {
				return ERROR
			}
			b := in.eval(n.children[1])
			kb := logicalKind(b)
			return tableResult(andTable[ka][kb])
		case "||":
			a := in.eval(n.children[0])
			ka := logicalKind(a)
			if ka == 0 {
				return TRUE
			}
			if ka == 5 {
				return ERROR
			}
			b := in.eval(n.children[1])
			kb := logicalKind(b)
			return tableResult(orTable[ka][kb])
		case "??":
			a := in.eval(n.children[0])
			if a.Type() == MT_ABSENT {
				return in.eval(n.children[1])
			}
			return a
		case "???":
			a := in.eval(n.children[0])
			t := a.Type()
			if t == MT_ABSENT || t == MT_VOID {
				return in.eval(n.children[1])
			}
			return a
		case "=~", "!=~":
			a := in.eval(n.children[0])
			rx, _ := in.regexFromNode(n.children[1])
			if a.Type() == MT_ABSENT {
				return ABSENT
			}
			if a.Type() == MT_MAP || a.Type() == MT_ARRAY || a.Type() == MT_ERROR {
				return ERROR
			}
			s := a.String()
			if op == "=~" {
				loc := rx.FindStringSubmatchIndex(s)
				if loc == nil {
					in.captures = []string{}
					in.capturesSet = true
					return FALSE
				}
				caps := make([]string, 10)
				for i := 0; i < 10; i++ {
					if 2*i+1 < len(loc) && loc[2*i] >= 0 {
						caps[i] = s[loc[2*i]:loc[2*i+1]]
					}
				}
				in.captures = caps
				in.capturesSet = true
				return TRUE
			}
			return FromBool(!rx.MatchString(s))
		}
		a := in.eval(n.children[0])
		b := in.eval(n.children[1])
		return evalBinaryOperator(op, a, b)
	case 3:
		if op == "?:" {
			c := in.eval(n.children[0])
			if c.Type() != MT_BOOLEAN {
				return ERROR
			}
			if c.boolval {
				return in.eval(n.children[1])
			}
			return in.eval(n.children[2])
		}
	}
	in.fatal("mlr: unhandled operator %s", op)
	return ERROR
}

func (in *Interp) evalSlice(n *ASTNode) *Mlrval {
	base := in.eval(n.children[0])
	var lo, hi *Mlrval
	if n.children[1].mv != nil && n.children[1].mv.Type() == MT_ABSENT && n.children[1].typ == "int literal" && n.children[1].text == "" {
		lo = nil
	} else {
		lo = in.eval(n.children[1])
	}
	if n.children[2].mv != nil && n.children[2].mv.Type() == MT_ABSENT && n.children[2].typ == "int literal" && n.children[2].text == "" {
		hi = nil
	} else {
		hi = in.eval(n.children[2])
	}
	switch base.Type() {
	case MT_ARRAY:
		nlen := len(base.arrayval)
		l, h, ok := sliceBounds(nlen, lo, hi)
		if !ok {
			return ERROR
		}
		if l > h {
			return FromArray([]*Mlrval{})
		}
		out := make([]*Mlrval, 0, h-l)
		for i := l; i < h; i++ {
			out = append(out, base.arrayval[i])
		}
		return FromArray(out)
	case MT_STRING, MT_VOID:
		runes := []rune(base.String())
		l, h, ok := sliceBounds(len(runes), lo, hi)
		if !ok {
			return ERROR
		}
		if l > h {
			return VOID
		}
		return FromString(string(runes[l:h]))
	case MT_ABSENT:
		return ABSENT
	}
	return ERROR
}

// sliceBounds converts 1-up inclusive [lo:hi] into 0-up [l,h).
func sliceBounds(n int, lo, hi *Mlrval) (int, int, bool) {
	l := int64(1)
	h := int64(n)
	if lo != nil {
		if lo.Type() != MT_INT {
			return 0, 0, false
		}
		l = lo.intval
	}
	if hi != nil {
		if hi.Type() != MT_INT {
			return 0, 0, false
		}
		h = hi.intval
	}
	// negative aliasing
	if l < 0 {
		l = int64(n) + 1 + l
	}
	if h < 0 {
		h = int64(n) + 1 + h
	}
	if l < 1 {
		l = 1
	}
	if h > int64(n) {
		h = int64(n)
	}
	if l > int64(n) || h < 1 {
		return 0, 0, true
	}
	return int(l - 1), int(h), true
}

// ---------------------------------------------------------------- function calls

func (in *Interp) evalFunctionCall(n *ASTNode) *Mlrval {
	name := n.text
	// user-defined function?
	if f, ok := in.funcs[name]; ok {
		args := make([]*Mlrval, len(n.children))
		for i, c := range n.children {
			args[i] = in.eval(c)
		}
		return in.callUserFunc(f, args)
	}
	// local variable holding a function?
	if lv := in.curFrame().lookup(name); lv != nil && lv.value.Type() == MT_FUNC {
		args := make([]*Mlrval, len(n.children))
		for i, c := range n.children {
			args[i] = in.eval(c)
		}
		return in.callUserFunc(lv.value.funcval, args)
	}
	return in.callBuiltin(name, n)
}

// ---------------------------------------------------------------- assignment

func (in *Interp) execAssignment(stmt *ASTNode) {
	lhs := stmt.children[0]
	rhs := in.eval(stmt.children[1])
	in.assign(lhs, rhs)
}

func (in *Interp) assign(lhs *ASTNode, rhs *Mlrval) {
	switch lhs.typ {
	case "direct field value":
		if in.inrec == nil {
			if in.inBeginOrEnd {
				in.fatal("mlr: begin/end blocks cannot refer to records via $x, $*, etc")
			}
			return
		}
		if rhs.Type() == MT_ABSENT {
			return
		}
		in.inrec.Put(lhs.text, copyForAssign(rhs))
	case "indirect field value":
		if in.inrec == nil {
			if in.inBeginOrEnd {
				in.fatal("mlr: begin/end blocks cannot refer to records via $x, $*, etc")
			}
			return
		}
		if rhs.Type() == MT_ABSENT {
			return
		}
		k := in.eval(lhs.children[0])
		in.inrec.Put(k.String(), copyForAssign(rhs))
	case "positionally-indexed field name":
		if in.inrec == nil {
			return
		}
		idx := in.eval(lhs.children[0])
		if idx.Type() != MT_INT {
			return
		}
		e := in.inrec.GetEntryByPosition(int(idx.intval))
		if e == nil {
			return
		}
		in.inrec.Rename(e.Key, rhs.String())
	case "positionally-indexed field value":
		if in.inrec == nil {
			return
		}
		if rhs.Type() == MT_ABSENT {
			return
		}
		idx := in.eval(lhs.children[0])
		if idx.Type() != MT_INT {
			return
		}
		e := in.inrec.GetEntryByPosition(int(idx.intval))
		if e == nil {
			return
		}
		e.Value = copyForAssign(rhs)
	case "full record":
		if in.inrec == nil {
			if in.inBeginOrEnd {
				in.fatal("mlr: begin/end blocks cannot refer to records via $x, $*, etc")
			}
			return
		}
		if rhs.Type() == MT_ABSENT {
			return
		}
		if rhs.Type() != MT_MAP {
			in.fatal("mlr: $* assignment: right-hand side is not a map; got %s.", rhs.TypeName())
		}
		newrec := rhs.mapval.Copy()
		in.inrec.Clear()
		for e := newrec.Head; e != nil; e = e.Next {
			if e.Value.Type() == MT_ABSENT {
				continue
			}
			in.inrec.Put(e.Key, e.Value)
		}
	case "direct oosvar value":
		if rhs.Type() == MT_ABSENT {
			return
		}
		in.oosvars.Put(lhs.text, copyForAssign(rhs))
	case "indirect oosvar value":
		if rhs.Type() == MT_ABSENT {
			return
		}
		k := in.eval(lhs.children[0])
		in.oosvars.Put(k.String(), copyForAssign(rhs))
	case "full oosvar":
		if rhs.Type() == MT_ABSENT {
			return
		}
		if rhs.Type() != MT_MAP {
			in.fatal("mlr: @* assignment: right-hand side is not a map; got %s.", rhs.TypeName())
		}
		in.oosvars = rhs.mapval.Copy()
	case "local variable":
		in.assignLocal(lhs, rhs)
	case "environment variable":
		if len(lhs.children) > 0 {
			k := in.eval(lhs.children[0])
			os.Setenv(k.String(), rhs.String())
		}
	case "array or map index access":
		in.assignIndexed(lhs, rhs)
	default:
		in.fatal("mlr: unassignable node type %s", lhs.typ)
	}
}

func copyForAssign(v *Mlrval) *Mlrval {
	if v.Type() == MT_MAP || v.Type() == MT_ARRAY {
		return v.Copy()
	}
	return v
}

func (in *Interp) assignLocal(lhs *ASTNode, rhs *Mlrval) {
	name := lhs.text
	frame := in.curFrame()
	if len(lhs.children) > 0 {
		// typed declaration: define in current scope
		typ := lhs.children[0].text
		if !typeGateOK(typ, rhs) {
			in.fatal("mlr: couldn't assign variable %s %s from value %s %s", typ, name, rhs.TypeName(), rhs.String())
		}
		frame.defineInCurrent(name, &localVar{value: copyForAssign(rhs), typ: typ})
		return
	}
	lv := frame.lookup(name)
	if lv == nil {
		frame.defineInCurrent(name, &localVar{value: copyForAssign(rhs)})
		return
	}
	if lv.typ != "" && lv.typ != "var" && !typeGateOK(lv.typ, rhs) {
		in.fatal("mlr: couldn't assign variable %s %s from value %s %s", lv.typ, name, rhs.TypeName(), rhs.String())
	}
	lv.value = copyForAssign(rhs)
}

// assignIndexed handles x[a][b] = v for fields, oosvars, locals, $*, @*.
func (in *Interp) assignIndexed(lhs *ASTNode, rhs *Mlrval) {
	if rhs.Type() == MT_ABSENT {
		return
	}
	base, indices := flattenIndexChain(lhs)
	idxVals := make([]*Mlrval, len(indices))
	for i, ix := range indices {
		idxVals[i] = in.eval(ix)
		if idxVals[i].Type() == MT_ABSENT {
			return
		}
	}
	// Obtain (or create) the base container as a *Mlrval holding a map/array.
	var container *Mlrval
	setBase := func(v *Mlrval) {}
	switch base.typ {
	case "direct field value", "indirect field value":
		if in.inrec == nil {
			if in.inBeginOrEnd {
				in.fatal("mlr: begin/end blocks cannot refer to records via $x, $*, etc")
			}
			return
		}
		name := base.text
		if base.typ == "indirect field value" {
			name = in.eval(base.children[0]).String()
		}
		container = in.inrec.Get(name)
		setBase = func(v *Mlrval) { in.inrec.Put(name, v) }
	case "full record":
		if in.inrec == nil {
			if in.inBeginOrEnd {
				in.fatal("mlr: begin/end blocks cannot refer to records via $x, $*, etc")
			}
			return
		}
		container = FromMap(in.inrec)
	case "direct oosvar value", "indirect oosvar value":
		name := base.text
		if base.typ == "indirect oosvar value" {
			name = in.eval(base.children[0]).String()
		}
		container = in.oosvars.Get(name)
		setBase = func(v *Mlrval) { in.oosvars.Put(name, v) }
	case "full oosvar":
		container = FromMap(in.oosvars)
	case "local variable":
		lv := in.curFrame().lookup(base.text)
		if lv == nil {
			lv = &localVar{value: ABSENT}
			in.curFrame().defineInCurrent(base.text, lv)
		}
		if lv.value.Type() == MT_MAP || lv.value.Type() == MT_ARRAY {
			container = lv.value
		} else {
			container = nil
		}
		setBase = func(v *Mlrval) {
			if lv.typ != "" && lv.typ != "var" && !typeGateOK(lv.typ, v) {
				in.fatal("mlr: couldn't assign variable %s %s from value %s %s", lv.typ, base.text, v.TypeName(), v.String())
			}
			lv.value = v
		}
	default:
		in.fatal("mlr: unassignable indexed node type %s", base.typ)
	}
	if container == nil || (container.Type() != MT_MAP && container.Type() != MT_ARRAY) {
		// auto-create map
		container = FromEmptyMap()
		setBase(container)
	}
	in.putIndexed(container, idxVals, copyForAssign(rhs))
}

// putIndexed sets container[idx0][idx1]... = value, auto-creating maps.
func (in *Interp) putIndexed(container *Mlrval, indices []*Mlrval, value *Mlrval) {
	cur := container
	for i, idx := range indices {
		last := i == len(indices)-1
		switch cur.Type() {
		case MT_MAP:
			key := idx.String()
			if last {
				cur.mapval.Put(key, value)
				return
			}
			next := cur.mapval.Get(key)
			if next == nil || (next.Type() != MT_MAP && next.Type() != MT_ARRAY) {
				next = FromEmptyMap()
				cur.mapval.Put(key, next)
			}
			cur = next
		case MT_ARRAY:
			if idx.Type() != MT_INT {
				in.fatal("mlr: array index must be an int; got %s.", idx.TypeName())
			}
			n := len(cur.arrayval)
			ix := idx.intval
			if ix == 0 {
				in.fatal("mlr: zero indices are not supported. Indices are 1-up")
			}
			var pos int
			if ix > 0 {
				if ix > int64(n) {
					// extend
					for int64(len(cur.arrayval)) < ix-1 {
						cur.arrayval = append(cur.arrayval, newJSONNullValue())
					}
					if last {
						cur.arrayval = append(cur.arrayval, value)
						return
					}
					nm := FromEmptyMap()
					cur.arrayval = append(cur.arrayval, nm)
					cur = nm
					continue
				}
				pos = int(ix - 1)
			} else {
				if -ix > int64(n) {
					in.fatal("mlr: array index %d out of bounds 1..%d", ix, n)
				}
				pos = int(int64(n) + ix)
			}
			if last {
				cur.arrayval[pos] = value
				return
			}
			next := cur.arrayval[pos]
			if next.Type() != MT_MAP && next.Type() != MT_ARRAY {
				next = FromEmptyMap()
				cur.arrayval[pos] = next
			}
			cur = next
		default:
			return
		}
	}
}

func parseIntOrZero(s string) int64 {
	v, _ := strconv.ParseInt(s, 10, 64)
	return v
}
EOF
echo ok"}

