type builtinFunc func(in *Interp, args []*Mlrval, argNodes []*ASTNode) *Mlrval

type builtinSpec struct {
	name    string
	minArgs int
	maxArgs int // -1 for variadic
	fn      builtinFunc
	// arities: explicit set of allowed arities (for "multiple-arity" functions)
	arities []int
}

var builtinTable map[string]*builtinSpec

func builtinExists(name string) bool {
	_, ok := builtinTable[name]
	return ok
}

func checkBuiltinArity(name string, n int) error {
	spec := builtinTable[name]
	if spec == nil {
		return nil
	}
	if spec.arities != nil {
		for _, a := range spec.arities {
			if a == n {
				return nil
			}
		}
		return fmt.Errorf("mlr: at CST BuildMultipleArityFunctionCallsiteNode: function name not found: %s", name)
	}
	if spec.maxArgs == -1 {
		if n < spec.minArgs {
			return fmt.Errorf("mlr: function %s takes minimum argument count %d; got %d", name, spec.minArgs, n)
		}
		return nil
	}
	if spec.minArgs == spec.maxArgs {
		if n != spec.minArgs {
			return fmt.Errorf("mlr: function %s invoked with %d argument%s; expected %d", name, n, plural(n), spec.minArgs)
		}
		return nil
	}
	if n < spec.minArgs {
		return fmt.Errorf("mlr: function %s takes minimum argument count %d; got %d", name, spec.minArgs, n)
	}
	if n > spec.maxArgs {
		return fmt.Errorf("mlr: function %s takes maximum argument count %d; got %d", name, spec.maxArgs, n)
	}
	return nil
}

func reg(name string, min, max int, fn builtinFunc) {
	builtinTable[name] = &builtinSpec{name: name, minArgs: min, maxArgs: max, fn: fn}
}

func regArities(name string, arities []int, fn builtinFunc) {
	builtinTable[name] = &builtinSpec{name: name, arities: arities, fn: fn}
}

func (in *Interp) callBuiltin(name string, n *ASTNode) *Mlrval {
	spec := builtinTable[name]
	if spec == nil {
		in.fatal("mlr: function name not found: %s", name)
	}
	args := make([]*Mlrval, len(n.children))
	for i, c := range n.children {
		args[i] = in.eval(c)
	}
	return spec.fn(in, args, n.children)
}

// ---------------------------------------------------------------- helpers

func math1(f func(float64) float64) builtinFunc {
	return func(in *Interp, args []*Mlrval, _ []*ASTNode) *Mlrval {
		a := args[0]
		switch a.Type() {
		case MT_INT:
			return FromFloat(f(float64(a.intval)))
		case MT_FLOAT:
			return FromFloat(f(a.floatval))
		case MT_ABSENT:
			return ABSENT
		case MT_VOID:
			return VOID
		}
		return ERROR
	}
}

// math1i: int-preserving where result is integral for ints (e.g. abs, ceil, floor, round, sgn)
func math1i(fi func(int64) int64, ff func(float64) float64) builtinFunc {
	return func(in *Interp, args []*Mlrval, _ []*ASTNode) *Mlrval {
		a := args[0]
		switch a.Type() {
		case MT_INT:
			return FromInt(fi(a.intval))
		case MT_FLOAT:
			return FromFloat(ff(a.floatval))
		case MT_ABSENT:
			return ABSENT
		case MT_VOID:
			return VOID
		}
		return ERROR
	}
}

func str1(f func(string) string) builtinFunc {
	return func(in *Interp, args []*Mlrval, _ []*ASTNode) *Mlrval {
		a := args[0]
		switch a.Type() {
		case MT_STRING:
			return FromString(f(a.printrep))
		case MT_VOID:
			return a
		case MT_ABSENT:
			return ABSENT
		case MT_ERROR:
			return ERROR
		case MT_MAP, MT_ARRAY:
			return ERROR
		}
		// numbers, bools: returned as-is
		return a
	}
}

// strOrInfer: applies string function then type-inference (e.g. for strip: " 1 " -> 1)
func str1infer(f func(string) string) builtinFunc {
	return func(in *Interp, args []*Mlrval, _ []*ASTNode) *Mlrval {
		a := args[0]
		switch a.Type() {
		case MT_STRING:
			return inferredFromString(f(a.printrep))
		case MT_VOID:
			return a
		case MT_ABSENT:
			return ABSENT
		case MT_ERROR:
			return ERROR
		case MT_MAP, MT_ARRAY:
			return ERROR
		}
		return a
	}
}

func hashFunc(h func([]byte) string) builtinFunc {
	return func(in *Interp, args []*Mlrval, _ []*ASTNode) *Mlrval {
		a := args[0]
		if a.Type() == MT_ABSENT {
			return ABSENT
		}
		if a.Type() == MT_MAP || a.Type() == MT_ARRAY || a.Type() == MT_ERROR {
			return ERROR
		}
		return FromString(h([]byte(a.String())))
	}
}

func collapseWhitespace(s string) string {
	var sb strings.Builder
	prevSpace := false
	for _, r := range s {
		if unicode.IsSpace(r) {
			if !prevSpace {
				sb.WriteRune(' ')
			}
			prevSpace = true
		} else {
			sb.WriteRune(r)
			prevSpace = false
		}
	}
	return sb.String()
}

func capitalizeString(s string) string {
	if s == "" {
		return s
	}
	r, size := utf8.DecodeRuneInString(s)
	return string(unicode.ToUpper(r)) + s[size:]
}

