		}
		return FromMap(out)
	})
	reg("unflatten", 2, 2, func(in *Interp, args []*Mlrval, _ []*ASTNode) *Mlrval {
		if args[0].Type() != MT_MAP {
			return args[0]
		}
		sep := args[1].String()
		out := NewMlrmap()
		for e := args[0].mapval.Head; e != nil; e = e.Next {
			v := e.Value
			if v.printrepValid && v.Type() != MT_MAP && v.Type() != MT_ARRAY {
				if v.printrep == "{}" {
					v = FromEmptyMap()
				} else if v.printrep == "[]" {
					v = FromArray([]*Mlrval{})
				}
			}
			if strings.Contains(e.Key, sep) {
				putIndexedAuto(out, strings.Split(e.Key, sep), v)
			} else {
				out.Put(e.Key, v)
			}
		}
		return FromMap(out)
	})
	reg("get_keys", 1, 1, func(in *Interp, args []*Mlrval, _ []*ASTNode) *Mlrval {
		a := args[0]
		switch a.Type() {
		case MT_MAP:
			out := make([]*Mlrval, 0, a.mapval.Len())
			for e := a.mapval.Head; e != nil; e = e.Next {
				out = append(out, FromString(e.Key))
			}
			return FromArray(out)
		case MT_ARRAY:
			out := make([]*Mlrval, 0, len(a.arrayval))
			for i := range a.arrayval {
				out = append(out, FromInt(int64(i+1)))
			}
			return FromArray(out)
		case MT_ABSENT:
			return ABSENT
		}
		return ERROR
	})
	reg("get_values", 1, 1, func(in *Interp, args []*Mlrval, _ []*ASTNode) *Mlrval {
		a := args[0]
		switch a.Type() {
		case MT_MAP:
			out := make([]*Mlrval, 0, a.mapval.Len())
			for e := a.mapval.Head; e != nil; e = e.Next {
				out = append(out, e.Value.Copy())
			}
			return FromArray(out)
		case MT_ARRAY:
			return a.Copy()
		case MT_ABSENT:
			return ABSENT
		}
		return ERROR
	})
	reg("haskey", 2, 2, func(in *Interp, args []*Mlrval, _ []*ASTNode) *Mlrval {
		a, k := args[0], args[1]
		switch a.Type() {
		case MT_MAP:
			if k.Type() == MT_MAP || k.Type() == MT_ARRAY || k.Type() == MT_ABSENT {
				return FALSE
			}
			return FromBool(a.mapval.Has(k.String()))
		case MT_ARRAY:
			if k.Type() != MT_INT {
				return FALSE
			}
			_, ok := arrayIndexResolve(len(a.arrayval), k.intval)
			return FromBool(ok)
		case MT_ABSENT:
			return ABSENT
		}
		return FALSE
	})
	reg("json_decode", 1, 1, bifJSONParse)
	reg("json_parse", 1, 1, bifJSONParse)
	regArities("json_encode", []int{1, 2}, bifJSONStringify)
	regArities("json_stringify", []int{1, 2}, bifJSONStringify)
	reg("leafcount", 1, 1, func(in *Interp, args []*Mlrval, _ []*ASTNode) *Mlrval {
		a := args[0]
		if a.Type() == MT_ABSENT {
			return ABSENT
		}
		if a.Type() != MT_MAP && a.Type() != MT_ARRAY {
			return ERROR
		}
		return FromInt(int64(leafCount(a)))
