	reg("length", 1, 1, func(in *Interp, args []*Mlrval, _ []*ASTNode) *Mlrval {
		a := args[0]
		switch a.Type() {
		case MT_MAP:
			return FromInt(int64(a.mapval.Len()))
		case MT_ARRAY:
			return FromInt(int64(len(a.arrayval)))
