	reg("mapdiff", 0, -1, func(in *Interp, args []*Mlrval, _ []*ASTNode) *Mlrval {
		if len(args) == 0 {
			return FromEmptyMap()
		}
		if args[0].Type() != MT_MAP {
			return ERROR
		}
		out := args[0].mapval.Copy()
		for _, a := range args[1:] {
			if a.Type() != MT_MAP {
				return ERROR
			}
			for e := a.mapval.Head; e != nil; e = e.Next {
				out.Remove(e.Key)
			}
		}
		return FromMap(out)
	})
	reg("mapsum", 0, -1, func(in *Interp, args []*Mlrval, _ []*ASTNode) *Mlrval {
		out := NewMlrmap()
		for _, a := range args {
			if a.Type() == MT_ABSENT {
				continue
			}
			if a.Type() != MT_MAP {
				return ERROR
			}
			for e := a.mapval.Head; e != nil; e = e.Next {
				out.Put(e.Key, e.Value.Copy())
			}
