		return FromMap(out)
	})
	reg("mapexcept", 1, -1, func(in *Interp, args []*Mlrval, _ []*ASTNode) *Mlrval {
		if args[0].Type() != MT_MAP {
			return ERROR
		}
		out := args[0].mapval.Copy()
		for _, a := range args[1:] {
			if a.Type() == MT_ARRAY {
				for _, e := range a.arrayval {
					out.Remove(e.String())
				}
			} else {
				out.Remove(a.String())
			}
		}
		return FromMap(out)
	})
	reg("mapselect", 1, -1, func(in *Interp, args []*Mlrval, _ []*ASTNode) *Mlrval {
		if args[0].Type() != MT_MAP {
			return ERROR
		}
		src := args[0].mapval
		out := NewMlrmap()
		var keys []string
		for _, a := range args[1:] {
			if a.Type() == MT_ARRAY {
				for _, e := range a.arrayval {
					keys = append(keys, e.String())
				}
			} else {
				keys = append(keys, a.String())
			}
		}
		for _, k := range keys {
			if v := src.Get(k); v != nil {
				out.Put(k, v.Copy())
			}
		}
		return FromMap(out)
	})

	// ---- system
	reg("hostname", 0, 0, func(in *Interp, args []*Mlrval, _ []*ASTNode) *Mlrval {
		h, err := os.Hostname()
		if err != nil {
			return ERROR
		}
		return FromString(h)
