	reg("os", 0, 0, func(in *Interp, args []*Mlrval, _ []*ASTNode) *Mlrval { return FromString(runtime.GOOS) })
	reg("version", 0, 0, func(in *Interp, args []*Mlrval, _ []*ASTNode) *Mlrval { return FromString(mlrVersion) })
	reg("system", 1, 1, func(in *Interp, args []*Mlrval, _ []*ASTNode) *Mlrval {
		cmd := exec.Command("/bin/sh", "-c", args[0].String())
		cmd.Stderr = os.Stderr
		out, err := cmd.Output()
