	// ---- stats and time are registered in their own files
	registerStatsBuiltins()
	registerTimeBuiltins()
}

func typeofName(v *Mlrval) string {
	if v.Type() == MT_VOID && v.isJSONNull {
		return "empty"
	}
	return v.TypeName()
}

func isAbsentF(v *Mlrval) bool { return v.Type() == MT_ABSENT }
func isEmptyF(v *Mlrval) bool  { return v.Type() == MT_VOID && !v.isJSONNull }
func isNotEmptyF(v *Mlrval) bool {
	t := v.Type()
	if t == MT_ABSENT {
		return false
	}
	if t == MT_VOID && !v.isJSONNull {
		return false
	}
	return true
}
func isNullF(v *Mlrval) bool {
	t := v.Type()
	return t == MT_ABSENT || t == MT_VOID
}
func isStringF(v *Mlrval) bool {
	t := v.Type()
	if t == MT_STRING {
		return true
	}
	if t == MT_VOID && !v.isJSONNull {
		return true
	}
	return false
}

func pred(f func(*Mlrval) bool) builtinFunc {
	return func(in *Interp, args []*Mlrval, _ []*ASTNode) *Mlrval {
		return FromBool(f(args[0]))
	}
}

func asserting(name string, f func(*Mlrval) bool) builtinFunc {
	return func(in *Interp, args []*Mlrval, _ []*ASTNode) *Mlrval {
		if !f(args[0]) {
			in.fatal("mlr: %s type-assertion failed at NR=%d FNR=%d FILENAME=%s", name, in.ctx.NR, in.ctx.FNR, in.ctx.FILENAME)
		}
		return args[0]
	}
}

func roundHalfAway(f float64) float64 {
	return math.Round(f)
}

func math2(a, b *Mlrval, f func(float64, float64) float64) *Mlrval {
	if a.Type() == MT_ABSENT {
		return ABSENT
	}
	if b.Type() == MT_ABSENT {
		return ABSENT
	}
	fa, oka := a.GetNumericToFloat()
	fb, okb := b.GetNumericToFloat()
	if !oka || !okb {
		if a.Type() == MT_VOID || b.Type() == MT_VOID {
			return VOID
		}
		return ERROR
	}
	return FromFloat(f(fa, fb))
}

func modArith(args []*Mlrval, f func(a, b, m int64) int64) *Mlrval {
	for _, a := range args {
		if a.Type() != MT_INT {
			if a.Type() == MT_ABSENT {
				return ABSENT
			}
			return ERROR
		}
	}
	m := args[2].intval
	if m == 0 {
		return ERROR
	}
	r := f(args[0].intval, args[1].intval, m) % m
	if r < 0 {
		r += m
	}
	return FromInt(r)
}

// invqnorm: inverse normal CDF (Acklam's algorithm with refinement)
func invqnorm(p float64) float64 {
	if p <= 0 || p >= 1 {
		if p == 0 {
			return math.Inf(-1)
		}
		if p == 1 {
			return math.Inf(1)
		}
		return 0
	}
	a := []float64{-3.969683028665376e+01, 2.209460984245205e+02, -2.759285104469687e+02, 1.383577518672690e+02, -3.066479806614716e+01, 2.506628277459239e+00}
	b := []float64{-5.447609879822406e+01, 1.615858368580409e+02, -1.556989798598866e+02, 6.680131188771972e+01, -1.328068155288572e+01}
	c := []float64{-7.784894002430293e-03, -3.223964580411365e-01, -2.400758277161838e+00, -2.549732539343734e+00, 4.374664141464968e+00, 2.938163982698783e+00}
	d := []float64{7.784695709041462e-03, 3.224671290700398e-01, 2.445134137142996e+00, 3.754408661907416e+00}
	plow := 0.02425
	phigh := 1 - plow
	var x float64
	if p < plow {
		q := math.Sqrt(-2 * math.Log(p))
		x = (((((c[0]*q+c[1])*q+c[2])*q+c[3])*q+c[4])*q + c[5]) / ((((d[0]*q+d[1])*q+d[2])*q+d[3])*q + 1)
	} else if p <= phigh {
		q := p - 0.5
		r := q * q
		x = (((((a[0]*r+a[1])*r+a[2])*r+a[3])*r+a[4])*r + a[5]) * q / (((((b[0]*r+b[1])*r+b[2])*r+b[3])*r+b[4])*r + 1)
	} else {
		q := math.Sqrt(-2 * math.Log(1-p))
		x = -(((((c[0]*q+c[1])*q+c[2])*q+c[3])*q+c[4])*q + c[5]) / ((((d[0]*q+d[1])*q+d[2])*q+d[3])*q + 1)
	}
	// refinement step
	e := 0.5*math.Erfc(-x/math.Sqrt2) - p
	u := e * math.Sqrt(2*math.Pi) * math.Exp(x*x/2)
	x = x - u/(1+x*u/2)
	return x
}

func valueDepth(v *Mlrval) int {
	switch v.Type() {
	case MT_MAP:
		max := 0
		for e := v.mapval.Head; e != nil; e = e.Next {
			d := valueDepth(e.Value)
			if d > max {
				max = d
			}
		}
		return max + 1
	case MT_ARRAY:
		max := 0
		for _, e := range v.arrayval {
			d := valueDepth(e)
			if d > max {
				max = d
			}
		}
		return max + 1
	}
	return 0
}

func leafCount(v *Mlrval) int {
	switch v.Type() {
	case MT_MAP:
		n := 0
		for e := v.mapval.Head; e != nil; e = e.Next {
			n += leafCount(e.Value)
		}
		return n
	case MT_ARRAY:
		n := 0
		for _, e := range v.arrayval {
			n += leafCount(e)
		}
		return n
	}
	return 1
}

// ---------------------------------------------------------------- string function impls

func bifTruncate(in *Interp, args []*Mlrval, _ []*ASTNode) *Mlrval {
	a, n := args[0], args[1]
	if a.Type() == MT_ABSENT {
		return ABSENT
	}
	if a.Type() == MT_ERROR || n.Type() != MT_INT {
		return ERROR
	}
	if a.Type() != MT_STRING && a.Type() != MT_VOID {
		return ERROR
	}
	if n.intval < 0 {
		return ERROR
	}
	runes := []rune(a.String())
	if int64(len(runes)) <= n.intval {
		return a
	}
	return FromString(string(runes[:n.intval]))
}

func padFunc(args []*Mlrval, left bool) *Mlrval {
	a, n, p := args[0], args[1], args[2]
	if a.Type() == MT_ABSENT {
		return ABSENT
	}
	if n.Type() != MT_INT {
		return ERROR
	}
	s := a.String()
	pad := p.String()
	if pad == "" {
		return a
	}
	padLen := utf8.RuneCountInString(pad)
	cur := utf8.RuneCountInString(s)
	var sb strings.Builder
	if left {
		for cur+padLen <= int(n.intval) {
			sb.WriteString(pad)
			cur += padLen
		}
		sb.WriteString(s)
	} else {
		sb.WriteString(s)
		for cur+padLen <= int(n.intval) {
			sb.WriteString(pad)
			cur += padLen
		}
	}
	return FromString(sb.String())
}

func bifFormat(in *Interp, args []*Mlrval, _ []*ASTNode) *Mlrval {
	if len(args) == 0 {
		return VOID
	}
	if args[0].Type() == MT_ABSENT {
		return ABSENT
	}
	fmtStr := args[0].String()
	var sb strings.Builder
	argi := 1
	for i := 0; i < len(fmtStr); i++ {
		if fmtStr[i] == '{' && i+1 < len(fmtStr) && fmtStr[i+1] == '}' {
			if argi < len(args) {
				sb.WriteString(args[argi].String())
			}
			argi++
			i++
			continue
		}
		sb.WriteByte(fmtStr[i])
	}
	return FromString(sb.String())
}

func bifUnformat(args []*Mlrval, infer bool) *Mlrval {
	if args[0].Type() == MT_ABSENT || args[1].Type() == MT_ABSENT {
		return ABSENT
	}
	fmtStr := args[0].String()
	input := args[1].String()
	// Split format on "{}"
	pieces := strings.Split(fmtStr, "{}")
	// The input must start with pieces[0], end with pieces[n-1], with pieces in between
	if !strings.HasPrefix(input, pieces[0]) {
		return ERROR
	}
	rest := input[len(pieces[0]):]
	out := make([]*Mlrval, 0, len(pieces)-1)
	for i := 1; i < len(pieces); i++ {
		sep := pieces[i]
		var val string
		if i == len(pieces)-1 {
			if sep == "" {
				val = rest
				rest = ""
			} else {
				if !strings.HasSuffix(rest, sep) {
					return ERROR
				}
				val = rest[:len(rest)-len(sep)]
				rest = ""
			}
		} else {
			if sep == "" {
				return ERROR
			}
			idx := strings.Index(rest, sep)
			if idx < 0 {
				return ERROR
			}
			val = rest[:idx]
			rest = rest[idx+len(sep):]
		}
		if infer {
			out = append(out, inferredFromString(val))
		} else {
			out = append(out, FromString(val))
		}
	}
	return FromArray(out)
}

// regex arg handling: use literal text when the node is a string literal.
func (in *Interp) regexArg(args []*Mlrval, nodes []*ASTNode, i int) (string, bool) {
	n := nodes[i]
	if n.typ == "string literal" {
		s := n.text
		if in.capturesSet && strings.Contains(s, "\\") {
			s = applyCaptures(s, in.captures)
		}
		return unescapeForRegex(s), false
	}
	if n.typ == "case-insensitive regular expression" {
		src := strings.TrimSuffix(n.text, "i")
		src = strings.TrimSuffix(strings.TrimPrefix(src, "\""), "\"")
		return "(?i)" + unescapeForRegex(src), true
	}
	return regexStringFromValue(args[i].String()), false
}

func stringArgCheck(a *Mlrval) (string, *Mlrval) {
	switch a.Type() {
	case MT_STRING, MT_VOID:
		return a.printrep, nil
	case MT_ABSENT:
		return "", ABSENT
	}
	return "", ERROR
}

func bifSub(in *Interp, args []*Mlrval, nodes []*ASTNode) *Mlrval {
	s, bad := stringArgCheck(args[0])
	if bad != nil {
		return bad
	}
	if args[2].Type() != MT_STRING && args[2].Type() != MT_VOID {
		return ERROR
	}
	rxs, _ := in.regexArg(args, nodes, 1)
	rx := compileRegexCached(rxs)
	repl := args[2].String()
	return FromString(regexSubWithCaptures(s, rx, repl))
}

func bifGsub(in *Interp, args []*Mlrval, nodes []*ASTNode) *Mlrval {
	s, bad := stringArgCheck(args[0])
	if bad != nil {
		return bad
	}
	if args[2].Type() != MT_STRING && args[2].Type() != MT_VOID {
		return ERROR
	}
	rxs, _ := in.regexArg(args, nodes, 1)
	rx := compileRegexCached(rxs)
	repl := args[2].String()
	return FromString(regexGsubWithCaptures(s, rx, repl))
}

func bifSsub(in *Interp, args []*Mlrval, _ []*ASTNode) *Mlrval {
	s, bad := stringArgCheck(args[0])
	if bad != nil {
		return bad
	}
	if args[1].Type() == MT_ABSENT || args[2].Type() == MT_ABSENT {
		return ABSENT
	}
	return FromString(strings.Replace(s, args[1].String(), args[2].String(), 1))
}

func bifGssub(in *Interp, args []*Mlrval, _ []*ASTNode) *Mlrval {
	s, bad := stringArgCheck(args[0])
	if bad != nil {
		return bad
	}
	if args[1].Type() == MT_ABSENT || args[2].Type() == MT_ABSENT {
		return ABSENT
	}
	old := args[1].String()
	if old == "" {
		return FromString(s)
	}
	return FromString(strings.ReplaceAll(s, old, args[2].String()))
}

func bifRegextract(in *Interp, args []*Mlrval, nodes []*ASTNode) *Mlrval {
	a := args[0]
	if a.Type() == MT_ABSENT {
		return ABSENT
	}
	if a.Type() == MT_MAP || a.Type() == MT_ARRAY || a.Type() == MT_ERROR {
		return ERROR
	}
	rxs, _ := in.regexArg(args, nodes, 1)
	rx := compileRegexCached(rxs)
	m := rx.FindString(a.String())
	if m == "" && !rx.MatchString(a.String()) {
		return ERROR
	}
	return inferredFromString(m)
}

func bifRegextractOrElse(in *Interp, args []*Mlrval, nodes []*ASTNode) *Mlrval {
	a := args[0]
	if a.Type() == MT_ABSENT {
		return ABSENT
	}
	if a.Type() == MT_MAP || a.Type() == MT_ARRAY || a.Type() == MT_ERROR {
		return ERROR
	}
	rxs, _ := in.regexArg(args, nodes, 1)
	rx := compileRegexCached(rxs)
	loc := rx.FindStringIndex(a.String())
	if loc == nil {
		return args[2]
	}
	return inferredFromString(a.String()[loc[0]:loc[1]])
}

func bifStrmatch(in *Interp, args []*Mlrval, nodes []*ASTNode) *Mlrval {
	a := args[0]
	if a.Type() == MT_ABSENT {
		return ABSENT
	}
	if a.Type() == MT_MAP || a.Type() == MT_ARRAY || a.Type() == MT_ERROR {
		return ERROR
	}
	rxs, _ := in.regexArg(args, nodes, 1)
	rx := compileRegexCached(rxs)
	return FromBool(rx.MatchString(a.String()))
}

func bifStrmatchx(in *Interp, args []*Mlrval, nodes []*ASTNode) *Mlrval {
	a := args[0]
	if a.Type() == MT_ABSENT {
		return ABSENT
	}
	if a.Type() == MT_MAP || a.Type() == MT_ARRAY || a.Type() == MT_ERROR {
		return ERROR
	}
	rxs, _ := in.regexArg(args, nodes, 1)
	rx := compileRegexCached(rxs)
	s := a.String()
	loc := rx.FindStringSubmatchIndex(s)
	out := NewMlrmap()
	if loc == nil {
		out.Put("matched", FALSE)
		return FromMap(out)
	}
	out.Put("matched", TRUE)
	out.Put("full_capture", inferredFromString(s[loc[0]:loc[1]]))
	out.Put("full_start", FromInt(int64(utf8.RuneCountInString(s[:loc[0]])+1)))
	out.Put("full_end", FromInt(int64(utf8.RuneCountInString(s[:loc[1]]))))
	n := len(loc)/2 - 1
	if n > 0 {
		caps := make([]*Mlrval, 0, n)
		starts := make([]*Mlrval, 0, n)
		ends := make([]*Mlrval, 0, n)
		for i := 1; i <= n; i++ {
			if loc[2*i] < 0 {
				caps = append(caps, VOID)
				starts = append(starts, FromInt(-1))
				ends = append(ends, FromInt(-1))
				continue
			}
			caps = append(caps, inferredFromString(s[loc[2*i]:loc[2*i+1]]))
			starts = append(starts, FromInt(int64(utf8.RuneCountInString(s[:loc[2*i]])+1)))
			ends = append(ends, FromInt(int64(utf8.RuneCountInString(s[:loc[2*i+1]]))))
		}
		out.Put("captures", FromArray(caps))
		out.Put("starts", FromArray(starts))
		out.Put("ends", FromArray(ends))
	}
	return FromMap(out)
}

func bifSubstr(args []*Mlrval, base int) *Mlrval {
	a := args[0]
	if a.Type() == MT_ABSENT {
		return ABSENT
	}
	if a.Type() == MT_MAP || a.Type() == MT_ARRAY || a.Type() == MT_ERROR {
		return ERROR
	}
	if args[1].Type() != MT_INT || args[2].Type() != MT_INT {
		return ERROR
	}
	runes := []rune(a.String())
	n := int64(len(runes))
	m := args[1].intval
	k := args[2].intval
	// convert to 1-up
	if base == 0 {
		if m < 0 {
			m = n + m
		}
		if k < 0 {
			k = n + k
		}
		m++
		k++
	} else {
		if m < 0 {
			m = n + 1 + m
		}
		if k < 0 {
			k = n + 1 + k
		}
	}
	if m < 1 || k > n || m > k {
		if m > k && m >= 1 && k <= n {
			return VOID
		}
		return ERROR
	}
	return FromString(string(runes[m-1 : k]))
}

func latin1ToUtf8(s string) string {
	// if already valid UTF-8 with non-ASCII, leave as is
	if utf8.ValidString(s) {
		return s
	}
	var sb strings.Builder
	for i := 0; i < len(s); i++ {
		sb.WriteRune(rune(s[i]))
	}
	return sb.String()
}

func utf8ToLatin1(s string) string {
	var sb strings.Builder
	for _, r := range s {
		if r > 255 {
			return s
		}
		sb.WriteByte(byte(r))
	}
	return sb.String()
}

func bifLatin1ToUtf8(v *Mlrval) *Mlrval {
	switch v.Type() {
	case MT_STRING:
		return FromString(latin1ToUtf8(v.printrep))
	case MT_MAP:
		out := NewMlrmap()
		for e := v.mapval.Head; e != nil; e = e.Next {
			out.Put(latin1ToUtf8(e.Key), bifLatin1ToUtf8(e.Value))
		}
		return FromMap(out)
	case MT_ARRAY:
		out := make([]*Mlrval, len(v.arrayval))
		for i, e := range v.arrayval {
			out[i] = bifLatin1ToUtf8(e)
		}
		return FromArray(out)
	}
	return v
}

func bifUtf8ToLatin1(v *Mlrval) *Mlrval {
	switch v.Type() {
	case MT_STRING:
		return FromString(utf8ToLatin1(v.printrep))
	case MT_MAP:
		out := NewMlrmap()
		for e := v.mapval.Head; e != nil; e = e.Next {
			out.Put(utf8ToLatin1(e.Key), bifUtf8ToLatin1(e.Value))
		}
		return FromMap(out)
	case MT_ARRAY:
		out := make([]*Mlrval, len(v.arrayval))
		for i, e := range v.arrayval {
			out[i] = bifUtf8ToLatin1(e)
		}
		return FromArray(out)
	}
	return v
}

// ---------------------------------------------------------------- conversion impls

func bifBoolean(in *Interp, args []*Mlrval, _ []*ASTNode) *Mlrval {
	a := args[0]
	switch a.Type() {
	case MT_BOOLEAN:
		return a
	case MT_STRING:
		if a.printrep == "true" {
			return TRUE
		}
		if a.printrep == "false" {
			return FALSE
		}
		return ERROR
	case MT_INT:
		return FromBool(a.intval != 0)
	case MT_FLOAT:
		return FromBool(a.floatval != 0)
	case MT_ABSENT:
		return ABSENT
	case MT_VOID:
		return VOID
	}
	return ERROR
}

func bifFloat(in *Interp, args []*Mlrval, _ []*ASTNode) *Mlrval {
	a := args[0]
	switch a.Type() {
	case MT_FLOAT:
		return a
	case MT_INT:
		return FromFloat(float64(a.intval))
	case MT_BOOLEAN:
		if a.boolval {
			return FromFloat(1)
		}
		return FromFloat(0)
	case MT_STRING:
		v := inferredFromString(a.printrep)
		if v.Type() == MT_INT {
			return FromFloat(float64(v.intval))
		}
		if v.Type() == MT_FLOAT {
			return FromFloat(v.floatval)
		}
		return ERROR
	case MT_ABSENT:
		return ABSENT
	case MT_VOID:
		return VOID
	}
	return ERROR
}

func bifInt(in *Interp, args []*Mlrval, _ []*ASTNode) *Mlrval {
	a := args[0]
	if len(args) == 2 && (a.Type() == MT_STRING) {
		if args[1].Type() != MT_INT {
			return ERROR
		}
		base := int(args[1].intval)
		s := a.printrep
		neg := false
		if strings.HasPrefix(s, "-") {
			neg = true
			s = s[1:]
		}
		if base == 16 {
			s = strings.TrimPrefix(strings.TrimPrefix(s, "0x"), "0X")
		} else if base == 2 {
			s = strings.TrimPrefix(strings.TrimPrefix(s, "0b"), "0B")
		} else if base == 8 {
			s = strings.TrimPrefix(strings.TrimPrefix(s, "0o"), "0O")
		}
		v, err := strconv.ParseInt(s, base, 64)
		if err != nil {
			u, err2 := strconv.ParseUint(s, base, 64)
			if err2 != nil {
				return ERROR
			}
			v = int64(u)
		}
		if neg {
			v = -v
		}
		return FromInt(v)
	}
	switch a.Type() {
	case MT_INT:
		return a
	case MT_FLOAT:
		return FromInt(int64(a.floatval))
	case MT_BOOLEAN:
		if a.boolval {
			return FromInt(1)
		}
		return FromInt(0)
	case MT_STRING:
		s := a.printrep
		v := inferredFromString(s)
		if v.Type() == MT_INT {
			return FromInt(v.intval)
		}
		if v.Type() == MT_FLOAT {
			return FromInt(int64(v.floatval))
		}
		// leading-zero octal
		if i, err := strconv.ParseInt(s, 0, 64); err == nil {
			return FromInt(i)
		}
		return ERROR
	case MT_ABSENT:
		return ABSENT
	case MT_VOID:
		return VOID
	}
	return ERROR
}

func bifJoink(in *Interp, args []*Mlrval, _ []*ASTNode) *Mlrval {
	a := args[0]
	sep := args[1].String()
	switch a.Type() {
	case MT_MAP:
		return FromString(strings.Join(a.mapval.Keys(), sep))
	case MT_ARRAY:
		parts := make([]string, len(a.arrayval))
		for i := range a.arrayval {
			parts[i] = strconv.Itoa(i + 1)
		}
		return FromString(strings.Join(parts, sep))
	case MT_ABSENT:
		return ABSENT
	}
	return ERROR
}

func bifJoinv(in *Interp, args []*Mlrval, _ []*ASTNode) *Mlrval {
	a := args[0]
	sep := args[1].String()
	switch a.Type() {
	case MT_MAP:
		parts := make([]string, 0, a.mapval.Len())
		for e := a.mapval.Head; e != nil; e = e.Next {
			parts = append(parts, e.Value.String())
		}
		return FromString(strings.Join(parts, sep))
	case MT_ARRAY:
		parts := make([]string, len(a.arrayval))
		for i, e := range a.arrayval {
			parts[i] = e.String()
		}
		return FromString(strings.Join(parts, sep))
	case MT_ABSENT:
		return ABSENT
	}
	return ERROR
}

func bifJoinkv(in *Interp, args []*Mlrval, _ []*ASTNode) *Mlrval {
	a := args[0]
	ps := args[1].String()
	fs := args[2].String()
	switch a.Type() {
	case MT_MAP:
		parts := make([]string, 0, a.mapval.Len())
		for e := a.mapval.Head; e != nil; e = e.Next {
			parts = append(parts, e.Key+ps+e.Value.String())
		}
		return FromString(strings.Join(parts, fs))
	case MT_ARRAY:
		parts := make([]string, len(a.arrayval))
		for i, e := range a.arrayval {
			parts[i] = strconv.Itoa(i+1) + ps + e.String()
		}
		return FromString(strings.Join(parts, fs))
	case MT_ABSENT:
		return ABSENT
	}
	return ERROR
}

func bifSplitax(args []*Mlrval, infer bool) *Mlrval {
	a := args[0]
	if a.Type() == MT_ABSENT {
		return ABSENT
	}
	if a.Type() == MT_MAP || a.Type() == MT_ARRAY || a.Type() == MT_ERROR {
		return ERROR
	}
	s := a.String()
	sep := args[1].String()
	if s == "" {
		return FromArray([]*Mlrval{})
	}
	var parts []string
	if sep == "" {
		for _, r := range s {
			parts = append(parts, string(r))
		}
	} else {
		parts = strings.Split(s, sep)
	}
	out := make([]*Mlrval, len(parts))
	for i, p := range parts {
		if infer {
			out[i] = inferredFromString(p)
		} else {
			out[i] = FromString(p)
		}
	}
	return FromArray(out)
}

func bifSplitnv(args []*Mlrval, infer bool) *Mlrval {
	a := args[0]
	if a.Type() == MT_ABSENT {
		return ABSENT
	}
	if a.Type() == MT_MAP || a.Type() == MT_ARRAY || a.Type() == MT_ERROR {
		return ERROR
	}
	s := a.String()
	sep := args[1].String()
	out := NewMlrmap()
	if s == "" {
		return FromMap(out)
	}
	parts := strings.Split(s, sep)
	for i, p := range parts {
		if infer {
			out.Put(strconv.Itoa(i+1), inferredFromString(p))
		} else {
			out.Put(strconv.Itoa(i+1), FromString(p))
		}
	}
	return FromMap(out)
}

func bifSplitkv(args []*Mlrval, infer bool) *Mlrval {
	a := args[0]
	if a.Type() == MT_ABSENT {
		return ABSENT
	}
	if a.Type() == MT_MAP || a.Type() == MT_ARRAY || a.Type() == MT_ERROR {
		return ERROR
	}
	s := a.String()
	ps := args[1].String()
	fs := args[2].String()
	out := NewMlrmap()
	if s == "" {
		return FromMap(out)
	}
	pairs := strings.Split(s, fs)
	for i, pair := range pairs {
		idx := strings.Index(pair, ps)
		var k, v string
		if idx < 0 {
			k = strconv.Itoa(i + 1)
			v = pair
		} else {
			k = pair[:idx]
			v = pair[idx+len(ps):]
		}
		if infer {
			out.Put(k, inferredFromString(v))
		} else {
			out.Put(k, FromString(v))
		}
	}
	return FromMap(out)
}

func bifJSONParse(in *Interp, args []*Mlrval, _ []*ASTNode) *Mlrval {
	a := args[0]
	if a.Type() == MT_ABSENT {
		return ABSENT
	}
	if a.Type() == MT_MAP || a.Type() == MT_ARRAY {
		return a
	}
	v, err := ParseJSONValue(a.String())
	if err != nil {
		return ERROR
	}
	return v
}

func bifJSONStringify(in *Interp, args []*Mlrval, _ []*ASTNode) *Mlrval {
	a := args[0]
	multiline := false
	if len(args) == 2 {
		if args[1].Type() != MT_BOOLEAN {
			return ERROR
		}
		multiline = args[1].boolval
	}
	if a.Type() == MT_ABSENT {
		return ABSENT
	}
	return FromString(jsonStringifyValue(a, multiline))
}

// ---------------------------------------------------------------- system

func bifExec(in *Interp, args []*Mlrval, _ []*ASTNode) *Mlrval {
	if args[0].Type() != MT_STRING {
		return ERROR
	}
	cmdName := args[0].String()
	var cmdArgs []string
	if len(args) >= 2 {
		if args[1].Type() != MT_ARRAY {
			return ERROR
		}
		for _, e := range args[1].arrayval {
			cmdArgs = append(cmdArgs, e.String())
		}
	}
	cmd := exec.Command(cmdName, cmdArgs...)
	cmd.Stderr = os.Stderr
	if len(args) >= 3 && args[2].Type() == MT_MAP {
		opts := args[2].mapval
		if env := opts.Get("env"); env != nil {
			if env.Type() == MT_ARRAY {
				for _, e := range env.arrayval {
					cmd.Env = append(cmd.Env, e.String())
				}
			} else {
				cmd.Env = append(cmd.Env, env.String())
			}
		}
		if dir := opts.Get("dir"); dir != nil {
			cmd.Dir = dir.String()
		}
		if si := opts.Get("stdin_string"); si != nil {
			cmd.Stdin = strings.NewReader(si.String())
		}
		if co := opts.Get("combined_output"); co != nil && co.Type() == MT_BOOLEAN && co.boolval {
			out, err := cmd.CombinedOutput()
			if err != nil && len(out) == 0 {
				return ERROR
			}
			return FromString(strings.TrimRight(string(out), "\n"))
		}
	}
	out, err := cmd.Output()
	if err != nil && len(out) == 0 {
		return ERROR
	}
	return FromString(strings.TrimRight(string(out), "\n"))
}

func bifStat(in *Interp, args []*Mlrval, _ []*ASTNode) *Mlrval {
	if args[0].Type() == MT_ABSENT {
		return ABSENT
	}
	path := args[0].String()
	fi, err := os.Stat(path)
	if err != nil {
		return NewError(err.Error())
	}
	out := NewMlrmap()
	out.Put("name", FromString(fi.Name()))
	out.Put("size", FromInt(fi.Size()))
	out.Put("mode", FromIntWithRep(int64(fi.Mode().Perm()), fmt.Sprintf("0%o", fi.Mode().Perm())))
	out.Put("modtime", FromInt(fi.ModTime().Unix()))
	out.Put("isdir", FromBool(fi.IsDir()))
	return FromMap(out)
}

// ---------------------------------------------------------------- higher-order

func (in *Interp) callFuncValue(f *Mlrval, args []*Mlrval) *Mlrval {
	if f.Type() != MT_FUNC {
		in.fatal("mlr: higher-order function: second argument must be a function; got %s.", f.TypeName())
	}
	return in.callUserFunc(f.funcval, args)
}

func hofCheck(in *Interp, name string, args []*Mlrval) {
	if args[0].Type() != MT_MAP && args[0].Type() != MT_ARRAY {
		in.fatal("mlr: %s: first argument must be a map or array; got %s.", name, args[0].TypeName())
	}
	if args[1].Type() != MT_FUNC {
		in.fatal("mlr: %s: second argument must be a function; got %s.", name, args[1].TypeName())
	}
}

func hofBoolCheck(in *Interp, name string, v *Mlrval) bool {
	if v.Type() != MT_BOOLEAN {
		in.fatal("mlr: %s: function returned non-boolean \"%s\".", name, v.String())
	}
	return v.boolval
}

func bifAny(in *Interp, args []*Mlrval, _ []*ASTNode) *Mlrval {
	if args[0].Type() == MT_ABSENT {
		return ABSENT
	}
	hofCheck(in, "any", args)
	f := args[1]
	if args[0].Type() == MT_ARRAY {
		for _, e := range args[0].arrayval {
			if hofBoolCheck(in, "any", in.callFuncValue(f, []*Mlrval{e})) {
				return TRUE
			}
		}
		return FALSE
	}
	for e := args[0].mapval.Head; e != nil; e = e.Next {
		if hofBoolCheck(in, "any", in.callFuncValue(f, []*Mlrval{inferredFromString(e.Key), e.Value})) {
			return TRUE
		}
	}
	return FALSE
}

func bifEvery(in *Interp, args []*Mlrval, _ []*ASTNode) *Mlrval {
	if args[0].Type() == MT_ABSENT {
		return ABSENT
	}
	hofCheck(in, "every", args)
	f := args[1]
	if args[0].Type() == MT_ARRAY {
		for _, e := range args[0].arrayval {
			if !hofBoolCheck(in, "every", in.callFuncValue(f, []*Mlrval{e})) {
				return FALSE
			}
		}
		return TRUE
	}
	for e := args[0].mapval.Head; e != nil; e = e.Next {
		if !hofBoolCheck(in, "every", in.callFuncValue(f, []*Mlrval{inferredFromString(e.Key), e.Value})) {
			return FALSE
		}
	}
	return TRUE
}

func bifApply(in *Interp, args []*Mlrval, _ []*ASTNode) *Mlrval {
	if args[0].Type() == MT_ABSENT {
		return ABSENT
	}
	hofCheck(in, "apply", args)
	f := args[1]
	if args[0].Type() == MT_ARRAY {
		out := make([]*Mlrval, 0, len(args[0].arrayval))
		for _, e := range args[0].arrayval {
			out = append(out, in.callFuncValue(f, []*Mlrval{e}))
		}
		return FromArray(out)
	}
	out := NewMlrmap()
	for e := args[0].mapval.Head; e != nil; e = e.Next {
		r := in.callFuncValue(f, []*Mlrval{inferredFromString(e.Key), e.Value})
		if r.Type() != MT_MAP {
			in.fatal("mlr: apply: function returned non-map \"%s\".", r.String())
		}
		for re := r.mapval.Head; re != nil; re = re.Next {
			out.Put(re.Key, re.Value)
		}
	}
	return FromMap(out)
}

func bifSelect(in *Interp, args []*Mlrval, _ []*ASTNode) *Mlrval {
	if args[0].Type() == MT_ABSENT {
		return ABSENT
	}
	hofCheck(in, "select", args)
	f := args[1]
	if args[0].Type() == MT_ARRAY {
		out := make([]*Mlrval, 0)
		for _, e := range args[0].arrayval {
			if hofBoolCheck(in, "select", in.callFuncValue(f, []*Mlrval{e})) {
				out = append(out, e)
			}
		}
		return FromArray(out)
	}
	out := NewMlrmap()
	for e := args[0].mapval.Head; e != nil; e = e.Next {
		if hofBoolCheck(in, "select", in.callFuncValue(f, []*Mlrval{inferredFromString(e.Key), e.Value})) {
			out.Put(e.Key, e.Value)
		}
	}
	return FromMap(out)
}

func bifReduce(in *Interp, args []*Mlrval, _ []*ASTNode) *Mlrval {
	if args[0].Type() == MT_ABSENT {
		return ABSENT
	}
	hofCheck(in, "reduce", args)
	f := args[1]
	if args[0].Type() == MT_ARRAY {
		arr := args[0].arrayval
		if len(arr) == 0 {
			return ABSENT
		}
		acc := arr[0]
		for _, e := range arr[1:] {
			acc = in.callFuncValue(f, []*Mlrval{acc, e})
		}
		return acc
	}
	m := args[0].mapval
	if m.Len() == 0 {
		return ABSENT
	}
	acck := inferredFromString(m.Head.Key)
	accv := m.Head.Value
	for e := m.Head.Next; e != nil; e = e.Next {
		r := in.callFuncValue(f, []*Mlrval{acck, accv, inferredFromString(e.Key), e.Value})
		if r.Type() != MT_MAP || r.mapval.Len() == 0 {
			in.fatal("mlr: reduce: function returned non-map \"%s\".", r.String())
		}
		acck = inferredFromString(r.mapval.Head.Key)
		accv = r.mapval.Head.Value
	}
	out := NewMlrmap()
	out.Put(acck.String(), accv)
	return FromMap(out)
}

func bifFold(in *Interp, args []*Mlrval, _ []*ASTNode) *Mlrval {
	if args[0].Type() == MT_ABSENT {
		return ABSENT
	}
	hofCheck(in, "fold", args)
	f := args[1]
	if args[0].Type() == MT_ARRAY {
		acc := args[2]
		for _, e := range args[0].arrayval {
			acc = in.callFuncValue(f, []*Mlrval{acc, e})
		}
		return acc
	}
	if args[2].Type() != MT_MAP || args[2].mapval.Len() == 0 {
		in.fatal("mlr: fold: accumulator argument must be a non-empty map.")
	}
	acck := inferredFromString(args[2].mapval.Head.Key)
	accv := args[2].mapval.Head.Value
	for e := args[0].mapval.Head; e != nil; e = e.Next {
		r := in.callFuncValue(f, []*Mlrval{acck, accv, inferredFromString(e.Key), e.Value})
		if r.Type() != MT_MAP || r.mapval.Len() == 0 {
			in.fatal("mlr: fold: function returned non-map \"%s\".", r.String())
		}
		acck = inferredFromString(r.mapval.Head.Key)
		accv = r.mapval.Head.Value
	}
	out := NewMlrmap()
	out.Put(acck.String(), accv)
	return FromMap(out)
}

func bifSort(in *Interp, args []*Mlrval, _ []*ASTNode) *Mlrval {
	a := args[0]
	if a.Type() == MT_ABSENT {
		return ABSENT
	}
	if a.Type() != MT_MAP && a.Type() != MT_ARRAY {
		return a
	}
	if len(args) == 2 && args[1].Type() == MT_FUNC {
		f := args[1]
		if a.Type() == MT_ARRAY {
			out := make([]*Mlrval, len(a.arrayval))
			copy(out, a.arrayval)
			sortSliceStable(len(out), func(i, j int) bool {
				r := in.callFuncValue(f, []*Mlrval{out[i], out[j]})
				if r.Type() != MT_INT {
					if r.Type() == MT_FLOAT {
						return r.floatval < 0
					}
					in.fatal("mlr: sort: comparator function returned non-int \"%s\".", r.String())
				}
				return r.intval < 0
			}, func(i, j int) { out[i], out[j] = out[j], out[i] })
			return FromArray(out)
		}
		var entries []*MlrmapEntry
		for e := a.mapval.Head; e != nil; e = e.Next {
			entries = append(entries, e)
		}
		sortSliceStable(len(entries), func(i, j int) bool {
			r := in.callFuncValue(f, []*Mlrval{inferredFromString(entries[i].Key), entries[i].Value, inferredFromString(entries[j].Key), entries[j].Value})
			if r.Type() != MT_INT {
				if r.Type() == MT_FLOAT {
					return r.floatval < 0
				}
				in.fatal("mlr: sort: comparator function returned non-int \"%s\".", r.String())
			}
			return r.intval < 0
		}, func(i, j int) { entries[i], entries[j] = entries[j], entries[i] })
		out := NewMlrmap()
		for _, e := range entries {
			out.Put(e.Key, e.Value)
		}
		return FromMap(out)
	}
	flags := ""
	if len(args) == 2 {
		flags = args[1].String()
	}
	reverse := strings.Contains(flags, "r")
	byValue := strings.Contains(flags, "v")
	var cmp func(x, y *Mlrval) int
	switch {
	case strings.Contains(flags, "t"):
		cmp = naturalCompare
	case strings.Contains(flags, "c"):
		cmp = caseFoldCompare
	case strings.Contains(flags, "f"):
		cmp = lexicalCompare
	default:
		cmp = collatedCompare
	}
	if a.Type() == MT_ARRAY {
		out := make([]*Mlrval, len(a.arrayval))
		copy(out, a.arrayval)
		sortSliceStable(len(out), func(i, j int) bool {
			c := cmp(out[i], out[j])
			if reverse {
				return c > 0
			}
			return c < 0
		}, func(i, j int) { out[i], out[j] = out[j], out[i] })
		return FromArray(out)
	}
	var entries []*MlrmapEntry
	for e := a.mapval.Head; e != nil; e = e.Next {
		entries = append(entries, e)
	}
	sortSliceStable(len(entries), func(i, j int) bool {
		var c int
		if byValue {
			c = cmp(entries[i].Value, entries[j].Value)
		} else {
			c = cmp(inferredFromString(entries[i].Key), inferredFromString(entries[j].Key))
		}
		if reverse {
			return c > 0
		}
		return c < 0
	}, func(i, j int) { entries[i], entries[j] = entries[j], entries[i] })
	out := NewMlrmap()
	for _, e := range entries {
		out.Put(e.Key, e.Value)
	}
	return FromMap(out)
}

func crc32Checksum(b []byte) uint32 {
	var table [256]uint32
	for i := 0; i < 256; i++ {
		c := uint32(i)
		for j := 0; j < 8; j++ {
			if c&1 == 1 {
				c = 0xEDB88320 ^ (c >> 1)
			} else {
				c >>= 1
			}
		}
		table[i] = c
	}
	crc := uint32(0xFFFFFFFF)
	for _, x := range b {
		crc = table[byte(crc)^x] ^ (crc >> 8)
	}
	return crc ^ 0xFFFFFFFF
}
EOF
echo ok"}

