// ---------------------------------------------------------------- system

func bifExec(in *Interp, args []*Mlrval, _ []*ASTNode) *Mlrval {
	if args[0].Type() != MT_STRING {
		return ERROR
	}
	cmdName := args[0].String()
	var cmdArgs []string
	if len(args) >= 2 {
		if args[1].Type() != MT_ARRAY {
			return ERROR
		}
		for _, e := range args[1].arrayval {
			cmdArgs = append(cmdArgs, e.String())
		}
	}
	cmd := exec.Command(cmdName, cmdArgs...)
	cmd.Stderr = os.Stderr
	if len(args) >= 3 && args[2].Type() == MT_MAP {
		opts := args[2].mapval
		if env := opts.Get("env"); env != nil {
			if env.Type() == MT_ARRAY {
				for _, e := range env.arrayval {
					cmd.Env = append(cmd.Env, e.String())
				}
			} else {
				cmd.Env = append(cmd.Env, env.String())
			}
		}
		if dir := opts.Get("dir"); dir != nil {
			cmd.Dir = dir.String()
		}
		if si := opts.Get("stdin_string"); si != nil {
			cmd.Stdin = strings.NewReader(si.String())
		}
		if co := opts.Get("combined_output"); co != nil && co.Type() == MT_BOOLEAN && co.boolval {
			out, err := cmd.CombinedOutput()
			if err != nil && len(out) == 0 {
				return ERROR
			}
			return FromString(strings.TrimRight(string(out), "\n"))
		}
	}
	out, err := cmd.Output()
	if err != nil && len(out) == 0 {
		return ERROR
	}
	return FromString(strings.TrimRight(string(out), "\n"))
}

func bifStat(in *Interp, args []*Mlrval, _ []*ASTNode) *Mlrval {
	if args[0].Type() == MT_ABSENT {
		return ABSENT
	}
	path := args[0].String()
	fi, err := os.Stat(path)
	if err != nil {
		return NewError(err.Error())
	}
	out := NewMlrmap()
	out.Put("name", FromString(fi.Name()))
	out.Put("size", FromInt(fi.Size()))
	out.Put("mode", FromIntWithRep(int64(fi.Mode().Perm()), fmt.Sprintf("0%o", fi.Mode().Perm())))
	out.Put("modtime", FromInt(fi.ModTime().Unix()))
	out.Put("isdir", FromBool(fi.IsDir()))
	return FromMap(out)
}

// ---------------------------------------------------------------- higher-order

func (in *Interp) callFuncValue(f *Mlrval, args []*Mlrval) *Mlrval {
	if f.Type() != MT_FUNC {
		in.fatal("mlr: higher-order function: second argument must be a function; got %s.", f.TypeName())
	}
	return in.callUserFunc(f.funcval, args)
}

func hofCheck(in *Interp, name string, args []*Mlrval) {
	if args[0].Type() != MT_MAP && args[0].Type() != MT_ARRAY {
		in.fatal("mlr: %s: first argument must be a map or array; got %s.", name, args[0].TypeName())
	}
	if args[1].Type() != MT_FUNC {
		in.fatal("mlr: %s: second argument must be a function; got %s.", name, args[1].TypeName())
	}
}

func hofBoolCheck(in *Interp, name string, v *Mlrval) bool {
	if v.Type() != MT_BOOLEAN {
		in.fatal("mlr: %s: function returned non-boolean \"%s\".", name, v.String())
	}
	return v.boolval
}

func bifAny(in *Interp, args []*Mlrval, _ []*ASTNode) *Mlrval {
	if args[0].Type() == MT_ABSENT {
		return ABSENT
	}
	hofCheck(in, "any", args)
	f := args[1]
	if args[0].Type() == MT_ARRAY {
		for _, e := range args[0].arrayval {
			if hofBoolCheck(in, "any", in.callFuncValue(f, []*Mlrval{e})) {
				return TRUE
			}
		}
		return FALSE
	}
	for e := args[0].mapval.Head; e != nil; e = e.Next {
		if hofBoolCheck(in, "any", in.callFuncValue(f, []*Mlrval{inferredFromString(e.Key), e.Value})) {
			return TRUE
		}
	}
	return FALSE
}

func bifEvery(in *Interp, args []*Mlrval, _ []*ASTNode) *Mlrval {
	if args[0].Type() == MT_ABSENT {
		return ABSENT
	}
	hofCheck(in, "every", args)
	f := args[1]
	if args[0].Type() == MT_ARRAY {
		for _, e := range args[0].arrayval {
			if !hofBoolCheck(in, "every", in.callFuncValue(f, []*Mlrval{e})) {
				return FALSE
			}
		}
		return TRUE
	}
	for e := args[0].mapval.Head; e != nil; e = e.Next {
		if !hofBoolCheck(in, "every", in.callFuncValue(f, []*Mlrval{inferredFromString(e.Key), e.Value})) {
			return FALSE
		}
	}
	return TRUE
}

func bifApply(in *Interp, args []*Mlrval, _ []*ASTNode) *Mlrval {
	if args[0].Type() == MT_ABSENT {
		return ABSENT
	}
	hofCheck(in, "apply", args)
	f := args[1]
	if args[0].Type() == MT_ARRAY {
		out := make([]*Mlrval, 0, len(args[0].arrayval))
		for _, e := range args[0].arrayval {
			out = append(out, in.callFuncValue(f, []*Mlrval{e}))
		}
		return FromArray(out)
	}
	out := NewMlrmap()
	for e := args[0].mapval.Head; e != nil; e = e.Next {
		r := in.callFuncValue(f, []*Mlrval{inferredFromString(e.Key), e.Value})
		if r.Type() != MT_MAP {
