func crc32Checksum(b []byte) uint32 {
	var table [256]uint32
	for i := 0; i < 256; i++ {
		c := uint32(i)
		for j := 0; j < 8; j++ {
			if c&1 == 1 {
				c = 0xEDB88320 ^ (c >> 1)
			} else {
				c >>= 1
			}
		}
		table[i] = c
	}
	crc := uint32(0xFFFFFFFF)
	for _, x := range b {
		crc = table[byte(crc)^x] ^ (crc >> 8)
	}
	return crc ^ 0xFFFFFFFF
}
