package main

import (
	"math"
	"strings"
	"unicode/utf8"
)

// collectionValues returns the values of an array or map, or nil if not a collection.
func collectionValues(v *Mlrval) ([]*Mlrval, bool) {
	switch v.Type() {
	case MT_ARRAY:
		return v.arrayval, true
	case MT_MAP:
		return v.mapval.Values(), true
	}
	return nil, false
}

// ---------------------------------------------------------------- streaming accumulators

type momentAccumulator struct {
	n     int64
	sumx  *Mlrval
	sumx2 *Mlrval
	sumx3 *Mlrval
	sumx4 *Mlrval
}

func newMomentAccumulator() *momentAccumulator {
	return &momentAccumulator{sumx: FromInt(0), sumx2: FromInt(0), sumx3: FromInt(0), sumx4: FromInt(0)}
}

func (acc *momentAccumulator) ingest(v *Mlrval) {
	acc.n++
	acc.sumx = binaryOpPlus(acc.sumx, v)
	x2 := binaryOpTimes(v, v)
	acc.sumx2 = binaryOpPlus(acc.sumx2, x2)
	x3 := binaryOpTimes(x2, v)
	acc.sumx3 = binaryOpPlus(acc.sumx3, x3)
	acc.sumx4 = binaryOpPlus(acc.sumx4, binaryOpTimes(x3, v))
}

func (acc *momentAccumulator) mean() *Mlrval {
	if acc.n == 0 {
		return VOID
	}
	return binaryOpDivide(acc.sumx, FromInt(acc.n))
}

// variance with Miller's formula: (sumx2 - mean*(2*sumx - n*mean)) / (n-1)
func getVar(n int64, mean, sumx, sumx2 float64) float64 {
	numerator := sumx2 - mean*(2.0*sumx-float64(n)*mean)
	if numerator < 0 {
		numerator = 0
	}
	denominator := float64(n) - 1.0
	return numerator / denominator
}

func (acc *momentAccumulator) variance() *Mlrval {
	if acc.n < 2 {
		return VOID
	}
	n := float64(acc.n)
	sumx := asFloat(acc.sumx)
	sumx2 := asFloat(acc.sumx2)
	mean := sumx / n
	return FromFloat(getVar(acc.n, mean, sumx, sumx2))
}

func (acc *momentAccumulator) stddev() *Mlrval {
	v := acc.variance()
	if v.Type() != MT_FLOAT {
		return v
	}
	return FromFloat(math.Sqrt(v.floatval))
}

func (acc *momentAccumulator) meaneb() *Mlrval {
	v := acc.variance()
	if v.Type() != MT_FLOAT {
		return v
	}
	return FromFloat(math.Sqrt(v.floatval / float64(acc.n)))
}

func (acc *momentAccumulator) skewness() *Mlrval {
	if acc.n < 2 {
		return VOID
	}
	n := float64(acc.n)
	sumx := asFloat(acc.sumx)
	sumx2 := asFloat(acc.sumx2)
	sumx3 := asFloat(acc.sumx3)
	mean := sumx / n
	numer := sumx3 - mean*(3.0*sumx2-2.0*n*mean*mean)
	numer = numer / n
	denom := math.Pow((sumx2/n - mean*mean), 1.5)
	return FromFloat(numer / denom)
}

func (acc *momentAccumulator) kurtosis() *Mlrval {
	if acc.n < 2 {
		return VOID
	}
	n := float64(acc.n)
	sumx := asFloat(acc.sumx)
	sumx2 := asFloat(acc.sumx2)
	sumx3 := asFloat(acc.sumx3)
	sumx4 := asFloat(acc.sumx4)
	mean := sumx / n
	numer := sumx4 - mean*(4.0*sumx3-mean*(6.0*sumx2-3.0*n*mean*mean))
	numer = numer / n
	denom := (sumx2/n - mean*mean)
	denom = denom * denom
	return FromFloat(numer/denom - 3.0)
}

// ---------------------------------------------------------------- percentiles

// sortForPercentiles sorts values using collation (numbers before strings).
func sortedCopy(vals []*Mlrval) []*Mlrval {
	out := make([]*Mlrval, len(vals))
	copy(out, vals)
	sortSliceStable(len(out), func(i, j int) bool {
		return collatedCompare(out[i], out[j]) < 0
	}, func(i, j int) { out[i], out[j] = out[j], out[i] })
	return out
}

func percentileNonInterpolated(sorted []*Mlrval, p float64) *Mlrval {
	n := len(sorted)
	if n == 0 {
		return VOID
	}
	idx := int(p / 100.0 * float64(n))
	if p/100.0*float64(n) < 0 {
		idx = 0
	}
	if idx < 0 {
		idx = 0
	}
	if idx >= n {
		idx = n - 1
	}
	return sorted[idx]
}

func percentileInterpolated(sorted []*Mlrval, p float64) *Mlrval {
	n := len(sorted)
	if n == 0 {
		return VOID
	}
	findex := (p / 100.0) * float64(n-1)
	if findex < 0 {
		findex = 0
	}
	iidx := int(findex)
	if iidx >= n-1 {
		return sorted[n-1]
	}
	frac := findex - float64(iidx)
	lo := sorted[iidx]
	hi := sorted[iidx+1]
	flo, ok1 := lo.GetNumericToFloat()
	fhi, ok2 := hi.GetNumericToFloat()
	if !ok1 || !ok2 {
		return ERROR
	}
	// lo + frac*(hi-lo)
	diff := binaryOpMinus(hi, lo)
	prod := binaryOpTimes(FromFloat(frac), diff)
	_ = flo
	_ = fhi
	return binaryOpPlus(lo, prod)
}

func parsePercentileOptions(opts *Mlrval) (interpolate, outputArray, isSorted bool, ok bool) {
	if opts == nil {
		return false, false, false, true
	}
	if opts.Type() != MT_MAP {
		return false, false, false, false
	}
	for e := opts.mapval.Head; e != nil; e = e.Next {
		b := e.Value.Type() == MT_BOOLEAN && e.Value.boolval
		switch e.Key {
		case "interpolate_linearly", "il":
			interpolate = b
		case "output_array_not_map", "oa":
			outputArray = b
		case "array_is_sorted", "ais":
			isSorted = b
		}
	}
	return interpolate, outputArray, isSorted, true
}

func bifPercentiles(in *Interp, args []*Mlrval, _ []*ASTNode) *Mlrval {
	coll := args[0]
	if coll.Type() == MT_ABSENT {
		return ABSENT
	}
	vals, ok := collectionValues(coll)
	if !ok {
		return ERROR
	}
	var opts *Mlrval
	if len(args) == 3 {
		opts = args[2]
	}
	interpolate, outputArray, isSorted, ok := parsePercentileOptions(opts)
	if !ok {
		return ERROR
	}
	var ps []*Mlrval
	switch args[1].Type() {
	case MT_ARRAY:
		ps = args[1].arrayval
	case MT_MAP:
		ps = args[1].mapval.Values()
	default:
		ps = []*Mlrval{args[1]}
	}
	sorted := vals
	if !isSorted {
		sorted = sortedCopy(vals)
	}
	outMap := NewMlrmap()
	outArr := make([]*Mlrval, 0, len(ps))
	for _, p := range ps {
		var r *Mlrval
		pf, isNum := p.GetNumericToFloat()
		if !isNum {
			r = ERROR
		} else if interpolate {
			r = percentileInterpolated(sorted, pf)
		} else {
			r = percentileNonInterpolated(sorted, pf)
		}
		if outputArray {
			outArr = append(outArr, r)
		} else {
			outMap.Put(p.String(), r)
		}
	}
	if outputArray {
		return FromArray(outArr)
	}
	return FromMap(outMap)
}

func bifPercentile(in *Interp, args []*Mlrval, _ []*ASTNode) *Mlrval {
	coll := args[0]
	if coll.Type() == MT_ABSENT {
		return ABSENT
	}
	vals, ok := collectionValues(coll)
	if !ok {
		return ERROR
	}
	var opts *Mlrval
	if len(args) == 3 {
		opts = args[2]
	}
	interpolate, _, isSorted, ok := parsePercentileOptions(opts)
	if !ok {
		return ERROR
	}
	pf, isNum := args[1].GetNumericToFloat()
	if !isNum {
		return ERROR
	}
	sorted := vals
	if !isSorted {
		sorted = sortedCopy(vals)
	}
	if interpolate {
		return percentileInterpolated(sorted, pf)
	}
	return percentileNonInterpolated(sorted, pf)
}

func bifMedian(in *Interp, args []*Mlrval, _ []*ASTNode) *Mlrval {
	newArgs := []*Mlrval{args[0], FromInt(50)}
	if len(args) == 2 {
		newArgs = append(newArgs, args[1])
	}
	return bifPercentile(in, newArgs, nil)
}

// ---------------------------------------------------------------- registration

func statsCollection(name string, f func(vals []*Mlrval) *Mlrval) builtinFunc {
	return func(in *Interp, args []*Mlrval, _ []*ASTNode) *Mlrval {
		if args[0].Type() == MT_ABSENT {
			return ABSENT
		}
		vals, ok := collectionValues(args[0])
		if !ok {
			return ERROR
		}
		return f(vals)
	}
}

func registerStatsBuiltins() {
	reg("count", 1, 1, statsCollection("count", func(vals []*Mlrval) *Mlrval { return FromInt(int64(len(vals))) }))
	reg("sum", 1, 1, statsCollection("sum", func(vals []*Mlrval) *Mlrval {
		acc := FromInt(0)
		for _, v := range vals {
			acc = binaryOpPlus(acc, v)
		}
		return acc
	}))
	reg("sum2", 1, 1, statsCollection("sum2", func(vals []*Mlrval) *Mlrval {
