		for _, v := range vals {
			acc = binaryOpPlus(acc, binaryOpTimes(v, v))
		}
		return acc
	}))
	reg("sum3", 1, 1, statsCollection("sum3", func(vals []*Mlrval) *Mlrval {
		acc := FromInt(0)
		for _, v := range vals {
