		}
		return acc
	}))
	reg("sum4", 1, 1, statsCollection("sum4", func(vals []*Mlrval) *Mlrval {
		acc := FromInt(0)
		for _, v := range vals {
			v2 := binaryOpTimes(v, v)
			acc = binaryOpPlus(acc, binaryOpTimes(v2, v2))
		}
		return acc
	}))
	reg("mean", 1, 1, statsCollection("mean", func(vals []*Mlrval) *Mlrval {
		if len(vals) == 0 {
			return VOID
		}
		acc := FromInt(0)
		for _, v := range vals {
			acc = binaryOpPlus(acc, v)
		}
		return binaryOpDivide(acc, FromInt(int64(len(vals))))
	}))
	momentF := func(getter func(*momentAccumulator) *Mlrval) builtinFunc {
		return statsCollection("", func(vals []*Mlrval) *Mlrval {
			acc := newMomentAccumulator()
			for _, v := range vals {
				if !v.IsNumeric() {
					return ERROR
				}
