			}
			return getter(acc)
		})
	}
	reg("variance", 1, 1, momentF((*momentAccumulator).variance))
	reg("var", 1, 1, momentF((*momentAccumulator).variance))
	reg("stddev", 1, 1, momentF((*momentAccumulator).stddev))
	reg("meaneb", 1, 1, momentF((*momentAccumulator).meaneb))
	reg("skewness", 1, 1, momentF((*momentAccumulator).skewness))
	reg("kurtosis", 1, 1, momentF((*momentAccumulator).kurtosis))
	reg("minlen", 1, 1, statsCollection("minlen", func(vals []*Mlrval) *Mlrval {
