func modeOrAntimode(vals []*Mlrval, isMode bool) *Mlrval {
	if len(vals) == 0 {
		return VOID
	}
	counts := map[string]int{}
	order := []string{}
	first := map[string]*Mlrval{}
	for _, v := range vals {
		s := v.String()
		if _, ok := counts[s]; !ok {
			order = append(order, s)
			first[s] = v
		}
		counts[s]++
	}
	best := order[0]
	for _, s := range order[1:] {
		if isMode {
			if counts[s] > counts[best] {
				best = s
			}
		} else {
			if counts[s] < counts[best] {
				best = s
			}
		}
	}
	return first[best]
}

// variadicMinMax implements min/max with Miller's type ordering.
// For min: numerics < booleans < voids < strings; absent ignored. Maps/arrays recursed.
func variadicMinMax(args []*Mlrval, isMin bool) *Mlrval {
	var result *Mlrval
	var visit func(v *Mlrval)
	visit = func(v *Mlrval) {
		switch v.Type() {
		case MT_ABSENT:
			return
		case MT_MAP:
			for e := v.mapval.Head; e != nil; e = e.Next {
				visit(e.Value)
			}
			return
		case MT_ARRAY:
			for _, e := range v.arrayval {
				visit(e)
			}
			return
		case MT_ERROR:
			result = ERROR
			return
		}
		if result == nil {
			result = v
			return
		}
		if result.Type() == MT_ERROR {
			return
		}
		result = minMaxPair(result, v, isMin)
	}
	for _, a := range args {
		visit(a)
	}
	if result == nil {
		return VOID
	}
	return result
}

// rank for min/max: numeric 1, bool 2, void 3, string 4
func minMaxRank(v *Mlrval) int {
	switch v.Type() {
	case MT_INT, MT_FLOAT:
		return 1
	case MT_BOOLEAN:
		return 2
	case MT_VOID:
		return 3
	case MT_STRING:
		return 4
	}
	return 5
}

func minMaxPair(a, b *Mlrval, isMin bool) *Mlrval {
	ra, rb := minMaxRank(a), minMaxRank(b)
	if ra != rb {
		// min: lower rank wins; max: higher rank wins... but void: "null loses" in max? Observed: max("",1) -> "" hmm
		if isMin {
			if ra < rb {
				return a
			}
			return b
		}
		if ra > rb {
			return a
		}
		return b
	}
	switch ra {
	case 1:
		if a.Type() == MT_INT && b.Type() == MT_INT {
			if isMin {
				if b.intval < a.intval {
					return b
				}
				return a
			}
			if b.intval > a.intval {
				return b
			}
			return a
		}
		fa, fb := asFloat(a), asFloat(b)
		if isMin {
			if fb < fa {
				return b
			}
			if fa < fb {
				return a
			}
			// equal: prefer... int over float? max(1,1.0) -> 1; min(1,1.0) -> 1; max(1.0,1) -> 1
			if a.Type() == MT_INT {
				return a
			}
			return b
		}
		if fb > fa {
			return b
		}
		if fa > fb {
			return a
		}
		if a.Type() == MT_INT {
			return a
		}
		return b
	case 2:
		if isMin {
			if !b.boolval {
				return b
			}
			return a
		}
		if b.boolval {
			return b
		}
		return a
	case 4:
		c := strings.Compare(a.printrep, b.printrep)
		if isMin {
			if c <= 0 {
				return a
			}
			return b
		}
		if c >= 0 {
			return a
		}
		return b
	}
	return a
}
