func localLocationFromArgs(args []*Mlrval, idx int) (*time.Location, error) {
	if len(args) > idx {
		return localLocation(args[idx].String())
	}
	return localLocation("")
}

var locationCache = map[string]*time.Location{}

func localLocation(name string) (*time.Location, error) {
	if name == "" {
		name = os.Getenv("TZ")
	}
	if name == "" {
		return time.UTC, nil
	}
	if loc, ok := locationCache[name]; ok {
		return loc, nil
	}
	loc, err := time.LoadLocation(name)
	if err != nil {
		return nil, err
	}
	locationCache[name] = loc
	return loc, nil
}

func checkTZ() {
	tz := os.Getenv("TZ")
	if tz != "" {
		if _, err := time.LoadLocation(tz); err != nil {
			fmt.Fprintf(os.Stderr, "mlr: TZ environment variable appears malformed: \"%s\"\n", tz)
			os.Exit(1)
		}
	}
}

