func bifSec2GMT(a *Mlrval, numDecimals int) *Mlrval {
	f, ok := a.GetNumericToFloat()
	if !ok {
		return a
	}
	return FromString(formatTimeFloat(f, time.UTC, "%Y-%m-%dT%H:%M:%SZ", numDecimals, true))
}

func bifSec2GMTDate(a *Mlrval) *Mlrval {
	f, ok := a.GetNumericToFloat()
	if !ok {
		return a
	}
	return FromString(formatTimeFloat(f, time.UTC, "%Y-%m-%d", 0, false))
}

// formatTimeFloat formats epoch seconds; if numDecimals>0 and the format has %S, uses fractional seconds.
func formatTimeFloat(f float64, loc *time.Location, format string, numDecimals int, allowFrac bool) string {
	sec := math.Floor(f)
	frac := f - sec
	nanos := int64(math.Round(frac * 1e9))
	if nanos >= 1e9 {
		nanos = 999999999
	}
	t := time.Unix(int64(sec), nanos).In(loc)
	if numDecimals > 0 && allowFrac {
		format = strings.Replace(format, "%S", "%"+strconv.Itoa(numDecimals)+"S", 1)
	}
	return strftimeGo(t, format)
}

func formatTimeNanos(ns int64, loc *time.Location, format string, numDecimals int, allowFrac bool) string {
	t := time.Unix(0, ns).In(loc)
	if numDecimals > 0 && allowFrac {
		format = strings.Replace(format, "%S", "%"+strconv.Itoa(numDecimals)+"S", 1)
	}
	return strftimeGo(t, format)
}

func bifStrftime(a, fmtv *Mlrval, loc *time.Location, isNanos bool) *Mlrval {
	if a.Type() == MT_ABSENT {
		return ABSENT
	}
	if fmtv.Type() != MT_STRING && fmtv.Type() != MT_VOID {
		return ERROR
	}
	if a.Type() == MT_VOID {
		return VOID
	}
	if isNanos {
		if a.Type() != MT_INT {
			return ERROR
		}
		t := time.Unix(0, a.intval).In(loc)
		return FromString(strftimeGo(t, fmtv.String()))
	}
	f, ok := a.GetNumericToFloat()
	if !ok {
		return ERROR
	}
	sec := math.Floor(f)
	frac := f - sec
	nanos := int64(math.Round(frac * 1e9))
	if nanos >= 1e9 {
		nanos = 999999999
	}
	t := time.Unix(int64(sec), nanos).In(loc)
	return FromString(strftimeGo(t, fmtv.String()))
}

var weekdayNames = []string{"Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"}
var monthNames = []string{"January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"}

// strftimeGo implements strftime-style formatting.
func strftimeGo(t time.Time, format string) string {
	var sb strings.Builder
	for i := 0; i < len(format); i++ {
		c := format[i]
		if c != '%' || i+1 >= len(format) {
			sb.WriteByte(c)
			continue
		}
		i++
		d := format[i]
		switch d {
		case 'Y':
			fmt.Fprintf(&sb, "%04d", t.Year())
		case 'C':
			fmt.Fprintf(&sb, "%02d", t.Year()/100)
		case 'y':
			fmt.Fprintf(&sb, "%02d", t.Year()%100)
		case 'm':
			fmt.Fprintf(&sb, "%02d", int(t.Month()))
		case 'd':
			fmt.Fprintf(&sb, "%02d", t.Day())
		case 'e':
			fmt.Fprintf(&sb, "%2d", t.Day())
		case 'H':
			fmt.Fprintf(&sb, "%02d", t.Hour())
		case 'k':
			fmt.Fprintf(&sb, "%2d", t.Hour())
		case 'I':
			h := t.Hour() % 12
			if h == 0 {
				h = 12
			}
			fmt.Fprintf(&sb, "%02d", h)
		case 'l':
			h := t.Hour() % 12
			if h == 0 {
				h = 12
			}
			fmt.Fprintf(&sb, "%2d", h)
		case 'M':
			fmt.Fprintf(&sb, "%02d", t.Minute())
		case 'S':
			fmt.Fprintf(&sb, "%02d", t.Second())
		case '1', '2', '3', '4', '5', '6', '7', '8', '9':
			if i+1 < len(format) && format[i+1] == 'S' {
				n := int(d - '0')
				i++
				fmt.Fprintf(&sb, "%02d.%s", t.Second(), fmt.Sprintf("%09d", t.Nanosecond())[:n])
			} else {
				sb.WriteByte('%')
				sb.WriteByte(d)
			}
		case 'j':
			fmt.Fprintf(&sb, "%03d", t.YearDay())
		case 'a':
			sb.WriteString(weekdayNames[t.Weekday()][:3])
		case 'A':
			sb.WriteString(weekdayNames[t.Weekday()])
		case 'b', 'h':
			sb.WriteString(monthNames[t.Month()-1][:3])
		case 'B':
			sb.WriteString(monthNames[t.Month()-1])
		case 'p':
			if t.Hour() < 12 {
				sb.WriteString("AM")
			} else {
				sb.WriteString("PM")
			}
		case 'Z':
			name, _ := t.Zone()
			sb.WriteString(name)
		case 'z':
			_, off := t.Zone()
			sign := '+'
			if off < 0 {
				sign = '-'
				off = -off
			}
			fmt.Fprintf(&sb, "%c%02d%02d", sign, off/3600, (off%3600)/60)
		case 's':
			fmt.Fprintf(&sb, "%d", t.Unix())
		case 'F':
			fmt.Fprintf(&sb, "%04d-%02d-%02d", t.Year(), int(t.Month()), t.Day())
		case 'T':
			fmt.Fprintf(&sb, "%02d:%02d:%02d", t.Hour(), t.Minute(), t.Second())
		case 'D':
			fmt.Fprintf(&sb, "%02d/%02d/%02d", int(t.Month()), t.Day(), t.Year()%100)
		case 'R':
			fmt.Fprintf(&sb, "%02d:%02d", t.Hour(), t.Minute())
		case 'r':
			h := t.Hour() % 12
			if h == 0 {
				h = 12
			}
			ampm := "AM"
			if t.Hour() >= 12 {
				ampm = "PM"
			}
			fmt.Fprintf(&sb, "%02d:%02d:%02d %s", h, t.Minute(), t.Second(), ampm)
		case 'c':
			fmt.Fprintf(&sb, "%s %s %2d %02d:%02d:%02d %04d", weekdayNames[t.Weekday()][:3], monthNames[t.Month()-1][:3], t.Day(), t.Hour(), t.Minute(), t.Second(), t.Year())
		case 'x':
			fmt.Fprintf(&sb, "%02d/%02d/%02d", int(t.Month()), t.Day(), t.Year()%100)
		case 'X':
			fmt.Fprintf(&sb, "%02d:%02d:%02d", t.Hour(), t.Minute(), t.Second())
		case 'v':
			fmt.Fprintf(&sb, "%2d-%s-%04d", t.Day(), monthNames[t.Month()-1][:3], t.Year())
		case 'u':
			wd := int(t.Weekday())
			if wd == 0 {
				wd = 7
			}
			fmt.Fprintf(&sb, "%d", wd)
		case 'w':
			fmt.Fprintf(&sb, "%d", int(t.Weekday()))
		case 'U':
			fmt.Fprintf(&sb, "%02d", (t.YearDay()+6-int(t.Weekday()))/7)
		case 'W':
			wd := (int(t.Weekday()) + 6) % 7
			fmt.Fprintf(&sb, "%02d", (t.YearDay()+6-wd)/7)
		case 'V':
			_, w := t.ISOWeek()
			fmt.Fprintf(&sb, "%02d", w)
		case 'G':
			y, _ := t.ISOWeek()
			fmt.Fprintf(&sb, "%04d", y)
		case 'g':
			y, _ := t.ISOWeek()
			fmt.Fprintf(&sb, "%02d", y%100)
		case 'n':
			sb.WriteByte('\n')
		case 't':
			sb.WriteByte('\t')
		case '%':
			sb.WriteByte('%')
		case 'N':
			fmt.Fprintf(&sb, "%09d", t.Nanosecond())
		case 'L':
			fmt.Fprintf(&sb, "%03d", t.Nanosecond()/1000000)
		case 'f':
			fmt.Fprintf(&sb, "%06d", t.Nanosecond()/1000)
		default:
			sb.WriteByte('%')
			sb.WriteByte(d)
		}
	}
	return sb.String()
}

// ---------------------------------------------------------------- strptime

type strptimeResult struct {
	year, month, day      int
	hour, minute, second  int
	nanos                 int
	hasOffset             bool
	offsetSeconds         int
	epochSeconds          *int64
	pm                    int // 0 none, 1 AM, 2 PM
	yday                  int
}

func parseNDigits(s string, pos int, maxDigits int) (int, int, bool) {
	start := pos
	val := 0
	for pos < len(s) && pos-start < maxDigits && s[pos] >= '0' && s[pos] <= '9' {
		val = val*10 + int(s[pos]-'0')
		pos++
	}
	if pos == start {
		return 0, pos, false
	}
	return val, pos, true
}

// strptimeGo parses input per format. Returns time and fractional nanos, or error.
func strptimeGo(input, format string, loc *time.Location) (time.Time, bool) {
	r := strptimeResult{year: 1970, month: 1, day: 1}
	pos := 0
	for i := 0; i < len(format); i++ {
		c := format[i]
		if c != '%' {
			if pos >= len(input) || input[pos] != c {
				return time.Time{}, false
			}
			pos++
			continue
		}
		i++
		if i >= len(format) {
			return time.Time{}, false
		}
		d := format[i]
		var ok bool
		switch d {
		case 'Y':
			neg := false
			if pos < len(input) && input[pos] == '-' {
				neg = true
				pos++
			}
			r.year, pos, ok = parseNDigits(input, pos, 4)
			if !ok {
				return time.Time{}, false
			}
			if neg {
				r.year = -r.year
			}
		case 'y':
			var y int
			y, pos, ok = parseNDigits(input, pos, 2)
			if !ok {
				return time.Time{}, false
			}
			if y < 69 {
				r.year = 2000 + y
			} else {
				r.year = 1900 + y
			}
		case 'm':
			r.month, pos, ok = parseNDigits(input, pos, 2)
			if !ok || r.month < 1 || r.month > 12 {
				return time.Time{}, false
			}
		case 'd', 'e':
			for d == 'e' && pos < len(input) && input[pos] == ' ' {
				pos++
			}
			r.day, pos, ok = parseNDigits(input, pos, 2)
			if !ok || r.day < 1 || r.day > 31 {
				return time.Time{}, false
			}
		case 'H', 'k':
			for d == 'k' && pos < len(input) && input[pos] == ' ' {
				pos++
			}
			r.hour, pos, ok = parseNDigits(input, pos, 2)
			if !ok || r.hour > 24 {
				return time.Time{}, false
			}
		case 'I', 'l':
			for d == 'l' && pos < len(input) && input[pos] == ' ' {
				pos++
			}
			r.hour, pos, ok = parseNDigits(input, pos, 2)
			if !ok || r.hour > 12 {
				return time.Time{}, false
			}
		case 'M':
			r.minute, pos, ok = parseNDigits(input, pos, 2)
			if !ok || r.minute > 59 {
				return time.Time{}, false
			}
		case 'S':
			r.second, pos, ok = parseNDigits(input, pos, 2)
			if !ok || r.second > 61 {
				return time.Time{}, false
			}
			// optional fractional seconds
			if pos < len(input) && input[pos] == '.' {
				p2 := pos + 1
				start := p2
				for p2 < len(input) && input[p2] >= '0' && input[p2] <= '9' {
					p2++
				}
				if p2 > start {
					fracStr := input[start:p2]
					for len(fracStr) < 9 {
						fracStr += "0"
					}
					fracStr = fracStr[:9]
					r.nanos, _ = strconv.Atoi(fracStr)
					pos = p2
				}
			}
		case 'j':
			r.yday, pos, ok = parseNDigits(input, pos, 3)
			if !ok {
				return time.Time{}, false
			}
		case 'b', 'h', 'B':
			matched := false
			for mi, name := range monthNames {
				if strings.HasPrefix(strings.ToLower(input[pos:]), strings.ToLower(name)) {
					r.month = mi + 1
					pos += len(name)
					matched = true
					break
				}
				if strings.HasPrefix(strings.ToLower(input[pos:]), strings.ToLower(name[:3])) {
					r.month = mi + 1
					pos += 3
					matched = true
					break
				}
			}
			if !matched {
				return time.Time{}, false
			}
		case 'a', 'A':
			matched := false
			for _, name := range weekdayNames {
				if strings.HasPrefix(strings.ToLower(input[pos:]), strings.ToLower(name)) {
					pos += len(name)
					matched = true
					break
				}
				if strings.HasPrefix(strings.ToLower(input[pos:]), strings.ToLower(name[:3])) {
					pos += 3
					matched = true
					break
				}
			}
			if !matched {
				return time.Time{}, false
			}
		case 'p':
			if pos+2 <= len(input) {
				ap := strings.ToUpper(input[pos : pos+2])
				if ap == "AM" {
					r.pm = 1
				} else if ap == "PM" {
					r.pm = 2
				} else {
					return time.Time{}, false
				}
				pos += 2
			} else {
				return time.Time{}, false
			}
		case 'z':
			if pos >= len(input) {
				return time.Time{}, false
			}
			sign := 1
			if input[pos] == '+' {
				pos++
			} else if input[pos] == '-' {
				sign = -1
				pos++
			} else if input[pos] == 'Z' {
				pos++
				r.hasOffset = true
				r.offsetSeconds = 0
				continue
			} else {
				return time.Time{}, false
			}
			var hh, mm int
			hh, pos, ok = parseNDigits(input, pos, 2)
			if !ok {
				return time.Time{}, false
			}
			if pos < len(input) && input[pos] == ':' {
				pos++
			}
			mm, pos, ok = parseNDigits(input, pos, 2)
			if !ok {
				return time.Time{}, false
			}
			r.hasOffset = true
			r.offsetSeconds = sign * (hh*3600 + mm*60)
		case 'Z':
			start := pos
			for pos < len(input) && ((input[pos] >= 'A' && input[pos] <= 'Z') || (input[pos] >= 'a' && input[pos] <= 'z')) {
				pos++
			}
			if pos == start {
				return time.Time{}, false
			}
		case 's':
			start := pos
			if pos < len(input) && input[pos] == '-' {
				pos++
			}
			for pos < len(input) && input[pos] >= '0' && input[pos] <= '9' {
				pos++
			}
			if pos == start {
				return time.Time{}, false
			}
			v, err := strconv.ParseInt(input[start:pos], 10, 64)
			if err != nil {
				return time.Time{}, false
			}
			r.epochSeconds = &v
		case 'F':
			t, p2, ok := strptimeSub(input, pos, "%Y-%m-%d", &r)
			if !ok {
				return time.Time{}, false
			}
			_ = t
			pos = p2
		case 'T':
			t, p2, ok := strptimeSub(input, pos, "%H:%M:%S", &r)
			if !ok {
				return time.Time{}, false
			}
			_ = t
			pos = p2
		case 'D':
			t, p2, ok := strptimeSub(input, pos, "%m/%d/%y", &r)
			if !ok {
				return time.Time{}, false
			}
			_ = t
			pos = p2
		case 'n', 't':
			for pos < len(input) && (input[pos] == ' ' || input[pos] == '\t' || input[pos] == '\n') {
				pos++
			}
		case '%':
			if pos >= len(input) || input[pos] != '%' {
				return time.Time{}, false
			}
			pos++
		default:
			return time.Time{}, false
		}
	}
	if pos != len(input) {
		return time.Time{}, false
	}
	if r.epochSeconds != nil {
		return time.Unix(*r.epochSeconds, 0).In(loc), true
	}
	hour := r.hour
	if r.pm == 2 && hour < 12 {
		hour += 12
	} else if r.pm == 1 && hour == 12 {
		hour = 0
	}
	var t time.Time
	if r.yday > 0 {
		t = time.Date(r.year, 1, 1, hour, r.minute, r.second, r.nanos, loc).AddDate(0, 0, r.yday-1)
	} else if r.hasOffset {
		t = time.Date(r.year, time.Month(r.month), r.day, hour, r.minute, r.second, r.nanos, time.FixedZone("", r.offsetSeconds))
	} else {
		t = time.Date(r.year, time.Month(r.month), r.day, hour, r.minute, r.second, r.nanos, loc)
	}
	return t, true
}

// strptimeSub parses a sub-format at pos, updating r via a recursive call on a slice of input.
func strptimeSub(input string, pos int, subfmt string, r *strptimeResult) (time.Time, int, bool) {
	// Find how much of input the sub-format consumes by trying increasing lengths.
	for end := pos; end <= len(input); end++ {
		t, ok := strptimeGo(input[pos:end], subfmt, time.UTC)
		if ok {
			r.year, r.month, r.day = t.Year(), int(t.Month()), t.Day()
			if strings.Contains(subfmt, "%H") {
				r.hour, r.minute, r.second = t.Hour(), t.Minute(), t.Second()
				r.nanos = t.Nanosecond()
			}
			return t, end, true
		}
	}
	return time.Time{}, pos, false
}

func bifStrptime(a, fmtv *Mlrval, loc *time.Location, isNanos bool) *Mlrval {
	if a.Type() == MT_ABSENT {
		return ABSENT
	}
	if a.Type() != MT_STRING && a.Type() != MT_VOID {
		return ERROR
	}
	if fmtv.Type() != MT_STRING {
		return ERROR
	}
	t, ok := strptimeGo(a.String(), fmtv.String(), loc)
	if !ok {
		return ERROR
	}
	if isNanos {
		return FromInt(t.UnixNano())
	}
	if t.Nanosecond() == 0 {
		return FromInt(t.Unix())
	}
	return FromFloat(float64(t.Unix()) + float64(t.Nanosecond())/1e9)
}

// bifGMT2Sec parses "YYYY-MM-DDTHH:MM:SSZ"-like timestamps leniently.
func bifGMT2Sec(a *Mlrval, loc *time.Location, isNanos bool) *Mlrval {
	if a.Type() == MT_ABSENT {
		return ABSENT
	}
	if a.Type() == MT_VOID {
		return VOID
	}
	s := a.String()
	t, ok := parseGMTLenient(s, loc)
	if !ok {
		return ERROR
	}
	if isNanos {
		return FromInt(t.UnixNano())
	}
	return FromInt(t.Unix())
}

func parseGMTLenient(s string, loc *time.Location) (time.Time, bool) {
	// Formats: YYYY-MM-DD, YYYY-MM-DDTHH:MM:SSZ, YYYY-MM-DD HH:MM:SS, with optional fractional seconds, optional Z
	s = strings.TrimSpace(s)
	layouts := []string{
		"2006-01-02T15:04:05Z",
		"2006-01-02 15:04:05Z",
		"2006-01-02T15:04:05",
		"2006-01-02 15:04:05",
		"2006-01-02T15:04Z",
		"2006-01-02T15:04",
		"2006-01-02 15:04",
		"2006-01-02T15Z",
		"2006-01-02T15",
		"2006-01-02",
		"2006-01-02T15:04:05.999999999Z",
		"2006-01-02 15:04:05.999999999",
		"2006-01-02T15:04:05.999999999",
		"2006-01-02T15:04:05Z07:00",
		"2006-01-02T15:04:05.999999999Z07:00",
		"2006-01",
		"2006",
	}
	for _, layout := range layouts {
		t, err := time.ParseInLocation(layout, s, loc)
		if err == nil {
			return t, true
		}
	}
	// lenient: single-digit fields
	var y, mo, d, h, mi, sec int
	var frac string
	n, _ := fmt.Sscanf(s, "%d-%d-%dT%d:%d:%d", &y, &mo, &d, &h, &mi, &sec)
	if n >= 3 {
		_ = frac
		return time.Date(y, time.Month(mo), d, h, mi, sec, 0, loc), true
	}
	return time.Time{}, false
}

// ---------------------------------------------------------------- dhms

func bifSec2dhms(in *Interp, args []*Mlrval, _ []*ASTNode) *Mlrval {
	a := args[0]
	if a.Type() == MT_ABSENT {
		return ABSENT
	}
	if a.Type() != MT_INT {
		return ERROR
	}
	secs := a.intval
	neg := secs < 0
	if neg {
		secs = -secs
	}
	d := secs / 86400
	h := (secs % 86400) / 3600
	m := (secs % 3600) / 60
	s := secs % 60
	var out string
	if d > 0 {
		out = fmt.Sprintf("%dd%02dh%02dm%02ds", d, h, m, s)
	} else if h > 0 {
		out = fmt.Sprintf("%dh%02dm%02ds", h, m, s)
	} else if m > 0 {
		out = fmt.Sprintf("%dm%02ds", m, s)
	} else {
		out = fmt.Sprintf("%ds", s)
	}
	if neg {
		out = "-" + out
	}
	return FromString(out)
}

func bifFsec2dhms(in *Interp, args []*Mlrval, _ []*ASTNode) *Mlrval {
	a := args[0]
	if a.Type() == MT_ABSENT {
		return ABSENT
	}
	f, ok := a.GetNumericToFloat()
	if !ok {
		return ERROR
	}
	neg := f < 0
	if neg {
		f = -f
	}
	isecs := int64(f)
	frac := f - float64(isecs)
	d := isecs / 86400
	h := (isecs % 86400) / 3600
	m := (isecs % 3600) / 60
	s := isecs % 60
	fs := float64(s) + frac
	var out string
	if d > 0 {
		out = fmt.Sprintf("%dd%02dh%02dm%09.6fs", d, h, m, fs)
	} else if h > 0 {
		out = fmt.Sprintf("%dh%02dm%09.6fs", h, m, fs)
	} else if m > 0 {
		out = fmt.Sprintf("%dm%09.6fs", m, fs)
	} else {
		out = fmt.Sprintf("%.6fs", fs)
	}
	if neg {
		out = "-" + out
	}
	return FromString(out)
}

func bifSec2hms(in *Interp, args []*Mlrval, _ []*ASTNode) *Mlrval {
	a := args[0]
