func bifDhms2sec(in *Interp, args []*Mlrval, _ []*ASTNode) *Mlrval {
	a := args[0]
	if a.Type() == MT_ABSENT {
		return ABSENT
	}
	if a.Type() != MT_STRING {
		return ERROR
	}
	s := a.printrep
	neg := false
	if strings.HasPrefix(s, "-") {
		neg = true
		s = s[1:]
	}
	if s == "" {
		return ERROR
	}
	total := int64(0)
	num := int64(0)
	haveNum := false
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c >= '0' && c <= '9' {
			num = num*10 + int64(c-'0')
			haveNum = true
			continue
		}
		if !haveNum {
			return ERROR
		}
		switch c {
		case 'd':
			total += num * 86400
		case 'h':
			total += num * 3600
		case 'm':
			total += num * 60
		case 's':
			total += num
		default:
			return ERROR
		}
		num = 0
		haveNum = false
	}
	if haveNum {
		return ERROR
	}
	if neg {
		total = -total
	}
	return FromInt(total)
}

func bifDhms2fsec(in *Interp, args []*Mlrval, _ []*ASTNode) *Mlrval {
	a := args[0]
	if a.Type() == MT_ABSENT {
		return ABSENT
	}
	if a.Type() != MT_STRING {
		return ERROR
	}
	s := a.printrep
	neg := false
	if strings.HasPrefix(s, "-") {
		neg = true
		s = s[1:]
	}
	if s == "" {
		return ERROR
	}
	total := 0.0
	start := 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		if (c >= '0' && c <= '9') || c == '.' {
			continue
		}
		if i == start {
			return ERROR
		}
		v, err := strconv.ParseFloat(s[start:i], 64)
		if err != nil {
			return ERROR
		}
		switch c {
		case 'd':
			total += v * 86400
		case 'h':
			total += v * 3600
		case 'm':
			total += v * 60
		case 's':
			total += v
		default:
			return ERROR
		}
		start = i + 1
	}
	if start != len(s) {
		return ERROR
	}
	if neg {
		total = -total
	}
	return FromFloat(total)
}

func bifHms2sec(in *Interp, args []*Mlrval, _ []*ASTNode) *Mlrval {
	a := args[0]
	if a.Type() == MT_ABSENT {
		return ABSENT
	}
	if a.Type() == MT_INT {
		return a
	}
	if a.Type() != MT_STRING {
		return ERROR
	}
	s := a.printrep
	neg := false
	if strings.HasPrefix(s, "-") {
		neg = true
		s = s[1:]
	}
	parts := strings.Split(s, ":")
	if len(parts) != 3 {
		return ERROR
	}
	total := int64(0)
	for _, p := range parts {
		v, err := strconv.ParseInt(p, 10, 64)
		if err != nil {
			return ERROR
		}
		total = total*60 + v
	}
	if neg {
		total = -total
	}
	return FromInt(total)
}

func bifHms2fsec(in *Interp, args []*Mlrval, _ []*ASTNode) *Mlrval {
	a := args[0]
	if a.Type() == MT_ABSENT {
		return ABSENT
	}
	if a.Type() == MT_INT || a.Type() == MT_FLOAT {
		return a
	}
	if a.Type() != MT_STRING {
		return ERROR
	}
	s := a.printrep
	neg := false
	if strings.HasPrefix(s, "-") {
		neg = true
		s = s[1:]
	}
	parts := strings.Split(s, ":")
	if len(parts) != 3 {
		return ERROR
	}
	total := 0.0
	for i, p := range parts {
		if i < 2 {
			v, err := strconv.ParseInt(p, 10, 64)
			if err != nil {
				return ERROR
			}
			total = total*60 + float64(v)
		} else {
			v, err := strconv.ParseFloat(p, 64)
			if err != nil {
				return ERROR
			}
			total = total*60 + v
		}
	}
	if neg {
		total = -total
	}
	return FromFloat(total)
}
