		var fv float64
		switch v.Type() {
		case MT_INT:
			fv = float64(v.intval)
		case MT_FLOAT:
			fv = v.floatval
		case MT_BOOLEAN:
			if v.boolval {
				fv = 1
			}
		default:
			return ERROR
		}
