// inferFromFormattedString: parse via ParseInt base 0 (so leading zeros are octal), else float, else string.
func inferFromFormattedString(s string) *Mlrval {
	if i, err := strconv.ParseInt(s, 0, 64); err == nil {
		if !strings.ContainsAny(s, " ,") {
			return FromIntWithRep(i, s)
		}
	}
	if f, err := strconv.ParseFloat(s, 64); err == nil {
		if !strings.ContainsAny(s, " ,_") && strings.TrimSpace(s) == s {
			lower := strings.ToLower(s)
			if !strings.Contains(lower, "inf") && !strings.Contains(lower, "nan") {
				return FromFloatWithRep(f, s)
			}
		}
	}
	return FromString(s)
}

func bifFmtnum(v *Mlrval, fmtv *Mlrval, ifnum bool) *Mlrval {
	if v.Type() == MT_ABSENT {
		return ABSENT
	}
	if fmtv.Type() != MT_STRING {
		return ERROR
	}
	format := fmtv.String()
	switch v.Type() {
	case MT_MAP:
		out := NewMlrmap()
		for e := v.mapval.Head; e != nil; e = e.Next {
			out.Put(e.Key, bifFmtnum(e.Value, fmtv, ifnum))
		}
		return FromMap(out)
	case MT_ARRAY:
		out := make([]*Mlrval, len(v.arrayval))
		for i, e := range v.arrayval {
			out[i] = bifFmtnum(e, fmtv, ifnum)
		}
		return FromArray(out)
	case MT_INT, MT_FLOAT, MT_BOOLEAN:
		r := fmtnumValue(v, format)
		if r.Type() == MT_ERROR && ifnum {
			return v
		}
		return r
	}
	if ifnum {
		return v
	}
	return ERROR
}
