package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"os/exec"
)

// fileOutput handles redirected output (tee/emit/print > file, >> file, | cmd).
type fileOutput struct {
	name     string
	isPipe   bool
	isStderr bool
	isStdout bool
	file     *os.File
	cmd      *exec.Cmd
	pipeIn   io.WriteCloser
	bw       *bufio.Writer
	writer   RecordWriter
	wopts    *WriterOptions
	opened   bool
	appendMode bool
}

var allRedirects []*fileOutput

func newFileOutput(name string, appendMode, isPipe bool, wopts *WriterOptions) *fileOutput {
	return &fileOutput{name: name, isPipe: isPipe, appendMode: appendMode, wopts: wopts}
}

func newStdFileOutput(isStderr bool, wopts *WriterOptions) *fileOutput {
	return &fileOutput{isStderr: isStderr, isStdout: !isStderr, wopts: wopts}
}

func (fo *fileOutput) open() {
	if fo.opened {
		return
	}
	fo.opened = true
	if fo.isStderr {
		fo.bw = bufio.NewWriter(os.Stderr)
	} else if fo.isStdout {
		fo.bw = stdoutWriter
	} else if fo.isPipe {
		cmd := exec.Command("/bin/sh", "-c", fo.name)
		cmd.Stdout = os.Stdout
		cmd.Stderr = os.Stderr
		in, err := cmd.StdinPipe()
		if err != nil {
			fmt.Fprintf(os.Stderr, "mlr: %v\n", err)
			os.Exit(1)
		}
		if err := cmd.Start(); err != nil {
			fmt.Fprintf(os.Stderr, "mlr: %v\n", err)
			os.Exit(1)
		}
		fo.cmd = cmd
		fo.pipeIn = in
		fo.bw = bufio.NewWriter(in)
	} else {
		flags := os.O_WRONLY | os.O_CREATE
		if fo.appendMode {
			flags |= os.O_APPEND
		} else {
			flags |= os.O_TRUNC
		}
		f, err := os.OpenFile(fo.name, flags, 0644)
		if err != nil {
			fmt.Fprintf(os.Stderr, "mlr: %v\n", err)
			os.Exit(1)
		}
		fo.file = f
		fo.bw = bufio.NewWriter(f)
	}
	w, err := createRecordWriter(fo.wopts)
	if err != nil {
		fmt.Fprintf(os.Stderr, "%v\n", err)
		os.Exit(1)
	}
	fo.writer = w
}

func (fo *fileOutput) writeRecord(rec *Mlrmap) {
	fo.open()
	prepared := prepareRecordForOutput(rec, fo.wopts)
	fo.writer.Write(prepared, fo.bw, false)
	if fo.isStderr || fo.isStdout {
		fo.bw.Flush()
	}
}

func (fo *fileOutput) writeString(s string) {
	fo.open()
	fo.bw.WriteString(s)
	if fo.isStderr || fo.isStdout {
		fo.bw.Flush()
	}
}

func (fo *fileOutput) close() {
	if !fo.opened {
		return
	}
	if fo.writer != nil {
		fo.writer.Write(nil, fo.bw, true)
	}
	fo.bw.Flush()
	if fo.file != nil {
		fo.file.Close()
		fo.file = nil
	}
	if fo.pipeIn != nil {
		fo.pipeIn.Close()
		fo.cmd.Wait()
		fo.pipeIn = nil
	}
	fo.opened = false
}

func closeAllRedirects() {
	for _, fo := range allRedirects {
		fo.close()
	}
	allRedirects = nil
}
