package main

import (
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

type putVerb struct {
	interp       *Interp
	isFilter     bool
	suppress     bool
	invert       bool
	beganRun     bool
	lastCtx      Context
	haveLastCtx  bool
}

func parsePut(args []string, argi *int, opts *Options) (Verb, error) {
	return parsePutOrFilter("put", args, argi, opts, false)
}

func parseFilter(args []string, argi *int, opts *Options) (Verb, error) {
	return parsePutOrFilter("filter", args, argi, opts, true)
}

func loadDSLFile(name string, verb string) []string {
	fi, err := os.Stat(name)
	if err != nil {
		fmt.Fprintf(os.Stderr, "mlr %s: cannot load DSL expression from file \"%s\": %v\n", verb, name, err)
		os.Exit(1)
	}
	if fi.IsDir() {
		entries, _ := filepath.Glob(filepath.Join(name, "*.mlr"))
		sort.Strings(entries)
		var out []string
		for _, e := range entries {
			data, err := os.ReadFile(e)
			if err == nil {
				out = append(out, string(data))
			}
		}
		return out
	}
	data, err := os.ReadFile(name)
	if err != nil {
		fmt.Fprintf(os.Stderr, "mlr %s: cannot load DSL expression from file \"%s\": %v\n", verb, name, err)
		os.Exit(1)
	}
	return []string{string(data)}
}

func parsePutOrFilter(name string, args []string, argi *int, opts *Options, isFilter bool) (Verb, error) {
	v := &putVerb{isFilter: isFilter}
	var exprs []string
	haveExprFromFlags := false
	var presets []string
	printAST := false
	parexAST := false
	parexOneLine := false
	echoExpr := false
	exitAfterParse := false
	p := newOptParser(name, args, argi)
	for {
		f := p.next()
		if f == "" {
			break
		}
		switch f {
		case "-f":
			fn := p.str()
			exprs = append(exprs, loadDSLFile(fn, name)...)
			haveExprFromFlags = true
		case "-e":
			exprs = append(exprs, p.str())
			haveExprFromFlags = true
		case "-s":
			presets = append(presets, p.str())
		case "-x":
			v.invert = true
			p.advance()
		case "-q":
			v.suppress = true
			p.advance()
		case "-S", "-F", "-w", "-W":
			p.advance()
		case "-p":
			printAST = true
			p.advance()
		case "-d":
			parexAST = true
			p.advance()
		case "-D":
			parexOneLine = true
			p.advance()
		case "-E":
			echoExpr = true
			p.advance()
		case "-v":
			echoExpr = true
			printAST = true
			p.advance()
		case "-X":
			exitAfterParse = true
			p.advance()
		default:
			p.unknown(f)
		}
	}
	if !haveExprFromFlags {
		s, ok := p.positional()
		if !ok {
			fmt.Fprintf(os.Stderr, "mlr %s: needs an expression.\n", name)
			os.Exit(1)
		}
		exprs = append(exprs, s)
	}
	// --load / --mload files
	var allExprs []string
	for _, lf := range opts.LoadFiles {
		allExprs = append(allExprs, loadDSLFile(lf, name)...)
	}
	allExprs = append(allExprs, exprs...)
	src := strings.Join(allExprs, "\n")
	root, err := ParseDSL(src)
	if err != nil {
		fmt.Fprint(os.Stderr, err.Error())
		os.Exit(1)
	}
	if echoExpr {
		fmt.Fprintf(stdoutWriter, "DSL EXPRESSION:\n%s\n", src)
	}
	if printAST {
		if echoExpr {
			fmt.Fprintf(stdoutWriter, "\nAST:\n")
		}
		fmt.Fprint(stdoutWriter, root.String())
		fmt.Fprintf(stdoutWriter, "\n")
	}
	if parexAST {
		fmt.Fprint(stdoutWriter, root.ParexString())
	}
	if parexOneLine {
		fmt.Fprint(stdoutWriter, root.ParexOneLineString())
	}
	if exitAfterParse {
		stdoutWriter.Flush()
		os.Exit(0)
	}
	interp, err := newInterp(root, opts, isFilter)
	if err != nil {
		fmt.Fprintf(os.Stderr, "%s\n", err.Error())
		os.Exit(1)
	}
	interp.suppressOutput = v.suppress
	interp.invertFilter = v.invert
	for _, preset := range presets {
		idx := strings.Index(preset, "=")
		if idx < 0 {
			fmt.Fprintf(os.Stderr, "mlr %s: -s flag requires name=value; got \"%s\".\n", name, preset)
			os.Exit(1)
		}
		interp.oosvars.Put(preset[:idx], inferredFromString(preset[idx+1:]))
	}
	v.interp = interp
	return v, nil
}

func (v *putVerb) flushEmitted(ctx *Context, out recordSink) {
	for _, rec := range v.interp.emitted {
		out(rec, ctx)
	}
	v.interp.emitted = nil
}

func (v *putVerb) Process(rec *Mlrmap, ctx *Context, out recordSink) {
	if !v.beganRun {
		v.beganRun = true
		v.interp.runBegin(ctx)
		v.flushEmitted(ctx, out)
	}
	v.lastCtx = *ctx
	v.haveLastCtx = true
	pass := v.interp.runMain(rec, ctx)
	v.flushEmitted(ctx, out)
	if v.invert {
		pass = !pass
	}
	if v.isFilter {
		if pass && !v.suppress {
			out(rec, ctx)
		}
		return
	}
	if pass && !v.suppress {
		out(rec, ctx)
	}
}

func (v *putVerb) Finish(ctx *Context, out recordSink) {
	if !v.beganRun {
		v.beganRun = true
		v.interp.runBegin(ctx)
		v.flushEmitted(ctx, out)
	}
	v.interp.runEnd(ctx)
	v.flushEmitted(ctx, out)
	for _, fo := range v.interp.redirects {
		fo.close()
	}
}
