func lecatMain(args []string) int {
	doColor := true
	var files []string
	for _, a := range args {
		if a == "--mono" {
			doColor = false
		} else if a == "-h" || a == "--help" {
			fmt.Fprint(stdoutWriter, "Usage: mlr lecat [options] {filenames ...}\nSimply echoes input, but flags CR characters in red and LF characters in green.\nIf zero filenames are supplied, standard input is read.\nOptions:\n--mono: don't try to colorize the output\n-h or --help: print this message\n")
			return 0
		} else {
			files = append(files, a)
		}
	}
	process := func(data []byte) {
		for _, b := range data {
			if b == '\r' {
				if doColor {
					stdoutWriter.WriteString("\033[31m[CR]\033[0m")
				} else {
					stdoutWriter.WriteString("[CR]")
				}
			} else if b == '\n' {
				if doColor {
					stdoutWriter.WriteString("\033[32m[LF]\033[0m\n")
				} else {
					stdoutWriter.WriteString("[LF]\n")
				}
			} else {
				stdoutWriter.WriteByte(b)
			}
		}
	}
	if len(files) == 0 {
		data, _ := readAllStdin()
		process(data)
	} else {
		for _, f := range files {
			data, err := os.ReadFile(f)
			if err != nil {
				fmt.Fprintf(os.Stderr, "mlr lecat: %v\n", err)
				return 1
			}
			process(data)
		}
	}
	return 0
}

func hexMain(args []string) int {
	raw := false
	var files []string
	for _, a := range args {
		if a == "-r" {
			raw = true
		} else if a == "-h" || a == "--help" {
			fmt.Fprint(stdoutWriter, "Usage: mlr hex [options] {zero or more file names}\nSimple hex-dump.\nIf zero file names are supplied, standard input is read.\nOptions:\n-r: print only raw hex without leading offset indicators or trailing ASCII dump.\n-h or --help: print this message\n")
			return 0
		} else {
			files = append(files, a)
		}
	}
	dump := func(data []byte) {
		for off := 0; off < len(data); off += 16 {
			end := off + 16
			if end > len(data) {
				end = len(data)
			}
			chunk := data[off:end]
			if !raw {
				fmt.Fprintf(stdoutWriter, "%08x: ", off)
			}
			for i := 0; i < 16; i++ {
				if i < len(chunk) {
					fmt.Fprintf(stdoutWriter, "%02x ", chunk[i])
				} else if !raw {
					stdoutWriter.WriteString("   ")
				}
				if i == 7 && !raw {
					stdoutWriter.WriteString(" ")
				}
			}
			if !raw {
				stdoutWriter.WriteString("|")
				for _, b := range chunk {
					if b >= 32 && b < 127 {
						stdoutWriter.WriteByte(b)
					} else {
						stdoutWriter.WriteByte('.')
					}
				}
				stdoutWriter.WriteString("|")
			}
			stdoutWriter.WriteString("\n")
		}
	}
	if len(files) == 0 {
		data, _ := readAllStdin()
		dump(data)
	} else {
		for _, f := range files {
			data, err := os.ReadFile(f)
			if err != nil {
				fmt.Fprintf(os.Stderr, "mlr hex: %v\n", err)
				return 1
			}
			if len(files) > 1 {
				fmt.Fprintf(stdoutWriter, "%s:\n", f)
			}
			dump(data)
			if len(files) > 1 {
				stdoutWriter.WriteString("\n")
			}
		}
	}
	return 0
}

func unhexMain(args []string) int {
	var files []string
	for _, a := range args {
		if a == "-h" || a == "--help" {
			fmt.Fprint(stdoutWriter, "Usage: mlr unhex [option] {zero or more file names}\nReads hex strings from input and writes the corresponding bytes to stdout.\nOptions:\n-h or --help: print this message\n")
			return 0
		}
		files = append(files, a)
	}
	process := func(data []byte) {
		for _, tok := range strings.Fields(string(data)) {
			tok = strings.TrimPrefix(tok, "0x")
			var b byte
			if _, err := fmt.Sscanf(tok, "%02x", &b); err == nil {
				stdoutWriter.WriteByte(b)
			}
		}
	}
	if len(files) == 0 {
		data, _ := readAllStdin()
		process(data)
	} else {
		for _, f := range files {
			data, err := os.ReadFile(f)
			if err != nil {
				return 1
			}
			process(data)
		}
	}
	return 0
}

func termcvtMain(args []string) int {
	mode := ""
	var files []string
	for _, a := range args {
		switch a {
		case "--cr2crlf", "--lf2crlf", "--crlf2cr", "--crlf2lf", "--cr2lf", "--lf2cr":
			mode = a
		case "-h", "--help":
			fmt.Fprint(stdoutWriter, "Usage: mlr termcvt [option] {zero or more file names}\nOption (exactly one is required):\n--cr2crlf\n--lf2crlf\n--crlf2cr\n--crlf2lf\n--cr2lf\n--lf2cr\n-I in-place processing (default is to write to stdout)\n-h or --help: print this message\nZero file names means read from standard input.\nOutput is always to standard output; files are not written in-place.\n")
			return 0
		default:
			files = append(files, a)
		}
	}
	convert := func(data []byte) string {
		s := string(data)
		switch mode {
		case "--cr2crlf":
			return strings.ReplaceAll(s, "\r", "\r\n")
		case "--lf2crlf":
			return strings.ReplaceAll(s, "\n", "\r\n")
		case "--crlf2cr":
			return strings.ReplaceAll(s, "\r\n", "\r")
		case "--crlf2lf":
			return strings.ReplaceAll(s, "\r\n", "\n")
		case "--cr2lf":
			return strings.ReplaceAll(s, "\r", "\n")
		case "--lf2cr":
			return strings.ReplaceAll(s, "\n", "\r")
		}
		return s
	}
	if len(files) == 0 {
		data, _ := readAllStdin()
		stdoutWriter.WriteString(convert(data))
	} else {
		for _, f := range files {
			data, err := os.ReadFile(f)
			if err != nil {
				return 1
			}
			stdoutWriter.WriteString(convert(data))
		}
	}
	return 0
}

func readAllStdin() ([]byte, error) {
	var buf []byte
	tmp := make([]byte, 65536)
	for {
		n, err := os.Stdin.Read(tmp)
		buf = append(buf, tmp[:n]...)
		if err != nil {
			break
		}
	}
	return buf, nil
}
