func parseCleanWhitespace(args []string, argi *int, opts *Options) (Verb, error) {
	v := &cleanWhitespaceVerb{keys: true, values: true}
	p := newOptParser("clean-whitespace", args, argi)
	for {
		f := p.next()
		if f == "" {
			break
		}
