			v.keys = true
			v.values = false
			p.advance()
		case "-v", "--values-only":
			v.keys = false
			v.values = true
			p.advance()
		default:
			p.unknown(f)
		}
	}
	return v, nil
}

func cleanWhitespaceString(s string) string {
	return strings.TrimSpace(collapseWhitespace(s))
}

func (v *cleanWhitespaceVerb) Process(rec *Mlrmap, ctx *Context, out recordSink) {
	newrec := NewMlrmap()
	for e := rec.Head; e != nil; e = e.Next {
		k := e.Key
		val := e.Value
		if v.keys {
			k = cleanWhitespaceString(k)
		}
		if v.values && (val.Type() == MT_STRING || val.Type() == MT_VOID) {
			val = inferredFromString(cleanWhitespaceString(val.String()))
		}
		newrec.Put(k, val)
	}
	out(newrec, ctx)
}
