{"command":"cd /workspace/src; cat > stats_acc.go <<'EOF'
package main

import (
	"fmt"
	"math"
	"os"
	"strconv"
	"strings"
	"unicode/utf8"
)

// stats1Acc is a univariate accumulator.
type stats1Acc interface {
	ingest(v *Mlrval)
	emit() *Mlrval
}

var stats1AccNames = []string{"median", "count", "null_count", "distinct_count", "mode", "antimode", "sum", "mean", "mad", "var", "stddev", "meaneb", "skewness", "kurtosis", "min", "max", "minlen", "maxlen", "first", "last"}

func isValidStats1AccName(name string) bool {
	if strings.HasPrefix(name, "p") && len(name) > 1 {
		if _, err := strconv.ParseFloat(name[1:], 64); err == nil {
			return true
		}
	}
	for _, n := range stats1AccNames {
		if n == name && n != "first" && n != "last" {
			return true
		}
	}
	return false
}

func makeStats1Acc(name string, interpolate bool) stats1Acc {
	switch name {
	case "count":
		return &countAcc{}
	case "null_count":
		return &nullCountAcc{}
	case "distinct_count":
		return &distinctCountAcc{seen: map[string]bool{}}
	case "mode":
		return &modeAcc{isMode: true, counts: map[string]int64{}, first: map[string]*Mlrval{}}
	case "antimode":
		return &modeAcc{isMode: false, counts: map[string]int64{}, first: map[string]*Mlrval{}}
	case "sum":
		return &sumAcc{sum: FromInt(0)}
	case "mean":
		return &meanAcc{sum: FromInt(0)}
	case "mad":
		return &madAcc{}
	case "var":
		return &momentAcc{which: "var", acc: newMomentAccumulator()}
	case "stddev":
		return &momentAcc{which: "stddev", acc: newMomentAccumulator()}
	case "meaneb":
		return &momentAcc{which: "meaneb", acc: newMomentAccumulator()}
	case "skewness":
		return &momentAcc{which: "skewness", acc: newMomentAccumulator()}
	case "kurtosis":
		return &momentAcc{which: "kurtosis", acc: newMomentAccumulator()}
	case "min":
		return &minMaxAcc{isMin: true}
	case "max":
		return &minMaxAcc{isMin: false}
	case "minlen":
		return &lenAcc{isMin: true}
	case "maxlen":
		return &lenAcc{isMin: false}
	case "first":
		return &firstLastAcc{isFirst: true}
	case "last":
		return &firstLastAcc{isFirst: false}
	case "median":
		return &percentileAcc{p: 50, interpolate: interpolate}
	}
	if strings.HasPrefix(name, "p") {
		p, err := strconv.ParseFloat(name[1:], 64)
		if err == nil {
			return &percentileAcc{p: p, interpolate: interpolate}
		}
	}
	return nil
}

type countAcc struct{ n int64 }

func (a *countAcc) ingest(v *Mlrval) { a.n++ }
func (a *countAcc) emit() *Mlrval    { return FromInt(a.n) }

type nullCountAcc struct{ n int64 }

func (a *nullCountAcc) ingest(v *Mlrval) {
	if v.Type() == MT_VOID {
		a.n++
	}
}
func (a *nullCountAcc) emit() *Mlrval { return FromInt(a.n) }

type distinctCountAcc struct{ seen map[string]bool }

func (a *distinctCountAcc) ingest(v *Mlrval) { a.seen[v.String()] = true }
func (a *distinctCountAcc) emit() *Mlrval    { return FromInt(int64(len(a.seen))) }

type modeAcc struct {
	isMode bool
	counts map[string]int64
	order  []string
	first  map[string]*Mlrval
}

func (a *modeAcc) ingest(v *Mlrval) {
	s := v.String()
	if _, ok := a.counts[s]; !ok {
		a.order = append(a.order, s)
		a.first[s] = v
	}
	a.counts[s]++
}

func (a *modeAcc) emit() *Mlrval {
	if len(a.order) == 0 {
		return ERROR
	}
	best := a.order[0]
	for _, s := range a.order[1:] {
		if a.isMode {
			if a.counts[s] > a.counts[best] {
				best = s
			}
		} else {
			if a.counts[s] < a.counts[best] {
				best = s
			}
		}
	}
	return a.first[best]
}

type sumAcc struct{ sum *Mlrval }

func (a *sumAcc) ingest(v *Mlrval) { a.sum = binaryOpPlus(a.sum, v) }
func (a *sumAcc) emit() *Mlrval    { return a.sum }

type meanAcc struct {
	sum *Mlrval
	n   int64
}

func (a *meanAcc) ingest(v *Mlrval) {
	a.sum = binaryOpPlus(a.sum, v)
	a.n++
}
func (a *meanAcc) emit() *Mlrval {
	if a.n == 0 {
		return ERROR
	}
	return binaryOpDivide(a.sum, FromInt(a.n))
}

type madAcc struct {
	vals []*Mlrval
}

func (a *madAcc) ingest(v *Mlrval) { a.vals = append(a.vals, v) }
func (a *madAcc) emit() *Mlrval {
	n := len(a.vals)
	if n == 0 {
		return ERROR
	}
	sum := FromInt(0)
	for _, v := range a.vals {
		sum = binaryOpPlus(sum, v)
	}
	mean := binaryOpDivide(sum, FromInt(int64(n)))
	if mean.Type() == MT_ERROR {
		return ERROR
	}
	acc := FromInt(0)
	for _, v := range a.vals {
		d := binaryOpMinus(v, mean)
		if d.Type() == MT_INT && d.intval < 0 {
			d = FromInt(-d.intval)
		} else if d.Type() == MT_FLOAT {
			d = FromFloat(math.Abs(d.floatval))
		}
		acc = binaryOpPlus(acc, d)
	}
	return binaryOpDivide(acc, FromInt(int64(n)))
}

type momentAcc struct {
	which string
	acc   *momentAccumulator
	bad   bool
}

func (a *momentAcc) ingest(v *Mlrval) {
	if !v.IsNumeric() {
		a.bad = true
		return
	}
	a.acc.ingest(v)
}
func (a *momentAcc) emit() *Mlrval {
	if a.bad {
		return ERROR
	}
	switch a.which {
	case "var":
		return a.acc.variance()
	case "stddev":
		return a.acc.stddev()
	case "meaneb":
		return a.acc.meaneb()
	case "skewness":
		return a.acc.skewness()
	case "kurtosis":
		return a.acc.kurtosis()
	}
	return ERROR
}

type minMaxAcc struct {
	isMin bool
	cur   *Mlrval
}

func (a *minMaxAcc) ingest(v *Mlrval) {
	if a.cur == nil {
		a.cur = v
		return
	}
	a.cur = minMaxPair(a.cur, v, a.isMin)
}
func (a *minMaxAcc) emit() *Mlrval {
	if a.cur == nil {
		return VOID
	}
	return a.cur
}

type lenAcc struct {
	isMin bool
	cur   int
	have  bool
}

func (a *lenAcc) ingest(v *Mlrval) {
	l := utf8.RuneCountInString(v.String())
	if !a.have {
		a.cur = l
		a.have = true
		return
	}
	if a.isMin {
		if l < a.cur {
			a.cur = l
		}
	} else {
		if l > a.cur {
			a.cur = l
		}
	}
}
func (a *lenAcc) emit() *Mlrval {
	if !a.have {
		return VOID
	}
	return FromInt(int64(a.cur))
}

type firstLastAcc struct {
	isFirst bool
	cur     *Mlrval
}

func (a *firstLastAcc) ingest(v *Mlrval) {
	if a.isFirst {
		if a.cur == nil {
			a.cur = v
		}
	} else {
		a.cur = v
	}
}
func (a *firstLastAcc) emit() *Mlrval {
	if a.cur == nil {
		return VOID
	}
	return a.cur
}

type percentileAcc struct {
	p           float64
	interpolate bool
	vals        []*Mlrval
}

func (a *percentileAcc) ingest(v *Mlrval) { a.vals = append(a.vals, v) }
func (a *percentileAcc) emit() *Mlrval {
	if len(a.vals) == 0 {
		return VOID
	}
	sorted := sortedCopy(a.vals)
	if a.interpolate {
		return percentileInterpolated(sorted, a.p)
	}
	return percentileNonInterpolated(sorted, a.p)
}

// ---------------------------------------------------------------- stats1 verb

type stats1Verb struct {
	accNames    []string
	valueFields []string
	groupFields []string
	valueRegexes []*regexpOrNil
	groupRegexes []*regexpOrNil
	invertValue bool
	invertGroup bool
	interpolate bool
	iterative   bool
	// group key -> field name -> acc name -> acc
	groups      *orderedMap
}

type regexpOrNil struct {
	rx interface{ MatchString(string) bool }
}

type stats1Group struct {
	groupingValues []*Mlrval
	groupFieldNames []string
	fieldAccs      *orderedMap // field name -> *orderedMap(acc name -> stats1Acc)
}

func parseStats1(args []string, argi *int, opts *Options) (Verb, error) {
	v := &stats1Verb{groups: newOrderedMap()}
	p := newOptParser("stats1", args, argi)
	for {
		f := p.next()
		if f == "" {
			break
		}
		switch f {
		case "-a":
			v.accNames = append(v.accNames, p.list()...)
		case "-f":
			v.valueFields = append(v.valueFields, p.list()...)
		case "-g":
			v.groupFields = append(v.groupFields, p.list()...)
		case "--fr":
			for _, r := range p.list() {
				v.valueRegexes = append(v.valueRegexes, &regexpOrNil{compileMillerRegexOrDie(r)})
			}
		case "--fx":
			for _, r := range p.list() {
				v.valueRegexes = append(v.valueRegexes, &regexpOrNil{compileMillerRegexOrDie(r)})
			}
			v.invertValue = true
		case "--gr":
			for _, r := range p.list() {
				v.groupRegexes = append(v.groupRegexes, &regexpOrNil{compileMillerRegexOrDie(r)})
			}
		case "--gx":
			for _, r := range p.list() {
				v.groupRegexes = append(v.groupRegexes, &regexpOrNil{compileMillerRegexOrDie(r)})
			}
			v.invertGroup = true
		case "--grfx":
			for _, r := range p.list() {
				rx := compileMillerRegexOrDie(r)
				v.groupRegexes = append(v.groupRegexes, &regexpOrNil{rx})
				v.valueRegexes = append(v.valueRegexes, &regexpOrNil{rx})
