}

// getValueFieldNames returns the value field names for this record.
func (v *stats1Verb) getValueFieldNames(rec *Mlrmap) []string {
	if len(v.valueRegexes) == 0 {
		return v.valueFields
	}
	var out []string
	for e := rec.Head; e != nil; e = e.Next {
		m := v.matchesAny(v.valueRegexes, e.Key)
		if m != v.invertValue {
			out = append(out, e.Key)
