cd /workspace/src; cat > verbs_more.go <<'EOF'
package main

import (
	"fmt"
	"math"
	"os"
	"regexp"
	"strconv"
	"strings"
)

// ---------------------------------------------------------------- sort

type sortKeySpec struct {
	field string
	kind  byte // 'f' lexical, 'c' casefold, 'n' numeric, 't' natural
	desc  bool
}

type sortVerb struct {
	specs     []sortKeySpec
	moveToStart bool
	groups    *orderedMap // key -> *recGroup (records with all sort keys)
	groupVals [][]*Mlrval
	missing   []*Mlrmap
	missingCtx []Context
}

func parseSort(args []string, argi *int, opts *Options) (Verb, error) {
	v := &sortVerb{groups: newOrderedMap()}
	p := newOptParser("sort", args, argi)
	for {
		f := p.next()
		if f == "" {
			break
		}
		var kind byte
		var desc bool
		switch f {
		case "-f":
			kind, desc = 'f', false
		case "-r":
			kind, desc = 'f', true
		case "-c":
			kind, desc = 'c', false
		case "-cr":
			kind, desc = 'c', true
		case "-n", "-nf":
			kind, desc = 'n', false
		case "-nr":
			kind, desc = 'n', true
		case "-t":
			kind, desc = 't', false
		case "-tr", "-rt":
			kind, desc = 't', true
		case "-b":
			v.moveToStart = true
			p.advance()
			continue
		default:
			p.unknown(f)
		}
		for _, name := range p.list() {
			v.specs = append(v.specs, sortKeySpec{field: name, kind: kind, desc: desc})
		}
	}
	if len(v.specs) == 0 {
		fmt.Fprintf(os.Stderr, "mlr sort: no sort keys given.\n")
		fmt.Fprint(os.Stderr, verbUsage("sort"))
		os.Exit(1)
	}
	return v, nil
}

func (v *sortVerb) Process(rec *Mlrmap, ctx *Context, out recordSink) {
	fields := make([]string, len(v.specs))
	for i, s := range v.specs {
		fields[i] = s.field
	}
	vals, ok := rec.GetSelectedValues(fields)
	if !ok {
		v.missing = append(v.missing, rec)
		v.missingCtx = append(v.missingCtx, *ctx)
		return
	}
	key, _ := rec.GetSelectedValuesJoined(fields)
	gi, ok := v.groups.Get(key)
	var g *recGroup
	if !ok {
		g = &recGroup{}
		v.groups.Put(key, g)
		v.groupVals = append(v.groupVals, vals)
	} else {
		g = gi.(*recGroup)
	}
	g.recs = append(g.recs, rec)
	g.ctxs = append(g.ctxs, *ctx)
}

func (v *sortVerb) compare(a, b []*Mlrval) int {
	for i, s := range v.specs {
		var c int
		switch s.kind {
		case 'f':
			c = lexicalCompare(a[i], b[i])
		case 'c':
			c = caseFoldCompare(a[i], b[i])
		case 'n':
			c = sortVerbNumericCompare(a[i], b[i])
		case 't':
			c = naturalCompare(a[i], b[i])
		}
		if s.desc {
			c = -c
		}
		if c != 0 {
			return c
		}
	}
	return 0
}

func (v *sortVerb) Finish(ctx *Context, out recordSink) {
	n := len(v.groups.keys)
	idx := make([]int, n)
	for i := range idx {
		idx[i] = i
	}
	sortSliceStable(n, func(i, j int) bool {
		return v.compare(v.groupVals[idx[i]], v.groupVals[idx[j]]) < 0
	}, func(i, j int) { idx[i], idx[j] = idx[j], idx[i] })
	for _, gi := range idx {
		g := v.groups.vals[v.groups.keys[gi]].(*recGroup)
		for i, rec := range g.recs {
			if v.moveToStart {
				for k := len(v.specs) - 1; k >= 0; k-- {
					f := v.specs[k].field
					if val := rec.Get(f); val != nil {
						rec.PutAtStart(f, val)
					}
				}
			}
			c := g.ctxs[i]
			out(rec, &c)
		}
	}
	for i, rec := range v.missing {
		c := v.missingCtx[i]
		out(rec, &c)
	}
}

// ---------------------------------------------------------------- count

type countVerb struct {
	groupBy    []string
	showNumDistinctOnly bool
	outputName string
	count      int64
	groups     *orderedMap
}

type countGroup struct {
	vals  []*Mlrval
	count int64
}

func parseCount(args []string, argi *int, opts *Options) (Verb, error) {
	v := &countVerb{outputName: "count", groups: newOrderedMap()}
	p := newOptParser("count", args, argi)
	for {
		f := p.next()
		if f == "" {
			break
		}
		switch f {
		case "-g":
			v.groupBy = p.list()
		case "-n":
			v.showNumDistinctOnly = true
			p.advance()
		case "-d":
			v.showNumDistinctOnly = true
			p.advance()
		case "-o":
			v.outputName = p.str()
		default:
			p.unknown(f)
		}
	}
	return v, nil
}

func (v *countVerb) Process(rec *Mlrmap, ctx *Context, out recordSink) {
	if v.groupBy == nil {
		v.count++
		return
	}
	vals, ok := rec.GetSelectedValues(v.groupBy)
	if !ok {
		return
	}
	key, _ := rec.GetSelectedValuesJoined(v.groupBy)
	gi, ok := v.groups.Get(key)
	if !ok {
		v.groups.Put(key, &countGroup{vals: vals, count: 1})
	} else {
		gi.(*countGroup).count++
	}
}

func (v *countVerb) Finish(ctx *Context, out recordSink) {
	if v.groupBy == nil {
		rec := NewMlrmap()
		rec.Put(v.outputName, FromInt(v.count))
		out(rec, ctx)
		return
	}
	if v.showNumDistinctOnly {
		rec := NewMlrmap()
		rec.Put(v.outputName, FromInt(int64(v.groups.Len())))
		out(rec, ctx)
		return
	}
	for _, k := range v.groups.keys {
		g := v.groups.vals[k].(*countGroup)
		rec := NewMlrmap()
		for i, f := range v.groupBy {
			rec.Put(f, g.vals[i])
		}
		rec.Put(v.outputName, FromInt(g.count))
		out(rec, ctx)
	}
}

// ---------------------------------------------------------------- count-distinct

type countDistinctVerb struct {
	fields     []string
	exclude    bool
	showNumDistinctOnly bool
	outputName string
	unlashed   bool
	groups     *orderedMap
	unlashedGroups []*orderedMap
}

func parseCountDistinct(args []string, argi *int, opts *Options) (Verb, error) {
	v := &countDistinctVerb{outputName: "count", groups: newOrderedMap()}
	p := newOptParser("count-distinct", args, argi)
	for {
		f := p.next()
		if f == "" {
			break
		}
		switch f {
		case "-f":
			v.fields = p.list()
		case "-x":
			v.fields = p.list()
			v.exclude = true
		case "-n":
			v.showNumDistinctOnly = true
			p.advance()
		case "-o":
			v.outputName = p.str()
		case "-u":
			v.unlashed = true
			p.advance()
		default:
			p.unknown(f)
		}
	}
	if v.fields == nil {
		fmt.Fprintf(os.Stderr, "mlr count-distinct: option -f is required.\n")
		fmt.Fprint(os.Stderr, verbUsage("count-distinct"))
		os.Exit(1)
	}
	if v.unlashed {
		for range v.fields {
			v.unlashedGroups = append(v.unlashedGroups, newOrderedMap())
		}
	}
	return v, nil
}

func (v *countDistinctVerb) Process(rec *Mlrmap, ctx *Context, out recordSink) {
	if v.unlashed {
		for i, f := range v.fields {
			val := rec.Get(f)
			if val == nil {
				continue
			}
			key := val.String()
			gi, ok := v.unlashedGroups[i].Get(key)
			if !ok {
				v.unlashedGroups[i].Put(key, &countGroup{vals: []*Mlrval{val}, count: 1})
			} else {
				gi.(*countGroup).count++
			}
		}
		return
	}
	var fields []string
	if v.exclude {
		set := map[string]bool{}
		for _, f := range v.fields {
			set[f] = true
		}
		for e := rec.Head; e != nil; e = e.Next {
			if !set[e.Key] {
				fields = append(fields, e.Key)
			}
		}
	} else {
		fields = v.fields
	}
	vals, ok := rec.GetSelectedValues(fields)
	if !ok {
		return
	}
	key, _ := rec.GetSelectedValuesJoined(fields)
	if v.exclude {
		key = strings.Join(fields, ",") + "\x01" + key
	}
	gi, ok := v.groups.Get(key)
	if !ok {
		v.groups.Put(key, &countGroupWithNames{names: fields, vals: vals, count: 1})
	} else {
		gi.(*countGroupWithNames).count++
	}
}

type countGroupWithNames struct {
	names []string
	vals  []*Mlrval
	count int64
}

func (v *countDistinctVerb) Finish(ctx *Context, out recordSink) {
	if v.unlashed {
		for i, f := range v.fields {
			for _, k := range v.unlashedGroups[i].keys {
				g := v.unlashedGroups[i].vals[k].(*countGroup)
				rec := NewMlrmap()
				rec.Put("field", FromString(f))
				rec.Put("value", g.vals[0])
				rec.Put("count", FromInt(g.count))
				out(rec, ctx)
			}
		}
		return
	}
	if v.showNumDistinctOnly {
		rec := NewMlrmap()
		rec.Put(v.outputName, FromInt(int64(v.groups.Len())))
		out(rec, ctx)
		return
	}
	for _, k := range v.groups.keys {
		g := v.groups.vals[k].(*countGroupWithNames)
		rec := NewMlrmap()
		for i, f := range g.names {
			rec.Put(f, g.vals[i])
		}
		rec.Put(v.outputName, FromInt(g.count))
		out(rec, ctx)
	}
}

// ---------------------------------------------------------------- uniq

type uniqVerb struct {
	groupBy    []string
	exclude    bool
	showCounts bool
	showNumDistinctOnly bool
	outputName string
	allFields  bool
	groups     *orderedMap
}

type uniqGroup struct {
	rec   *Mlrmap
	ctx   Context
	count int64
}

func parseUniq(args []string, argi *int, opts *Options) (Verb, error) {
	v := &uniqVerb{outputName: "count", groups: newOrderedMap()}
	p := newOptParser("uniq", args, argi)
	for {
		f := p.next()
		if f == "" {
			break
		}
		switch f {
		case "-g", "-f":
			v.groupBy = p.list()
		case "-x":
			v.groupBy = p.list()
			v.exclude = true
		case "-c":
			v.showCounts = true
			p.advance()
		case "-n":
			v.showNumDistinctOnly = true
			p.advance()
		case "-o":
			v.outputName = p.str()
		case "-a":
			v.allFields = true
			p.advance()
		case "-d", "-u":
			p.advance()
		default:
			p.unknown(f)
		}
	}
	if v.groupBy == nil && !v.allFields {
		fmt.Fprintf(os.Stderr, "mlr uniq: option -g is required.\n")
		fmt.Fprint(os.Stderr, verbUsage("uniq"))
		os.Exit(1)
	}
	return v, nil
}

func (v *uniqVerb) Process(rec *Mlrmap, ctx *Context, out recordSink) {
	if v.allFields {
		key := rec.ToDKVPString("\x01", "\x02")
		gi, ok := v.groups.Get(key)
		if !ok {
			v.groups.Put(key, &uniqGroup{rec: rec, ctx: *ctx, count: 1})
			if !v.showCounts && !v.showNumDistinctOnly {
				out(rec, ctx)
			}
		} else {
			gi.(*uniqGroup).count++
		}
		return
	}
	var fields []string
	if v.exclude {
		set := map[string]bool{}
		for _, f := range v.groupBy {
			set[f] = true
		}
		for e := rec.Head; e != nil; e = e.Next {
			if !set[e.Key] {
				fields = append(fields, e.Key)
			}
		}
	} else {
		fields = v.groupBy
	}
	vals, ok := rec.GetSelectedValues(fields)
	if !ok {
		return
	}
	key, _ := rec.GetSelectedValuesJoined(fields)
	if v.exclude {
		key = strings.Join(fields, ",") + "\x01" + key
	}
	gi, ok := v.groups.Get(key)
	if !ok {
		newrec := NewMlrmap()
		for i, f := range fields {
			newrec.Put(f, vals[i])
		}
		v.groups.Put(key, &uniqGroup{rec: newrec, ctx: *ctx, count: 1})
		if !v.showCounts && !v.showNumDistinctOnly {
			out(newrec, ctx)
		}
	} else {
		gi.(*uniqGroup).count++
	}
}

func (v *uniqVerb) Finish(ctx *Context, out recordSink) {
	if v.showNumDistinctOnly {
		rec := NewMlrmap()
		rec.Put(v.outputName, FromInt(int64(v.groups.Len())))
		out(rec, ctx)
		return
	}
	if !v.showCounts {
		return
	}
	for _, k := range v.groups.keys {
		g := v.groups.vals[k].(*uniqGroup)
		if v.allFields {
			rec := NewMlrmap()
			rec.Put(v.outputName, FromInt(g.count))
			for e := g.rec.Head; e != nil; e = e.Next {
				rec.Put(e.Key, e.Value)
			}
			c := g.ctx
			out(rec, &c)
		} else {
			rec := g.rec.ShallowCopy()
			rec.Put(v.outputName, FromInt(g.count))
			c := g.ctx
			out(rec, &c)
		}
	}
}

// ---------------------------------------------------------------- count-similar

type countSimilarVerb struct {
	groupBy    []string
	outputName string
	groups     *orderedMap
}

func parseCountSimilar(args []string, argi *int, opts *Options) (Verb, error) {
	v := &countSimilarVerb{outputName: "count", groups: newOrderedMap()}
	p := newOptParser("count-similar", args, argi)
	for {
		f := p.next()
		if f == "" {
			break
		}
		switch f {
		case "-g":
			v.groupBy = p.list()
		case "-o":
			v.outputName = p.str()
		default:
			p.unknown(f)
		}
	}
	if v.groupBy == nil {
		fmt.Fprintf(os.Stderr, "mlr count-similar: option -g is required.\n")
		fmt.Fprint(os.Stderr, verbUsage("count-similar"))
		os.Exit(1)
	}
	return v, nil
}

func (v *countSimilarVerb) Process(rec *Mlrmap, ctx *Context, out recordSink) {
	key, ok := groupingKey(rec, v.groupBy)
	if !ok {
		return
	}
	gi, ok := v.groups.Get(key)
	var g *recGroup
	if !ok {
		g = &recGroup{}
		v.groups.Put(key, g)
	} else {
		g = gi.(*recGroup)
	}
	g.recs = append(g.recs, rec)
	g.ctxs = append(g.ctxs, *ctx)
}

func (v *countSimilarVerb) Finish(ctx *Context, out recordSink) {
	for _, k := range v.groups.keys {
		g := v.groups.vals[k].(*recGroup)
		n := int64(len(g.recs))
		for i, rec := range g.recs {
			rec.Put(v.outputName, FromInt(n))
			c := g.ctxs[i]
			out(rec, &c)
		}
	}
}

// ---------------------------------------------------------------- top

type topVerb struct {
	fields     []string
	groupBy    []string
	n          int64
	allFields  bool
	useMin     bool
	keepFloats bool
	outputName string
	groups     *orderedMap
}

type topGroup struct {
	groupVals []*Mlrval
	// per value field: sorted list of (value, record)
	tops [][]topEntry
}

type topEntry struct {
	val *Mlrval
	rec *Mlrmap
	ctx Context
}

func parseTop(args []string, argi *int, opts *Options) (Verb, error) {
	v := &topVerb{n: 1, outputName: "top_idx", groups: newOrderedMap()}
	p := newOptParser("top", args, argi)
	for {
		f := p.next()
		if f == "" {
			break
		}
		switch f {
		case "-f":
			v.fields = p.list()
		case "-g":
			v.groupBy = p.list()
		case "-n":
			v.n = p.int()
		case "-a":
			v.allFields = true
			p.advance()
		case "--min":
			v.useMin = true
			p.advance()
		case "--max":
			v.useMin = false
			p.advance()
		case "-F":
			v.keepFloats = true
			p.advance()
		case "-o":
			v.outputName = p.str()
		default:
			p.unknown(f)
		}
	}
	if v.fields == nil {
		fmt.Fprintf(os.Stderr, "mlr top: option -f is required.\n")
		fmt.Fprint(os.Stderr, verbUsage("top"))
		os.Exit(1)
	}
	if v.allFields && len(v.fields) != 1 {
		fmt.Fprintf(os.Stderr, "mlr top: -a is only compatible with a single value-field name.\n")
		os.Exit(1)
	}
	return v, nil
}

func (v *topVerb) Process(rec *Mlrmap, ctx *Context, out recordSink) {
	groupVals, ok := rec.GetSelectedValues(v.groupBy)
	if !ok {
		return
	}
	key, _ := rec.GetSelectedValuesJoined(v.groupBy)
	gi, ok := v.groups.Get(key)
	var g *topGroup
	if !ok {
		g = &topGroup{groupVals: groupVals, tops: make([][]topEntry, len(v.fields))}
		v.groups.Put(key, g)
	} else {
		g = gi.(*topGroup)
	}
	for i, f := range v.fields {
		val := rec.Get(f)
		if val == nil || val.Type() == MT_VOID {
			continue
		}
		fv, isNum := val.GetNumericToFloat()
		if !isNum {
			continue
		}
		_ = fv
		entry := topEntry{val: val, rec: rec, ctx: *ctx}
		// insert into sorted position (desc for max, asc for min), keep at most n
		list := g.tops[i]
		pos := len(list)
		for j := 0; j < len(list); j++ {
			lf, _ := list[j].val.GetNumericToFloat()
			if v.useMin {
				if fv < lf {
					pos = j
					break
				}
			} else {
				if fv > lf {
					pos = j
					break
				}
			}
		}
		if int64(pos) >= v.n {
			continue
		}
		list = append(list, topEntry{})
		copy(list[pos+1:], list[pos:])
		list[pos] = entry
		if int64(len(list)) > v.n {
			list = list[:v.n]
		}
		g.tops[i] = list
	}
}

func (v *topVerb) Finish(ctx *Context, out recordSink) {
	for _, k := range v.groups.keys {
		g := v.groups.vals[k].(*topGroup)
		if v.allFields {
			for _, e := range g.tops[0] {
				c := e.ctx
				out(e.rec, &c)
			}
			continue
		}
		for i := int64(0); i < v.n; i++ {
			rec := NewMlrmap()
			for j, f := range v.groupBy {
				rec.Put(f, g.groupVals[j])
			}
			rec.Put(v.outputName, FromInt(i+1))
			any := false
			for j, f := range v.fields {
				if int(i) < len(g.tops[j]) {
					val := g.tops[j][i].val
					if v.keepFloats {
						fv, _ := val.GetNumericToFloat()
						val = FromFloat(fv)
					}
					rec.Put(f+"_top", val)
					any = true
				} else {
					rec.Put(f+"_top", VOID)
				}
			}
			if !any {
				break
			}
			out(rec, ctx)
		}
	}
}

// ---------------------------------------------------------------- step

type stepVerb struct {
	stepperNames []string
	fields       []string
	groupBy      []string
	alphas       []string
	ewmaSuffixes []string
	groups       *orderedMap
	// for shift_lead / slwin: pending records
	pending      []pendingRec
	maxLead      int
}

type pendingRec struct {
	rec *Mlrmap
	ctx Context
}

type stepGroup struct {
	// per field: per stepper: state
	states map[string][]stepper
}

type stepper interface {
	process(val *Mlrval, rec *Mlrmap)
}

func parseStep(args []string, argi *int, opts *Options) (Verb, error) {
	v := &stepVerb{groups: newOrderedMap()}
	p := newOptParser("step", args, argi)
	for {
		f := p.next()
		if f == "" {
			break
		}
		switch f {
		case "-a":
			v.stepperNames = append(v.stepperNames, p.list()...)
		case "-f":
			v.fields = p.list()
		case "-g":
			v.groupBy = p.list()
		case "-d":
			v.alphas = p.list()
		case "-o":
			v.ewmaSuffixes = p.list()
		case "-F":
			p.advance()
		default:
			p.unknown(f)
		}
	}
	if len(v.stepperNames) == 0 || v.fields == nil {
		fmt.Fprintf(os.Stderr, "mlr step: options -a and -f are required.\n")
		fmt.Fprint(os.Stderr, verbUsage("step"))
		os.Exit(1)
	}
	if v.alphas == nil {
		v.alphas = []string{"0.5"}
	}
	if v.ewmaSuffixes == nil {
		v.ewmaSuffixes = v.alphas
	}
	if len(v.ewmaSuffixes) != len(v.alphas) {
		fmt.Fprintf(os.Stderr, "mlr step: -d and -o must have the same number of items.\n")
		os.Exit(1)
	}
	for _, name := range v.stepperNames {
		switch name {
		case "counter", "delta", "ewma", "from-first", "ratio", "rprod", "rsum", "shift", "shift_lag", "shift_lead":
		default:
			if strings.HasPrefix(name, "slwin_") {
				parts := strings.Split(name, "_")
				if len(parts) == 3 {
					if _, err := strconv.Atoi(parts[1]); err == nil {
						if n, err := strconv.Atoi(parts[2]); err == nil {
							if n > v.maxLead {
								v.maxLead = n
							}
							continue
						}
					}
				}
			}
			fmt.Fprintf(os.Stderr, "mlr step: stepper \"%s\" not found.\n", name)
			os.Exit(1)
		}
		if name == "shift_lead" && v.maxLead < 1 {
			v.maxLead = 1
		}
	}
	return v, nil
}

// Simple (non-lookahead) steppers

type stepperDelta struct {
	field string
	prev  *Mlrval
}

func (s *stepperDelta) process(val *Mlrval, rec *Mlrmap) {
	if s.prev == nil {
		rec.Put(s.field+"_delta", FromInt(0))
	} else {
		rec.Put(s.field+"_delta", binaryOpMinus(val, s.prev))
	}
	s.prev = val
}

type stepperShift struct {
	field string
	name  string
	prev  *Mlrval
}

func (s *stepperShift) process(val *Mlrval, rec *Mlrmap) {
	if s.prev == nil {
		rec.Put(s.field+"_"+s.name, VOID)
	} else {
		rec.Put(s.field+"_"+s.name, s.prev)
	}
	s.prev = val
}

type stepperFromFirst struct {
	field string
	first *Mlrval
}

func (s *stepperFromFirst) process(val *Mlrval, rec *Mlrmap) {
	if s.first == nil {
		s.first = val
	}
	rec.Put(s.field+"_from-first", binaryOpMinus(val, s.first))
}

type stepperRatio struct {
	field string
	prev  *Mlrval
}

func (s *stepperRatio) process(val *Mlrval, rec *Mlrmap) {
	if s.prev == nil {
		rec.Put(s.field+"_ratio", FromInt(0))
	} else {
		rec.Put(s.field+"_ratio", binaryOpDivide(val, s.prev))
	}
	s.prev = val
}

type stepperRsum struct {
	field string
	sum   *Mlrval
}

func (s *stepperRsum) process(val *Mlrval, rec *Mlrmap) {
	if s.sum == nil {
		s.sum = val
	} else {
		s.sum = binaryOpPlus(s.sum, val)
	}
	rec.Put(s.field+"_rsum", s.sum)
}

type stepperRprod struct {
	field string
	prod  *Mlrval
}

func (s *stepperRprod) process(val *Mlrval, rec *Mlrmap) {
	if s.prod == nil {
		s.prod = val
	} else {
		s.prod = binaryOpTimes(s.prod, val)
	}
	rec.Put(s.field+"_rprod", s.prod)
}

type stepperCounter struct {
	field string
	count int64
}

func (s *stepperCounter) process(val *Mlrval, rec *Mlrmap) {
	s.count++
	rec.Put(s.field+"_counter", FromInt(s.count))
}

type stepperEwma struct {
	field    string
	alphas   []float64
	suffixes []string
	prevs    []*Mlrval
	have     bool
}

func (s *stepperEwma) process(val *Mlrval, rec *Mlrmap) {
	if !s.have {
		s.have = true
		s.prevs = make([]*Mlrval, len(s.alphas))
		for i := range s.alphas {
			s.prevs[i] = val
			rec.Put(s.field+"_ewma_"+s.suffixes[i], val)
		}
		return
	}
	for i, alpha := range s.alphas {
		// alpha*val + (1-alpha)*prev
		cur := binaryOpPlus(binaryOpTimes(FromFloat(alpha), val), binaryOpTimes(FromFloat(1-alpha), s.prevs[i]))
		s.prevs[i] = cur
		rec.Put(s.field+"_ewma_"+s.suffixes[i], cur)
	}
}

func (v *stepVerb) makeStepper(name, field string) stepper {
	switch name {
	case "delta":
		return &stepperDelta{field: field}
	case "shift", "shift_lag":
		return &stepperShift{field: field, name: name}
	case "from-first":
		return &stepperFromFirst{field: field}
	case "ratio":
		return &stepperRatio{field: field}
	case "rsum":
		return &stepperRsum{field: field}
	case "rprod":
		return &stepperRprod{field: field}
	case "counter":
		return &stepperCounter{field: field}
	case "ewma":
		alphas := make([]float64, len(v.alphas))
		for i, a := range v.alphas {
			alphas[i], _ = strconv.ParseFloat(a, 64)
		}
		return &stepperEwma{field: field, alphas: alphas, suffixes: v.ewmaSuffixes}
	}
	return nil
}

// For lookahead steppers (shift_lead, slwin), we buffer all records per group.
type stepLookahead struct {
	recs []*Mlrmap
	ctxs []Context
}

func (v *stepVerb) Process(rec *Mlrmap, ctx *Context, out recordSink) {
	key, ok := groupingKey(rec, v.groupBy)
	if !ok {
		out(rec, ctx)
		return
	}
	gi, ok := v.groups.Get(key)
	var g *stepGroup
	if !ok {
		g = &stepGroup{states: map[string][]stepper{}}
		v.groups.Put(key, g)
	} else {
		g = gi.(*stepGroup)
	}
	for _, f := range v.fields {
		val := rec.Get(f)
		if val == nil || val.Type() == MT_VOID {
			continue
		}
		steppers, ok := g.states[f]
		if !ok {
			for _, name := range v.stepperNames {
				steppers = append(steppers, v.makeStepper(name, f))
			}
			g.states[f] = steppers
		}
		for _, s := range steppers {
			if s != nil {
				s.process(val, rec)
			}
		}
	}
	if v.maxLead > 0 {
		v.pending = append(v.pending, pendingRec{rec: rec, ctx: *ctx})
		return
	}
	out(rec, ctx)
}

func (v *stepVerb) Finish(ctx *Context, out recordSink) {
	if v.maxLead == 0 {
		return
	}
	// Lookahead steppers: process per group over the buffered records
	// Build group index lists
	groupIdx := map[string][]int{}
	var groupOrder []string
	for i, pr := range v.pending {
		key, ok := groupingKey(pr.rec, v.groupBy)
		if !ok {
			continue
		}
		if _, seen := groupIdx[key]; !seen {
			groupOrder = append(groupOrder, key)
		}
		groupIdx[key] = append(groupIdx[key], i)
	}
	for _, key := range groupOrder {
		idxs := groupIdx[key]
		for _, f := range v.fields {
			// collect values
			vals := make([]*Mlrval, len(idxs))
			for j, i := range idxs {
				val := v.pending[i].rec.Get(f)
				if val != nil && val.Type() != MT_VOID {
					vals[j] = val
				}
			}
			for _, name := range v.stepperNames {
				if name == "shift_lead" {
					for j, i := range idxs {
						if vals[j] == nil {
							continue
						}
						if j+1 < len(idxs) && vals[j+1] != nil {
							v.pending[i].rec.Put(f+"_shift_lead", vals[j+1])
						} else {
							v.pending[i].rec.Put(f+"_shift_lead", VOID)
						}
					}
				} else if strings.HasPrefix(name, "slwin_") {
					parts := strings.Split(name, "_")
					back, _ := strconv.Atoi(parts[1])
					fwd, _ := strconv.Atoi(parts[2])
					for j, i := range idxs {
						if vals[j] == nil {
							continue
						}
						sum := 0.0
						n := 0
						for k := j - back; k <= j+fwd; k++ {
							if k < 0 || k >= len(idxs) || vals[k] == nil {
								continue
							}
							fv, ok := vals[k].GetNumericToFloat()
							if !ok {
								continue
							}
							sum += fv
							n++
						}
						if n > 0 {
							v.pending[i].rec.Put(f+"_"+name, FromFloat(sum/float64(n)))
						}
					}
				}
			}
		}
	}
	for _, pr := range v.pending {
		c := pr.ctx
		out(pr.rec, &c)
	}
	v.pending = nil
}

// ---------------------------------------------------------------- merge-fields

type mergeFieldsVerb struct {
	accNames    []string
	fields      []string
	regexes     []*regexp.Regexp
	collapses   []string
	outputName  string
	keepInputs  bool
	interpolate bool
	mode        byte // 'f', 'r', 'c'
}

func parseMergeFields(args []string, argi *int, opts *Options) (Verb, error) {
	v := &mergeFieldsVerb{}
	p := newOptParser("merge-fields", args, argi)
	for {
		f := p.next()
		if f == "" {
			break
		}
		switch f {
		case "-a":
			v.accNames = append(v.accNames, p.list()...)
		case "-f":
			v.fields = p.list()
			v.mode = 'f'
		case "-r":
			for _, r := range p.list() {
				v.regexes = append(v.regexes, compileMillerRegexOrDie(r))
			}
			v.mode = 'r'
		case "-c":
			v.collapses = p.list()
			v.mode = 'c'
		case "-o":
			v.outputName = p.str()
		case "-k":
			v.keepInputs = true
			p.advance()
		case "-i":
			v.interpolate = true
			p.advance()
		default:
			p.unknown(f)
		}
	}
	if len(v.accNames) == 0 {
		fmt.Fprintf(os.Stderr, "mlr merge-fields: option -a is required.\n")
		fmt.Fprint(os.Stderr, verbUsage("merge-fields"))
		os.Exit(1)
	}
	if v.mode == 0 {
		fmt.Fprintf(os.Stderr, "mlr merge-fields: one of -f, -r, or -c is required.\n")
		fmt.Fprint(os.Stderr, verbUsage("merge-fields"))
		os.Exit(1)
	}
	if (v.mode == 'f' || v.mode == 'r') && v.outputName == "" {
		fmt.Fprintf(os.Stderr, "mlr merge-fields: option -o is required with -f or -r.\n")
		fmt.Fprint(os.Stderr, verbUsage("merge-fields"))
		os.Exit(1)
	}
	for _, a := range v.accNames {
		if !isValidStats1AccName(a) {
			fmt.Fprintf(os.Stderr, "mlr merge-fields: accumulator \"%s\" not found\n", a)
			os.Exit(1)
		}
	}
	return v, nil
}

func (v *mergeFieldsVerb) newAccs() *orderedMap {
	accs := newOrderedMap()
	for _, an := range v.accNames {
		accs.Put(an, makeStats1Acc(an, v.interpolate))
	}
	return accs
}

func ingestAccs(accs *orderedMap, val *Mlrval) {
	if val.Type() == MT_VOID {
		for _, an := range accs.keys {
			if an == "null_count" {
				accs.vals[an].(stats1Acc).ingest(val)
			}
		}
		return
	}
	for _, an := range accs.keys {
		accs.vals[an].(stats1Acc).ingest(val)
	}
}

func (v *mergeFieldsVerb) Process(rec *Mlrmap, ctx *Context, out recordSink) {
	switch v.mode {
	case 'f':
		accs := v.newAccs()
		for _, f := range v.fields {
			val := rec.Get(f)
			if val == nil {
				continue
			}
			ingestAccs(accs, val)
			if !v.keepInputs {
				rec.Remove(f)
			}
		}
		for _, an := range accs.keys {
			rec.Put(v.outputName+"_"+an, accs.vals[an].(stats1Acc).emit())
		}
	case 'r':
		accs := v.newAccs()
		var toRemove []string
		for e := rec.Head; e != nil; e = e.Next {
			matched := false
			for _, rx := range v.regexes {
				if rx.MatchString(e.Key) {
					matched = true
					break
				}
			}
			if !matched {
				continue
			}
			ingestAccs(accs, e.Value)
			if !v.keepInputs {
				toRemove = append(toRemove, e.Key)
			}
		}
		for _, k := range toRemove {
			rec.Remove(k)
		}
		for _, an := range accs.keys {
			rec.Put(v.outputName+"_"+an, accs.vals[an].(stats1Acc).emit())
		}
	case 'c':
		shortNames := newOrderedMap()
		var toRemove []string
		for e := rec.Head; e != nil; e = e.Next {
			for _, sub := range v.collapses {
				if strings.Contains(e.Key, sub) {
					short := strings.Replace(e.Key, sub, "", 1)
					ai, ok := shortNames.Get(short)
					var accs *orderedMap
					if !ok {
						accs = v.newAccs()
						shortNames.Put(short, accs)
					} else {
						accs = ai.(*orderedMap)
					}
					ingestAccs(accs, e.Value)
					if !v.keepInputs {
						toRemove = append(toRemove, e.Key)
					}
					break
				}
			}
		}
		for _, k := range toRemove {
			rec.Remove(k)
		}
		for _, short := range shortNames.keys {
			accs := shortNames.vals[short].(*orderedMap)
			for _, an := range accs.keys {
				rec.Put(short+"_"+an, accs.vals[an].(stats1Acc).emit())
			}
		}
	}
	out(rec, ctx)
}
func (v *mergeFieldsVerb) Finish(ctx *Context, out recordSink) {}

// ---------------------------------------------------------------- most-frequent / least-frequent

type mostFrequentVerb struct {
	fields     []string
	n          int64
	brief      bool
	outputName string
	descending bool
	groups     *orderedMap
	name       string
}

func parseMostFrequent(args []string, argi *int, opts *Options) (Verb, error) {
	return parseFrequent("most-frequent", true, args, argi)
}

func parseLeastFrequent(args []string, argi *int, opts *Options) (Verb, error) {
	return parseFrequent("least-frequent", false, args, argi)
}

func parseFrequent(name string, desc bool, args []string, argi *int) (Verb, error) {
	v := &mostFrequentVerb{n: 10, outputName: "count", descending: desc, groups: newOrderedMap(), name: name}
	p := newOptParser(name, args, argi)
	for {
		f := p.next()
		if f == "" {
			break
		}
		switch f {
		case "-f":
			v.fields = p.list()
		case "-n":
			v.n = p.int()
		case "-b":
			v.brief = true
			p.advance()
		case "-o":
			v.outputName = p.str()
		default:
			p.unknown(f)
		}
	}
	if v.fields == nil {
		fmt.Fprintf(os.Stderr, "mlr %s: option -f is required.\n", name)
		fmt.Fprint(os.Stderr, verbUsage(name))
		os.Exit(1)
	}
	return v, nil
}

func (v *mostFrequentVerb) Process(rec *Mlrmap, ctx *Context, out recordSink) {
	vals, ok := rec.GetSelectedValues(v.fields)
	if !ok {
		return
	}
	key, _ := rec.GetSelectedValuesJoined(v.fields)
	gi, ok := v.groups.Get(key)
	if !ok {
		v.groups.Put(key, &countGroup{vals: vals, count: 1})
	} else {
		gi.(*countGroup).count++
	}
}

func (v *mostFrequentVerb) Finish(ctx *Context, out recordSink) {
	n := v.groups.Len()
	idx := make([]int, n)
	for i := range idx {
		idx[i] = i
	}
	counts := make([]int64, n)
	for i, k := range v.groups.keys {
		counts[i] = v.groups.vals[k].(*countGroup).count
	}
	sortSliceStable(n, func(i, j int) bool {
		if v.descending {
			return counts[idx[i]] > counts[idx[j]]
		}
		return counts[idx[i]] < counts[idx[j]]
	}, func(i, j int) { idx[i], idx[j] = idx[j], idx[i] })
	for i := 0; i < n && int64(i) < v.n; i++ {
		g := v.groups.vals[v.groups.keys[idx[i]]].(*countGroup)
		rec := NewMlrmap()
		for j, f := range v.fields {
			rec.Put(f, g.vals[j])
		}
		if !v.brief {
			rec.Put(v.outputName, FromInt(g.count))
		}
		out(rec, ctx)
	}
}

// ---------------------------------------------------------------- fraction

type fractionVerb struct {
	fields     []string
	groupBy    []string
	percent    bool
	cumulative bool
	recs       []*Mlrmap
	ctxs       []Context
	sums       map[string]map[string]*Mlrval
}

func parseFraction(args []string, argi *int, opts *Options) (Verb, error) {
	v := &fractionVerb{sums: map[string]map[string]*Mlrval{}}
	p := newOptParser("fraction", args, argi)
	for {
		f := p.next()
		if f == "" {
			break
		}
		switch f {
		case "-f":
			v.fields = p.list()
		case "-g":
			v.groupBy = p.list()
		case "-p":
			v.percent = true
			p.advance()
		case "-c":
			v.cumulative = true
			p.advance()
		default:
			p.unknown(f)
		}
	}
	if v.fields == nil {
		fmt.Fprintf(os.Stderr, "mlr fraction: option -f is required.\n")
		fmt.Fprint(os.Stderr, verbUsage("fraction"))
		os.Exit(1)
	}
	return v, nil
}

func (v *fractionVerb) Process(rec *Mlrmap, ctx *Context, out recordSink) {
	v.recs = append(v.recs, rec)
	v.ctxs = append(v.ctxs, *ctx)
	key, ok := groupingKey(rec, v.groupBy)
	if !ok {
		return
	}
	sums, ok := v.sums[key]
	if !ok {
		sums = map[string]*Mlrval{}
		v.sums[key] = sums
	}
	for _, f := range v.fields {
		val := rec.Get(f)
		if val == nil || !val.IsNumeric() {
			continue
		}
		if cur, ok := sums[f]; ok {
			sums[f] = binaryOpPlus(cur, val)
		} else {
			sums[f] = val
		}
	}
}

func (v *fractionVerb) Finish(ctx *Context, out recordSink) {
	cums := map[string]map[string]*Mlrval{}
	suffix := "_fraction"
	if v.cumulative {
		suffix = "_cumulative_fraction"
	}
	if v.percent {
		suffix = strings.Replace(suffix, "fraction", "percent", 1)
	}
	for i, rec := range v.recs {
		key, ok := groupingKey(rec, v.groupBy)
		if ok {
			sums := v.sums[key]
			cum, ok := cums[key]
			if !ok {
				cum = map[string]*Mlrval{}
				cums[key] = cum
			}
			for _, f := range v.fields {
				val := rec.Get(f)
				if val == nil || !val.IsNumeric() {
					continue
				}
				denom := sums[f]
				var numer *Mlrval
				if v.cumulative {
					if c, ok := cum[f]; ok {
						cum[f] = binaryOpPlus(c, val)
					} else {
						cum[f] = val
					}
					numer = cum[f]
				} else {
					numer = val
				}
				var frac *Mlrval
				if v.percent {
					frac = binaryOpDivide(binaryOpTimes(FromInt(100), numer), denom)
				} else {
					frac = binaryOpDivide(numer, denom)
				}
				if frac.Type() == MT_INT {
					frac = FromFloat(float64(frac.intval))
				}
				rec.Put(f+suffix, frac)
			}
		}
		c := v.ctxs[i]
		out(rec, &c)
	}
}

// ---------------------------------------------------------------- histogram

type histogramVerb struct {
	fields []string
	lo, hi float64
	nbins  int64
	auto   bool
	prefix string
	counts map[string][]int64
	values map[string][]float64
	haveLoHi bool
}

func parseHistogram(args []string, argi *int, opts *Options) (Verb, error) {
	v := &histogramVerb{nbins: 20, counts: map[string][]int64{}, values: map[string][]float64{}}
	p := newOptParser("histogram", args, argi)
	for {
		f := p.next()
		if f == "" {
			break
		}
		switch f {
		case "-f":
			v.fields = p.list()
		case "--lo":
			v.lo = p.float()
			v.haveLoHi = true
		case "--hi":
			v.hi = p.float()
			v.haveLoHi = true
		case "--nbins":
			v.nbins = p.int()
		case "--auto":
			v.auto = true
			p.advance()
		case "-o":
			v.prefix = p.str()
		default:
			p.unknown(f)
		}
	}
	if v.fields == nil {
		fmt.Fprintf(os.Stderr, "mlr histogram: option -f is required.\n")
		fmt.Fprint(os.Stderr, verbUsage("histogram"))
		os.Exit(1)
	}
	if !v.auto && v.lo == v.hi {
		fmt.Fprintf(os.Stderr, "mlr histogram: --lo and --hi must be specified (or --auto).\n")
		fmt.Fprint(os.Stderr, verbUsage("histogram"))
		os.Exit(1)
	}
	for _, f := range v.fields {
		v.counts[f] = make([]int64, v.nbins)
	}
	return v, nil
}

func (v *histogramVerb) Process(rec *Mlrmap, ctx *Context, out recordSink) {
	for _, f := range v.fields {
		val := rec.Get(f)
		if val == nil || val.Type() == MT_VOID {
			continue
		}
		fv, ok := val.GetNumericToFloat()
		if !ok {
			fmt.Fprintf(os.Stderr, "mlr histogram: cannot parse \"%s\" as number.\n", val.String())
			os.Exit(1)
		}
		if v.auto {
			v.values[f] = append(v.values[f], fv)
			continue
		}
		v.binValue(f, fv, v.lo, v.hi)
	}
}

func (v *histogramVerb) binValue(f string, fv, lo, hi float64) {
	if fv < lo || fv > hi {
		return
	}
	var idx int64
	if fv == hi {
		idx = v.nbins - 1
	} else {
		idx = int64((fv - lo) / (hi - lo) * float64(v.nbins))
	}
	if idx < 0 || idx >= v.nbins {
		return
	}
	v.counts[f][idx]++
}

func (v *histogramVerb) Finish(ctx *Context, out recordSink) {
	lo, hi := v.lo, v.hi
	if v.auto {
		first := true
		for _, f := range v.fields {
			for _, fv := range v.values[f] {
				if first {
					lo, hi = fv, fv
					first = false
				} else {
					if fv < lo {
						lo = fv
					}
					if fv > hi {
						hi = fv
					}
				}
			}
		}
		for _, f := range v.fields {
			for _, fv := range v.values[f] {
				v.binValue(f, fv, lo, hi)
			}
		}
	}
	binWidth := (hi - lo) / float64(v.nbins)
	for i := int64(0); i < v.nbins; i++ {
		rec := NewMlrmap()
		rec.Put(v.prefix+"bin_lo", FromFloat(lo+float64(i)*binWidth))
		rec.Put(v.prefix+"bin_hi", FromFloat(lo+float64(i+1)*binWidth))
		for _, f := range v.fields {
			rec.Put(v.prefix+f+"_count", FromInt(v.counts[f][i]))
		}
		out(rec, ctx)
	}
}

// ---------------------------------------------------------------- repeat

type repeatVerb struct {
	n     int64
	field string
}

func parseRepeat(args []string, argi *int, opts *Options) (Verb, error) {
	v := &repeatVerb{n: -1}
	p := newOptParser("repeat", args, argi)
	for {
		f := p.next()
		if f == "" {
			break
		}
		switch f {
		case "-n":
			v.n = p.int()
		case "-f":
			v.field = p.str()
		default:
			p.unknown(f)
		}
	}
	if v.n < 0 && v.field == "" {
		fmt.Fprint(os.Stderr, verbUsage("repeat"))
		os.Exit(1)
	}
	return v, nil
}

func (v *repeatVerb) Process(rec *Mlrmap, ctx *Context, out recordSink) {
	n := v.n
	if v.field != "" {
		val := rec.Get(v.field)
		if val == nil {
			return
		}
		if val.Type() == MT_INT {
			n = val.intval
		} else if val.Type() == MT_FLOAT {
			n = int64(val.floatval)
		} else {
			return
		}
	}
	for i := int64(0); i < n; i++ {
		if i == 0 {
			out(rec, ctx)
		} else {
			out(rec.Copy(), ctx)
		}
	}
}
func (v *repeatVerb) Finish(ctx *Context, out recordSink) {}

// ---------------------------------------------------------------- format-values

type formatValuesVerb struct {
	intFmt, floatFmt, strFmt string
	coerceFloat bool
}

func parseFormatValues(args []string, argi *int, opts *Options) (Verb, error) {
	v := &formatValuesVerb{intFmt: "%d", floatFmt: "%f", strFmt: "%s"}
	p := newOptParser("format-values", args, argi)
	for {
		f := p.next()
		if f == "" {
			break
		}
		switch f {
		case "-i":
			v.intFmt = p.str()
		case "-f":
			v.floatFmt = p.str()
		case "-s":
			v.strFmt = p.str()
		case "-n":
			v.coerceFloat = true
			p.advance()
		default:
			p.unknown(f)
		}
	}
	return v, nil
}

func (v *formatValuesVerb) Process(rec *Mlrmap, ctx *Context, out recordSink) {
	for e := rec.Head; e != nil; e = e.Next {
		switch e.Value.Type() {
		case MT_INT:
			if v.coerceFloat {
				e.Value = fmtnumValue(FromFloat(float64(e.Value.intval)), v.floatFmt)
			} else {
				e.Value = fmtnumValue(e.Value, v.intFmt)
			}
		case MT_FLOAT:
			e.Value = fmtnumValue(e.Value, v.floatFmt)
		case MT_BOOLEAN, MT_STRING, MT_VOID:
			e.Value = FromString(fmt.Sprintf(strings.ReplaceAll(v.strFmt, "%s", "%s"), e.Value.String()))
		}
	}
	out(rec, ctx)
}
func (v *formatValuesVerb) Finish(ctx *Context, out recordSink) {}

// ---------------------------------------------------------------- sub/gsub/ssub verbs

type subVerb struct {
	name    string
	fields  []string
	fieldSet map[string]bool
	regex   *regexp.Regexp
	all     bool
	old     string
	new     string
	oldRx   *regexp.Regexp
}

func parseSubVerb(args []string, argi *int, opts *Options) (Verb, error) {
	return parseSubLike("sub", args, argi)
}
func parseGsubVerb(args []string, argi *int, opts *Options) (Verb, error) {
	return parseSubLike("gsub", args, argi)
}
func parseSsubVerb(args []string, argi *int, opts *Options) (Verb, error) {
	return parseSubLike("ssub", args, argi)
}

func parseSubLike(name string, args []string, argi *int) (Verb, error) {
	v := &subVerb{name: name, fieldSet: map[string]bool{}}
	p := newOptParser(name, args, argi)
	for {
		f := p.next()
		if f == "" {
			break
		}
		switch f {
		case "-f":
			v.fields = p.list()
		case "-r":
			v.regex = compileMillerRegexOrDie(p.str())
		case "-a":
			v.all = true
			p.advance()
		default:
			p.unknown(f)
		}
	}
	if v.fields == nil && v.regex == nil && !v.all {
		fmt.Fprintf(os.Stderr, "mlr %s: one of -f, -r, or -a is required.\n", name)
		fmt.Fprint(os.Stderr, verbUsage(name))
		os.Exit(1)
	}
	old, ok1 := p.positional()
	nw, ok2 := p.positional()
	if !ok1 || !ok2 {
		fmt.Fprint(os.Stderr, verbUsage(name))
		os.Exit(1)
	}
	v.old = old
	v.new = nw
	for _, f := range v.fields {
		v.fieldSet[f] = true
	}
	if name != "ssub" {
		v.oldRx = compileMillerRegexOrDie(old)
	}
	return v, nil
}

func (v *subVerb) apply(val *Mlrval) *Mlrval {
	if val.Type() != MT_STRING && val.Type() != MT_VOID {
		if !val.IsNumeric() && val.Type() != MT_BOOLEAN {
			return val
		}
	}
	s := val.String()
	switch v.name {
	case "sub":
		return inferredFromString(regexSubWithCaptures(s, v.oldRx, v.new))
	case "gsub":
		return inferredFromString(regexGsubWithCaptures(s, v.oldRx, v.new))
	default:
		return inferredFromString(strings.Replace(s, v.old, v.new, 1))
	}
}

func (v *subVerb) Process(rec *Mlrmap, ctx *Context, out recordSink) {
	for e := rec.Head; e != nil; e = e.Next {
		if v.all || v.fieldSet[e.Key] || (v.regex != nil && v.regex.MatchString(e.Key)) {
			e.Value = v.apply(e.Value)
		}
	}
	out(rec, ctx)
}
func (v *subVerb) Finish(ctx *Context, out recordSink) {}

// ---------------------------------------------------------------- case

type caseVerb struct {
	keys, values bool
	fields       map[string]bool
	style        byte // 'u','l','s','t'
}

func parseCase(args []string, argi *int, opts *Options) (Verb, error) {
	v := &caseVerb{keys: true, values: true}
	p := newOptParser("case", args, argi)
	for {
		f := p.next()
		if f == "" {
			break
		}
		switch f {
		case "-k":
			v.keys = true
			v.values = false
			p.advance()
		case "-v":
			v.keys = false
			v.values = true
			p.advance()
		case "-f":
			v.fields = map[string]bool{}
			for _, n := range p.list() {
				v.fields[n] = true
			}
		case "-u":
			v.style = 'u'
			p.advance()
		case "-l":
			v.style = 'l'
			p.advance()
		case "-s":
			v.style = 's'
			p.advance()
		case "-t":
			v.style = 't'
			p.advance()
		default:
			p.unknown(f)
		}
	}
	if v.style == 0 {
		fmt.Fprintf(os.Stderr, "mlr case: one of -u, -l, -s, -t is required.\n")
		fmt.Fprint(os.Stderr, verbUsage("case"))
		os.Exit(1)
	}
	return v, nil
}

func (v *caseVerb) convert(s string) string {
	switch v.style {
	case 'u':
		return strings.ToUpper(s)
	case 'l':
		return strings.ToLower(s)
	case 's':
		if s == "" {
			return s
		}
		return strings.ToUpper(s[:1]) + strings.ToLower(s[1:])
	case 't':
		words := strings.Split(s, " ")
		for i, w := range words {
			if w != "" {
				words[i] = strings.ToUpper(w[:1]) + strings.ToLower(w[1:])
			}
		}
		return strings.Join(words, " ")
	}
	return s
}

func (v *caseVerb) Process(rec *Mlrmap, ctx *Context, out recordSink) {
	newrec := NewMlrmap()
	for e := rec.Head; e != nil; e = e.Next {
		k := e.Key
		val := e.Value
		if v.fields == nil || v.fields[e.Key] {
			if v.keys {
				k = v.convert(k)
			}
			if v.values && (val.Type() == MT_STRING) {
				val = FromString(v.convert(val.String()))
			}
		}
		newrec.Put(k, val)
	}
	out(newrec, ctx)
}
func (v *caseVerb) Finish(ctx *Context, out recordSink) {}

// ---------------------------------------------------------------- bar

type barVerb struct {
	fields []string
	lo, hi float64
	width  int64
	auto   bool
	fill, oob, blank string
	recs   []*Mlrmap
	ctxs   []Context
}

func parseBar(args []string, argi *int, opts *Options) (Verb, error) {
	v := &barVerb{lo: 0, hi: 100, width: 40, fill: "*", oob: "#", blank: "."}
	p := newOptParser("bar", args, argi)
	for {
		f := p.next()
		if f == "" {
			break
		}
		switch f {
		case "-f":
			v.fields = p.list()
		case "--lo":
			v.lo = p.float()
		case "--hi":
			v.hi = p.float()
		case "-w":
			v.width = p.int()
		case "--auto":
			v.auto = true
			p.advance()
		case "-c":
			v.fill = p.str()
		case "-x":
			v.oob = p.str()
		case "-b":
			v.blank = p.str()
		default:
			p.unknown(f)
		}
	}
	if v.fields == nil {
		fmt.Fprintf(os.Stderr, "mlr bar: option -f is required.\n")
		fmt.Fprint(os.Stderr, verbUsage("bar"))
		os.Exit(1)
	}
	return v, nil
}

func (v *barVerb) bar(fv float64, lo, hi float64) string {
	idx := int64((float64(v.width) * (fv - lo)) / (hi - lo))
	var sb strings.Builder
	if idx < 0 {
		sb.WriteString(v.oob)
		for i := int64(1); i < v.width; i++ {
			sb.WriteString(v.blank)
		}
	} else if idx >= v.width {
		for i := int64(0); i < v.width-1; i++ {
			sb.WriteString(v.fill)
		}
		sb.WriteString(v.oob)
	} else {
		for i := int64(0); i < idx; i++ {
			sb.WriteString(v.fill)
		}
		for i := idx; i < v.width; i++ {
			sb.WriteString(v.blank)
		}
	}
	return sb.String()
}

func (v *barVerb) Process(rec *Mlrmap, ctx *Context, out recordSink) {
	if v.auto {
		v.recs = append(v.recs, rec)
		v.ctxs = append(v.ctxs, *ctx)
		return
	}
	for _, f := range v.fields {
		val := rec.Get(f)
		if val == nil {
			continue
		}
		fv, ok := val.GetNumericToFloat()
		if !ok {
			continue
		}
		rec.Put(f, FromString(v.bar(fv, v.lo, v.hi)))
	}
	out(rec, ctx)
}

func (v *barVerb) Finish(ctx *Context, out recordSink) {
	if !v.auto {
		return
	}
	for _, f := range v.fields {
		lo, hi := 0.0, 0.0
		first := true
		for _, rec := range v.recs {
			val := rec.Get(f)
			if val == nil {
				continue
			}
			fv, ok := val.GetNumericToFloat()
			if !ok {
				continue
			}
			if first {
				lo, hi = fv, fv
				first = false
			} else {
				lo = math.Min(lo, fv)
				hi = math.Max(hi, fv)
			}
		}
		for _, rec := range v.recs {
			val := rec.Get(f)
			if val == nil {
				continue
			}
			fv, ok := val.GetNumericToFloat()
			if !ok {
				continue
			}
			rec.Put(f, FromString(fmt.Sprintf("[%g]%s[%g]", lo, v.bar(fv, lo, hi), hi)))
		}
	}
	for i, rec := range v.recs {
		c := v.ctxs[i]
		out(rec, &c)
	}
}
