package main

import (
	"fmt"
	"net/url"
	"os"
	"path/filepath"
	"regexp"
	"strconv"
	"strings"
)

// ---------------------------------------------------------------- nest

type nestVerb struct {
	explode   bool
	values    bool // vs pairs
	acrossRecords bool
	field     string
	fieldRegex *regexp.Regexp
	nestedFS  string
	nestedPS  string
	// for implode across records
	groups    *orderedMap
}

type nestImplodeGroup struct {
	rec    *Mlrmap
	ctx    Context
	values []string
}

func parseNest(args []string, argi *int, opts *Options) (Verb, error) {
	v := &nestVerb{nestedFS: ";", nestedPS: ":", groups: newOrderedMap()}
	haveExplode, haveValues, haveAcross := false, false, false
	p := newOptParser("nest", args, argi)
	for {
		f := p.next()
		if f == "" {
			break
		}
		switch f {
		case "--explode":
			v.explode = true
			haveExplode = true
			p.advance()
		case "--implode":
			v.explode = false
			haveExplode = true
			p.advance()
		case "--values":
			v.values = true
			haveValues = true
			p.advance()
		case "--pairs":
			v.values = false
			haveValues = true
			p.advance()
		case "--across-records":
			v.acrossRecords = true
			haveAcross = true
			p.advance()
		case "--across-fields":
			v.acrossRecords = false
			haveAcross = true
			p.advance()
		case "-f":
			v.field = p.str()
		case "-r":
			v.fieldRegex = compileMillerRegexOrDie(p.str())
		case "--nested-fs":
			v.nestedFS = unbackslashSeparator(p.str())
		case "--nested-ps":
			v.nestedPS = unbackslashSeparator(p.str())
		case "--evar":
			v.nestedFS = unbackslashSeparator(p.str())
			v.explode, v.values, v.acrossRecords = true, true, true
			haveExplode, haveValues, haveAcross = true, true, true
		case "--ivar":
			v.nestedFS = unbackslashSeparator(p.str())
			v.explode, v.values, v.acrossRecords = false, true, true
			haveExplode, haveValues, haveAcross = true, true, true
		default:
			p.unknown(f)
		}
	}
	if !haveExplode || !haveValues || !haveAcross || (v.field == "" && v.fieldRegex == nil) {
		fmt.Fprint(os.Stderr, verbUsage("nest"))
		os.Exit(1)
	}
	return v, nil
}

func (v *nestVerb) fieldNames(rec *Mlrmap) []string {
	if v.fieldRegex == nil {
		return []string{v.field}
	}
	var out []string
	for e := rec.Head; e != nil; e = e.Next {
		if v.fieldRegex.MatchString(e.Key) {
			out = append(out, e.Key)
		}
	}
	return out
}

func (v *nestVerb) Process(rec *Mlrmap, ctx *Context, out recordSink) {
	if v.explode {
		if v.acrossRecords {
			v.explodeAcrossRecords(rec, ctx, out, v.fieldNames(rec))
		} else {
			for _, f := range v.fieldNames(rec) {
				v.explodeAcrossFields(rec, f)
			}
			out(rec, ctx)
		}
		return
	}
	// implode
	if v.acrossRecords {
		f := v.field
		if v.fieldRegex != nil {
			names := v.fieldNames(rec)
			if len(names) == 0 {
				out(rec, ctx)
				return
			}
			f = names[0]
		}
		val := rec.Get(f)
		if val == nil {
			out(rec, ctx)
			return
		}
		// group by other fields
		var sb strings.Builder
		for e := rec.Head; e != nil; e = e.Next {
			if e.Key == f {
				continue
			}
			sb.WriteString(e.Key)
			sb.WriteString("\x01")
			sb.WriteString(e.Value.String())
			sb.WriteString("\x02")
		}
		key := sb.String()
		gi, ok := v.groups.Get(key)
		if !ok {
			v.groups.Put(key, &nestImplodeGroup{rec: rec, ctx: *ctx, values: []string{val.String()}})
		} else {
			g := gi.(*nestImplodeGroup)
			g.values = append(g.values, val.String())
		}
		return
	}
	// implode across fields: x_1, x_2, ... -> x
	f := v.field
	var pieces []string
	var firstEntry *MlrmapEntry
	var toRemove []string
	for e := rec.Head; e != nil; e = e.Next {
		if strings.HasPrefix(e.Key, f+"_") {
			if _, err := strconv.Atoi(e.Key[len(f)+1:]); err == nil {
				if firstEntry == nil {
					firstEntry = e
				}
				pieces = append(pieces, e.Value.String())
				toRemove = append(toRemove, e.Key)
			}
		}
	}
	if firstEntry != nil {
		rec.PutAfter(firstEntry, f, inferredFromString(strings.Join(pieces, v.nestedFS)))
		for _, k := range toRemove {
			rec.Remove(k)
		}
	}
	out(rec, ctx)
}

func (v *nestVerb) explodeAcrossRecords(rec *Mlrmap, ctx *Context, out recordSink, fields []string) {
	if len(fields) == 0 {
		out(rec, ctx)
		return
	}
	f := fields[0]
	rest := fields[1:]
	val := rec.Get(f)
	if val == nil {
		v.explodeAcrossRecords(rec, ctx, out, rest)
		return
	}
	pieces := strings.Split(val.String(), v.nestedFS)
	for _, piece := range pieces {
		newrec := rec.ShallowCopy()
		if v.values {
			newrec.Put(f, inferredFromString(piece))
		} else {
			idx := strings.Index(piece, v.nestedPS)
			if idx < 0 {
				newrec.Put(f, inferredFromString(piece))
			} else {
				e := newrec.GetEntry(f)
				newrec.PutAfter(e, piece[:idx], inferredFromString(piece[idx+len(v.nestedPS):]))
				if piece[:idx] != f {
					newrec.Remove(f)
				}
			}
		}
		if len(rest) > 0 {
			v.explodeAcrossRecords(newrec, ctx, out, rest)
		} else {
			out(newrec, ctx)
		}
	}
}

func (v *nestVerb) explodeAcrossFields(rec *Mlrmap, f string) {
	e := rec.GetEntry(f)
	if e == nil {
		return
	}
	pieces := strings.Split(e.Value.String(), v.nestedFS)
	cur := e
	for i, piece := range pieces {
		var k string
		var val *Mlrval
		if v.values {
			k = fmt.Sprintf("%s_%d", f, i+1)
			val = inferredFromString(piece)
		} else {
			idx := strings.Index(piece, v.nestedPS)
			if idx < 0 {
				k = f
				val = inferredFromString(piece)
			} else {
				k = piece[:idx]
				val = inferredFromString(piece[idx+len(v.nestedPS):])
			}
		}
		rec.PutAfter(cur, k, val)
		cur = rec.GetEntry(k)
	}
	if !rec.hasKeyAmong(f, pieces, v) {
		rec.Remove(f)
	}
}

// hasKeyAmong: whether the original field name was re-created as a pair key.
func (m *Mlrmap) hasKeyAmong(f string, pieces []string, v *nestVerb) bool {
	if v.values {
		return false
	}
	for _, piece := range pieces {
		idx := strings.Index(piece, v.nestedPS)
		if idx < 0 || piece[:idx] == f {
			return true
		}
	}
	return false
}

func (v *nestVerb) Finish(ctx *Context, out recordSink) {
	if v.explode || !v.acrossRecords {
		return
	}
	for _, k := range v.groups.keys {
		g := v.groups.vals[k].(*nestImplodeGroup)
		f := v.field
		if v.fieldRegex != nil {
			names := v.fieldNames(g.rec)
			if len(names) > 0 {
				f = names[0]
			}
		}
		g.rec.Put(f, inferredFromString(strings.Join(g.values, v.nestedFS)))
		c := g.ctx
		out(g.rec, &c)
	}
}

// ---------------------------------------------------------------- reshape

type reshapeVerb struct {
	inputFields  []string
	inputRegexes []*regexp.Regexp
	keyField     string
	valueField   string
	splitFields  []string
	// long-to-wide state
	groups       *orderedMap
	otherRecs    []*Mlrmap
	otherCtxs    []Context
	wideKeys     *orderedMap
}

type reshapeGroup struct {
	rec  *Mlrmap
	ctx  Context
	pairs *Mlrmap
}

func parseReshape(args []string, argi *int, opts *Options) (Verb, error) {
	v := &reshapeVerb{groups: newOrderedMap(), wideKeys: newOrderedMap()}
	p := newOptParser("reshape", args, argi)
	for {
		f := p.next()
		if f == "" {
			break
		}
		switch f {
		case "-i":
			v.inputFields = append(v.inputFields, p.list()...)
		case "-r":
			for _, r := range p.list() {
				v.inputRegexes = append(v.inputRegexes, compileMillerRegexOrDie(r))
			}
		case "-o":
			names := p.list()
			if len(names) != 2 {
				fmt.Fprint(os.Stderr, verbUsage("reshape"))
				os.Exit(1)
			}
			v.keyField = names[0]
			v.valueField = names[1]
		case "-s":
			names := p.list()
			if len(names) != 2 {
				fmt.Fprint(os.Stderr, verbUsage("reshape"))
				os.Exit(1)
			}
			v.splitFields = names
		default:
			p.unknown(f)
		}
	}
	if v.splitFields == nil {
		if (v.inputFields == nil && v.inputRegexes == nil) || v.keyField == "" {
			fmt.Fprint(os.Stderr, verbUsage("reshape"))
			os.Exit(1)
		}
	}
	return v, nil
}

func (v *reshapeVerb) Process(rec *Mlrmap, ctx *Context, out recordSink) {
	if v.splitFields == nil {
		// wide-to-long
		var pairs []*MlrmapEntry
		for e := rec.Head; e != nil; e = e.Next {
			matched := false
			for _, f := range v.inputFields {
				if e.Key == f {
					matched = true
					break
				}
			}
			if !matched {
				for _, rx := range v.inputRegexes {
					if rx.MatchString(e.Key) {
						matched = true
						break
					}
				}
			}
			if matched {
				pairs = append(pairs, e)
			}
		}
		if len(pairs) == 0 {
			out(rec, ctx)
			return
		}
		base := rec.ShallowCopy()
		for _, e := range pairs {
			base.Remove(e.Key)
		}
		for _, e := range pairs {
			newrec := base.ShallowCopy()
			newrec.Put(v.keyField, FromString(e.Key))
			newrec.Put(v.valueField, e.Value)
			out(newrec, ctx)
		}
		return
	}
	// long-to-wide
	keyField, valueField := v.splitFields[0], v.splitFields[1]
	kv := rec.Get(keyField)
	vv := rec.Get(valueField)
	if kv == nil || vv == nil {
		v.otherRecs = append(v.otherRecs, rec)
		v.otherCtxs = append(v.otherCtxs, *ctx)
		return
	}
	others := rec.ShallowCopy()
	others.Remove(keyField)
	others.Remove(valueField)
	groupKey := others.ToDKVPString("\x01", "\x02")
	gi, ok := v.groups.Get(groupKey)
	var g *reshapeGroup
	if !ok {
		g = &reshapeGroup{rec: others, ctx: *ctx, pairs: NewMlrmap()}
		v.groups.Put(groupKey, g)
	} else {
		g = gi.(*reshapeGroup)
	}
	g.pairs.Put(kv.String(), vv)
	v.wideKeys.Put(kv.String(), true)
}

func (v *reshapeVerb) Finish(ctx *Context, out recordSink) {
	if v.splitFields == nil {
		return
	}
	for _, k := range v.groups.keys {
		g := v.groups.vals[k].(*reshapeGroup)
		newrec := g.rec.ShallowCopy()
		for _, wk := range v.wideKeys.keys {
			val := g.pairs.Get(wk)
			if val == nil {
				newrec.Put(wk, VOID)
			} else {
				newrec.Put(wk, val)
			}
		}
		c := g.ctx
		out(newrec, &c)
	}
	for i, rec := range v.otherRecs {
		c := v.otherCtxs[i]
		out(rec, &c)
	}
}

// ---------------------------------------------------------------- join

type joinVerb struct {
	leftFile       string
	outputJoinFields []string
	leftJoinFields []string
	rightJoinFields []string
	leftKeepFields []string
	leftPrefix     string
	rightPrefix    string
	emitPaired     bool
	emitLeftUnpaired bool
	emitRightUnpaired bool
	leftOpts       ReaderOptions
	// state
	loaded         bool
	buckets        *orderedMap // join values -> *joinBucket
	leftUnkeyed    []*Mlrmap
}

type joinBucket struct {
	recs   []*Mlrmap
	paired bool
}

func parseJoin(args []string, argi *int, opts *Options) (Verb, error) {
	v := &joinVerb{emitPaired: true, buckets: newOrderedMap()}
	v.leftOpts = opts.Reader
	leftOptsOverride := &Options{Reader: opts.Reader, Writer: opts.Writer}
	leftOptsOverride.Reader.ifsWasSpecified = false
	leftOptsOverride.Reader.ipsWasSpecified = false
	leftOptsOverride.Reader.irsWasSpecified = false
	formatChanged := false
	p := newOptParser("join", args, argi)
	for {
		f := p.next()
		if f == "" {
			break
		}
		switch f {
		case "-f":
			v.leftFile = p.str()
		case "-j":
			v.outputJoinFields = p.list()
		case "-l":
			v.leftJoinFields = p.list()
		case "-r":
			v.rightJoinFields = p.list()
		case "--lk", "--left-keep-field-names":
			v.leftKeepFields = p.list()
		case "--lp":
			v.leftPrefix = p.str()
		case "--rp":
			v.rightPrefix = p.str()
		case "--np":
			v.emitPaired = false
			p.advance()
		case "--ul":
			v.emitLeftUnpaired = true
			p.advance()
		case "--ur":
			v.emitRightUnpaired = true
			p.advance()
		case "-u", "-s", "--sorted-input":
			p.advance()
		case "-i":
			leftOptsOverride.Reader.InputFileFormat = p.str()
			formatChanged = true
		case "--prepipe":
			leftOptsOverride.Reader.Prepipe = p.str()
			leftOptsOverride.Reader.PrepipeIsRaw = false
		case "--prepipex":
			leftOptsOverride.Reader.Prepipe = p.str()
			leftOptsOverride.Reader.PrepipeIsRaw = true
		default:
			j := *argi
			if parseMainFlag(args, &j, leftOptsOverride) {
				*argi = j
				formatChanged = true
			} else {
				p.unknown(f)
			}
		}
	}
	if v.leftFile == "" {
		fmt.Fprintf(os.Stderr, "mlr join: option -f is required.\n")
		fmt.Fprint(os.Stderr, verbUsage("join"))
		os.Exit(1)
	}
	if v.outputJoinFields == nil {
		if v.leftJoinFields != nil {
			v.outputJoinFields = v.leftJoinFields
		} else if v.rightJoinFields != nil {
			v.outputJoinFields = v.rightJoinFields
		} else {
			fmt.Fprintf(os.Stderr, "mlr join: option -j is required.\n")
			fmt.Fprint(os.Stderr, verbUsage("join"))
			os.Exit(1)
		}
	}
	if v.leftJoinFields == nil {
		v.leftJoinFields = v.outputJoinFields
	}
	if v.rightJoinFields == nil {
		v.rightJoinFields = v.outputJoinFields
	}
	if len(v.leftJoinFields) != len(v.rightJoinFields) || len(v.leftJoinFields) != len(v.outputJoinFields) {
		fmt.Fprintf(os.Stderr, "mlr join: -j, -l, and -r field names must have the same length.\n")
		os.Exit(1)
	}
	if formatChanged {
		leftOptsOverride.finalize()
		v.leftOpts = leftOptsOverride.Reader
	} else {
		v.leftOpts = opts.Reader
	}
	return v, nil
}

func (v *joinVerb) loadLeft() {
	if v.loaded {
		return
	}
	v.loaded = true
	ropts := v.leftOpts
	reader, err := createRecordReader(&ropts)
	if err != nil {
		fmt.Fprintf(os.Stderr, "%s\n", err.Error())
		os.Exit(1)
	}
	ctx := &Context{}
	var keepSet map[string]bool
	if v.leftKeepFields != nil {
		keepSet = map[string]bool{}
		for _, f := range v.leftKeepFields {
			keepSet[f] = true
		}
		for _, f := range v.leftJoinFields {
			keepSet[f] = true
		}
	}
	err = reader.Read([]string{v.leftFile}, ctx, func(rec *Mlrmap, c *Context) bool {
		if keepSet != nil {
			newrec := NewMlrmap()
			for e := rec.Head; e != nil; e = e.Next {
				if keepSet[e.Key] {
					newrec.Put(e.Key, e.Value)
				}
			}
			rec = newrec
		}
		key, ok := rec.GetSelectedValuesJoined(v.leftJoinFields)
		if !ok {
			v.leftUnkeyed = append(v.leftUnkeyed, rec)
			return true
		}
		bi, ok := v.buckets.Get(key)
		if !ok {
			v.buckets.Put(key, &joinBucket{recs: []*Mlrmap{rec}})
		} else {
			b := bi.(*joinBucket)
			b.recs = append(b.recs, rec)
		}
		return true
	})
	if err != nil {
		msg := err.Error()
		if !strings.HasSuffix(msg, "\n") {
			msg += "\n"
		}
		fmt.Fprint(os.Stderr, msg)
		os.Exit(1)
	}
}

func (v *joinVerb) Process(rec *Mlrmap, ctx *Context, out recordSink) {
	v.loadLeft()
	key, ok := rec.GetSelectedValuesJoined(v.rightJoinFields)
	if !ok {
		if v.emitRightUnpaired {
			out(rec, ctx)
		}
		return
	}
	bi, ok := v.buckets.Get(key)
	if !ok {
		if v.emitRightUnpaired {
			out(rec, ctx)
		}
		return
	}
	b := bi.(*joinBucket)
	b.paired = true
	if !v.emitPaired {
		return
	}
	leftSet := map[string]bool{}
	for _, f := range v.leftJoinFields {
		leftSet[f] = true
	}
	rightSet := map[string]bool{}
	for _, f := range v.rightJoinFields {
		rightSet[f] = true
	}
	for _, leftRec := range b.recs {
		outrec := NewMlrmap()
		for i, lf := range v.leftJoinFields {
			val := leftRec.Get(lf)
			if val != nil {
				outrec.Put(v.outputJoinFields[i], val)
			}
		}
		for e := leftRec.Head; e != nil; e = e.Next {
			if leftSet[e.Key] {
				continue
			}
			k := e.Key
			if v.leftPrefix != "" {
				k = v.leftPrefix + k
			}
			outrec.Put(k, e.Value)
		}
		for e := rec.Head; e != nil; e = e.Next {
			if rightSet[e.Key] {
				continue
			}
			k := e.Key
			if v.rightPrefix != "" {
				k = v.rightPrefix + k
			}
			outrec.Put(k, e.Value)
		}
		out(outrec, ctx)
	}
}

func (v *joinVerb) Finish(ctx *Context, out recordSink) {
	v.loadLeft()
	if !v.emitLeftUnpaired {
		return
	}
	for _, k := range v.buckets.keys {
		b := v.buckets.vals[k].(*joinBucket)
		if b.paired {
			continue
		}
		for _, rec := range b.recs {
			out(rec, ctx)
		}
	}
	for _, rec := range v.leftUnkeyed {
		out(rec, ctx)
	}
}

// ---------------------------------------------------------------- split

type splitVerb struct {
	n, m      int64
	groupBy   []string
	prefix    string
	suffix    string
	folder    string
	appendMode bool
	passThrough bool
	noEscape  bool
	joiner    string
	wopts     WriterOptions
	count     int64
	outputs   map[string]*fileOutput
}

func parseSplit(args []string, argi *int, opts *Options) (Verb, error) {
	v := &splitVerb{prefix: "split", joiner: "_", outputs: map[string]*fileOutput{}}
	localOpts := &Options{Reader: opts.Reader, Writer: opts.Writer}
	p := newOptParser("split", args, argi)
	for {
		f := p.next()
		if f == "" {
			break
		}
		switch f {
		case "-n":
			v.n = p.int()
		case "-m":
			v.m = p.int()
		case "-g":
			v.groupBy = p.list()
		case "--prefix":
			v.prefix = p.str()
		case "--suffix":
			v.suffix = p.str()
		case "--folder":
			v.folder = p.str()
		case "-a":
			v.appendMode = true
			p.advance()
		case "-v":
			v.passThrough = true
			p.advance()
		case "-e":
			v.noEscape = true
			p.advance()
		case "-j":
			v.joiner = p.str()
		default:
			j := *argi
			if parseMainFlag(args, &j, localOpts) {
				*argi = j
			} else {
				p.unknown(f)
			}
		}
	}
	if v.n == 0 && v.m == 0 && v.groupBy == nil {
		fmt.Fprint(os.Stderr, verbUsage("split"))
		os.Exit(1)
	}
	localOpts.Reader.ifsWasSpecified = true
	localOpts.Reader.ipsWasSpecified = true
	localOpts.Reader.irsWasSpecified = true
	localOpts.finalize()
	v.wopts = localOpts.Writer
	if v.suffix == "" {
		v.suffix = v.wopts.OutputFileFormat
		if v.suffix == "markdown" {
			v.suffix = "md"
		}
	}
	return v, nil
}

func (v *splitVerb) getOutput(name string) *fileOutput {
	fo, ok := v.outputs[name]
	if ok {
		return fo
	}
	path := name
	if v.folder != "" {
		path = filepath.Join(v.folder, name)
	}
	wopts := v.wopts
	fo = newFileOutput(path, v.appendMode, false, &wopts)
	v.outputs[name] = fo
	return fo
}

func (v *splitVerb) Process(rec *Mlrmap, ctx *Context, out recordSink) {
	v.count++
	var name string
	if v.n > 0 {
		idx := (v.count-1)/v.n + 1
		name = fmt.Sprintf("%s%s%d.%s", v.prefix, v.joiner, idx, v.suffix)
	} else if v.m > 0 {
		idx := (v.count-1)%v.m + 1
		name = fmt.Sprintf("%s%s%d.%s", v.prefix, v.joiner, idx, v.suffix)
	} else {
		vals, ok := rec.GetSelectedValues(v.groupBy)
		if !ok {
			if v.passThrough {
				out(rec, ctx)
			}
			return
		}
		parts := []string{v.prefix}
		for _, val := range vals {
			s := val.String()
			if !v.noEscape {
				s = url.QueryEscape(s)
			}
			parts = append(parts, s)
		}
		name = strings.Join(parts, v.joiner) + "." + v.suffix
	}
	fo := v.getOutput(name)
	fo.writeRecord(rec.Copy())
	if v.passThrough {
		out(rec, ctx)
	}
}

func (v *splitVerb) Finish(ctx *Context, out recordSink) {
	for _, fo := range v.outputs {
		fo.close()
	}
}
