package main

import (
	"fmt"
	"math"
	"os"
)

type bivarAcc struct {
	n                 int64
	sumx, sumy        float64
	sumxy             float64
	sumx2, sumy2      float64
	xs, ys            []float64 // for logireg / pca fits
}

func (b *bivarAcc) ingest(x, y float64) {
	b.n++
	b.sumx += x
	b.sumy += y
	b.sumxy += x * y
	b.sumx2 += x * x
	b.sumy2 += y * y
}

func getCov(n int64, sumx, sumy, sumxy float64) float64 {
	fn := float64(n)
	meanx := sumx / fn
	meany := sumy / fn
	numerator := sumxy - meanx*sumy - meany*sumx + fn*meanx*meany
	return numerator / (fn - 1)
}

func (b *bivarAcc) ols() (m, bb float64, ok bool) {
	n := float64(b.n)
	d := n*b.sumx2 - b.sumx*b.sumx
	if d == 0 || b.n < 2 {
		return 0, 0, false
	}
	m = (n*b.sumxy - b.sumx*b.sumy) / d
	bb = (-b.sumx*b.sumxy + b.sumx2*b.sumy) / d
	return m, bb, true
}

type stats2Verb struct {
	accNames   []string
	fieldPairs [][2]string
	groupBy    []string
	verbose    bool
	iterative  bool
	doFit      bool
	groups     *orderedMap
	recs       []*Mlrmap
	ctxs       []Context
}

type stats2Group struct {
	groupVals []*Mlrval
	accs      map[string]*bivarAcc // key "x,y"
}

func parseStats2(args []string, argi *int, opts *Options) (Verb, error) {
	v := &stats2Verb{groups: newOrderedMap()}
	var fields []string
	p := newOptParser("stats2", args, argi)
	for {
		f := p.next()
		if f == "" {
			break
		}
		switch f {
		case "-a":
			v.accNames = append(v.accNames, p.list()...)
		case "-f":
			fields = append(fields, p.list()...)
		case "-g":
			v.groupBy = p.list()
		case "-v":
			v.verbose = true
			p.advance()
		case "-s":
			v.iterative = true
			p.advance()
		case "--fit":
			v.doFit = true
			p.advance()
		default:
			p.unknown(f)
		}
	}
	if len(v.accNames) == 0 || len(fields) == 0 {
		fmt.Fprintf(os.Stderr, "mlr stats2: options -a and -f are required.\n")
		fmt.Fprint(os.Stderr, verbUsage("stats2"))
		os.Exit(1)
	}
	if len(fields)%2 != 0 {
		fmt.Fprintf(os.Stderr, "mlr stats2: argument to -f must have even number of fields.\n")
		os.Exit(1)
	}
	for i := 0; i < len(fields); i += 2 {
		v.fieldPairs = append(v.fieldPairs, [2]string{fields[i], fields[i+1]})
	}
	for _, a := range v.accNames {
		switch a {
		case "linreg-ols", "linreg-pca", "r2", "logireg", "corr", "cov", "covx":
		default:
			fmt.Fprintf(os.Stderr, "mlr stats2: accumulator \"%s\" not found.\n", a)
			os.Exit(1)
		}
	}
	return v, nil
}

func (v *stats2Verb) Process(rec *Mlrmap, ctx *Context, out recordSink) {
	groupVals, ok := rec.GetSelectedValues(v.groupBy)
	if !ok {
		return
	}
	key, _ := rec.GetSelectedValuesJoined(v.groupBy)
	gi, ok := v.groups.Get(key)
	var g *stats2Group
	if !ok {
		g = &stats2Group{groupVals: groupVals, accs: map[string]*bivarAcc{}}
		v.groups.Put(key, g)
	} else {
		g = gi.(*stats2Group)
	}
	for _, pair := range v.fieldPairs {
		xv := rec.Get(pair[0])
		yv := rec.Get(pair[1])
		if xv == nil || yv == nil || xv.Type() == MT_VOID || yv.Type() == MT_VOID {
			continue
		}
		x, okx := xv.GetNumericToFloat()
		y, oky := yv.GetNumericToFloat()
		if !okx || !oky {
			fmt.Fprintf(os.Stderr, "mlr stats2: non-numeric input \"%s\" or \"%s\".\n", xv.String(), yv.String())
			os.Exit(1)
		}
		k := pair[0] + "," + pair[1]
		acc, ok := g.accs[k]
		if !ok {
			acc = &bivarAcc{}
			g.accs[k] = acc
		}
		acc.ingest(x, y)
		acc.xs = append(acc.xs, x)
		acc.ys = append(acc.ys, y)
	}
	if v.doFit {
		v.recs = append(v.recs, rec)
		v.ctxs = append(v.ctxs, *ctx)
		return
	}
	if v.iterative {
		newrec := rec.ShallowCopy()
		v.emitInto(newrec, g)
		out(newrec, ctx)
	}
}

func (v *stats2Verb) emitInto(rec *Mlrmap, g *stats2Group) {
	for _, pair := range v.fieldPairs {
		k := pair[0] + "," + pair[1]
		acc, ok := g.accs[k]
		if !ok {
			continue
		}
		prefix := pair[0] + "_" + pair[1]
		for _, an := range v.accNames {
			switch an {
			case "linreg-ols":
				m, b, ok := acc.ols()
				if ok {
					rec.Put(prefix+"_m", FromFloat(m))
					rec.Put(prefix+"_b", FromFloat(b))
				} else {
					rec.Put(prefix+"_m", VOID)
					rec.Put(prefix+"_b", VOID)
				}
				rec.Put(prefix+"_n", FromInt(acc.n))
			case "r2":
				n := float64(acc.n)
				numer := n*acc.sumxy - acc.sumx*acc.sumy
				numer = numer * numer
				denom := (n*acc.sumx2 - acc.sumx*acc.sumx) * (n*acc.sumy2 - acc.sumy*acc.sumy)
				if acc.n < 2 || denom == 0 {
					rec.Put(prefix+"_r2", VOID)
				} else {
					rec.Put(prefix+"_r2", FromFloat(numer/denom))
				}
			case "corr":
				if acc.n < 2 {
					rec.Put(prefix+"_corr", VOID)
				} else {
					n := float64(acc.n)
					sigmaxy := getCov(acc.n, acc.sumx, acc.sumy, acc.sumxy)
					sigmax := math.Sqrt(getVar(acc.n, acc.sumx/n, acc.sumx, acc.sumx2))
					sigmay := math.Sqrt(getVar(acc.n, acc.sumy/n, acc.sumy, acc.sumy2))
					rec.Put(prefix+"_corr", FromFloat(sigmaxy/(sigmax*sigmay)))
				}
			case "cov":
				if acc.n < 2 {
					rec.Put(prefix+"_cov", VOID)
				} else {
					rec.Put(prefix+"_cov", FromFloat(getCov(acc.n, acc.sumx, acc.sumy, acc.sumxy)))
				}
			case "covx":
				if acc.n < 2 {
					rec.Put(prefix+"_xvar", VOID)
					rec.Put(prefix+"_xycov", VOID)
					rec.Put(prefix+"_yvar", VOID)
				} else {
					n := float64(acc.n)
					rec.Put(prefix+"_xvar", FromFloat(getVar(acc.n, acc.sumx/n, acc.sumx, acc.sumx2)))
					rec.Put(prefix+"_xycov", FromFloat(getCov(acc.n, acc.sumx, acc.sumy, acc.sumxy)))
					rec.Put(prefix+"_yvar", FromFloat(getVar(acc.n, acc.sumy/n, acc.sumy, acc.sumy2)))
				}
			case "linreg-pca":
				v.emitPCA(rec, prefix, acc)
			case "logireg":
				m, b, n, ell, ok := logisticRegression(acc.xs, acc.ys)
				if ok {
					rec.Put(prefix+"_logistic_m", FromFloat(m))
					rec.Put(prefix+"_logistic_b", FromFloat(b))
					rec.Put(prefix+"_logistic_n", FromInt(n))
					rec.Put(prefix+"_logistic_ell", FromFloat(ell))
				} else {
					rec.Put(prefix+"_logistic_m", VOID)
					rec.Put(prefix+"_logistic_b", VOID)
					rec.Put(prefix+"_logistic_n", FromInt(n))
					rec.Put(prefix+"_logistic_ell", VOID)
				}
			}
		}
	}
}

func (v *stats2Verb) emitPCA(rec *Mlrmap, prefix string, acc *bivarAcc) {
	if acc.n < 2 {
		rec.Put(prefix+"_pca_m", VOID)
		rec.Put(prefix+"_pca_b", VOID)
		rec.Put(prefix+"_pca_n", FromInt(acc.n))
		rec.Put(prefix+"_pca_quality", VOID)
		return
	}
	n := float64(acc.n)
	xbar := acc.sumx / n
	ybar := acc.sumy / n
	varx := getVar(acc.n, xbar, acc.sumx, acc.sumx2)
	vary := getVar(acc.n, ybar, acc.sumy, acc.sumy2)
	covxy := getCov(acc.n, acc.sumx, acc.sumy, acc.sumxy)
	l1, l2, e1, e2 := eigen2x2(varx, covxy, covxy, vary)
	abs1 := math.Abs(l1)
	abs2 := math.Abs(l2)
	var quality float64
	if abs1 == 0 {
		quality = 0
	} else if abs2 == 0 {
		quality = 1
	} else {
		quality = math.Log(abs1/abs2) / math.Log(10)
	}
	x0, y0 := e1[0], e1[1]
	m := y0 / x0
	b := ybar - m*xbar
	rec.Put(prefix+"_pca_m", FromFloat(m))
	rec.Put(prefix+"_pca_b", FromFloat(b))
	rec.Put(prefix+"_pca_n", FromInt(acc.n))
	rec.Put(prefix+"_pca_quality", FromFloat(quality))
	if v.verbose {
		rec.Put(prefix+"_pca_l1", FromFloat(l1))
		rec.Put(prefix+"_pca_l2", FromFloat(l2))
		rec.Put(prefix+"_pca_v11", FromFloat(e1[0]))
		rec.Put(prefix+"_pca_v12", FromFloat(e1[1]))
		rec.Put(prefix+"_pca_v21", FromFloat(e2[0]))
		rec.Put(prefix+"_pca_v22", FromFloat(e2[1]))
	}
}

// eigen2x2 returns eigenvalues (largest first) and unit eigenvectors of a symmetric 2x2 matrix.
func eigen2x2(a, b, c, d float64) (float64, float64, [2]float64, [2]float64) {
	tr := a + d
	det := a*d - b*c
	disc := math.Sqrt(math.Max(tr*tr/4-det, 0))
	l1 := tr/2 + disc
	l2 := tr/2 - disc
	var e1, e2 [2]float64
	if b != 0 {
		e1 = [2]float64{l1 - d, b}
		e2 = [2]float64{l2 - d, b}
	} else {
		if a >= d {
			e1 = [2]float64{1, 0}
			e2 = [2]float64{0, 1}
		} else {
			e1 = [2]float64{0, 1}
			e2 = [2]float64{1, 0}
		}
	}
	norm := func(v [2]float64) [2]float64 {
		n := math.Hypot(v[0], v[1])
		if n == 0 {
			return v
		}
		return [2]float64{v[0] / n, v[1] / n}
	}
	return l1, l2, norm(e1), norm(e2)
}

// logisticRegression via Newton's method.
func logisticRegression(xs, ys []float64) (m, b float64, n int64, ell float64, ok bool) {
	n = int64(len(xs))
	if n < 2 {
		return 0, 0, n, 0, false
	}
	m, b = 0, 0
	for iter := 0; iter < 100; iter++ {
		var g0, g1, h00, h01, h11 float64
		for i := range xs {
			x := xs[i]
			y := ys[i]
			p := 1.0 / (1.0 + math.Exp(-m*x-b))
			g0 += (y - p) * x
			g1 += (y - p)
			w := p * (1 - p)
			h00 += w * x * x
			h01 += w * x
			h11 += w
		}
		det := h00*h11 - h01*h01
		if det == 0 {
			return m, b, n, 0, false
		}
		dm := (h11*g0 - h01*g1) / det
		db := (-h01*g0 + h00*g1) / det
		m += dm
		b += db
		if math.Abs(dm) < 1e-9 && math.Abs(db) < 1e-9 {
			break
		}
	}
	ell = 0
	for i := range xs {
		p := 1.0 / (1.0 + math.Exp(-m*xs[i]-b))
		if ys[i] == 1 {
			ell += math.Log(p)
		} else {
			ell += math.Log(1 - p)
		}
	}
	return m, b, n, ell, true
}

func (v *stats2Verb) Finish(ctx *Context, out recordSink) {
	if v.doFit {
		for i, rec := range v.recs {
			groupVals, ok := rec.GetSelectedValues(v.groupBy)
			_ = groupVals
			if !ok {
				continue
			}
			key, _ := rec.GetSelectedValuesJoined(v.groupBy)
			gi, _ := v.groups.Get(key)
			g := gi.(*stats2Group)
			for _, pair := range v.fieldPairs {
				acc, ok := g.accs[pair[0]+","+pair[1]]
				if !ok {
					continue
				}
				xv := rec.Get(pair[0])
				if xv == nil {
					continue
				}
				x, okx := xv.GetNumericToFloat()
				if !okx {
					continue
				}
				prefix := pair[0] + "_" + pair[1]
				for _, an := range v.accNames {
					switch an {
					case "linreg-ols":
						m, b, ok := acc.ols()
						if ok {
							rec.Put(prefix+"_ols_fit", FromFloat(m*x+b))
						}
					case "linreg-pca":
						tmp := NewMlrmap()
						v.emitPCA(tmp, prefix, acc)
						mv := tmp.Get(prefix + "_pca_m")
						bv := tmp.Get(prefix + "_pca_b")
						if mv != nil && mv.Type() == MT_FLOAT {
							rec.Put(prefix+"_pca_fit", FromFloat(mv.floatval*x+bv.floatval))
						}
					case "logireg":
						m, b, _, _, ok := logisticRegression(acc.xs, acc.ys)
						if ok {
							rec.Put(prefix+"_logistic_fit", FromFloat(1.0/(1.0+math.Exp(-m*x-b))))
						}
					}
				}
			}
			c := v.ctxs[i]
			out(rec, &c)
		}
		return
	}
	if v.iterative {
		return
	}
	for _, k := range v.groups.keys {
		g := v.groups.vals[k].(*stats2Group)
		rec := NewMlrmap()
		for i, f := range v.groupBy {
			rec.Put(f, g.groupVals[i])
		}
		v.emitInto(rec, g)
		out(rec, ctx)
	}
}
