{"command":"cd /workspace/src; cat > verbs_summary.go <<'EOF'
package main

import (
	"fmt"
	"os"
	"sort"
	"strings"
	"unicode/utf8"
)

var allSummarizers = []string{"field_type", "count", "null_count", "distinct_count", "mode", "sum", "mean", "stddev", "var", "skewness", "minlen", "maxlen", "min", "p25", "median", "p75", "max", "iqr", "lof", "lif", "uif", "uof"}
var defaultSummarizers = map[string]bool{"field_type": true, "count": true, "mean": true, "min": true, "max": true, "null_count": true, "distinct_count": true}

type summaryVerb struct {
	summarizers []string
	transpose   bool
	fields      *orderedMap // field name -> *fieldSummary
}

type fieldSummary struct {
	types       []string
	typeSet     map[string]bool
	count       int64
	nullCount   int64
	distinct    map[string]int64
	distinctOrder []string
	moments     *momentAccumulator
	numericN    int64
	minlen, maxlen int
	haveLen     bool
	minv, maxv  *Mlrval
	values      []*Mlrval
}

func parseSummary(args []string, argi *int, opts *Options) (Verb, error) {
	v := &summaryVerb{fields: newOrderedMap()}
	var only []string
	var except map[string]bool
	all := false
	p := newOptParser("summary", args, argi)
	for {
		f := p.next()
		if f == "" {
			break
		}
		switch f {
		case "-a":
			only = append(only, p.list()...)
		case "-x":
			except = map[string]bool{}
			for _, n := range p.list() {
				except[n] = true
			}
		case "--all":
			all = true
			p.advance()
		case "--transpose":
			v.transpose = true
			p.advance()
		default:
			p.unknown(f)
		}
	}
	valid := map[string]bool{}
	for _, s := range allSummarizers {
		valid[s] = true
	}
	for _, s := range only {
		if !valid[s] {
			fmt.Fprintf(os.Stderr, "mlr summary: unrecognized summarizer \"%s\".\n", s)
			os.Exit(1)
		}
	}
	for s := range except {
		if !valid[s] {
			fmt.Fprintf(os.Stderr, "mlr summary: unrecognized summarizer \"%s\".\n", s)
			os.Exit(1)
		}
	}
	onlySet := map[string]bool{}
	for _, s := range only {
		onlySet[s] = true
	}
	for _, s := range allSummarizers {
		include := false
		if all {
			include = true
		} else if only != nil {
			include = onlySet[s]
		} else if except != nil {
			include = !except[s]
		} else {
			include = defaultSummarizers[s]
		}
		if include {
			v.summarizers = append(v.summarizers, s)
		}
	}
	return v, nil
}

func (v *summaryVerb) Process(rec *Mlrmap, ctx *Context, out recordSink) {
	for e := rec.Head; e != nil; e = e.Next {
		fi, ok := v.fields.Get(e.Key)
		var fs *fieldSummary
		if !ok {
			fs = &fieldSummary{typeSet: map[string]bool{}, distinct: map[string]int64{}, moments: newMomentAccumulator()}
			v.fields.Put(e.Key, fs)
		} else {
			fs = fi.(*fieldSummary)
		}
		val := e.Value
		fs.count++
		tn := typeofName(val)
		if !fs.typeSet[tn] {
			fs.typeSet[tn] = true
			fs.types = append(fs.types, tn)
		}
		if val.Type() == MT_VOID {
			fs.nullCount++
		}
		s := val.String()
		if _, ok := fs.distinct[s]; !ok {
			fs.distinctOrder = append(fs.distinctOrder, s)
		}
		fs.distinct[s]++
		l := utf8.RuneCountInString(s)
		if !fs.haveLen {
			fs.minlen, fs.maxlen = l, l
			fs.haveLen = true
		} else {
			if l < fs.minlen {
				fs.minlen = l
			}
			if l > fs.maxlen {
				fs.maxlen = l
			}
		}
		if val.IsNumeric() {
			fs.moments.ingest(val)
			fs.numericN++
		}
		if val.Type() != MT_VOID {
			if fs.minv == nil {
				fs.minv, fs.maxv = val, val
			} else {
				fs.minv = minMaxPair(fs.minv, val, true)
				fs.maxv = minMaxPair(fs.maxv, val, false)
			}
			fs.values = append(fs.values, val)
		}
	}
}

func (fs *fieldSummary) summarize(name string) *Mlrval {
	switch name {
	case "field_type":
		return FromString(strings.Join(fs.types, "-"))
	case "count":
		return FromInt(fs.count)
	case "null_count":
		return FromInt(fs.nullCount)
	case "distinct_count":
		return FromInt(int64(len(fs.distinct)))
	case "mode":
		if len(fs.distinctOrder) == 0 {
			return VOID
		}
		best := fs.distinctOrder[0]
		for _, s := range fs.distinctOrder[1:] {
			if fs.distinct[s] > fs.distinct[best] {
				best = s
			}
		}
		return inferredFromString(best)
	case "sum":
		if fs.numericN == 0 {
			return FromInt(0)
		}
		return fs.moments.sumx
	case "mean":
		if fs.numericN == 0 {
			return VOID
		}
		return fs.moments.mean()
	case "stddev":
		if fs.numericN == 0 {
			return VOID
		}
		return fs.moments.stddev()
	case "var":
		if fs.numericN == 0 {
			return VOID
		}
		return fs.moments.variance()
	case "skewness":
		if fs.numericN == 0 {
			return VOID
		}
		return fs.moments.skewness()
	case "minlen":
		if !fs.haveLen {
			return VOID
		}
		return FromInt(int64(fs.minlen))
	case "maxlen":
		if !fs.haveLen {
			return VOID
		}
		return FromInt(int64(fs.maxlen))
	case "min":
		if fs.minv == nil {
			return VOID
		}
		return fs.minv
	case "max":
		if fs.maxv == nil {
			return VOID
		}
		return fs.maxv
	case "p25", "median", "p75", "iqr", "lof", "lif", "uif", "uof":
		if len(fs.values) == 0 {
			return VOID
		}
		sorted := sortedCopy(fs.values)
		p25 := percentileNonInterpolated(sorted, 25)
		p50 := percentileNonInterpolated(sorted, 50)
		p75 := percentileNonInterpolated(sorted, 75)
		switch name {
		case "p25":
			return p25
		case "median":
			return p50
		case "p75":
			return p75
		}
		iqr := binaryOpMinus(p75, p25)
		switch name {
		case "iqr":
			return iqr
		case "lof":
