}

func parseSurv(args []string, argi *int, opts *Options) (Verb, error) {
	v := &survVerb{}
	p := newOptParser("surv", args, argi)
	for {
		f := p.next()
		if f == "" {
			break
		}
		switch f {
		case "-d":
			v.durationField = p.str()
		case "-s":
			v.statusField = p.str()
		default:
			p.unknown(f)
		}
	}
	if v.durationField == "" || v.statusField == "" {
		fmt.Fprint(os.Stderr, verbUsage("surv"))
		os.Exit(1)
	}
	return v, nil
}

func (v *survVerb) Process(rec *Mlrmap, ctx *Context, out recordSink) {
	d := rec.Get(v.durationField)
	s := rec.Get(v.statusField)
	if d == nil || s == nil {
