	}
	v.durations = append(v.durations, df)
	v.statuses = append(v.statuses, int(sf))
}

func (v *survVerb) Finish(ctx *Context, out recordSink) {
	n := len(v.durations)
	idx := make([]int, n)
	for i := range idx {
		idx[i] = i
	}
	sort.SliceStable(idx, func(a, b int) bool { return v.durations[idx[a]] < v.durations[idx[b]] })
	surv := 1.0
	atRisk := n
	i := 0
	for i < n {
		t := v.durations[idx[i]]
		events := 0
		censored := 0
		j := i
		for j < n && v.durations[idx[j]] == t {
			if v.statuses[idx[j]] == 1 {
				events++
			} else {
				censored++
			}
			j++
		}
		if events > 0 {
			surv *= 1.0 - float64(events)/float64(atRisk)
		}
		rec := NewMlrmap()
		rec.Put("time", FromFloat(t))
		rec.Put("n_at_risk", FromInt(int64(atRisk)))
		rec.Put("n_events", FromInt(int64(events)))
		rec.Put("n_censored", FromInt(int64(censored)))
		rec.Put("survival", FromFloat(surv))
		out(rec, ctx)
		atRisk -= (j - i)
		i = j
	}
