// writeYAMLListItem writes a list element after a "-" at the given indent.
func writeYAMLListItem(sb *strings.Builder, mv *Mlrval, indent int) {
	pad := strings.Repeat(" ", indent)
	switch mv.Type() {
	case MT_MAP:
		if mv.mapval.Len() == 0 {
			sb.WriteString(" {}\n")
			return
		}
		first := true
		for e := mv.mapval.Head; e != nil; e = e.Next {
			if first {
				sb.WriteString(" ")
				first = false
			} else {
				sb.WriteString(pad)
			}
			sb.WriteString(yamlKey(e.Key))
			sb.WriteString(":")
			writeYAMLValue(sb, e.Value, indent+2)
		}
	case MT_ARRAY:
		if len(mv.arrayval) == 0 {
			sb.WriteString(" []\n")
			return
		}
		sb.WriteString("\n")
		for _, el := range mv.arrayval {
			sb.WriteString(pad)
			sb.WriteString("-")
			writeYAMLListItem(sb, el, indent+2)
		}
	default:
		sb.WriteString(" ")
		sb.WriteString(yamlScalar(mv))
		sb.WriteString("\n")
	}
}

func yamlKey(k string) string {
	if yamlNeedsQuote(k) {
		return jsonEncodeString(k)
	}
	return k
}

func (w *yamlWriter) Write(rec *Mlrmap, out *bufio.Writer, isFinal bool) {
	if rec == nil {
		return
	}
	var sb strings.Builder
	if w.wopts.YArray {
		sb.WriteString("-")
		writeYAMLListItem(&sb, FromMap(rec), 2)
	} else {
		if w.numWritten > 0 {
			sb.WriteString("---\n")
		}
		for e := rec.Head; e != nil; e = e.Next {
			sb.WriteString(yamlKey(e.Key))
			sb.WriteString(":")
			writeYAMLValue(&sb, e.Value, 2)
		}
	}
	w.numWritten++
	out.WriteString(sb.String())
}

// Simple YAML reader: supports top-level sequences of maps, documents separated by ---,
// nested maps via indentation, and sequences of scalars.
type yamlReader struct {
	ropts *ReaderOptions
}

type yamlLine struct {
	indent int
	text   string
}

func (r *yamlReader) Read(filenames []string, ctx *Context, handler RecordHandler) error {
	return forEachFile(filenames, r.ropts, ctx, func(in io.Reader, ctx *Context) (bool, error) {
		data, err := io.ReadAll(in)
		if err != nil {
			return false, err
		}
		docs := strings.Split(string(data), "\n---")
		for di, doc := range docs {
			if di == 0 {
				doc = strings.TrimPrefix(doc, "---")
			}
			var lines []yamlLine
			for _, raw := range strings.Split(doc, "\n") {
				raw = strings.TrimRight(raw, "\r")
				if strings.TrimSpace(raw) == "" || strings.HasPrefix(strings.TrimSpace(raw), "#") {
					continue
				}
				indent := len(raw) - len(strings.TrimLeft(raw, " "))
				lines = append(lines, yamlLine{indent: indent, text: strings.TrimLeft(raw, " ")})
			}
			if len(lines) == 0 {
				continue
			}
			pos := 0
			val := parseYAMLBlock(lines, &pos, lines[0].indent)
			var recs []*Mlrmap
			switch val.Type() {
			case MT_MAP:
				recs = append(recs, val.mapval)
			case MT_ARRAY:
				for _, el := range val.arrayval {
					if el.Type() == MT_MAP {
						recs = append(recs, el.mapval)
					}
				}
			}
			for _, rec := range recs {
				ctx.NR++
				ctx.FNR++
				if !handler(rec, ctx) {
					return false, nil
				}
			}
		}
		return true, nil
	})
}

func yamlScalarValue(s string) *Mlrval {
	s = strings.TrimSpace(s)
	if s == "" || s == "~" || s == "null" {
		if s == "" {
			return VOID
		}
		return newJSONNullValue()
	}
	if s == "true" {
		return TRUE
	}
	if s == "false" {
		return FALSE
	}
	if len(s) >= 2 && ((s[0] == '"' && s[len(s)-1] == '"') || (s[0] == '\'' && s[len(s)-1] == '\'')) {
		if s[0] == '"' {
			if v, err := ParseJSONValue(s); err == nil {
				return FromString(v.String())
			}
		}
		return FromString(s[1 : len(s)-1])
	}
	if strings.HasPrefix(s, "[") || strings.HasPrefix(s, "{") {
		if v, err := ParseJSONValue(s); err == nil {
			return v
		}
	}
	return FromInferredString(s)
}

func parseYAMLBlock(lines []yamlLine, pos *int, indent int) *Mlrval {
	if *pos >= len(lines) {
		return VOID
	}
	if strings.HasPrefix(lines[*pos].text, "- ") || lines[*pos].text == "-" {
		arr := []*Mlrval{}
		for *pos < len(lines) && lines[*pos].indent == indent && (strings.HasPrefix(lines[*pos].text, "- ") || lines[*pos].text == "-") {
			item := strings.TrimSpace(strings.TrimPrefix(lines[*pos].text, "-"))
			if item == "" {
				*pos++
				if *pos < len(lines) && lines[*pos].indent > indent {
					arr = append(arr, parseYAMLBlock(lines, pos, lines[*pos].indent))
				} else {
					arr = append(arr, VOID)
				}
				continue
			}
			// inline map start: "- key: value"
			if k, v, ok := splitYAMLKV(item); ok {
				// Treat as a map whose first entry is on this line; subsequent entries at indent+2
				subIndent := indent + 2
				lines[*pos] = yamlLine{indent: subIndent, text: k + ":" + v}
				arr = append(arr, parseYAMLBlock(lines, pos, subIndent))
				continue
			}
			arr = append(arr, yamlScalarValue(item))
			*pos++
		}
		return FromArray(arr)
	}
	m := NewMlrmap()
	for *pos < len(lines) && lines[*pos].indent == indent {
		text := lines[*pos].text
		if strings.HasPrefix(text, "- ") {
			break
		}
		k, v, ok := splitYAMLKV(text)
		if !ok {
			*pos++
			continue
		}
		*pos++
		if strings.TrimSpace(v) == "" {
			if *pos < len(lines) && lines[*pos].indent > indent {
				m.Put(k, parseYAMLBlock(lines, pos, lines[*pos].indent))
			} else if *pos < len(lines) && lines[*pos].indent == indent && strings.HasPrefix(lines[*pos].text, "- ") {
				m.Put(k, parseYAMLBlock(lines, pos, indent))
			} else {
				m.Put(k, VOID)
			}
		} else {
			m.Put(k, yamlScalarValue(v))
		}
	}
	return FromMap(m)
}

func splitYAMLKV(text string) (string, string, bool) {
	// key: value, where key may be quoted
	if strings.HasPrefix(text, "\"") {
		end := strings.Index(text[1:], "\"")
		if end >= 0 {
			key := text[1 : end+1]
			rest := text[end+2:]
			if strings.HasPrefix(rest, ":") {
				return key, rest[1:], true
			}
		}
	}
	idx := strings.Index(text, ": ")
	if idx < 0 {
		if strings.HasSuffix(text, ":") {
			return text[:len(text)-1], "", true
		}
		return "", "", false
	}
	return text[:idx], text[idx+2:], true
}

func yamlInt(s string) (int64, bool) {
	v, err := strconv.ParseInt(s, 10, 64)
	return v, err == nil
}
