package main
import ("fmt"; "math")
func main(){
  xs := []float64{4,5,9,10,11}
  n := float64(len(xs))
  var sumx, sumx2 float64
  for _, x := range xs { sumx += x; sumx2 += x*x }
  mean := sumx/n
  v1 := (sumx2 - mean*(2.0*sumx-n*mean))/(n-1)
  var m2 float64
  for _, x := range xs { d := x-mean; m2 += d*d }
  v2 := m2/(n-1)
  // Welford
  var wm, wM2 float64
  for i, x := range xs { k := float64(i+1); d := x - wm; wm += d/k; wM2 += d*(x-wm) }
  v3 := wM2/(n-1)
  v4 := (sumx2/n - mean*mean) * n/(n-1)
  v5 := (sumx2 - sumx*sumx/n)/(n-1)
  D := n*sumx2 - sumx*sumx
  v6 := D/(n*(n-1))
  fmt.Println(v1, v2, v3, v4, v5, v6)
  fmt.Println(math.Sqrt(v1), math.Sqrt(v2), math.Sqrt(v5), math.Sqrt(v6))
  // kurtosis variants
  var sumx3, sumx4 float64
  for _, x := range xs { sumx3 += x*x*x; sumx4 += x*x*x*x }
