  numer = numer/n
  denom := (sumx2/n - mean*mean); denom = denom*denom
  fmt.Println(numer/denom - 3.0)
  // skewness
  sn := sumx3 - mean*(3.0*sumx2-2.0*n*mean*mean); sn = sn/n
  fmt.Println(sn/math.Pow(v1,1.5), sn/math.Pow((sumx2/n-mean*mean),1.5))
  // meaneb for [4,5,7,10]
  ys := []float64{4,5,7,10}
